class _FastSlabRebarItem {
  const _FastSlabRebarItem({
    required this.p1,
    required this.p2,
    required this.geometrySegments,
    required this.captureStyle,
    required this.measuredLengthM,
    required this.mark,
    required this.diameterMm,
    required this.numberOfBars,
    required this.groupFactor,
    this.bundleCountPoints = const <Offset>[],
    required this.spacingMm,
    required this.layer,
    required this.direction,
    required this.quantityMode,
    required this.distributionWidthM,
    required this.boq,
  });

  final Offset p1;
  final Offset p2;
  final List<Map<String, dynamic>> geometrySegments;
  final String captureStyle;
  final double measuredLengthM;
  final String mark;
  final int diameterMm;
  final int numberOfBars;
  final double groupFactor;
  final List<Offset> bundleCountPoints;
  final double spacingMm;
  final String layer;
  final String direction;
  final String quantityMode;
  final double? distributionWidthM;
  final BoqPick boq;

  double get unitWeightKgPerM => rebarUnitWeightKgPerM(diameterMm);
  double get baseTotalLengthM => measuredLengthM * numberOfBars;
  double get totalLengthM => baseTotalLengthM * groupFactor;
  double get totalWeightKg => totalLengthM * unitWeightKgPerM;

  _FastSlabRebarItem withBundleCount(List<Offset> points) {
    return _FastSlabRebarItem(
      p1: p1,
      p2: p2,
      geometrySegments: geometrySegments,
      captureStyle: captureStyle,
      measuredLengthM: measuredLengthM,
      mark: mark,
      diameterMm: diameterMm,
      numberOfBars: numberOfBars,
      groupFactor: points.length.toDouble(),
      bundleCountPoints: List<Offset>.from(points),
      spacingMm: spacingMm,
      layer: layer,
      direction: direction,
      quantityMode: quantityMode,
      distributionWidthM: distributionWidthM,
      boq: boq,
    );
  }
}

class ImageTakeoffController extends GetxController implements LinksContext {
  PavementTransferRequest? pendingPavementTransfer;

  void requestPavementTransfer({required String areaGroupId, required double sourcePolygonAreaM2}) {
    pendingPavementTransfer = PavementTransferRequest(areaGroupId: areaGroupId, sourcePolygonAreaM2: sourcePolygonAreaM2);
  }

  void cancelPavementTransfer() => pendingPavementTransfer = null;

  Future<void> applyPavementTransferDeduction({required CollectionReference<Map<String, dynamic>> measurementsRef, required double transferAreaM2, required List<Offset> transferPolygon}) async {
    final req = pendingPavementTransfer;
    if (req == null || transferAreaM2 <= 0 || req.sourcePolygonAreaM2 <= 0) return;
    final snap = await measurementsRef.where('areaGroupId', isEqualTo: req.areaGroupId).get();
    if (snap.docs.isEmpty) return;
    final ratio = (transferAreaM2 / req.sourcePolygonAreaM2).clamp(0.0, 1.0);
    final points = transferPolygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();
    final batch = FirebaseFirestore.instance.batch();
    for (final d in snap.docs) {
      final data = d.data();
      double n(dynamic v) => v is num ? v.toDouble() : double.tryParse('${v ?? ''}') ?? 0.0;
      final oldValue = n(data['value']);
      final oldQty = n(data['quantity']);
      final oldNet = n(data['polygonNetAreaM2']);
      batch.update(d.reference, {
        'value': oldValue * (1.0 - ratio),
        'quantity': oldQty * (1.0 - ratio),
        if (oldNet > 0) 'polygonNetAreaM2': (oldNet - transferAreaM2).clamp(0.0, double.infinity),
        'transferDeductionPolygons': FieldValue.arrayUnion([{'points': points, 'areaM2': transferAreaM2, 'label': 'Transferred area'}]),
        'updatedAt': FieldValue.serverTimestamp(),
      });
    }
    await batch.commit();
  }

  PendingSlabRebarCapture? _pendingSlabRebarCapture;
  BoqPick? _lastSlabRebarBoq;
  int _lastFastSlabRebarDiameterMm = 16;
  int _lastFastSlabRebarCount = 1;
  double _lastFastSlabRebarSpacingMm = 200;
  String _lastFastSlabRebarLayer = 'T1';
  String _lastFastSlabRebarDirection = 'X';
  String _lastFastSlabRebarQuantityMode = 'count';
  double _lastFastSlabRebarDistributionWidthM = 5.0;
  final List<_FastSlabRebarItem> _fastSlabRebarSession = [];
  _FastSlabRebarItem? _pendingFastSlabRebarBundleItem;

  bool get isCountingFastSlabRebarBundles =>
      _pendingFastSlabRebarBundleItem != null;

  String get pendingFastSlabRebarBundleMark =>
      _pendingFastSlabRebarBundleItem?.mark ?? '';

  List<CountMarker> get pendingFastSlabRebarBundleMarkers {
    final markers = <CountMarker>[];
    for (
      var itemIndex = 0;
      itemIndex < _fastSlabRebarSession.length;
      itemIndex++
    ) {
      final item = _fastSlabRebarSession[itemIndex];
      for (
        var pointIndex = 0;
        pointIndex < item.bundleCountPoints.length;
        pointIndex++
      ) {
        markers.add(
          CountMarker(
            id: 'slab-rebar-bundle-$itemIndex-$pointIndex',
            groupId: 'slab-rebar-bundle-session-$itemIndex',
            position: item.bundleCountPoints[pointIndex],
            color: currentColor,
            mark: 'tick',
            label: '${item.mark} ×${pointIndex + 1}',
          ),
        );
      }
    }
    return markers;
  }

  /// Unsaved slab-rebar geometry kept only in memory until Commit all.
  /// The viewer uses this so the QS can immediately see which bar runs have
  /// already been captured during the current temporary session.
  List<Map<String, dynamic>> get pendingFastSlabRebarSegments {
    final out = <Map<String, dynamic>>[];
    for (
      var itemIndex = 0;
      itemIndex < _fastSlabRebarSession.length;
      itemIndex++
    ) {
      final item = _fastSlabRebarSession[itemIndex];
      for (
        var segmentIndex = 0;
        segmentIndex < item.geometrySegments.length;
        segmentIndex++
      ) {
        final segment = item.geometrySegments[segmentIndex];
        out.add(<String, dynamic>{
          'draftId': 'slab-rebar-temp-$itemIndex-$segmentIndex',
          'sessionItemIndex': itemIndex,
          'segmentIndex': segmentIndex,
          'p1': segment['p1'],
          'p2': segment['p2'],
          'lengthM': segment['lengthM'],
          'mark': item.mark,
          'diameterMm': item.diameterMm,
          'layer': item.layer,
          'direction': item.direction,
          'color': currentColor.value,
        });
      }
    }
    return List<Map<String, dynamic>>.unmodifiable(out);
  }

  bool get hasPendingSlabRebarLengthCapture => _pendingSlabRebarCapture != null;

  /// The drawing region used to capture the pending bar mark. Keep exposing
  /// this polygon until the measured group has been saved so the viewer can
  /// continue to identify the mark while the user measures its bar length and
  /// selects the related BOQ item.
  List<Offset> get pendingSlabRebarMarkPolygon =>
      _pendingSlabRebarCapture == null
          ? const <Offset>[]
          : List<Offset>.unmodifiable(_pendingSlabRebarCapture!.markPolygon);

  Future<void> _waitForMeasurementDialogRestore({
    required String title,
    IconData icon = Icons.straighten_rounded,
  }) async {
    // Get.dialog completes before its route has necessarily finished the pop
    // transition. Inserting the restore control immediately can leave it
    // underneath that outgoing route, so wait until the next rendered frame
    // and always attach it to the application's root navigator overlay.
    await WidgetsBinding.instance.endOfFrame;

    final overlay = Get.key.currentState?.overlay;
    if (overlay == null) return;

    final completer = Completer<void>();
    late final OverlayEntry entry;
    entry = OverlayEntry(
      maintainState: true,
      builder:
          (context) => Positioned(
            // Place the restore action beside the left-hand tools menu.
            left: 134,
            bottom: 24,
            child: SafeArea(
              child: Material(
                elevation: 24,
                color: Colors.transparent,
                borderRadius: BorderRadius.circular(18),
                child: FilledButton.icon(
                  onPressed: () {
                    entry.remove();
                    if (!completer.isCompleted) completer.complete();
                  },
                  style: FilledButton.styleFrom(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 20,
                      vertical: 18,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(18),
                    ),
                  ),
                  icon: Icon(icon),
                  label: Text('Restore $title'),
                ),
              ),
            ),
          ),
    );
    overlay.insert(entry);
    await completer.future;
  }

