  void keepPendingFinishSessionForTool({
    required String drawingId,
    required String measureType,
  }) {
    if (_pendingFinishPolygons.isEmpty) return;
    final normalized = measureType.trim().toLowerCase();
    final toolKey =
        normalized == 'ceiling'
            ? 'ceiling'
            : normalized == 'tiling'
            ? 'tiling'
            : null;
    if (_pendingFinishDrawingId != drawingId ||
        toolKey == null ||
        toolKey != _pendingFinishToolKey) {
      clearPendingFinishSession();
    }
  }

  @override
  void onInit() {
    super.onInit();

    drawingRef = FirebaseFirestore.instance
        .collection('projects')
        .doc(projectId)
        .collection('buildings')
        .doc(buildingId)
        .collection('drawings')
        .doc(drawingId);

    measurementsRef = FirebaseFirestore.instance
        .collection('projects')
        .doc(projectId)
        .collection('buildings')
        .doc(buildingId)
        .collection('measurements');

    // Warm the building BOQ catalogue while the drawing workspace opens so
    // every take-off picker can read it from memory immediately.
    BoqPickerDialog.preload(projectId: projectId, buildingId: buildingId);
  }

  void _resetRetainingWallDraft() {
    lengthP1 = null;
    lengthP2 = null;
    rwDraftSegs.clear();
    _rwDraftWallGroupId = null;
    update(['viewer']);
  }

  void resetLength() {
    lengthP1 = null;
    lengthP2 = null;
    update(['viewer']);
  }

  void clearCalibrationDraft({bool notify = true}) {
    calibP1 = null;
    calibP2 = null;
    if (notify) {
      update(['viewer', 'viewr']);
    }
  }

  // inside your controller:

  Offset? _pendingP1;

  /// Returns null until the second tap. On second tap, returns (p1,p2) and clears state.
  Future<TwoTapPoints?> captureLengthTwoPoints({
    required Offset imagePos,
    required Map<String, dynamic> drawingData,
  }) async {
    // You can add hit-test / snapping here if you want.
    if (_pendingP1 == null) {
      _pendingP1 = imagePos;
      update(['preview']); // if you draw a rubber band line
      return null;
    } else {
      final p1 = _pendingP1!;
      final p2 = imagePos;
      _pendingP1 = null;
      update(['preview']);
      return TwoTapPoints(p1, p2);
    }
  }

  // ---------------------------------------------------------
  // Helpers copied from your State class
  // ---------------------------------------------------------
  Future<void> commitMeasurementBatchOrThrow(
    List<Map<String, dynamic>> docs,
  ) async {
    final db = FirebaseFirestore.instance;
    final batch = db.batch();

    for (final data in docs) {
      final ref = measurementsRef.doc(); // uses your existing measurementsRef
      batch.set(ref, data);
    }

    await batch.commit();
  }

  Future<void> onCanvasTapToShowFootingDetails({
    required Offset tapPosImage,
    required List<QueryDocumentSnapshot<Map<String, dynamic>>>
    cachedMeasurementDocs,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
  }) async {
    final groupId = findFootingGroupIdAtTap(
      tapPosImage: tapPosImage,
      docs: cachedMeasurementDocs,
    );

    if (groupId == null) return;

    await openFootingDetailsDialog(
      measurementsRef: measurementsRef,
      footingGroupId: groupId,
      projectId: projectId,
      buildingId: buildingId,
      drawingId: drawingId,
    );
  }

  Future<void> openFootingDetailsDialog({
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String footingGroupId,
    required String projectId,
    required String buildingId,
    required String drawingId,
  }) async {
    await showDraggableDialog2<void>(
      width: 780,
      height: 720,
      builder: (ctx, setState, offset, setOffset) {
        return Column(
          children: [
            // Drag header
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanUpdate: (d) => setOffset(offset + d.delta),
              child: Container(
                color: Colors.grey.shade100,
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 10,
                ),
                child: Row(
                  children: [
                    const Icon(Icons.drag_indicator),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Footing Details ($footingGroupId)',
                        style: const TextStyle(fontWeight: FontWeight.w800),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    IconButton(
                      onPressed: () => Get.back(),
                      icon: const Icon(Icons.close),
                    ),
                  ],
                ),
              ),
            ),

            Expanded(
              child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream:
                    measurementsRef
                        .where('footingGroupId', isEqualTo: footingGroupId)
                        .stateSnapshots(),
                builder: (_, snap) {
                  if (snap.hasError) {
                    return Padding(
                      padding: const EdgeInsets.all(12),
                      child: Text('Load error: ${snap.error}'),
                    );
                  }
                  if (!snap.hasData) {
                    return const Center(child: CircularProgressIndicator());
                  }

                  final docs = snap.data!.docs;

                  final footing =
                      <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                  final column =
                      <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                  final earth = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
                  final other = <QueryDocumentSnapshot<Map<String, dynamic>>>[];

                  for (final doc in docs) {
                    final d = doc.data();
                    switch (sectionOf(d)) {
                      case FootingSection.footing:
                        footing.add(doc);
                        break;
                      case FootingSection.column:
                        column.add(doc);
                        break;
                      case FootingSection.earthworks:
                        earth.add(doc);
                        break;
                      case FootingSection.other:
                        other.add(doc);
                        break;
                    }
                  }

                  // Optional: sort nicely
                  int orderOf(Map<String, dynamic> d) {
                    final t = (d['type'] ?? '').toString().toLowerCase();
                    if (t.contains('concrete')) return 1;
                    if (t.contains('formwork')) return 2;
                    if (t.contains('rebar') || t.contains('stirr')) return 3;
                    if (t.contains('excav')) return 1;
                    if (t.contains('backfill')) return 2;
                    if (t.contains('disposal') || t.contains('surplus'))
                      return 3;
                    return 99;
                  }

                  footing.sort(
                    (a, b) => orderOf(a.data()).compareTo(orderOf(b.data())),
                  );
                  column.sort(
                    (a, b) => orderOf(a.data()).compareTo(orderOf(b.data())),
                  );
                  earth.sort(
                    (a, b) => orderOf(a.data()).compareTo(orderOf(b.data())),
                  );

                  return ListView(
                    padding: const EdgeInsets.all(12),
                    children: [
                      sectionTile(
                        title: 'Footing',
                        docs: footing,
                        onAdd:
                            () => addPartDialog(
                              measurementsRef: measurementsRef,
                              footingGroupId: footingGroupId,
                              projectId: projectId,
                              buildingId: buildingId,
                              drawingId: drawingId,
                              defaultSection: FootingSection.footing,
                              // use any existing doc to copy polygon/color
                              sampleDoc: docs.isNotEmpty ? docs.first : null,
                            ),
                      ),
                      const SizedBox(height: 8),

                      sectionTile(
                        title: 'Foundation Column',
                        docs: column,
                        onAdd:
                            () => addPartDialog(
                              measurementsRef: measurementsRef,
                              footingGroupId: footingGroupId,
                              projectId: projectId,
                              buildingId: buildingId,
                              drawingId: drawingId,
                              defaultSection: FootingSection.column,
                              sampleDoc: docs.isNotEmpty ? docs.first : null,
                            ),
                      ),
                      const SizedBox(height: 8),

                      sectionTile(
                        title: 'Earthworks',
                        docs: earth,
                        onAdd:
                            () => addPartDialog(
                              measurementsRef: measurementsRef,
                              footingGroupId: footingGroupId,
                              projectId: projectId,
                              buildingId: buildingId,
                              drawingId: drawingId,
                              defaultSection: FootingSection.earthworks,
                              sampleDoc: docs.isNotEmpty ? docs.first : null,
                            ),
                      ),

                      if (other.isNotEmpty) ...[
                        const SizedBox(height: 8),
                        sectionTile(title: 'Other', docs: other, onAdd: null),
                      ],
                    ],
                  );
                },
              ),
            ),

            Padding(
              padding: const EdgeInsets.all(12),
              child: Align(
                alignment: Alignment.centerRight,
                child: TextButton(
                  onPressed: () => Get.back(),
                  child: const Text('Close'),
                ),
              ),
            ),
          ],
        );
      },
    );
  }

  Future<void> openFootingDetailsDialogFromCache({
    required String footingGroupId,
    required List<dynamic> docs,
  }) async {
    String s(dynamic v) => (v ?? '').toString().trim();
    double numd(dynamic v) =>
        v is num ? v.toDouble() : double.tryParse('${v ?? ''}') ?? 0.0;

    Map<String, dynamic> dataOf(dynamic doc) {
      if (doc is Map<String, dynamic>) return doc;
      // Firestore snapshot support
      final d = (doc as dynamic).data();
      if (d is Map<String, dynamic>) return d;
      return <String, dynamic>{};
    }

    String unitPretty(String u) => u == 'm2' ? 'm²' : (u == 'm3' ? 'm³' : u);

    final rows =
        docs.map((doc) {
            final d = dataOf(doc);
            return {
              'type': s(d['type']),
              'label': s(d['label']).isEmpty ? s(d['type']) : s(d['label']),
              'boq': s(d['boqCode']),
              'desc': s(d['boqDescription']),
              'unit': unitPretty(s(d['unit'])),
              'value': numd(d['value']),
            };
          }).toList()
          ..sort(
            (a, b) => (a['type'] as String).compareTo(b['type'] as String),
          );

    await showDraggableDialog2<void>(
      width: 720,
      height: 680,
      builder: (ctx, setState, offset, setOffset) {
        return Column(
          children: [
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanUpdate: (d) => setOffset(offset + d.delta),
              child: Container(
                color: Colors.grey.shade100,
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 10,
                ),
                child: Row(
                  children: [
                    const Icon(Icons.drag_indicator),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Footing Details ($footingGroupId)',
                        style: const TextStyle(fontWeight: FontWeight.w800),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    IconButton(
                      onPressed: () => Get.back(),
                      icon: const Icon(Icons.close),
                    ),
                  ],
                ),
              ),
            ),
            Expanded(
              child: ListView.separated(
                padding: const EdgeInsets.all(12),
                itemCount: rows.length,
                separatorBuilder: (_, __) => const Divider(height: 1),
                itemBuilder: (_, i) {
                  final r = rows[i];
                  return ListTile(
                    dense: true,
                    title: Text(
                      '${r['label']}',
                      style: const TextStyle(
                        fontWeight: FontWeight.w700,
                        fontSize: 13,
                      ),
                    ),
                    subtitle: Text(
                      '${r['boq']} ${r['desc']}'.trim(),
                      maxLines: 2,
                      overflow: TextOverflow.ellipsis,
                    ),
                    trailing: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      crossAxisAlignment: CrossAxisAlignment.end,
                      children: [
                        Text(
                          (r['value'] as double).toStringAsFixed(3),
                          style: const TextStyle(fontWeight: FontWeight.w800),
                        ),
                        Text(
                          '${r['unit']}',
                          style: const TextStyle(fontSize: 11),
                        ),
                      ],
                    ),
                  );
                },
              ),
            ),
            Padding(
              padding: const EdgeInsets.all(12),
              child: Align(
                alignment: Alignment.centerRight,
                child: TextButton(
                  onPressed: () => Get.back(),
                  child: const Text('Close'),
                ),
              ),
            ),
          ],
        );
      },
    );
  }

  Future<bool> handleFootingViewTap(
    Offset imagePos,
    Map<String, List<dynamic>> footingCompositeDocsByGroupId,
    Map<String, List<dynamic>> rebarFootingDocsByGroupId,
    Map<String, List<dynamic>> rebarColumnDocsByGroupId, {
    required String projectId,
    required String buildingId,
    required String drawingId,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
  }) async {
    final groupId = hitFootingGroupId(imagePos, footingCompositeDocsByGroupId);
    if (groupId == null) return false;

    // ✅ Option A: open details from CACHE (fast, no extra reads)
    final cached = <dynamic>[
      ...?footingCompositeDocsByGroupId[groupId],
      ...?rebarFootingDocsByGroupId[groupId],
      ...?rebarColumnDocsByGroupId[groupId],
    ];

    // await openFootingDetailsDialogFromCache(
    //   footingGroupId: groupId,
    //   docs: cached,
    // );

    // ✅ Option B: if you prefer live fetch instead, use this:
    await openFootingDetailsDialog(
      measurementsRef: measurementsRef,
      footingGroupId: groupId,
      projectId: projectId,
      buildingId: buildingId,
      drawingId: drawingId,
    );

    return true;
  }

