  Future<void> handleCalibrateTap(
    Offset pos,
    Map<String, dynamic> drawingData,
  ) async {
    debugPrint(
      '🎯 handleCalibrateTap pos=$pos calibP1=$calibP1 calibP2=$calibP2',
    );
    debugPrint('drawingid: $drawingId');

    // 1) Collect points
    if (calibP1 == null) {
      calibP1 = pos;
      calibP2 = null;
      update(['viewer', 'viewr']);
      debugPrint('📍 Set calibP1=$calibP1');
      return;
    }

    if (calibP2 == null) {
      calibP2 = pos;
      update(['viewer', 'viewr']);
      debugPrint('📍 Set calibP2=$calibP2');
    } else {
      calibP1 = pos;
      calibP2 = null;
      update(['viewer', 'viewr']);
      debugPrint('🔁 Reset: new calibP1=$calibP1');
      return;
    }

    if (calibP1 == null || calibP2 == null) return;

    // 2) Compute pixel distance
    final p1 = calibP1!;
    final p2 = calibP2!;
    final dx = p2.dx - p1.dx;
    final dy = p2.dy - p1.dy;
    final pixelDistanceBase = math.sqrt(dx * dx + dy * dy);

    debugPrint('📏 pixelDistanceBase=$pixelDistanceBase');

    if (pixelDistanceBase <= 0.00001) {
      Get.snackbar(
        'Calibration',
        'Points are too close. Tap two different points.',
      );
      clearCalibrationDraft();
      return;
    }

    // 3) Ask user for real distance
    final controller = TextEditingController();
    bool dialogBuilt = false;

    final ok =
        await Get.dialog<bool>(
          Builder(
            builder: (ctx) {
              dialogBuilt = true;
              return AlertDialog(
                title: const Text('Set scale'),
                content: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const Text(
                      'Enter the real distance (m) between the two points.',
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: controller,
                      autofocus: true,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      decoration: const InputDecoration(
                        labelText: 'Real distance (m)',
                      ),
                    ),
                  ],
                ),
                actions: [
                  TextButton(
                    onPressed: () => Get.back(result: false),
                    child: const Text('Cancel'),
                  ),
                  FilledButton(
                    onPressed: () => Get.back(result: true),
                    child: const Text('Save'),
                  ),
                ],
              );
            },
          ),
          barrierDismissible: false,
        ) ??
        false;

    debugPrint('🧾 dialogBuilt=$dialogBuilt ok=$ok input="${controller.text}"');

    if (!dialogBuilt) {
      // This means Get.dialog never rendered => overlay/context issue
      Get.snackbar(
        'Calibration',
        'Dialog did not open. Check GetMaterialApp / overlay context.',
      );
      clearCalibrationDraft();
      return;
    }

    if (!ok) {
      clearCalibrationDraft();
      return;
    }

    // 4) Validate real distance
    final realDist = double.tryParse(controller.text.trim());
    if (realDist == null || realDist <= 0) {
      Get.snackbar('Invalid', 'Enter a valid positive distance in meters.');
      clearCalibrationDraft();
      return;
    }

    final pxPerM = pixelDistanceBase / realDist;
    debugPrint('✅ pxPerM=$pxPerM');

    // 5) Save to Firestore (with error reporting)
    try {
      await drawingRef.update({
        'calibrated': true,
        'unit': 'm',
        'pixelsPerUnit': pxPerM,
        'scaleText':
            'Calibrated: ~${pxPerM.toStringAsFixed(2)} px per meter (image base)',
        'updatedAt': FieldValue.serverTimestamp(),
      });

      // Update local map (helps immediate UI if UI reads this map)
      drawingData['calibrated'] = true;
      drawingData['unit'] = 'm';
      drawingData['pixelsPerUnit'] = pxPerM;
      drawingData['scaleText'] =
          'Calibrated: ~${pxPerM.toStringAsFixed(2)} px per meter (image base)';

      update(['viewer', 'viewr', 'topbar']);
      Get.snackbar('Saved', 'Scale calibrated successfully');
    } catch (e, st) {
      debugPrint('❌ drawingRef.update failed: $e\n$st');
      Get.snackbar(
        'Save failed',
        e.toString(),
        snackPosition: SnackPosition.BOTTOM,
      );
    } finally {
      clearCalibrationDraft(notify: false);
      update(['viewer', 'viewr', 'topbar']);
    }
  }

  Future<void> saveMeasurement({
    required Offset p1,
    required Offset p2,
    required double? lengthMeters,
    double? overrideHeightM,
  }) async {
    if ((activeBoqCode ?? '').trim().isEmpty) return;

    final unit = activeUnit ?? 'm';
    final walling = isWallingActive;

    double? quantity;
    double? heightForThis;

    if (lengthMeters != null) {
      switch (unit) {
        case 'm':
          quantity = lengthMeters;
          break;
        case 'm2':
          if (walling) {
            heightForThis = overrideHeightM ?? activeHeightM;
            if (heightForThis != null && heightForThis > 0) {
              quantity = lengthMeters * heightForThis;
            }
          } else {
            quantity = lengthMeters;
          }
          break;
        case 'item':
        case 'ps':
          quantity = 1.0;
          break;
        case 'm3':
        case 'kg':
          quantity = lengthMeters;
          break;
        default:
          quantity = lengthMeters;
          break;
      }
    }

    await measurementsRef.add({
      'projectId': projectId,
      'drawingId': drawingId,
      'buildingId': buildingId,
      'type': 'length',
      'measureType':
          activeMeasureType ?? inferMeasureTypeFromLabel(activeLabel ?? ''),
      'unit': unit,
      'value': quantity,
      'baseLengthM': lengthMeters,
      'heightM': heightForThis,
      'label': activeLabel,
      'boqCode': activeBoqCode,
      'color': currentColor.value,
      'p1': {'x': p1.dx, 'y': p1.dy},
      'p2': {'x': p2.dx, 'y': p2.dy},
      'createdAt': FieldValue.serverTimestamp(),
    });
  }

  Future<BeamSaveAction> openBeamCompositeDialog({
    required Offset p1,
    required Offset p2,
    required Map<String, dynamic> drawingData,
    required double baseLengthM,
    List<Map<String, dynamic>>? polylineSegments,
    String? activeLabel,
    String? initialFormError,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return BeamSaveAction.cancel;

    // ---------------- helpers (remember defaults) ----------------
    TextEditingController nCtrl(String key, String fallback) {
      final v = lastBeamDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    bool bCtrl(String key, bool fallback) {
      final v = lastBeamDefaults[key];
      if (v is bool) return v;
      if (v is num) return v != 0;
      if (v is String) {
        final s = v.trim().toLowerCase();
        return s == 'true' || s == '1' || s == 'yes' || s == 'y';
      }
      return fallback;
    }

    double parseD(TextEditingController c, double fallback) =>
        double.tryParse(c.text.trim()) ?? fallback;

    int parseI(TextEditingController c, int fallback) =>
        int.tryParse(c.text.trim()) ?? fallback;

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    InputDecoration deco(String label) => InputDecoration(
      labelText: label,
      border: const OutlineInputBorder(),
      isDense: true,
    );

    Future<void> pickBoq(
      BuildContext context,
      void Function(BoqPick p) apply,
      StateSetter setState,
    ) async {
      final pick = await showBoqPickerDialog(context: context);
      if (pick == null) return;
      setState(() => apply(pick));
    }

    Widget boqLine(
      String title,
      BoqPick? pick,
      VoidCallback onPick, {
      VoidCallback? onClear,
      String? quantityText,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  title,
                  style: const TextStyle(fontWeight: FontWeight.w800),
                ),
              ),
              if ((quantityText ?? '').isNotEmpty)
                Text(
                  quantityText!,
                  style: const TextStyle(
                    color: Color(0xFF155EEF),
                    fontWeight: FontWeight.w900,
                  ),
                ),
            ],
          ),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              if (onClear != null) ...[
                const SizedBox(width: 8),
                OutlinedButton(onPressed: onClear, child: const Text('Clear')),
              ],
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    // ---------------- remembered defaults (except length) ----------------
    final beamNameCtrl = nCtrl('beamName', (activeLabel ?? 'Beam').trim());
    final beamTypeCtrl = nCtrl('beamType', 'B1');

    // ✅ DO NOT REMEMBER LENGTH
    final lengthCtrl = TextEditingController(
      text: baseLengthM.toStringAsFixed(3),
    );

    // geometry + qty
    final widthCtrl = nCtrl('beamWidthM', '0.23');
    final depthCtrl = nCtrl('beamDepthM', '0.45');
    final qtyCtrl = nCtrl('qty', '1');
    final factorCtrl = nCtrl('buildingFactor', '1');

    bool isRingBeam = bCtrl('isRingBeam', false);

    // concrete & formwork BOQs remembered
    BoqPick? boqConcrete = pickFromMap(lastBeamDefaults['boqConcrete']);
    BoqPick? boqFwkSides = pickFromMap(lastBeamDefaults['boqFwkSides']);
    bool includePlasterSides = bCtrl('includePlasterSides', false);
    bool includePaintSides = bCtrl('includePaintSides', false);
    BoqPick? boqPlasterSides = pickFromMap(lastBeamDefaults['boqPlasterSides']);
    BoqPick? boqPaintSides = pickFromMap(lastBeamDefaults['boqPaintSides']);

    // Remember the last rebar groups, but do not create automatic defaults.
    final List<BeamMainRebarGroup> mainGroups = [];
    final savedMainGroups = lastBeamDefaults['mainRebarGroups'];
    if (savedMainGroups is List) {
      for (final value in savedMainGroups) {
        if (value is Map) {
          mainGroups.add(
            BeamMainRebarGroup.fromMap(Map<String, dynamic>.from(value)),
          );
        }
      }
    }

    // Remember the last stirrup zones, but do not create automatic defaults.
    final List<BeamStirrupZone> stirZones = [];
    final savedStirrupZones = lastBeamDefaults['stirrupZones'];
    if (savedStirrupZones is List) {
      for (final value in savedStirrupZones) {
        if (value is Map) {
          stirZones.add(
            BeamStirrupZone.fromMap(Map<String, dynamic>.from(value)),
          );
        }
      }
    }

    String? formError = initialFormError;

    void restoreLastEntries(StateSetter setState) {
      if (lastBeamDefaults.isEmpty) return;

      setState(() {
        beamNameCtrl.text =
            (lastBeamDefaults['beamName'] ?? beamNameCtrl.text).toString();
        beamTypeCtrl.text =
            (lastBeamDefaults['beamType'] ?? beamTypeCtrl.text).toString();
        widthCtrl.text =
            (lastBeamDefaults['beamWidthM'] ?? widthCtrl.text).toString();
        depthCtrl.text =
            (lastBeamDefaults['beamDepthM'] ?? depthCtrl.text).toString();
        qtyCtrl.text = (lastBeamDefaults['qty'] ?? qtyCtrl.text).toString();
        factorCtrl.text =
            (lastBeamDefaults['buildingFactor'] ?? factorCtrl.text).toString();
        isRingBeam = bCtrl('isRingBeam', false);

        boqConcrete = pickFromMap(lastBeamDefaults['boqConcrete']);
        boqFwkSides = pickFromMap(lastBeamDefaults['boqFwkSides']);
        includePlasterSides = bCtrl('includePlasterSides', false);
        includePaintSides = bCtrl('includePaintSides', false);
        boqPlasterSides = pickFromMap(lastBeamDefaults['boqPlasterSides']);
        boqPaintSides = pickFromMap(lastBeamDefaults['boqPaintSides']);

        mainGroups.clear();
        final rememberedMainGroups = lastBeamDefaults['mainRebarGroups'];
        if (rememberedMainGroups is List) {
          for (final value in rememberedMainGroups) {
            if (value is Map) {
              mainGroups.add(
                BeamMainRebarGroup.fromMap(Map<String, dynamic>.from(value)),
              );
            }
          }
        }

        stirZones.clear();
        final rememberedStirrupZones = lastBeamDefaults['stirrupZones'];
        if (rememberedStirrupZones is List) {
          for (final value in rememberedStirrupZones) {
            if (value is Map) {
              stirZones.add(
                BeamStirrupZone.fromMap(Map<String, dynamic>.from(value)),
              );
            }
          }
        }

        formError = null;
      });
    }

    // ---------- dialogs to edit groups/zones ----------
    Future<BeamMainRebarGroup?> _editMainGroup({
      BeamMainRebarGroup? existing,
    }) async {
      const standardGroupNames = ['Top', 'Bottom', 'Extra', 'Side'];
      var groupName = existing?.name ?? standardGroupNames.first;
      final groupNames = <String>[
        ...standardGroupNames,
        if (!standardGroupNames.contains(groupName)) groupName,
      ];
      final diaCtrl = TextEditingController(text: '${existing?.diaMm ?? 16}');
      final barsCtrl = TextEditingController(text: '${existing?.bars ?? 2}');
      final embedCtrl = TextEditingController(
        text: '${existing?.embedEachEndM ?? 0.30}',
      );
      final lapCtrl = TextEditingController(
        text: '${existing?.lapExtraM ?? 0.0}',
      );
      BoqPick? bq = existing?.boq;

      final r = await Get.dialog<BeamMainRebarGroup>(
        AlertDialog(
          title: Text(
            existing == null ? 'Add main rebar group' : 'Edit main rebar group',
          ),
          content: SizedBox(
            width: 520,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                DropdownButtonFormField<String>(
                  initialValue: groupName,
                  decoration: deco('Group name'),
                  items: [
                    for (final name in groupNames)
                      DropdownMenuItem(value: name, child: Text(name)),
                  ],
                  onChanged: (value) {
                    if (value != null) groupName = value;
                  },
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: diaCtrl,
                        keyboardType: TextInputType.number,
                        decoration: deco('Dia (mm)'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        controller: barsCtrl,
                        keyboardType: TextInputType.number,
                        decoration: deco('No. of bars'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: embedCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: deco('Embed each end (m)'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        controller: lapCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: deco('Extra (laps/hooks) (m)'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                StatefulBuilder(
                  builder: (c, ss) {
                    final dia = int.tryParse(diaCtrl.text.trim()) ?? 0;
                    final bars = int.tryParse(barsCtrl.text.trim()) ?? 0;
                    final embed = double.tryParse(embedCtrl.text.trim()) ?? 0;
                    final lap = double.tryParse(lapCtrl.text.trim()) ?? 0;
                    final beamLength = parseD(lengthCtrl, baseLengthM);
                    final totalBeams =
                        parseI(qtyCtrl, 1).clamp(1, 999999) *
                        parseI(factorCtrl, 1).clamp(1, 999999);
                    final kg =
                        dia > 0 && bars > 0
                            ? bars *
                                (beamLength + 2 * embed + lap) *
                                totalBeams *
                                rebarUnitWeightKgPerM(dia)
                            : 0.0;
                    return boqLine(
                      'BOQ for this main group (kg)',
                      bq,
                      () => pickBoq(c, (p) => bq = p, ss),
                      onClear: () => ss(() => bq = null),
                      quantityText: '${kg.toStringAsFixed(2)} kg',
                    );
                  },
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Get.back(result: null),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final dia = int.tryParse(diaCtrl.text.trim()) ?? 0;
                final bars = int.tryParse(barsCtrl.text.trim()) ?? 0;
                final embed = double.tryParse(embedCtrl.text.trim()) ?? 0.0;
                final lap = double.tryParse(lapCtrl.text.trim()) ?? 0.0;

                if (dia <= 0 || bars <= 0) {
                  Get.snackbar('Invalid', 'Enter valid dia and bar count.');
                  return;
                }
                if (bq == null) {
                  Get.snackbar('Missing', 'Pick BOQ for this rebar group.');
                  return;
                }

                Get.back(
                  result: BeamMainRebarGroup(
                    name: groupName,
                    diaMm: dia,
                    bars: bars,
                    embedEachEndM: embed,
                    lapExtraM: lap,
                    boq: bq,
                  ),
                );
              },
              child: const Text('Save'),
            ),
          ],
        ),
        barrierDismissible: false,
      );

      diaCtrl.dispose();
      barsCtrl.dispose();
      embedCtrl.dispose();
      lapCtrl.dispose();
      return r;
    }

    Future<BeamStirrupZone?> _editStirZone({BeamStirrupZone? existing}) async {
      const standardZoneNames = ['Full length', 'Ends', 'Mid'];
      var zoneName = existing?.name ?? standardZoneNames.first;
      final zoneNames = <String>[
        ...standardZoneNames,
        if (!standardZoneNames.contains(zoneName)) zoneName,
      ];
      final diaCtrl = TextEditingController(text: '${existing?.diaMm ?? 10}');
      final spacingCtrl = TextEditingController(
        text: '${existing?.spacingM ?? 0.20}',
      );
      final coverCtrl = TextEditingController(
        text: '${existing?.coverM ?? 0.04}',
      );
      final hookCtrl = TextEditingController(
        text: '${existing?.hookExtraM ?? 0.20}',
      );
      final zoneLenCtrl = TextEditingController(
        text: '${existing?.zoneLengthM ?? 0.0}',
      );
      BoqPick? bq = existing?.boq;

      final r = await Get.dialog<BeamStirrupZone>(
        AlertDialog(
          title: Text(
            existing == null ? 'Add stirrup zone' : 'Edit stirrup zone',
          ),
          content: SizedBox(
            width: 520,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                DropdownButtonFormField<String>(
                  initialValue: zoneName,
                  decoration: deco('Zone name'),
                  items: [
                    for (final name in zoneNames)
                      DropdownMenuItem(value: name, child: Text(name)),
                  ],
                  onChanged: (value) {
                    if (value != null) zoneName = value;
                  },
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: diaCtrl,
                        keyboardType: TextInputType.number,
                        decoration: deco('Dia (mm)'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        controller: spacingCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: deco('Spacing (m)'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: coverCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: deco('Cover (m)'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: TextField(
                        controller: hookCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: deco('Hooks add (m)'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                TextField(
                  controller: zoneLenCtrl,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: deco('Zone length (m) (0 = full beam length)'),
                ),
                const SizedBox(height: 10),
                StatefulBuilder(
                  builder: (c, ss) {
                    final dia = int.tryParse(diaCtrl.text.trim()) ?? 0;
                    final spacing =
                        double.tryParse(spacingCtrl.text.trim()) ?? 0;
                    final cover = double.tryParse(coverCtrl.text.trim()) ?? 0;
                    final hook = double.tryParse(hookCtrl.text.trim()) ?? 0;
                    final beamLength = parseD(lengthCtrl, baseLengthM);
                    final zoneLength =
                        double.tryParse(zoneLenCtrl.text.trim()) ?? 0;
                    final usedZoneLength =
                        zoneLength <= 0 ? beamLength : zoneLength;
                    final clearB = (parseD(widthCtrl, 0.23) - 2 * cover).clamp(
                      0.0,
                      double.infinity,
                    );
                    final clearH = (parseD(depthCtrl, 0.45) - 2 * cover).clamp(
                      0.0,
                      double.infinity,
                    );
                    final stirrupLength = 2 * (clearB + clearH) + hook;
                    final count =
                        spacing > 0 ? (usedZoneLength / spacing).ceil() + 1 : 0;
                    final totalBeams =
                        parseI(qtyCtrl, 1).clamp(1, 999999) *
                        parseI(factorCtrl, 1).clamp(1, 999999);
                    final kg =
                        dia > 0 && count > 0
                            ? stirrupLength *
                                count *
                                totalBeams *
                                rebarUnitWeightKgPerM(dia)
                            : 0.0;
                    return boqLine(
                      'BOQ for this stirrup zone (kg)',
                      bq,
                      () => pickBoq(c, (p) => bq = p, ss),
                      onClear: () => ss(() => bq = null),
                      quantityText: '${kg.toStringAsFixed(2)} kg',
                    );
                  },
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Get.back(result: null),
              child: const Text('Cancel'),
            ),
            FilledButton(
              onPressed: () {
                final dia = int.tryParse(diaCtrl.text.trim()) ?? 0;
                final spacing = double.tryParse(spacingCtrl.text.trim()) ?? 0.0;
                final cover = double.tryParse(coverCtrl.text.trim()) ?? 0.0;
                final hook = double.tryParse(hookCtrl.text.trim()) ?? 0.0;
                final zlen = double.tryParse(zoneLenCtrl.text.trim()) ?? 0.0;

                if (dia <= 0 || spacing <= 0) {
                  Get.snackbar('Invalid', 'Enter valid dia and spacing.');
                  return;
                }
                if (bq == null) {
                  Get.snackbar('Missing', 'Pick BOQ for this stirrup zone.');
                  return;
                }

                Get.back(
                  result: BeamStirrupZone(
                    name: zoneName,
                    diaMm: dia,
                    spacingM: spacing,
                    coverM: cover,
                    hookExtraM: hook,
                    zoneLengthM: zlen,
                    boq: bq,
                  ),
                );
              },
              child: const Text('Save'),
            ),
          ],
        ),
        barrierDismissible: false,
      );

      diaCtrl.dispose();
      spacingCtrl.dispose();
      coverCtrl.dispose();
      hookCtrl.dispose();
      zoneLenCtrl.dispose();
      return r;
    }

    // ---------------- dialog UI + live totals ----------------
    final BeamSaveAction action =
        await Get.dialog<BeamSaveAction>(
          StatefulBuilder(
            builder: (dialogCtx, setState) {
              final lenM = parseD(lengthCtrl, baseLengthM).clamp(0.0, 1e9);
              final b = parseD(widthCtrl, 0.23).clamp(0.0, 1e9);
              final h = parseD(depthCtrl, 0.45).clamp(0.0, 1e9);

              final qtyEach = parseI(qtyCtrl, 1).clamp(1, 999999);
              final factor = parseI(factorCtrl, 1).clamp(1, 999999);
              final qtyTotal = qtyEach * factor;

              final concM3 = b * h * lenM * qtyTotal;
              final sidesM2 = 2 * h * lenM * qtyTotal;
              final soffitM2 = isRingBeam ? (b * lenM * qtyTotal) : 0.0;
              final finishAreaM2 = sidesM2 + soffitM2;

              final hasSelectedBoq =
                  boqConcrete != null ||
                  boqFwkSides != null ||
                  boqPlasterSides != null ||
                  boqPaintSides != null ||
                  mainGroups.any((group) => group.boq != null) ||
                  stirZones.any((zone) => zone.boq != null);

              String? validateForm() {
                if (lenM <= 0 || b <= 0 || h <= 0) {
                  return 'Enter a valid beam length, width, and depth.';
                }
                if (boqConcrete == null || boqFwkSides == null) {
                  return 'Select BOQ items for concrete and formwork sides.';
                }
                if (includePlasterSides && boqPlasterSides == null) {
                  return 'Select a BOQ item for plaster to the beam surfaces or untick it.';
                }
                if (includePaintSides && boqPaintSides == null) {
                  return 'Select a BOQ item for painting to the beam surfaces or untick it.';
                }
                if (mainGroups.isEmpty) {
                  return 'Add at least one main rebar group.';
                }
                final mainWithoutBoq = mainGroups.where(
                  (group) => group.boq == null,
                );
                if (mainWithoutBoq.isNotEmpty) {
                  return 'Select a BOQ item for main rebar group “${mainWithoutBoq.first.name}”.';
                }
                if (stirZones.isEmpty) {
                  return 'Add at least one stirrup zone.';
                }
                final zoneWithoutBoq = stirZones.where(
                  (zone) => zone.boq == null,
                );
                if (zoneWithoutBoq.isNotEmpty) {
                  return 'Select a BOQ item for stirrup zone “${zoneWithoutBoq.first.name}”.';
                }
                return null;
              }

              void submit(BeamSaveAction action) {
                final error = validateForm();
                if (error != null) {
                  setState(() => formError = error);
                  return;
                }
                Get.back(result: action);
              }

              // main groups totals
              double mainKgAll = 0.0;
              final mainPreview = <String>[];
              for (final g in mainGroups) {
                final barLenOne = lenM + 2 * g.embedEachEndM + g.lapExtraM;
                final totalLen = g.bars * barLenOne * qtyTotal;
                final uw = rebarUnitWeightKgPerM(g.diaMm);
                final kg = totalLen * uw;
                mainKgAll += kg;
                mainPreview.add(
                  '${g.name}: ${g.bars}Y${g.diaMm} → ${kg.toStringAsFixed(2)} kg'
                  '${(g.boq?.code ?? '').trim().isNotEmpty ? ' (BOQ ${g.boq!.code})' : ''}',
                );
              }

              // stirrup zones totals
              double stirKgAll = 0.0;
              final stirPreview = <String>[];
              for (final z in stirZones) {
                final clearB = (b - 2 * z.coverM).clamp(0.0, 1e9);
                final clearH = (h - 2 * z.coverM).clamp(0.0, 1e9);
                final stirLenOne = 2 * (clearB + clearH) + z.hookExtraM;

                final zoneLen = (z.zoneLengthM <= 0) ? lenM : z.zoneLengthM;
                final count = (zoneLen / z.spacingM).ceil() + 1;

                final totalLen = stirLenOne * count * qtyTotal;
                final uw = rebarUnitWeightKgPerM(z.diaMm);
                final kg = totalLen * uw;

                stirKgAll += kg;
                stirPreview.add(
                  '${z.name}: Y${z.diaMm} @${z.spacingM.toStringAsFixed(3)}m'
                  ' (zone ${zoneLen.toStringAsFixed(2)}m)'
                  ' → ${kg.toStringAsFixed(2)} kg'
                  '${(z.boq?.code ?? '').trim().isNotEmpty ? ' (BOQ ${z.boq!.code})' : ''}',
                );
              }

