  Future<void> openSlabCompositeFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,
  }) async {
    if (polygon.length < 3) return;

    // =========================
    // ✅ calibration
    // =========================
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('$v') ?? fb;
    }

    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0.0);

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar('Not calibrated', 'Calibrate drawing to measure slab.');
      return;
    }

    // =========================
    // ✅ geometry helpers
    // =========================
    double polygonAreaPx2(List<Offset> pts) {
      double sum = 0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        sum += (a.dx * b.dy) - (b.dx * a.dy);
      }
      return (sum / 2.0).abs();
    }

    double edgeLenM(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      final px = math.sqrt(dx * dx + dy * dy);
      return px / pxPerM;
    }

    final areaPx2 = polygonAreaPx2(polygon);
    final polygonAreaM2 = areaPx2 / (pxPerM * pxPerM);

    // bounding box spans (computed)
    double minX = polygon.first.dx, maxX = polygon.first.dx;
    double minY = polygon.first.dy, maxY = polygon.first.dy;
    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }
    final computedLm = (maxX - minX) / pxPerM;
    final computedBm = (maxY - minY) / pxPerM;

    // edges list for selection (based on actual polygon)
    final edges = <EdgeSel>[];
    for (int i = 0; i < polygon.length; i++) {
      final a = polygon[i];
      final b = polygon[(i + 1) % polygon.length];
      edges.add(EdgeSel(index: i, lengthM: edgeLenM(a, b)));
    }

    // polygon data for firestore
    Map<String, dynamic> _pt(Offset p) => {'x': p.dx, 'y': p.dy};
    final polyData = polygon.map(_pt).toList();

    // =========================
    // ✅ remembered defaults helpers
    // =========================
    TextEditingController _ctrlNum(String key, String fallback) {
      final v = lastSlabDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    TextEditingController _ctrlText(String key) {
      final v = lastSlabDefaults[key];
      return TextEditingController(text: (v == null) ? '' : '$v');
    }

    double _d(TextEditingController c, [double fb = 0.0]) =>
        double.tryParse(c.text.trim()) ?? fb;

    int _i(TextEditingController c, [int fb = 1]) =>
        int.tryParse(c.text.trim()) ?? fb;

    // =========================
    // ✅ remember-rebar-signature BOQ
    // =========================
    String rebarKey({
      required int diaMm,
      required double spacingMm,
      required String direction,
      required String position,
    }) {
      final sp = spacingMm.round(); // mm
      final dir = (direction == 'alongB') ? 'alongB' : 'alongL';
      final pos =
          (position == 'top' || position == 'center') ? position : 'bottom';
      return '${diaMm}Y@${sp}|$dir|$pos';
    }

    final Map<String, Map<String, String>> rebarBoqByKey =
        (() {
          final raw = lastSlabDefaults['rebarBoqByKey'];
          if (raw is Map) {
            final out = <String, Map<String, String>>{};
            raw.forEach((k, v) {
              if (k == null) return;
              if (v is Map) {
                out['$k'] = {
                  'code': (v['code'] ?? '').toString(),
                  'desc': (v['desc'] ?? '').toString(),
                };
              }
            });
            return out;
          }
          return <String, Map<String, String>>{};
        })();

    // =========================
    // ✅ controllers (DON’T dispose until dialog really closes)
    // =========================
    final buildingFactorCtrl = _ctrlNum('buildingFactor', '1');

    // show computed L/W but user can override
    final lengthCtrl = TextEditingController(
      text: computedLm.toStringAsFixed(3),
    );
    final widthCtrl = TextEditingController(
      text: computedBm.toStringAsFixed(3),
    );

    // thickness only needed for concrete/edge
    final thicknessCtrl = _ctrlNum('thicknessM', '0.15');
    final qtyCtrl = _ctrlNum('qty', '1'); // slabs per building

    final useLWArea = ValueNotifier<bool>(
      (lastSlabDefaults['useLWArea'] is bool)
          ? lastSlabDefaults['useLWArea'] as bool
          : true,
    );
    final concreteMeasureUnit = ValueNotifier<String>(
      lastSlabDefaults['concreteMeasureUnit'] == 'm2' ? 'm2' : 'm3',
    );

    // ✅ OPTIONS: QS can save only rebars
    final includeConcrete = ValueNotifier<bool>(
      (lastSlabDefaults['includeConcrete'] is bool)
          ? lastSlabDefaults['includeConcrete'] as bool
          : true,
    );
    final includeSoffit = ValueNotifier<bool>(
      (lastSlabDefaults['includeSoffit'] is bool)
          ? lastSlabDefaults['includeSoffit'] as bool
          : true,
    );
    final includeEdgeFormwork = ValueNotifier<bool>(
      (lastSlabDefaults['includeEdge'] is bool)
          ? lastSlabDefaults['includeEdge'] as bool
          : true,
    );
    final includeSoffitPlaster = ValueNotifier<bool>(
      (lastSlabDefaults['includeSoffitPlaster'] is bool)
          ? lastSlabDefaults['includeSoffitPlaster'] as bool
          : false,
    );
    final includeSoffitPaint = ValueNotifier<bool>(
      (lastSlabDefaults['includeSoffitPaint'] is bool)
          ? lastSlabDefaults['includeSoffitPaint'] as bool
          : false,
    );
    final includeRebars = ValueNotifier<bool>(
      (lastSlabDefaults['includeRebars'] is bool)
          ? lastSlabDefaults['includeRebars'] as bool
          : true,
    );
    final isConcreteBed = ValueNotifier<bool>(
      lastSlabDefaults['isConcreteBed'] == true,
    );
    final includeBedFabric = ValueNotifier<bool>(true);
    final includeBedEdge = ValueNotifier<bool>(true);

    // BOQ fields
    final boqConcreteCtrl = _ctrlText('boqConcreteCode');
    final boqConcreteDescCtrl = _ctrlText('boqConcreteDesc');

    final boqSoffitCtrl = _ctrlText('boqSoffitCode');
    final boqSoffitDescCtrl = _ctrlText('boqSoffitDesc');

    final boqEdgeCtrl = _ctrlText('boqEdgeCode');
    final boqEdgeDescCtrl = _ctrlText('boqEdgeDesc');

    final boqPlasterCtrl = _ctrlText('boqPlasterCode');
    final boqPlasterDescCtrl = _ctrlText('boqPlasterDesc');

    final boqPaintCtrl = _ctrlText('boqPaintCode');
    final boqPaintDescCtrl = _ctrlText('boqPaintDesc');
    final boqBedFabricCtrl = _ctrlText('boqBedFabricCode');
    final boqBedFabricDescCtrl = _ctrlText('boqBedFabricDesc');
    final boqBedEdgeCtrl = _ctrlText('boqBedEdgeCode');
    final boqBedEdgeDescCtrl = _ctrlText('boqBedEdgeDesc');

    // restore exposed edges
    final exposedIdx =
        (lastSlabDefaults['exposedEdges'] is List)
            ? List<int>.from(lastSlabDefaults['exposedEdges'] as List)
            : <int>[];
    for (final e in edges) {
      e.exposed = exposedIdx.contains(e.index);
    }

    // slab group id (kept across segments)
    draftSlabGroupId ??= measurementsRef.doc().id;
    final slabGroupId = draftSlabGroupId!;

    // =========================
    // ✅ rebar lines (editable list)
    // =========================
    final List<Map<String, dynamic>> rebarLines = [];

    final savedRebars =
        (lastSlabDefaults['rebars'] is List)
            ? List<Map<String, dynamic>>.from(
              lastSlabDefaults['rebars'] as List,
            )
            : <Map<String, dynamic>>[];

    for (final rb in savedRebars) {
      final id = (rb['id'] ?? '').toString().trim();
      if (id.isEmpty) continue;

      final dia = (rb['diaMm'] is num) ? (rb['diaMm'] as num).toInt() : 12;
      final spacing =
          (rb['spacingMm'] is num)
              ? (rb['spacingMm'] as num).toDouble()
              : double.tryParse('${rb['spacingMm']}') ?? 150.0;

      final direction = (rb['direction'] ?? 'alongL').toString();
      final position = (rb['position'] ?? 'bottom').toString();
      final mark = (rb['mark'] ?? '').toString();

      String code = (rb['boqCode'] ?? '').toString();
      String desc = (rb['boqDesc'] ?? '').toString();

      if (code.trim().isEmpty) {
        final key = rebarKey(
          diaMm: dia,
          spacingMm: spacing,
          direction: direction,
          position: position,
        );
        final mem = rebarBoqByKey[key];
        if (mem != null) {
          code = (mem['code'] ?? '').trim();
          desc = (mem['desc'] ?? '').trim();
        }
      }

      rebarLines.add({
        'id': id,
        'diaMm': dia,
        'spacingMm': spacing,
        'direction': direction,
        'position': position,
        'mark': mark,
        'boqCode': code,
        'boqDesc': desc,
      });
    }

    // =========================
    // ✅ pick BOQ helpers
    // =========================
    Future<void> pickBoqInto(
      BuildContext ctx,
      TextEditingController code,
      TextEditingController desc,
    ) async {
      final picked = await showBoqPickerDialog(context: ctx);
      if (picked == null) return;
      code.text = (picked.code ?? '').toString().trim();
      desc.text = (picked.description ?? '').toString().trim();
    }

    Future<void> pickBoqForRebarLine(
      BuildContext ctx,
      StateSetter setStateDialog,
      Map<String, dynamic> r,
    ) async {
      final picked = await showBoqPickerDialog(context: ctx);
      if (picked == null) return;

      setStateDialog(() {
        r['boqCode'] = (picked.code ?? '').toString().trim();
        r['boqDesc'] = (picked.description ?? '').toString().trim();

        final key = rebarKey(
          diaMm: (r['diaMm'] as int),
          spacingMm: (r['spacingMm'] as double),
          direction: (r['direction'] ?? 'alongL').toString(),
          position: (r['position'] ?? 'bottom').toString(),
        );
        rebarBoqByKey[key] = {
          'code': r['boqCode'].toString().trim(),
          'desc': r['boqDesc'].toString().trim(),
        };
      });
    }

    void autoSwapRebarBoqIfRemembered(
      StateSetter setStateDialog,
      Map<String, dynamic> r,
    ) {
      final key = rebarKey(
        diaMm: (r['diaMm'] as int),
        spacingMm: (r['spacingMm'] as double),
        direction: (r['direction'] ?? 'alongL').toString(),
        position: (r['position'] ?? 'bottom').toString(),
      );
      final mem = rebarBoqByKey[key];
      if (mem == null) return;

      setStateDialog(() {
        r['boqCode'] = (mem['code'] ?? '').trim();
        r['boqDesc'] = (mem['desc'] ?? '').trim();
      });
    }

    void addRebarLine(
      StateSetter setStateDialog, {
      required int diaMm,
      required double spacingMm,
      required String direction,
      required String position,
      required String mark,
    }) {
      if (diaMm <= 0) return;
      if (spacingMm <= 0) {
        Get.snackbar('Invalid', 'Spacing must be > 0');
        return;
      }

      final id = 'rb-${DateTime.now().microsecondsSinceEpoch}';

      final key = rebarKey(
        diaMm: diaMm,
        spacingMm: spacingMm,
        direction: direction,
        position: position,
      );
      final mem = rebarBoqByKey[key];

      setStateDialog(() {
        rebarLines.add({
          'id': id,
          'diaMm': diaMm,
          'spacingMm': spacingMm,
          'direction': direction,
          'position': position,
          'mark': mark.trim(),
          'boqCode': (mem?['code'] ?? '').trim(),
          'boqDesc': (mem?['desc'] ?? '').trim(),
        });
      });
    }

    // =========================
    // ✅ compute rebar helper
    // =========================
    Map<String, double> computeRebarLine({
      required double Lm,
      required double Bm,
      required Map<String, dynamic> r,
    }) {
      final dia = (r['diaMm'] as int);
      final spacingMm = (r['spacingMm'] as double);
      final dir = (r['direction'] ?? 'alongL').toString();

      final clearSpan = (dir == 'alongL') ? Lm : Bm; // bar length
      final across = (dir == 'alongL') ? Bm : Lm; // count dimension

      final acrossMm = across * 1000.0;
      final nBars = (spacingMm > 0) ? ((acrossMm / spacingMm).floor() + 1) : 0;

      final totalLenM = nBars * clearSpan;
      final uw = rebarUnitWeightKgPerM(dia);
      final totalKg = totalLenM * uw;

      return {
        'bars': nBars.toDouble(),
        'barLen': clearSpan,
        'len': totalLenM,
        'kg': totalKg,
        'uw': uw,
      };
    }

    // =========================
    // ✅ progress + commit + verify
    // =========================
    Future<bool> commitBatchWithVerify({
      required WriteBatch batch,
      required List<DocumentReference<Map<String, dynamic>>> verifyRefs,
      required String successMessage,
    }) async {
      Get.dialog(
        const AlertDialog(
          content: SizedBox(
            height: 80,
            child: Row(
              children: [
                CircularProgressIndicator(),
                SizedBox(width: 16),
                Expanded(child: Text('Saving… please wait')),
              ],
            ),
          ),
        ),
        barrierDismissible: false,
      );

      try {
        await batch.commit();

        for (final ref in verifyRefs) {
          final snap = await ref.get();
          if (!snap.exists) {
            throw Exception('Save verification failed: ${ref.path} not found.');
          }
        }

        if (Get.isDialogOpen == true) Get.back();
        Get.snackbar('Saved', successMessage);
        return true;
      } catch (e, st) {
        if (Get.isDialogOpen == true) Get.back();
        debugPrint('❌ SAVE FAILED: $e\n$st');
        Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
        return false;
      }
    }

    // =========================
    // ✅ ADD-REBAR entry state (MUST be outside builder to not reset!)
    // =========================
    final diaOptions = <int>[8, 10, 12, 16, 20, 25, 32];

    int addDia =
        (lastSlabDefaults['lastRebarDia'] is num)
            ? (lastSlabDefaults['lastRebarDia'] as num).toInt()
            : 12;
    if (!diaOptions.contains(addDia)) addDia = 12;

    double addSpacing =
        (lastSlabDefaults['lastRebarSpacingMm'] is num)
            ? (lastSlabDefaults['lastRebarSpacingMm'] as num).toDouble()
            : 150.0;

    String addDir = (lastSlabDefaults['lastRebarDir'] ?? 'alongL').toString();
    if (addDir != 'alongB') addDir = 'alongL';

    String addPos = (lastSlabDefaults['lastRebarPos'] ?? 'bottom').toString();
    if (addPos != 'top' && addPos != 'center') addPos = 'bottom';

    final addSpacingCtrl = TextEditingController(
      text: addSpacing.toStringAsFixed(0),
    );
    final addMarkCtrl = TextEditingController(
      text: (lastSlabDefaults['lastRebarMark'] ?? '').toString(),
    );

    // =========================
    // ✅ dialog + save inside (so controllers are alive until closed)
    // =========================
    bool didClose = false;
    int selectedSlabTab = 0;
    bool activeSlabModuleExpanded = true;

    Future<void> disposeAll() async {
      if (didClose) return;
      didClose = true;

      buildingFactorCtrl.dispose();
      lengthCtrl.dispose();
      widthCtrl.dispose();
      thicknessCtrl.dispose();
      qtyCtrl.dispose();

      boqConcreteCtrl.dispose();
      boqConcreteDescCtrl.dispose();
      boqSoffitCtrl.dispose();
      boqSoffitDescCtrl.dispose();
      boqEdgeCtrl.dispose();
      boqEdgeDescCtrl.dispose();
      boqPlasterCtrl.dispose();
      boqPlasterDescCtrl.dispose();
      boqPaintCtrl.dispose();
      boqPaintDescCtrl.dispose();
      boqBedFabricCtrl.dispose();
      boqBedFabricDescCtrl.dispose();
      boqBedEdgeCtrl.dispose();
      boqBedEdgeDescCtrl.dispose();

      addSpacingCtrl.dispose();
      addMarkCtrl.dispose();

      useLWArea.dispose();
      concreteMeasureUnit.dispose();
      includeConcrete.dispose();
      includeSoffit.dispose();
      includeEdgeFormwork.dispose();
      includeSoffitPlaster.dispose();
      includeSoffitPaint.dispose();
      includeRebars.dispose();
      isConcreteBed.dispose();
      includeBedFabric.dispose();
      includeBedEdge.dispose();
    }

    Future<void> attemptSave(
      BuildContext dialogContext,
      StateSetter setStateDialog,
      SlabSaveAction action,
    ) async {
      // --- read current inputs ---
      final Lm = _d(lengthCtrl, computedLm);
      final Bm = _d(widthCtrl, computedBm);

      final factor = _i(buildingFactorCtrl, 1).clamp(1, 999999);
      final qty = _i(qtyCtrl, 1).clamp(1, 999999);

      final needThickness =
          isConcreteBed.value ||
          includeConcrete.value ||
          includeEdgeFormwork.value;
      final t = needThickness ? _d(thicknessCtrl, 0.0) : 0.0;

      // --- validate basics for what is selected ---
      if (Lm <= 0 || Bm <= 0) {
        Get.snackbar('Invalid', 'Enter valid Length and Width.');
        return; // keep dialog open
      }

      if (needThickness && t <= 0) {
        Get.snackbar('Invalid', 'Thickness is required for concrete/edge.');
        return;
      }

      if (!isConcreteBed.value && includeConcrete.value) {
        if (concreteMeasureUnit.value == 'm2' && t >= 0.15) {
          Get.snackbar(
            'Concrete measurement unit',
            'Square-metre measurement is available only below 150 mm thickness.',
          );
          return;
        }
        if (concreteMeasureUnit.value == 'm3' && t < 0.15) {
          Get.snackbar(
            'Concrete measurement unit',
            'Slabs below 150 mm must be measured in square metres.',
          );
          return;
        }
      }

      if (isConcreteBed.value && t >= 0.15) {
        Get.snackbar(
          'Concrete bed thickness',
          'Concrete bed measured in m² must be less than 150 mm thick.',
        );
        return;
      }

      if (isConcreteBed.value) {
        if (boqConcreteCtrl.text.trim().isEmpty ||
            (includeBedFabric.value && boqBedFabricCtrl.text.trim().isEmpty) ||
            (includeBedEdge.value && boqBedEdgeCtrl.text.trim().isEmpty)) {
          Get.snackbar(
            'BOQ item required',
            'Pick a BOQ item for every selected concrete bed quantity.',
          );
          return;
        }
      }

      // BOQ validations per selected item
      if (!isConcreteBed.value &&
          includeConcrete.value &&
          boqConcreteCtrl.text.trim().isEmpty) {
        Get.snackbar('Missing', 'Pick concrete BOQ or untick concrete.');
        return;
      }
      if (!isConcreteBed.value &&
          includeSoffit.value &&
          boqSoffitCtrl.text.trim().isEmpty) {
        Get.snackbar('Missing', 'Pick soffit formwork BOQ or untick it.');
        return;
      }
      if (!isConcreteBed.value &&
          includeEdgeFormwork.value &&
          boqEdgeCtrl.text.trim().isEmpty) {
        Get.snackbar('Missing', 'Pick edge formwork BOQ or untick it.');
        return;
      }
      if (!isConcreteBed.value &&
          includeSoffitPlaster.value &&
          boqPlasterCtrl.text.trim().isEmpty) {
        Get.snackbar('Missing', 'Pick soffit plaster BOQ or untick it.');
        return;
      }
      if (!isConcreteBed.value &&
          includeSoffitPaint.value &&
          boqPaintCtrl.text.trim().isEmpty) {
        Get.snackbar('Missing', 'Pick soffit paint BOQ or untick it.');
        return;
      }

      if (!isConcreteBed.value && includeRebars.value) {
        if (rebarLines.isEmpty) {
          Get.snackbar('Rebars', 'Add at least 1 rebar line before saving.');
          return;
        }
        for (final r in rebarLines) {
          if ((r['boqCode'] ?? '').toString().trim().isEmpty) {
            Get.snackbar('Missing', 'Pick BOQ for every rebar line.');
            return;
          }
        }
      }

      // area used for calc
      final calcAreaM2 = useLWArea.value ? (Lm * Bm) : polygonAreaM2;

      // exposed edge len
      final exposedEdgeLen = edges
          .where((e) => e.exposed)
          .fold<double>(0, (s, e) => s + e.lengthM);
      final bedEdgeLen = edges.fold<double>(0, (s, e) => s + e.lengthM);

      // per slab
      final concreteOne =
          (includeConcrete.value && t > 0)
              ? (concreteMeasureUnit.value == 'm2'
                  ? calcAreaM2
                  : calcAreaM2 * t)
              : 0.0;
      final soffitM2One = calcAreaM2;
      final edgeUsesLinearMetres = t <= 0.15;
      final edgeM2One =
          includeEdgeFormwork.value
              ? (edgeUsesLinearMetres ? exposedEdgeLen : exposedEdgeLen * t)
              : 0.0;

      // per building
      final concretePerBuilding = concreteOne * qty;
      final soffitM2PerBuilding =
          includeSoffit.value ? (soffitM2One * qty) : 0.0;
      final edgeM2PerBuilding =
          includeEdgeFormwork.value ? (edgeM2One * qty) : 0.0;
      final plasterM2PerBuilding =
          includeSoffitPlaster.value ? (soffitM2One * qty) : 0.0;
      final paintM2PerBuilding =
          includeSoffitPaint.value ? (soffitM2One * qty) : 0.0;

      // totals (x factor)
      final totalSlabs = qty * factor;
      final concreteAll = concretePerBuilding * factor;
      final soffitM2All = soffitM2PerBuilding * factor;
      final edgeM2All = edgeM2PerBuilding * factor;
      final plasterM2All = plasterM2PerBuilding * factor;
      final paintM2All = paintM2PerBuilding * factor;

      // rebar totals
      double rebarKgOne = 0.0;
      if (includeRebars.value) {
        for (final r in rebarLines) {
          final c = computeRebarLine(Lm: Lm, Bm: Bm, r: r);
          rebarKgOne += (c['kg'] ?? 0.0);
        }
      }
      final rebarKgPerBuilding = rebarKgOne * qty;
      final rebarKgAll = rebarKgPerBuilding * factor;

      // ---------------- SAVE ----------------
      final segmentId = measurementsRef.doc().id;
      final now = FieldValue.serverTimestamp();

      Map<String, dynamic> common() => {
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'measureType': 'compositeSlab',
        'polygon': polyData,
        'color': currentColor.value,

        'slabGroupId': slabGroupId,
        'segmentId': segmentId,

        'createdAt': now,
        'updatedAt': now,

        // factor fields
        'buildingFactor': factor,
        'qtyPerBuilding': qty,
        'totalQty': totalSlabs,

        // geometry
        'polygonAreaM2_one': polygonAreaM2,
        'useLWArea': useLWArea.value,
        'lengthM': Lm,
        'widthM': Bm,
      };

      final batch = FirebaseFirestore.instance.batch();
      int ops = 0;

      void bset(String id, Map<String, dynamic> data) {
        batch.set(measurementsRef.doc(id), data);
        ops++;
      }

      if (isConcreteBed.value) {
        final bedAreaOne = calcAreaM2;
        final bedAreaPerBuilding = bedAreaOne * qty;
        final bedAreaAll = bedAreaPerBuilding * factor;
        final bedEdgeOne = bedEdgeLen;
        final bedEdgePerBuilding = bedEdgeOne * qty;
        final bedEdgeAll = bedEdgePerBuilding * factor;

        bset('$segmentId-bed-conc', {
          ...common(),
          'type': 'concreteBed',
          'unit': 'm2',
          'value': bedAreaAll,
          'valuePerBuilding': bedAreaPerBuilding,
          'valueOne': bedAreaOne,
          'areaM2_one': bedAreaOne,
          'thicknessM': t,
          'label': '${activeLabel ?? 'Slab'} - Concrete bed',
          'boqCode': boqConcreteCtrl.text.trim(),
          'boqDescription': boqConcreteDescCtrl.text.trim(),
        });

        if (includeBedFabric.value) {
          bset('$segmentId-bed-fabric', {
            ...common(),
            'type': 'concreteBedFabricMesh',
            'unit': 'm2',
            'value': bedAreaAll,
            'valuePerBuilding': bedAreaPerBuilding,
            'valueOne': bedAreaOne,
            'areaM2_one': bedAreaOne,
            'label': '${activeLabel ?? 'Slab'} - Fabric reinforcement mesh',
            'boqCode': boqBedFabricCtrl.text.trim(),
            'boqDescription': boqBedFabricDescCtrl.text.trim(),
          });
        }

        if (includeBedEdge.value && bedEdgeAll > 0) {
          bset('$segmentId-bed-edge', {
            ...common(),
            'type': 'concreteBedEdge',
            'unit': 'm',
            'value': bedEdgeAll,
            'valuePerBuilding': bedEdgePerBuilding,
            'valueOne': bedEdgeOne,
            'edgeLengthM_one': bedEdgeOne,
            'label': '${activeLabel ?? 'Slab'} - Edge of concrete bed',
            'boqCode': boqBedEdgeCtrl.text.trim(),
            'boqDescription': boqBedEdgeDescCtrl.text.trim(),
          });
        }
      }

      // concrete
      if (!isConcreteBed.value && includeConcrete.value && concreteAll > 0) {
        bset('$segmentId-conc', {
          ...common(),
          'type': 'slabConcrete',
          'unit': concreteMeasureUnit.value,
          'value': concreteAll,
          'valuePerBuilding': concretePerBuilding,
          'valueOne': concreteOne,
          'areaM2_one': calcAreaM2,
          'thicknessM': t,
          'label': '${activeLabel ?? 'Slab'} - Concrete',
          'boqCode': boqConcreteCtrl.text.trim(),
          'boqDescription': boqConcreteDescCtrl.text.trim(),
        });
      }

      // soffit formwork
      if (!isConcreteBed.value && includeSoffit.value && soffitM2All > 0) {
        bset('$segmentId-sof', {
          ...common(),
          'type': 'slabSoffitFormwork',
          'unit': 'm2',
          'value': soffitM2All,
          'valuePerBuilding': soffitM2PerBuilding,
          'valueOne': soffitM2One,
          'areaM2_one': calcAreaM2,
          'label': '${activeLabel ?? 'Slab'} - Soffit formwork',
          'boqCode': boqSoffitCtrl.text.trim(),
          'boqDescription': boqSoffitDescCtrl.text.trim(),
        });
      }

      // soffit plaster
      if (!isConcreteBed.value &&
          includeSoffitPlaster.value &&
          plasterM2All > 0) {
        bset('$segmentId-plast', {
          ...common(),
          'type': 'slabSoffitPlaster',
          'unit': 'm2',
          'value': plasterM2All,
          'valuePerBuilding': plasterM2PerBuilding,
          'valueOne': soffitM2One,
          'areaM2_one': calcAreaM2,
          'label': '${activeLabel ?? 'Slab'} - Soffit plaster',
          'boqCode': boqPlasterCtrl.text.trim(),
          'boqDescription': boqPlasterDescCtrl.text.trim(),
        });
      }

      // soffit paint
      if (!isConcreteBed.value && includeSoffitPaint.value && paintM2All > 0) {
        bset('$segmentId-paint', {
          ...common(),
          'type': 'slabSoffitPaint',
          'unit': 'm2',
          'value': paintM2All,
          'valuePerBuilding': paintM2PerBuilding,
          'valueOne': soffitM2One,
          'areaM2_one': calcAreaM2,
          'label': '${activeLabel ?? 'Slab'} - Soffit paint/decoration',
          'boqCode': boqPaintCtrl.text.trim(),
          'boqDescription': boqPaintDescCtrl.text.trim(),
        });
      }

      // edge formwork
      if (!isConcreteBed.value && includeEdgeFormwork.value && edgeM2All > 0) {
        bset('$segmentId-edge', {
          ...common(),
          'type': 'slabEdgeFormwork',
          'unit': edgeUsesLinearMetres ? 'm' : 'm2',
          'value': edgeM2All,
          'valuePerBuilding': edgeM2PerBuilding,
          'valueOne': edgeM2One,
          'exposedEdgeLenM_one': exposedEdgeLen,
          'thicknessM': t,
          'label': '${activeLabel ?? 'Slab'} - Edge formwork',
          'boqCode': boqEdgeCtrl.text.trim(),
          'boqDescription': boqEdgeDescCtrl.text.trim(),
        });
      }

      // rebars (multiple docs)
      if (!isConcreteBed.value && includeRebars.value) {
        int rbIdx = 0;
        for (final r in rebarLines) {
          rbIdx++;

          final dia = (r['diaMm'] as int);
          final spacingMm = (r['spacingMm'] as double);
          final dir = (r['direction'] ?? 'alongL').toString();
          final pos = (r['position'] ?? 'bottom').toString();
          final mark = (r['mark'] ?? '').toString();

          final c = computeRebarLine(Lm: Lm, Bm: Bm, r: r);
          final nBars = (c['bars'] ?? 0).round();
          final barLen = (c['barLen'] ?? 0.0);
          final lenPerSlab = (c['len'] ?? 0.0);
          final wtPerSlab = (c['kg'] ?? 0.0);
          final uw = (c['uw'] ?? rebarUnitWeightKgPerM(dia));

          final wtPerBuilding = wtPerSlab * qty;
          final lenPerBuilding = lenPerSlab * qty;

          final wtAll = wtPerBuilding * factor;
          final lenAll = lenPerBuilding * factor;

          bset('$segmentId-rb-$rbIdx', {
            ...common(),
            'type': 'rebarSlab',
            'unit': 'kg',
            'value': wtAll,
            'valuePerBuilding': wtPerBuilding,
            'valueOne': wtPerSlab,

            'lengthAllM': lenAll,
            'lengthPerBuildingM': lenPerBuilding,
            'lengthOneM': lenPerSlab,

            'diameterMm': dia,
            'spacingMm': spacingMm,
            'direction': dir,
            'position': pos,
            'mark': mark,

            'barsPerSlab': nBars,
            'barLengthM': barLen,
            'unitWeightKgPerM': uw,

            'label': '${activeLabel ?? 'Slab'} - Rebar',
            'boqCode': (r['boqCode'] ?? '').toString().trim(),
            'boqDescription': (r['boqDesc'] ?? '').toString().trim(),
          });
        }
      }

      // ✅ nothing selected / no ops
      if (ops == 0) {
        Get.snackbar(
          'Nothing to save',
          'Select at least one item and ensure it has data.',
        );
        return;
      }

      // ✅ verify at least one written doc
      final verifyRefs = <DocumentReference<Map<String, dynamic>>>[];
      if (isConcreteBed.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-bed-conc'));
      } else if (includeRebars.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-rb-1'));
      } else if (includeConcrete.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-conc'));
      } else if (includeSoffit.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-sof'));
      } else if (includeEdgeFormwork.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-edge'));
      } else if (includeSoffitPlaster.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-plast'));
      } else if (includeSoffitPaint.value) {
        verifyRefs.add(measurementsRef.doc('$segmentId-paint'));
      }

      debugPrint(
        '✅ saving to measurementsRef.path=${measurementsRef.path} segmentId=$segmentId ops=$ops',
      );

      final ok = await commitBatchWithVerify(
        batch: batch,
        verifyRefs: verifyRefs,
        successMessage: 'Slab saved successfully.',
      );

      if (!ok) return; // keep dialog open

      // ✅ remember defaults ONLY AFTER real save
      lastSlabDefaults = {
        'buildingFactor': factor,
        'useLWArea': useLWArea.value,
        'thicknessM': _d(thicknessCtrl, 0.15),
        'concreteMeasureUnit': concreteMeasureUnit.value,
        'qty': qty,
        'isConcreteBed': isConcreteBed.value,

        'includeConcrete': includeConcrete.value,
        'includeSoffit': includeSoffit.value,
        'includeEdge': includeEdgeFormwork.value,
        'includeSoffitPlaster': includeSoffitPlaster.value,
        'includeSoffitPaint': includeSoffitPaint.value,
        'includeRebars': includeRebars.value,

        'boqConcreteCode': boqConcreteCtrl.text.trim(),
        'boqConcreteDesc': boqConcreteDescCtrl.text.trim(),
        'boqSoffitCode': boqSoffitCtrl.text.trim(),
        'boqSoffitDesc': boqSoffitDescCtrl.text.trim(),
        'boqEdgeCode': boqEdgeCtrl.text.trim(),
        'boqEdgeDesc': boqEdgeDescCtrl.text.trim(),
        'boqPlasterCode': boqPlasterCtrl.text.trim(),
        'boqPlasterDesc': boqPlasterDescCtrl.text.trim(),
        'boqPaintCode': boqPaintCtrl.text.trim(),
        'boqPaintDesc': boqPaintDescCtrl.text.trim(),
        'boqBedFabricCode': boqBedFabricCtrl.text.trim(),
        'boqBedFabricDesc': boqBedFabricDescCtrl.text.trim(),
        'boqBedEdgeCode': boqBedEdgeCtrl.text.trim(),
        'boqBedEdgeDesc': boqBedEdgeDescCtrl.text.trim(),

        'exposedEdges':
            edges.where((e) => e.exposed).map((e) => e.index).toList(),

        'rebarBoqByKey': rebarBoqByKey,

        'rebars':
            rebarLines
                .map(
                  (r) => {
                    'id': r['id'],
                    'diaMm': r['diaMm'],
                    'spacingMm': r['spacingMm'],
                    'direction': r['direction'],
                    'position': r['position'],
                    'mark': r['mark'],
                    'boqCode': r['boqCode'],
                    'boqDesc': r['boqDesc'],
                  },
                )
                .toList(),

        'lastRebarDia': addDia,
        'lastRebarSpacingMm':
            double.tryParse(addSpacingCtrl.text.trim()) ?? addSpacing,
        'lastRebarDir': addDir,
        'lastRebarPos': addPos,
        'lastRebarMark': addMarkCtrl.text,
      };

      // group handling
      if (action == SlabSaveAction.finish) {
        draftSlabGroupId = null;
      }

      update(['viewer', 'overlay']);

      // Close this slab dialog explicitly after a successful save. Using the
      // dialog context avoids accidentally targeting a transient progress or
      // notification route.
      if (dialogContext.mounted) {
        Navigator.of(
          dialogContext,
          rootNavigator: true,
        ).pop<SlabSaveAction>(SlabSaveAction.finish);
      }
    }

    // =========================
    // ✅ SHOW DIALOG
    // =========================
    final result = await Get.dialog<SlabSaveAction>(
      StatefulBuilder(
        builder: (dCtx, setStateDialog) {
          final Lm = _d(lengthCtrl, computedLm);
          final Bm = _d(widthCtrl, computedBm);

          final factor = _i(buildingFactorCtrl, 1).clamp(1, 999999);
          final qty = _i(qtyCtrl, 1).clamp(1, 999999);

          final calcAreaM2 = useLWArea.value ? (Lm * Bm) : polygonAreaM2;

          final exposedEdgeLen = edges
              .where((e) => e.exposed)
              .fold<double>(0, (s, e) => s + e.lengthM);
          final bedEdgeLen = edges.fold<double>(0, (s, e) => s + e.lengthM);

          final needThickness =
              isConcreteBed.value ||
              includeConcrete.value ||
              includeEdgeFormwork.value;
          final t = needThickness ? _d(thicknessCtrl, 0.0) : 0.0;

          // preview totals (only for selected)
          final concreteOne =
              (includeConcrete.value && t > 0)
                  ? (concreteMeasureUnit.value == 'm2'
                      ? calcAreaM2
                      : calcAreaM2 * t)
                  : 0.0;
          final concreteAll = concreteOne * qty * factor;

          final soffitM2All =
              includeSoffit.value ? (calcAreaM2 * qty * factor) : 0.0;
          final edgeM2All =
              (includeEdgeFormwork.value && t > 0)
                  ? (exposedEdgeLen * t * qty * factor)
                  : 0.0;
          final plasterM2All =
              includeSoffitPlaster.value ? (calcAreaM2 * qty * factor) : 0.0;
          final paintM2All =
              includeSoffitPaint.value ? (calcAreaM2 * qty * factor) : 0.0;
          final bedAreaAll = calcAreaM2 * qty * factor;
          final bedEdgeAll = bedEdgeLen * qty * factor;

          double rebarKgAll = 0.0;
          if (includeRebars.value) {
            double one = 0.0;
            for (final r in rebarLines) {
              one += (computeRebarLine(Lm: Lm, Bm: Bm, r: r)['kg'] ?? 0.0);
            }
            rebarKgAll = one * qty * factor;
          }

          final normalConcreteUnitValid =
              !includeConcrete.value ||
              (t > 0 &&
                  ((concreteMeasureUnit.value == 'm2' && t < 0.15) ||
                      (concreteMeasureUnit.value == 'm3' && t >= 0.15)));
          final normalBoqsReady =
              normalConcreteUnitValid &&
              (!includeConcrete.value ||
                  boqConcreteCtrl.text.trim().isNotEmpty) &&
              (!includeSoffit.value || boqSoffitCtrl.text.trim().isNotEmpty) &&
              (!includeEdgeFormwork.value ||
                  boqEdgeCtrl.text.trim().isNotEmpty) &&
              (!includeSoffitPlaster.value ||
                  boqPlasterCtrl.text.trim().isNotEmpty) &&
              (!includeSoffitPaint.value ||
                  boqPaintCtrl.text.trim().isNotEmpty) &&
              (!includeRebars.value ||
                  (rebarLines.isNotEmpty &&
                      rebarLines.every(
                        (r) =>
                            (r['boqCode'] ?? '').toString().trim().isNotEmpty,
                      ))) &&
              (includeConcrete.value ||
                  includeSoffit.value ||
                  includeEdgeFormwork.value ||
                  includeSoffitPlaster.value ||
                  includeSoffitPaint.value ||
                  includeRebars.value);
          final bedBoqsReady =
              t > 0 &&
              t < 0.15 &&
              boqConcreteCtrl.text.trim().isNotEmpty &&
              (!includeBedFabric.value ||
                  boqBedFabricCtrl.text.trim().isNotEmpty) &&
              (!includeBedEdge.value || boqBedEdgeCtrl.text.trim().isNotEmpty);
          final canSave =
              Lm > 0 &&
              Bm > 0 &&
              (isConcreteBed.value ? bedBoqsReady : normalBoqsReady);

          Widget slabMetric(String label, String value, IconData icon) {
            return Container(
              constraints: const BoxConstraints(minWidth: 140),
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
              decoration: BoxDecoration(
                color: const Color(0xFFF8FAFC),
                borderRadius: BorderRadius.circular(16),
                border: Border.all(color: const Color(0xFFE4E7EC)),
              ),
              child: Row(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Icon(icon, color: const Color(0xFF155EEF), size: 18),
                  const SizedBox(width: 8),
                  Flexible(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          label,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: Color(0xFF667085),
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                        const SizedBox(height: 3),
                        Text(
                          value,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: Color(0xFF101828),
                            fontSize: 14,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          }

          Widget slabPanel({
            required String title,
            required String subtitle,
            required IconData icon,
            required Widget child,
            bool expanded = true,
            VoidCallback? onToggle,
          }) {
            return Container(
              width: double.infinity,
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: const Color(0xFFE4E7EC)),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x0A101828),
                    blurRadius: 18,
                    offset: Offset(0, 10),
                  ),
                ],
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 38,
                        height: 38,
                        decoration: BoxDecoration(
                          gradient: const LinearGradient(
                            colors: [Color(0xFF155EEF), Color(0xFF0B3B8F)],
                            begin: Alignment.topLeft,
                            end: Alignment.bottomRight,
                          ),
                          borderRadius: BorderRadius.circular(13),
                        ),
                        child: Icon(icon, color: Colors.white, size: 20),
                      ),
                      const SizedBox(width: 11),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              style: const TextStyle(
                                color: Color(0xFF101828),
                                fontSize: 15,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              subtitle,
                              style: const TextStyle(
                                color: Color(0xFF667085),
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                      if (onToggle != null)
                        IconButton(
                          tooltip: expanded ? 'Hide module' : 'Show module',
                          onPressed: onToggle,
                          icon: Icon(
                            expanded
                                ? Icons.keyboard_arrow_up_rounded
                                : Icons.keyboard_arrow_down_rounded,
                            color: const Color(0xFF344054),
                          ),
                        ),
                    ],
                  ),
                  if (expanded) ...[const SizedBox(height: 14), child],
                ],
              ),
            );
          }

          return AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(28),
            ),
            clipBehavior: Clip.antiAlias,
            titlePadding: EdgeInsets.zero,
            contentPadding: const EdgeInsets.fromLTRB(18, 18, 18, 8),
            actionsPadding: const EdgeInsets.fromLTRB(18, 8, 18, 18),
            title: Container(
              padding: const EdgeInsets.fromLTRB(22, 20, 18, 20),
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  colors: [Color(0xFF102A56), Color(0xFF155EEF)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: Row(
                children: [
                  Container(
                    width: 44,
                    height: 44,
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(0.12),
                      borderRadius: BorderRadius.circular(15),
                      border: Border.all(color: Colors.white24),
                    ),
                    child: const Icon(
                      Icons.grid_view_rounded,
                      color: Color(0xFFD6E4FF),
                    ),
                  ),
                  const SizedBox(width: 12),
                  const Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Composite slab',
                          style: TextStyle(
                            color: Colors.white,
                            fontSize: 20,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                        SizedBox(height: 4),
                        Text(
                          'Slab construction and reinforcement in separate workspaces',
                          style: TextStyle(
                            color: Color(0xFFD6E4FF),
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            content: SizedBox(
              width: 900,
              child: SingleChildScrollView(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.all(5),
                      decoration: BoxDecoration(
                        color: const Color(0xFFF2F4F7),
                        borderRadius: BorderRadius.circular(16),
                        border: Border.all(color: const Color(0xFFE4E7EC)),
                      ),
                      child: SegmentedButton<int>(
                        showSelectedIcon: false,
                        expandedInsets: EdgeInsets.zero,
                        segments: const [
                          ButtonSegment<int>(
                            value: 0,
                            icon: Icon(Icons.layers_outlined),
                            label: Text('Slab composite'),
                          ),
                          ButtonSegment<int>(
                            value: 1,
                            icon: Icon(Icons.line_weight_outlined),
                            label: Text('Rebars'),
                          ),
                        ],
                        selected: {selectedSlabTab},
                        onSelectionChanged:
                            (selection) => setStateDialog(() {
                              selectedSlabTab = selection.first;
                              activeSlabModuleExpanded = true;
                            }),
                      ),
                    ),
                    const SizedBox(height: 14),
                    if (selectedSlabTab == 0)
                      Container(
                        decoration: BoxDecoration(
                          color:
                              isConcreteBed.value
                                  ? const Color(0xFFEFF4FF)
                                  : const Color(0xFFF8FAFC),
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(
                            color:
                                isConcreteBed.value
                                    ? const Color(0xFF84ADFF)
                                    : const Color(0xFFE4E7EC),
                          ),
                        ),
                        child: SwitchListTile(
                          value: isConcreteBed.value,
                          onChanged:
                              (value) => setStateDialog(() {
                                isConcreteBed.value = value;
                              }),
                          title: const Text(
                            'Measure as concrete bed',
                            style: TextStyle(fontWeight: FontWeight.w900),
                          ),
                          subtitle: const Text(
                            'For beds under 150 mm: concrete and fabric mesh are measured in m²; perimeter edges are measured in m.',
                          ),
                          secondary: const Icon(Icons.foundation_outlined),
                        ),
                      ),
                    if (selectedSlabTab == 0) const SizedBox(height: 14),
                    slabPanel(
                      title: 'Slab geometry',
                      subtitle:
                          'Confirm polygon area, slab spans, quantity, and thickness',
                      icon: Icons.straighten_outlined,
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Wrap(
                            spacing: 8,
                            runSpacing: 8,
                            children: [
                              slabMetric(
                                'Polygon area',
                                '${polygonAreaM2.toStringAsFixed(3)} m²',
                                Icons.crop_square_rounded,
                              ),
                              slabMetric(
                                'Computed L',
                                '${computedLm.toStringAsFixed(3)} m',
                                Icons.swap_horiz_rounded,
                              ),
                              slabMetric(
                                'Computed W',
                                '${computedBm.toStringAsFixed(3)} m',
                                Icons.swap_vert_rounded,
                              ),
                              slabMetric(
                                isConcreteBed.value
                                    ? 'Bed concrete preview'
                                    : 'Concrete preview',
                                isConcreteBed.value
                                    ? '${bedAreaAll.toStringAsFixed(3)} m²'
                                    : '${concreteAll.toStringAsFixed(3)} ${concreteMeasureUnit.value == 'm2' ? 'm²' : 'm³'}',
                                Icons.view_in_ar_outlined,
                              ),
                            ],
                          ),
                          const SizedBox(height: 14),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: lengthCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    labelText: 'Length L (m)',
                                    border: OutlineInputBorder(),
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setStateDialog(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
