  String? draftColumnGroupId;

  Future<void> openColumnCompositeFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,
  }) async {
    if (polygon.length < 3) return;

    // ---------- calibration ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM =
        (drawingData['pixelsPerUnit'] is num)
            ? (drawingData['pixelsPerUnit'] as num).toDouble()
            : double.tryParse('${drawingData['pixelsPerUnit']}') ?? 0.0;

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar('Not calibrated', 'Calibrate drawing to measure column.');
      return;
    }

    // ---------- geometry ----------
    double polygonAreaPx2(List<Offset> pts) {
      double sum = 0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        sum += (a.dx * b.dy) - (b.dx * a.dy);
      }
      return (sum / 2.0).abs();
    }

    double polygonPerimeterPx(List<Offset> pts) {
      double p = 0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        p += (b - a).distance;
      }
      return p;
    }

    final polyAreaM2 = polygonAreaPx2(polygon) / (pxPerM * pxPerM);
    final polyPerimM = polygonPerimeterPx(polygon) / pxPerM;

    // bounding box for default L/W
    double minX = polygon.first.dx, maxX = polygon.first.dx;
    double minY = polygon.first.dy, maxY = polygon.first.dy;
    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }
    final defaultLm = (maxX - minX) / pxPerM;
    final defaultWm = (maxY - minY) / pxPerM;

    final polyData = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    // ---------- controllers (AUTO remember) ----------
    // Keep on controller:
    // Map<String, dynamic> lastColumnDefaults = {};
    // String? draftColumnGroupId;
    // CollectionReference<Map<String, dynamic>> measurementsRef;

    TextEditingController ctrlNum(String key, String fallback) {
      final v = lastColumnDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    TextEditingController ctrlText(String key, String fallback) {
      final v = lastColumnDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    // ✅ NEW: building factor (remembered)
    final buildingFactorCtrl = ctrlNum('buildingFactor', '1');

    final nameCtrl = ctrlText('name', activeLabel ?? 'Column');
    final legacyHeight = '${lastColumnDefaults['heightM'] ?? '3.00'}';
    final substructureHeightCtrl = ctrlNum('substructureHeightM', '1.50');
    final superstructureHeightCtrl = ctrlNum(
      'superstructureHeightM',
      legacyHeight,
    );
    final qtyCtrl = ctrlNum('qty', '1'); // qty per building

    // ✅ editable plan L/W (override polygon area/perim when BOTH > 0)
    final lengthCtrl = TextEditingController(
      text: defaultLm.toStringAsFixed(3),
    );
    final widthCtrl = TextEditingController(text: defaultWm.toStringAsFixed(3));

    // BOQs
    final boqSubConcCodeCtrl = ctrlText('boqSubConcCode', '');
    final boqSubConcDescCtrl = ctrlText('boqSubConcDesc', '');
    final boqConcCodeCtrl = ctrlText('boqConcCode', '');
    final boqConcDescCtrl = ctrlText('boqConcDesc', '');

    final boqSubFwkCodeCtrl = ctrlText('boqSubFwkCode', '');
    final boqSubFwkDescCtrl = ctrlText('boqSubFwkDesc', '');
    final boqFwkCodeCtrl = ctrlText('boqFwkCode', '');
    final boqFwkDescCtrl = ctrlText('boqFwkDesc', '');

    final boqSubMainRebCodeCtrl = ctrlText('boqSubMainRebCode', '');
    final boqSubMainRebDescCtrl = ctrlText('boqSubMainRebDesc', '');
    final boqMainRebCodeCtrl = ctrlText('boqMainRebCode', '');
    final boqMainRebDescCtrl = ctrlText('boqMainRebDesc', '');

    final boqSubStirCodeCtrl = ctrlText('boqSubStirCode', '');
    final boqSubStirDescCtrl = ctrlText('boqSubStirDesc', '');
    final boqStirCodeCtrl = ctrlText('boqStirCode', '');
    final boqStirDescCtrl = ctrlText('boqStirDesc', '');

    // Optional substructure adjustments. Excavation is measured with the
    // footing; this column workflow can add backfill and/or disposal only.
    var isSubstructureColumn =
        lastColumnDefaults['isSubstructureColumn'] == true;
    var includeColumnBackfill =
        lastColumnDefaults['includeColumnBackfill'] as bool? ?? true;
    var includeColumnDisposal =
        lastColumnDefaults['includeColumnDisposal'] as bool? ?? true;
    final foundationDepthCtrl = ctrlNum('columnFoundationDepthM', '1.50');
    final boqBackfillCodeCtrl = ctrlText('columnBackfillBoqCode', '');
    final boqBackfillDescCtrl = ctrlText('columnBackfillBoqDesc', '');
    final boqDisposalCodeCtrl = ctrlText('columnDisposalBoqCode', '');
    final boqDisposalDescCtrl = ctrlText('columnDisposalBoqDesc', '');

    // main bars inputs
    final mainMarkCtrl = TextEditingController();
    final mainEmbedTopCtrl = ctrlNum('mainEmbedTopM', '0.30');
    final mainEmbedBotCtrl = ctrlNum('mainEmbedBotM', '0.30');
    final mainExtraCtrl = ctrlNum('mainExtraM', '0.00');

    // stirrups inputs
    final stirDiaCtrl = ctrlNum('stirDiaMm', '10'); // mm
    final stirSpacingCtrl = ctrlNum('stirSpacingM', '0.20'); // m
    final stirCoverCtrl = ctrlNum('stirCoverM', '0.04'); // m
    final stirHookCtrl = ctrlNum('stirHookExtraM', '0.20'); // m (total hooks)

    // stored sets (per mark)
    final List<ColumnMainBarSet> mainSets = [];
    var stirrupConfigured = false;
    String? errorText;

    double d(TextEditingController c, [double fallback = 0.0]) =>
        double.tryParse(c.text.trim()) ?? fallback;
    int i(TextEditingController c, [int fallback = 1]) =>
        int.tryParse(c.text.trim()) ?? fallback;

    Future<void> pickBoqInto(
      BuildContext ctx,
      TextEditingController code,
      TextEditingController desc,
    ) async {
      final picked = await showBoqPickerDialog(context: ctx);
      if (picked == null) return;
      code.text = (picked.code ?? '').toString().trim();
      desc.text = (picked.description ?? '').toString().trim();
    }

    Future<void> showMainBarEditor(
      BuildContext context,
      StateSetter refresh,
      double colH, {
      int? index,
    }) async {
      final existing = index == null ? null : mainSets[index];
      mainMarkCtrl.text = existing?.raw ?? '';
      mainEmbedTopCtrl.text = (existing?.embedTopM ?? 0.30).toStringAsFixed(2);
      mainEmbedBotCtrl.text = (existing?.embedBotM ?? 0.30).toStringAsFixed(2);
      mainExtraCtrl.text = (existing?.extraM ?? 0.00).toStringAsFixed(2);
      final groupSubBoqCodeCtrl = TextEditingController(
        text:
            existing?.substructureBoqCode ?? boqSubMainRebCodeCtrl.text.trim(),
      );
      final groupSubBoqDescCtrl = TextEditingController(
        text:
            existing?.substructureBoqDescription ??
            boqSubMainRebDescCtrl.text.trim(),
      );
      final groupSuperBoqCodeCtrl = TextEditingController(
        text: existing?.superstructureBoqCode ?? boqMainRebCodeCtrl.text.trim(),
      );
      final groupSuperBoqDescCtrl = TextEditingController(
        text:
            existing?.superstructureBoqDescription ??
            boqMainRebDescCtrl.text.trim(),
      );
      String? dialogError;

      final saved = await showDialog<bool>(
        context: context,
        barrierDismissible: false,
        builder:
            (dialogContext) => StatefulBuilder(
              builder:
                  (dialogContext, setDialogState) => AlertDialog(
                    title: Text(
                      index == null
                          ? 'Add main rebar group'
                          : 'Edit main rebar group',
                    ),
                    content: SizedBox(
                      width: 620,
                      child: SingleChildScrollView(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            TextField(
                              controller: mainMarkCtrl,
                              decoration: const InputDecoration(
                                labelText: 'Bar mark (e.g. 8Y16)',
                                border: OutlineInputBorder(),
                              ),
                            ),
                            const SizedBox(height: 12),
                            Row(
                              children: [
                                Expanded(
                                  child: TextField(
                                    controller: mainEmbedBotCtrl,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                          decimal: true,
                                        ),
                                    decoration: const InputDecoration(
                                      labelText: 'Embed bottom (m)',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: TextField(
                                    controller: mainEmbedTopCtrl,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                          decimal: true,
                                        ),
                                    decoration: const InputDecoration(
                                      labelText: 'Embed top (m)',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 12),
                                Expanded(
                                  child: TextField(
                                    controller: mainExtraCtrl,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                          decimal: true,
                                        ),
                                    decoration: const InputDecoration(
                                      labelText: 'Extra / laps (m)',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            if (d(substructureHeightCtrl) > 0) ...[
                              const SizedBox(height: 12),
                              Row(
                                children: [
                                  Expanded(
                                    child: TextField(
                                      controller: groupSubBoqCodeCtrl,
                                      readOnly: true,
                                      decoration: const InputDecoration(
                                        labelText: 'Substructure BOQ (kg)',
                                        border: OutlineInputBorder(),
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  OutlinedButton.icon(
                                    onPressed: () async {
                                      await pickBoqInto(
                                        dialogContext,
                                        groupSubBoqCodeCtrl,
                                        groupSubBoqDescCtrl,
                                      );
                                      setDialogState(() {});
                                    },
                                    icon: const Icon(Icons.search, size: 18),
                                    label: const Text('Pick'),
                                  ),
                                ],
                              ),
                              if (groupSubBoqDescCtrl.text
                                  .trim()
                                  .isNotEmpty) ...[
                                const SizedBox(height: 6),
                                Align(
                                  alignment: Alignment.centerLeft,
                                  child: Text(
                                    groupSubBoqDescCtrl.text.trim(),
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Color(0xFF475569),
                                    ),
                                  ),
                                ),
                              ],
                            ],
                            if (d(superstructureHeightCtrl) > 0) ...[
                              const SizedBox(height: 12),
                              Row(
                                children: [
                                  Expanded(
                                    child: TextField(
                                      controller: groupSuperBoqCodeCtrl,
                                      readOnly: true,
                                      decoration: const InputDecoration(
                                        labelText: 'Superstructure BOQ (kg)',
                                        border: OutlineInputBorder(),
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 8),
                                  OutlinedButton.icon(
                                    onPressed: () async {
                                      await pickBoqInto(
                                        dialogContext,
                                        groupSuperBoqCodeCtrl,
                                        groupSuperBoqDescCtrl,
                                      );
                                      setDialogState(() {});
                                    },
                                    icon: const Icon(Icons.search, size: 18),
                                    label: const Text('Pick'),
                                  ),
                                ],
                              ),
                              if (groupSuperBoqDescCtrl.text
                                  .trim()
                                  .isNotEmpty) ...[
                                const SizedBox(height: 6),
                                Align(
                                  alignment: Alignment.centerLeft,
                                  child: Text(
                                    groupSuperBoqDescCtrl.text.trim(),
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Color(0xFF475569),
                                    ),
                                  ),
                                ),
                              ],
                            ],
                            if (dialogError != null) ...[
                              const SizedBox(height: 10),
                              Align(
                                alignment: Alignment.centerLeft,
                                child: Text(
                                  dialogError!,
                                  style: const TextStyle(color: Colors.red),
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(dialogContext, false),
                        child: const Text('Cancel'),
                      ),
                      FilledButton(
                        onPressed: () {
                          try {
                            final parsed = parseColumnMainMark(
                              mainMarkCtrl.text.trim(),
                            );
                            final embedTop = d(mainEmbedTopCtrl);
                            final embedBot = d(mainEmbedBotCtrl);
                            final extra = d(mainExtraCtrl);
                            if (d(substructureHeightCtrl) > 0 &&
                                groupSubBoqCodeCtrl.text.trim().isEmpty) {
                              throw const FormatException(
                                'Select the substructure BOQ for this group.',
                              );
                            }
                            if (d(superstructureHeightCtrl) > 0 &&
                                groupSuperBoqCodeCtrl.text.trim().isEmpty) {
                              throw const FormatException(
                                'Select the superstructure BOQ for this group.',
                              );
                            }
                            final barLength =
                                colH + embedTop + embedBot + extra;
                            final unitWeight = rebarUnitWeightKgPerM(
                              parsed.diameterMm,
                            );
                            final set = ColumnMainBarSet(
                              raw: mainMarkCtrl.text.trim(),
                              quantityBars: parsed.quantity,
                              diameterMm: parsed.diameterMm,
                              heightM: colH,
                              embedTopM: embedTop,
                              embedBotM: embedBot,
                              extraM: extra,
                              barLengthM: barLength,
                              totalLengthM: parsed.quantity * barLength,
                              unitWeightKgPerM: unitWeight,
                              totalWeightKg:
                                  parsed.quantity * barLength * unitWeight,
                              substructureBoqCode:
                                  groupSubBoqCodeCtrl.text.trim(),
                              substructureBoqDescription:
                                  groupSubBoqDescCtrl.text.trim(),
                              superstructureBoqCode:
                                  groupSuperBoqCodeCtrl.text.trim(),
                              superstructureBoqDescription:
                                  groupSuperBoqDescCtrl.text.trim(),
                            );
                            if (index == null) {
                              mainSets.add(set);
                            } else {
                              mainSets[index] = set;
                            }
                            Navigator.pop(dialogContext, true);
                          } catch (e) {
                            setDialogState(
                              () =>
                                  dialogError = e.toString().replaceFirst(
                                    'FormatException: ',
                                    '',
                                  ),
                            );
                          }
                        },
                        child: const Text('Save'),
                      ),
                    ],
                  ),
            ),
      );
      if (saved == true) refresh(() => errorText = null);
      groupSubBoqCodeCtrl.dispose();
      groupSubBoqDescCtrl.dispose();
      groupSuperBoqCodeCtrl.dispose();
      groupSuperBoqDescCtrl.dispose();
    }

    Future<void> showStirrupEditor(
      BuildContext context,
      StateSetter refresh,
    ) async {
      String? dialogError;
      final saved = await showDialog<bool>(
        context: context,
        barrierDismissible: false,
        builder:
            (dialogContext) => StatefulBuilder(
              builder:
                  (dialogContext, setDialogState) => AlertDialog(
                    title: Text(
                      stirrupConfigured
                          ? 'Edit stirrup zone'
                          : 'Add stirrup zone',
                    ),
                    content: SizedBox(
                      width: 620,
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: stirDiaCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'Diameter (mm)',
                                    border: OutlineInputBorder(),
                                  ),
                                ),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: TextField(
                                  controller: stirSpacingCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    labelText: 'Spacing (m)',
                                    border: OutlineInputBorder(),
                                  ),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 12),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: stirCoverCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    labelText: 'Cover (m)',
                                    border: OutlineInputBorder(),
                                  ),
                                ),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: TextField(
                                  controller: stirHookCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: const InputDecoration(
                                    labelText: 'Hooks add (m)',
                                    border: OutlineInputBorder(),
                                  ),
                                ),
                              ),
                            ],
                          ),
                          if (dialogError != null) ...[
                            const SizedBox(height: 10),
                            Align(
                              alignment: Alignment.centerLeft,
                              child: Text(
                                dialogError!,
                                style: const TextStyle(color: Colors.red),
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                    actions: [
                      TextButton(
                        onPressed: () => Navigator.pop(dialogContext, false),
                        child: const Text('Cancel'),
                      ),
                      FilledButton(
                        onPressed: () {
                          if ((int.tryParse(stirDiaCtrl.text.trim()) ?? 0) <=
                                  0 ||
                              d(stirSpacingCtrl) <= 0 ||
                              d(stirCoverCtrl) < 0 ||
                              d(stirHookCtrl) < 0) {
                            setDialogState(
                              () =>
                                  dialogError =
                                      'Enter valid stirrup diameter, spacing, cover, and hooks.',
                            );
                            return;
                          }
                          Navigator.pop(dialogContext, true);
                        },
                        child: const Text('Save'),
                      ),
                    ],
                  ),
            ),
      );
      if (saved == true) refresh(() => stirrupConfigured = true);
    }

    void pasteLastEntries(StateSetter refresh) {
      if (lastColumnDefaults.isEmpty) return;

      void paste(String key, TextEditingController controller) {
        final value = lastColumnDefaults[key];
        if (value != null) controller.text = '$value';
      }

      paste('name', nameCtrl);
      paste('buildingFactor', buildingFactorCtrl);
      paste('qty', qtyCtrl);
      paste('substructureHeightM', substructureHeightCtrl);
      paste('superstructureHeightM', superstructureHeightCtrl);
      paste('columnFoundationDepthM', foundationDepthCtrl);
      paste('columnBackfillBoqCode', boqBackfillCodeCtrl);
      paste('columnBackfillBoqDesc', boqBackfillDescCtrl);
      paste('columnDisposalBoqCode', boqDisposalCodeCtrl);
      paste('columnDisposalBoqDesc', boqDisposalDescCtrl);
      paste('boqSubConcCode', boqSubConcCodeCtrl);
      paste('boqSubConcDesc', boqSubConcDescCtrl);
      paste('boqConcCode', boqConcCodeCtrl);
      paste('boqConcDesc', boqConcDescCtrl);
      paste('boqSubFwkCode', boqSubFwkCodeCtrl);
      paste('boqSubFwkDesc', boqSubFwkDescCtrl);
      paste('boqFwkCode', boqFwkCodeCtrl);
      paste('boqFwkDesc', boqFwkDescCtrl);
      paste('boqSubMainRebCode', boqSubMainRebCodeCtrl);
      paste('boqSubMainRebDesc', boqSubMainRebDescCtrl);
      paste('boqMainRebCode', boqMainRebCodeCtrl);
      paste('boqMainRebDesc', boqMainRebDescCtrl);
      paste('boqSubStirCode', boqSubStirCodeCtrl);
      paste('boqSubStirDesc', boqSubStirDescCtrl);
      paste('boqStirCode', boqStirCodeCtrl);
      paste('boqStirDesc', boqStirDescCtrl);
      paste('stirDiaMm', stirDiaCtrl);
      paste('stirSpacingM', stirSpacingCtrl);
      paste('stirCoverM', stirCoverCtrl);
      paste('stirHookExtraM', stirHookCtrl);

      includeColumnBackfill =
          lastColumnDefaults['includeColumnBackfill'] as bool? ?? true;
      includeColumnDisposal =
          lastColumnDefaults['includeColumnDisposal'] as bool? ?? true;
      stirrupConfigured =
          lastColumnDefaults['stirrupConfigured'] as bool? ?? false;

      mainSets.clear();
      final savedMarks = lastColumnDefaults['mainMarks'];
      if (savedMarks is List) {
        final totalHeight =
            d(substructureHeightCtrl, 0.0) + d(superstructureHeightCtrl, 0.0);
        for (final rawMark in savedMarks.whereType<Map>()) {
          try {
            final raw = '${rawMark['raw'] ?? ''}'.trim();
            final parsed = parseColumnMainMark(raw);
            final embedTop = double.tryParse('${rawMark['embedTopM']}') ?? 0.30;
            final embedBot = double.tryParse('${rawMark['embedBotM']}') ?? 0.30;
            final extra = double.tryParse('${rawMark['extraM']}') ?? 0.0;
            final barLength = totalHeight + embedTop + embedBot + extra;
            final unitWeight = rebarUnitWeightKgPerM(parsed.diameterMm);
            mainSets.add(
              ColumnMainBarSet(
                raw: raw,
                quantityBars: parsed.quantity,
                diameterMm: parsed.diameterMm,
                heightM: totalHeight,
                embedTopM: embedTop,
                embedBotM: embedBot,
                extraM: extra,
                barLengthM: barLength,
                totalLengthM: parsed.quantity * barLength,
                unitWeightKgPerM: unitWeight,
                totalWeightKg: parsed.quantity * barLength * unitWeight,
                substructureBoqCode:
                    '${rawMark['substructureBoqCode'] ?? boqSubMainRebCodeCtrl.text}'
                        .trim(),
                substructureBoqDescription:
                    '${rawMark['substructureBoqDescription'] ?? boqSubMainRebDescCtrl.text}'
                        .trim(),
                superstructureBoqCode:
                    '${rawMark['superstructureBoqCode'] ?? boqMainRebCodeCtrl.text}'
                        .trim(),
                superstructureBoqDescription:
                    '${rawMark['superstructureBoqDescription'] ?? boqMainRebDescCtrl.text}'
                        .trim(),
              ),
            );
          } catch (_) {
            // Ignore a malformed remembered mark without blocking other values.
          }
        }
      }

      refresh(() => errorText = null);
    }

    // group id across multiple columns
    draftColumnGroupId ??= measurementsRef.doc().id;
    final columnGroupId = draftColumnGroupId!;
    final segmentId = measurementsRef.doc().id;

    ColumnSaveAction action;
    do {
      action =
          await Get.dialog<ColumnSaveAction>(
            StatefulBuilder(
              builder: (ctx, setState) {
                final subH = d(substructureHeightCtrl, 0.0);
                final superH = d(superstructureHeightCtrl, 0.0);
                final colH = subH + superH;
                isSubstructureColumn = subH > 0;
                final qtyPerBuilding = i(qtyCtrl, 1).clamp(1, 999999);
                final factor = i(buildingFactorCtrl, 1).clamp(1, 999999);

                final L = d(lengthCtrl, 0.0);
                final W = d(widthCtrl, 0.0);
                final useRectOverride = (L > 0 && W > 0);

                final usedAreaM2 = useRectOverride ? (L * W) : polyAreaM2;
                final usedPerimM = useRectOverride ? (2 * (L + W)) : polyPerimM;

                // concrete + formwork (per column, split by BOQ zone)
                final concSubOne = usedAreaM2 * subH;
                final concSuperOne = usedAreaM2 * superH;
                final fwkSubOne = usedPerimM * subH;
                final fwkSuperOne = usedPerimM * superH;
                final concM3One = concSubOne + concSuperOne;
                final fwkM2One = fwkSubOne + fwkSuperOne;

                // per building
                final concM3PerBuilding = concM3One * qtyPerBuilding;
                final fwkM2PerBuilding = fwkM2One * qtyPerBuilding;

                // total x factor
                final totalQty = qtyPerBuilding * factor;
                final concM3All = concM3PerBuilding * factor;
                final fwkM2All = fwkM2PerBuilding * factor;

                // main bars totals (per column)
                double mainSubKgOne = 0.0;
                double mainSuperKgOne = 0.0;
                for (final s in mainSets) {
                  if (subH > 0) {
                    mainSubKgOne +=
                        s.quantityBars *
                        (subH + s.embedBotM) *
                        s.unitWeightKgPerM;
                  }
                  if (superH > 0) {
                    mainSuperKgOne +=
                        s.quantityBars *
                        (superH + s.embedTopM + s.extraM) *
                        s.unitWeightKgPerM;
                  }
                }
                final mainKgOne = mainSubKgOne + mainSuperKgOne;
                final mainKgPerBuilding = mainKgOne * qtyPerBuilding;
                final mainKgAll = mainKgPerBuilding * factor;

                // stirrups totals (per column)
                final stirDia = int.tryParse(stirDiaCtrl.text.trim()) ?? 10;
                final stirSpacing = d(stirSpacingCtrl, 0.20);
                final stirCover = d(stirCoverCtrl, 0.04);
                final stirHook = d(stirHookCtrl, 0.20);

                // choose plan dims for stirrups: prefer override; else bbox defaults
                final stirL = (L > 0) ? L : defaultLm;
                final stirW = (W > 0) ? W : defaultWm;

                final stirSub =
                    stirrupConfigured && subH > 0
                        ? calcColumnStirrups(
                          colL: stirL,
                          colW: stirW,
                          colH: subH,
                          coverM: stirCover,
                          spacingM: stirSpacing,
                          diaMm: stirDia,
                          hookExtraM: stirHook,
                          unitWeightKgPerM: rebarUnitWeightKgPerM,
                        )
                        : <String, dynamic>{'ok': false};
                final stirSuper =
                    stirrupConfigured && superH > 0
                        ? calcColumnStirrups(
                          colL: stirL,
                          colW: stirW,
                          colH: superH,
                          coverM: stirCover,
                          spacingM: stirSpacing,
                          diaMm: stirDia,
                          hookExtraM: stirHook,
                          unitWeightKgPerM: rebarUnitWeightKgPerM,
                        )
                        : <String, dynamic>{'ok': false};
                final stirSubKgOne =
                    (stirSub['ok'] == true)
                        ? (stirSub['totalKg'] as double)
                        : 0.0;
                final stirSuperKgOne =
                    (stirSuper['ok'] == true)
                        ? (stirSuper['totalKg'] as double)
                        : 0.0;
                final stirCountOne =
                    ((stirSub['count'] as num?)?.toInt() ?? 0) +
                    ((stirSuper['count'] as num?)?.toInt() ?? 0);
                final stirOneLen =
                    (stirSub['oneLenM'] as num?)?.toDouble() ??
                    (stirSuper['oneLenM'] as num?)?.toDouble() ??
                    0.0;
                final stirKgOne = stirSubKgOne + stirSuperKgOne;
                final stirKgPerBuilding = stirKgOne * qtyPerBuilding;
                final stirKgAll = stirKgPerBuilding * factor;
                final foundationDepth = d(foundationDepthCtrl, 0.0);
                final occupiedDepth = foundationDepth.clamp(0.0, subH);
                final occupiedOne = usedAreaM2 * occupiedDepth;
                final backfillOne = -occupiedOne;
                final backfillAll = backfillOne * totalQty;
                final disposalOne = occupiedOne;
                final disposalAll = disposalOne * totalQty;
                final hasAnyBoq =
                    boqSubConcCodeCtrl.text.trim().isNotEmpty ||
                    boqConcCodeCtrl.text.trim().isNotEmpty ||
                    boqSubFwkCodeCtrl.text.trim().isNotEmpty ||
                    boqFwkCodeCtrl.text.trim().isNotEmpty ||
                    mainSets.any(
                      (set) =>
                          set.substructureBoqCode.isNotEmpty ||
                          set.superstructureBoqCode.isNotEmpty,
                    ) ||
                    boqSubStirCodeCtrl.text.trim().isNotEmpty ||
                    boqStirCodeCtrl.text.trim().isNotEmpty;

                InputDecoration deco(String label) => InputDecoration(
                  labelText: label,
                  border: const OutlineInputBorder(),
                  isDense: true,
                );

                Widget columnMetric(String label, String value, IconData icon) {
                  return Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: const Color(0xFFF8FAFC),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(color: const Color(0xFFE2E8F0)),
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 34,
                          height: 34,
                          decoration: BoxDecoration(
                            color: const Color(0xFFEFF6FF),
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Icon(
                            icon,
                            color: const Color(0xFF155EEF),
                            size: 18,
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                value,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  fontSize: 16,
                                  fontWeight: FontWeight.w900,
                                  color: Color(0xFF0F172A),
                                ),
                              ),
                              const SizedBox(height: 2),
                              Text(
                                label,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w700,
                                  color: Color(0xFF64748B),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  );
                }

                Widget columnPanel({
                  required String title,
                  required String subtitle,
                  required IconData icon,
                  required Widget child,
                }) {
                  return Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(18),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(24),
                      border: Border.all(color: const Color(0xFFE2E8F0)),
                      boxShadow: const [
                        BoxShadow(
                          color: Color(0x0A0F172A),
                          blurRadius: 22,
                          offset: Offset(0, 10),
                        ),
                      ],
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Container(
                              width: 42,
                              height: 42,
                              decoration: BoxDecoration(
                                gradient: const LinearGradient(
                                  colors: [
                                    Color(0xFF155EEF),
                                    Color(0xFF3B82F6),
                                  ],
                                ),
                                borderRadius: BorderRadius.circular(15),
                              ),
                              child: Icon(icon, color: Colors.white, size: 22),
                            ),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    title,
                                    style: const TextStyle(
                                      fontSize: 18,
                                      fontWeight: FontWeight.w900,
                                      color: Color(0xFF0F172A),
                                    ),
                                  ),
                                  const SizedBox(height: 2),
                                  Text(
                                    subtitle,
                                    style: const TextStyle(
                                      fontSize: 12,
                                      fontWeight: FontWeight.w600,
                                      color: Color(0xFF64748B),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 16),
                        child,
                      ],
                    ),
                  );
                }

                Widget boqSelector({
                  required String label,
                  required String summary,
                  required TextEditingController code,
                  required TextEditingController desc,
                }) {
                  return Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: const Color(0xFFF8FAFC),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(color: const Color(0xFFE2E8F0)),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: code,
                                readOnly: true,
                                decoration: deco(label),
                              ),
                            ),
                            const SizedBox(width: 8),
                            OutlinedButton.icon(
                              onPressed: () async {
                                await pickBoqInto(ctx, code, desc);
                                setState(() {});
                              },
                              icon: const Icon(Icons.search, size: 18),
                              label: const Text('Pick'),
                            ),
                          ],
                        ),
                        if (desc.text.trim().isNotEmpty) ...[
                          const SizedBox(height: 8),
                          Text(
                            desc.text,
                            style: const TextStyle(
                              fontSize: 12,
                              color: Color(0xFF475569),
                            ),
                          ),
                        ],
                        const SizedBox(height: 8),
                        Text(
                          summary,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF334155),
                          ),
                        ),
                      ],
                    ),
                  );
                }

                return AlertDialog(
                  titlePadding: EdgeInsets.zero,
                  contentPadding: EdgeInsets.zero,
                  actionsPadding: const EdgeInsets.fromLTRB(24, 0, 24, 24),
                  clipBehavior: Clip.antiAlias,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(28),
                  ),
                  title: Container(
                    padding: const EdgeInsets.fromLTRB(28, 26, 28, 24),
                    decoration: const BoxDecoration(
                      gradient: LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [Color(0xFF102A56), Color(0xFF155EEF)],
                      ),
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 54,
                          height: 54,
                          decoration: BoxDecoration(
                            color: Colors.white.withOpacity(0.14),
                            borderRadius: BorderRadius.circular(18),
                            border: Border.all(color: Colors.white24),
                          ),
                          child: const Icon(
                            Icons.view_column_rounded,
                            color: Colors.white,
                            size: 28,
                          ),
                        ),
                        const SizedBox(width: 16),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              const Text(
                                'Column composite',
                                style: TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.w900,
                                  fontSize: 28,
                                ),
                              ),
                              const SizedBox(height: 6),
                              Text(
                                'Concrete, side formwork, main bars and stirrups',
                                style: TextStyle(
                                  color: Colors.white.withOpacity(0.78),
                                  fontSize: 13,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ],
                          ),
                        ),
                        TextButton.icon(
                          onPressed:
                              lastColumnDefaults.isEmpty
                                  ? null
                                  : () => pasteLastEntries(setState),
                          style: TextButton.styleFrom(
                            foregroundColor: Colors.white,
                          ),
                          icon: const Icon(Icons.content_paste_rounded),
                          label: const Text('Paste last entries'),
                        ),
                        const SizedBox(width: 6),
                        IconButton(
                          tooltip: 'Hide temporarily',
                          onPressed:
                              () => Get.back(result: ColumnSaveAction.hide),
                          icon: const Icon(
                            Icons.visibility_off_rounded,
                            color: Colors.white,
                          ),
                        ),
                      ],
                    ),
                  ),
                  content: SizedBox(
                    width: 900,
                    child: SingleChildScrollView(
                      child: Container(
                        color: const Color(0xFFF8FAFC),
                        padding: const EdgeInsets.all(24),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            columnPanel(
                              title: 'Column geometry',
                              subtitle:
                                  'Confirm plan size, height and repeated quantities',
                              icon: Icons.crop_square_rounded,
                              child: Column(
                                children: [
                                  Row(
                                    children: [
                                      Expanded(
                                        child: columnMetric(
                                          'Polygon area',
                                          '${polyAreaM2.toStringAsFixed(3)} m²',
                                          Icons.polyline_rounded,
                                        ),
                                      ),
                                      const SizedBox(width: 12),
                                      Expanded(
                                        child: columnMetric(
                                          'Used area',
                                          '${usedAreaM2.toStringAsFixed(3)} m²',
                                          Icons.square_foot_rounded,
                                        ),
                                      ),
                                      const SizedBox(width: 12),
                                      Expanded(
                                        child: columnMetric(
                                          'Total columns',
                                          '$totalQty',
                                          Icons.functions_rounded,
                                        ),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 16),
                                  TextField(
                                    controller: nameCtrl,
                                    decoration: deco('Column name/label'),
                                    onChanged: (_) => setState(() {}),
                                  ),
                                  const SizedBox(height: 12),
                                  TextField(
                                    controller: buildingFactorCtrl,
                                    keyboardType: TextInputType.number,
                                    decoration: deco(
                                      'Building factor (x1, x2, x3...)',
                                    ),
                                    onChanged: (_) => setState(() {}),
                                  ),
                                  const SizedBox(height: 12),
                                  Row(
                                    children: [
                                      Expanded(
                                        child: TextField(
                                          controller: lengthCtrl,
                                          keyboardType:
                                              const TextInputType.numberWithOptions(
                                                decimal: true,
                                              ),
                                          decoration: deco('Plan Length L (m)'),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                      ),
                                      const SizedBox(width: 12),
                                      Expanded(
                                        child: TextField(
                                          controller: widthCtrl,
                                          keyboardType:
                                              const TextInputType.numberWithOptions(
                                                decimal: true,
                                              ),
                                          decoration: deco('Plan Width W (m)'),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 8),
                                  Row(
                                    children: [
                                      Expanded(
                                        child: Column(
                                          crossAxisAlignment:
                                              CrossAxisAlignment.start,
                                          children: [
                                            Text(
                                              'Measured from drawing: ${defaultLm.toStringAsFixed(3)} m × ${defaultWm.toStringAsFixed(3)} m',
                                              style: const TextStyle(
                                                fontSize: 12,
                                                fontWeight: FontWeight.w800,
                                                color: Color(0xFF155EEF),
                                              ),
                                            ),
                                            const SizedBox(height: 2),
                                            Text(
                                              useRectOverride
                                                  ? 'Using L×W → Area ${usedAreaM2.toStringAsFixed(3)} m² | Perimeter ${usedPerimM.toStringAsFixed(3)} m'
                                                  : 'Using polygon geometry. Set both L and W above zero to override.',
                                              style: TextStyle(
                                                fontSize: 12,
                                                fontWeight: FontWeight.w700,
                                                color:
                                                    useRectOverride
                                                        ? Colors.green.shade700
                                                        : Colors.grey.shade700,
                                              ),
                                            ),
                                          ],
                                        ),
                                      ),
                                      TextButton.icon(
                                        onPressed:
                                            () => setState(() {
                                              lengthCtrl.text = defaultLm
                                                  .toStringAsFixed(3);
                                              widthCtrl.text = defaultWm
                                                  .toStringAsFixed(3);
                                            }),
                                        icon: const Icon(
                                          Icons.my_location_rounded,
                                          size: 17,
                                        ),
                                        label: const Text(
                                          'Use drawing dimensions',
                                        ),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 12),
                                  Row(
                                    children: [
                                      Expanded(
                                        child: TextField(
                                          controller: substructureHeightCtrl,
                                          keyboardType:
                                              const TextInputType.numberWithOptions(
                                                decimal: true,
                                              ),
                                          decoration: deco(
                                            'Substructure height (m)',
                                          ),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                      ),
                                      const SizedBox(width: 12),
                                      Expanded(
                                        child: TextField(
                                          controller: superstructureHeightCtrl,
