                                  () =>
                                      setStateDialog(() => boqIntTiles = null),
                            ),
                            const SizedBox(height: 12),
                            SwitchListTile(
                              value: includeIntTileBacking,
                              onChanged:
                                  (value) => setStateDialog(
                                    () => includeIntTileBacking = value,
                                  ),
                              title: Text(
                                'Internal tile backing (${intTilesM2.toStringAsFixed(3)} m²)',
                              ),
                              subtitle: const Text(
                                'Backing quantity follows the selected internal tile faces.',
                              ),
                              contentPadding: EdgeInsets.zero,
                            ),
                            if (includeIntTileBacking) ...[
                              boqLine(
                                ctx: ctx,
                                title: 'Internal tile backing BOQ (m²)',
                                quantity: '${intTilesM2.toStringAsFixed(3)} m²',
                                pick: boqIntTileBacking,
                                onPick:
                                    () => pickBoq(
                                      ctx,
                                      (pick) => boqIntTileBacking = pick,
                                      setStateDialog,
                                    ),
                                onClear:
                                    () => setStateDialog(
                                      () => boqIntTileBacking = null,
                                    ),
                              ),
                              const SizedBox(height: 12),
                            ],
                          ],

                          SwitchListTile(
                            value: includeExtTiles,
                            onChanged: (v) {
                              setStateDialog(() {
                                includeExtTiles = v;
                                allocateFinishFaces('externalTiles', v ? 1 : 0);
                                if (v) includeExtTiles = true;
                              });
                            },
                            title: const Text('External tiles (m²)'),
                            contentPadding: EdgeInsets.zero,
                          ),
                          if (includeExtTiles) ...[
                            boqLine(
                              ctx: ctx,
                              title: 'External tiles BOQ (m²)',
                              quantity: '${extTilesM2.toStringAsFixed(3)} m²',
                              pick: boqExtTiles,
                              onPick:
                                  () => pickBoq(
                                    ctx,
                                    (p) => boqExtTiles = p,
                                    setStateDialog,
                                  ),
                              onClear:
                                  () =>
                                      setStateDialog(() => boqExtTiles = null),
                            ),
                            const SizedBox(height: 12),
                            SwitchListTile(
                              value: includeExtTileBacking,
                              onChanged:
                                  (value) => setStateDialog(
                                    () => includeExtTileBacking = value,
                                  ),
                              title: Text(
                                'External tile backing (${extTilesM2.toStringAsFixed(3)} m²)',
                              ),
                              subtitle: const Text(
                                'Backing quantity follows the external tiled face.',
                              ),
                              contentPadding: EdgeInsets.zero,
                            ),
                            if (includeExtTileBacking) ...[
                              boqLine(
                                ctx: ctx,
                                title: 'External tile backing BOQ (m²)',
                                quantity: '${extTilesM2.toStringAsFixed(3)} m²',
                                pick: boqExtTileBacking,
                                onPick:
                                    () => pickBoq(
                                      ctx,
                                      (pick) => boqExtTileBacking = pick,
                                      setStateDialog,
                                    ),
                                onClear:
                                    () => setStateDialog(
                                      () => boqExtTileBacking = null,
                                    ),
                              ),
                              const SizedBox(height: 12),
                            ],
                          ],

                          const Divider(height: 24),

                          Row(
                            children: [
                              const Expanded(
                                child: Text(
                                  'Deduct openings',
                                  style: TextStyle(fontWeight: FontWeight.w800),
                                ),
                              ),
                              OutlinedButton.icon(
                                onPressed:
                                    () => setStateDialog(
                                      () => openings.add(newOpeningDefault()),
                                    ),
                                icon: const Icon(Icons.add, size: 18),
                                label: const Text('Add deduction'),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),

                          if (openings.isEmpty)
                            const Text(
                              'No deductions. Add width × height × quantity only when required.',
                              style: TextStyle(fontSize: 12),
                            )
                          else
                            ...List.generate(
                              openings.length,
                              (idx) => openingCard(idx),
                            ),

                          const SizedBox(height: 14),
                          wallPanel(
                            title: 'Preview totals',
                            subtitle:
                                'Per building quantities multiplied by factor',
                            icon: Icons.analytics_outlined,
                            child: Wrap(
                              spacing: 8,
                              runSpacing: 8,
                              children: [
                                wallMetric(
                                  'Factor',
                                  'x${i(factorCtrl, 1).clamp(1, 999999)}',
                                  Icons.close_fullscreen_outlined,
                                ),
                                wallMetric(
                                  'Net walling',
                                  '${netAll.toStringAsFixed(3)} m²',
                                  Icons.done_all_outlined,
                                ),
                                wallMetric(
                                  'Internal finishes',
                                  '${intFinishM2.toStringAsFixed(3)} m²',
                                  Icons.format_paint_outlined,
                                ),
                                wallMetric(
                                  'External finishes',
                                  '${extFinishM2.toStringAsFixed(3)} m²',
                                  Icons.layers_outlined,
                                ),
                                wallMetric(
                                  'Internal tiles',
                                  '${intTilesM2.toStringAsFixed(3)} m²',
                                  Icons.grid_on_outlined,
                                ),
                                wallMetric(
                                  'External tiles',
                                  '${extTilesM2.toStringAsFixed(3)} m²',
                                  Icons.grid_view_outlined,
                                ),
                                wallMetric(
                                  'Openings',
                                  'D $totalDoorNo • W $totalWindowNo',
                                  Icons.door_front_door_outlined,
                                ),
                                wallMetric(
                                  'Frames',
                                  '${totalFramePerimM.toStringAsFixed(3)} m',
                                  Icons.crop_free_outlined,
                                ),
                                wallMetric(
                                  'Glazing',
                                  '${totalGlazingM2.toStringAsFixed(3)} m²',
                                  Icons.window_outlined,
                                ),
                                if (totalTransomM2 > 0)
                                  wallMetric(
                                    'Transom glazing',
                                    '${totalTransomM2.toStringAsFixed(3)} m²',
                                    Icons.window_rounded,
                                  ),
                              ],
                            ),
                          ),
                          if (!canSaveWall) ...[
                            const SizedBox(height: 12),
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 10,
                              ),
                              decoration: BoxDecoration(
                                color: const Color(0xFFFFF7ED),
                                borderRadius: BorderRadius.circular(14),
                                border: Border.all(
                                  color: const Color(0xFFFDBA74),
                                ),
                              ),
                              child: Text(
                                missingTileBackingBoq
                                    ? 'Pick a BOQ item for each enabled tile backing before saving.'
                                    : 'Pick at least one BOQ item before saving. Only picked BOQ items will be saved.',
                                style: const TextStyle(
                                  color: Color(0xFF9A3412),
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ),
                          ],
                        ],
                      ),
                    ),
                  ),
                  actions: [
                    TextButton(
                      onPressed: () => Get.back(result: WallSaveAction.cancel),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed:
                          canSaveWall
                              ? () => Get.back(result: WallSaveAction.finish)
                              : null,
                      child: const Text('Save'),
                    ),
                  ],
                ),
              );
            },
          ),
          barrierDismissible: false,
        ) ??
        WallSaveAction.cancel;

    if (action == WallSaveAction.minimize) {
      // Keep the current unsaved form values as the next wall draft defaults.
      // The measured wall draft itself remains on the canvas until Save/Cancel.
      final draftH = double.tryParse(heightCtrl.text.trim()) ?? 3.0;
      final draftQtyWalls = (int.tryParse(qtyWallsCtrl.text.trim()) ?? 1).clamp(1, 999999);
      final draftFactor = (int.tryParse(factorCtrl.text.trim()) ?? 1).clamp(1, 999999);
      lastWallDefaults = {
        ...lastWallDefaults,
        'buildingFactor': draftFactor,
        'wallHeightM': draftH,
        'qtyWalls': draftQtyWalls,
        'wallName': wallNameCtrl.text.trim(),
        'wallThicknessMm': wallThicknessMm,
        'internalFaces': internalFaces,
        'externalFaces': externalFaces,
        'internalTileFaces': internalTileFaces,
        'externalTileFaces': externalTileFaces,
        'includeWalling': includeWalling,
        'includeIntPlaster': includeIntPlaster,
        'includeIntPaint': includeIntPaint,
        'includeExtRender': includeExtRender,
        'includeExtPaint': includeExtPaint,
        'includeIntTiles': includeIntTiles,
        'includeExtTiles': includeExtTiles,
        'includeIntTileBacking': includeIntTileBacking,
        'includeExtTileBacking': includeExtTileBacking,
        'boqWalling': pickToMap(boqWalling),
        'boqIntPlaster': pickToMap(boqIntPlaster),
        'boqIntPaint': pickToMap(boqIntPaint),
        'boqExtRender': pickToMap(boqExtRender),
        'boqExtPaint': pickToMap(boqExtPaint),
        'boqIntTiles': pickToMap(boqIntTiles),
        'boqExtTiles': pickToMap(boqExtTiles),
        'boqIntTileBacking': pickToMap(boqIntTileBacking),
        'boqExtTileBacking': pickToMap(boqExtTileBacking),
      };
      lastWallTemplate = WallTemplate(
        heightM: draftH,
        qtyWalls: draftQtyWalls,
        internalFaces: internalFaces,
        externalFaces: externalFaces,
        includeWalling: includeWalling,
        includeInternalPlaster: includeIntPlaster,
        includeInternalPaint: includeIntPaint,
        includeExternalRender: includeExtRender,
        includeExternalPaint: includeExtPaint,
        boqWalling: pickToMap(boqWalling),
        boqIntPlaster: pickToMap(boqIntPlaster),
        boqIntPaint: pickToMap(boqIntPaint),
        boqExtRender: pickToMap(boqExtRender),
        boqExtPaint: pickToMap(boqExtPaint),
        openings: openings.map((e) => {
          'typeName': e.type.name,
          'qtyPerWall': e.qtyPerWall,
          'w': e.w,
          'h': e.h,
          'inclLeaf': false,
          'inclFrame': false,
          'inclIron': false,
          'inclGlazing': false,
        }).toList(),
      );
      lengthCtrl.dispose();
      heightCtrl.dispose();
      qtyWallsCtrl.dispose();
      wallNameCtrl.dispose();
      factorCtrl.dispose();
      return WallSaveAction.minimize;
    }

    if (action == WallSaveAction.cancel) {
      lengthCtrl.dispose();
      heightCtrl.dispose();
      qtyWallsCtrl.dispose();
      wallNameCtrl.dispose();
      factorCtrl.dispose();
      return WallSaveAction.cancel;
    }

    // ---------- VALIDATION ----------
    final factor = (int.tryParse(factorCtrl.text.trim()) ?? 1).clamp(1, 999999);
    final L = double.tryParse(lengthCtrl.text.trim()) ?? baseLengthM;
    final H = double.tryParse(heightCtrl.text.trim()) ?? 0.0;
    final qtyWalls = (int.tryParse(qtyWallsCtrl.text.trim()) ?? 1).clamp(
      1,
      999999,
    );

    if (L <= 0 || H <= 0) {
      Get.snackbar('Invalid', 'Enter valid Length and Height.');
      return WallSaveAction.cancel;
    }

    if (!hasAnyWallBoqPick()) {
      Get.snackbar('BOQ required', 'Pick at least one BOQ item before saving.');
      return WallSaveAction.cancel;
    }

    if (includeIntTiles && includeIntTileBacking && boqIntTileBacking == null) {
      Get.snackbar('BOQ required', 'Pick the internal tile backing BOQ.');
      return WallSaveAction.cancel;
    }
    if (includeExtTiles && includeExtTileBacking && boqExtTileBacking == null) {
      Get.snackbar('BOQ required', 'Pick the external tile backing BOQ.');
      return WallSaveAction.cancel;
    }

    if (includeIntTiles) {
      final faces = internalTileFaces.clamp(0, 2);
      if (faces == 0) {
        Get.snackbar('Invalid', 'Select internal tiles faces (1 or 2).');
        return WallSaveAction.cancel;
      }
    }

    // validate openings BOQs for enabled parts
    for (final e in openings) {
      if (e.qtyPerWall <= 0) {
        Get.snackbar('Invalid', 'Opening qty must be > 0 (${e.type.name}).');
        return WallSaveAction.cancel;
      }
    }

    // ---------- CALCS (per building) ----------
    final grossPerWall = L * H;

    double openingsAreaPerWall = 0.0;
    for (final e in openings) {
      openingsAreaPerWall += e.area;
    }

    final netPerWall = (grossPerWall - openingsAreaPerWall).clamp(
      0.0,
      double.infinity,
    );

    final grossAllPerBuilding = grossPerWall * qtyWalls;
    final openingsAllPerBuilding = openingsAreaPerWall * qtyWalls;
    final netAllPerBuilding = netPerWall * qtyWalls;

    final intFaces = internalFaces.clamp(0, 2);
    final extFaces = externalFaces.clamp(0, 2);

    final intFinishPerBuildingM2 = netAllPerBuilding * intFaces;
    final extFinishPerBuildingM2 = netAllPerBuilding * extFaces;

    final intTileFacesClamped =
        includeIntTiles ? internalTileFaces.clamp(1, 2) : 0;
    final extTileFacesClamped = includeExtTiles ? 1 : 0;

    final intTilesPerBuildingM2 = netAllPerBuilding * intTileFacesClamped;
    final extTilesPerBuildingM2 = netAllPerBuilding * extTileFacesClamped;

    // ---------- TOTAL (x factor) ----------
    final grossAll = grossAllPerBuilding * factor;
    final openingsAll = openingsAllPerBuilding * factor;
    final netAll = netAllPerBuilding * factor;

    final intFinishM2 = intFinishPerBuildingM2 * factor;
    final extFinishM2 = extFinishPerBuildingM2 * factor;

    final intTilesM2 = intTilesPerBuildingM2 * factor;
    final extTilesM2 = extTilesPerBuildingM2 * factor;
    final wallTypeLabel = 'Walling $wallThicknessMm mm';

    // each wall segment shares wallGroupId, has its own segmentId
    final segmentId = measurementsRef.doc().id;
    final now = FieldValue.serverTimestamp();

    Map<String, dynamic> commonMeta() => {
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,
      'wallGroupId': wallGroupId,
      'segmentId': segmentId,
      'wallName': wallNameCtrl.text.trim(),
      'wallThicknessMm': wallThicknessMm,
      'wallThicknessM': wallThicknessMm / 1000,
      'wallType': wallThicknessMm == 230 ? 'wall230' : 'wall150',
      'internalFinishFaces': intFaces,
      'externalFinishFaces': extFaces,
      'internalTileFaces': intTileFacesClamped,
      'externalTileFaces': extTileFacesClamped,
      'allocatedFinishFaces':
          intFaces + extFaces + intTileFacesClamped + extTileFacesClamped,
      'lengthM': L,
      'heightM': H,
      'qtyWallsPerBuilding': qtyWalls,
      'buildingFactor': factor,
      'grossAreaPerBuildingM2': grossAllPerBuilding,
      'openingsAreaPerBuildingM2': openingsAllPerBuilding,
      'netAreaPerBuildingM2': netAllPerBuilding,
      'grossAreaTotalM2': grossAll,
      'openingsAreaTotalM2': openingsAll,
      'netAreaTotalM2': netAll,
      'wallSegmentCount':
          cleanedWallSegments.isNotEmpty ? cleanedWallSegments.length : 1,
      'polylineSegments': cleanedWallSegments,
      'p1': {'x': p1.dx, 'y': p1.dy},
      'p2': {'x': p2.dx, 'y': p2.dy},
      'color': currentColor.value,
      'createdAt': now,
      'updatedAt': now,
    };

    bool wallSavingDialogOpen = false;
    bool wallSavingDone = false;
    bool wallSavingFailed = false;
    double wallSavingProgress = 0.05;
    String wallSavingTitle = 'Saving wall measurement';
    String wallSavingMessage =
        'Please wait while the grouped wall measurement is saved.';
    StateSetter? wallSavingSetState;

    void showWallSavingDialog() {
      wallSavingDialogOpen = true;
      Get.dialog<void>(
        StatefulBuilder(
          builder: (ctx, setStateDialog) {
            wallSavingSetState = setStateDialog;
            return AlertDialog(
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(18),
              ),
              content: SizedBox(
                width: 340,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        if (wallSavingDone)
                          Icon(
                            wallSavingFailed
                                ? Icons.error_outline
                                : Icons.check_circle_outline,
                            color:
                                wallSavingFailed
                                    ? const Color(0xFFB42318)
                                    : const Color(0xFF027A48),
                            size: 24,
                          )
                        else
                          const Icon(
                            Icons.cloud_upload_outlined,
                            color: Color(0xFF155EEF),
                            size: 24,
                          ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Text(
                            wallSavingTitle,
                            style: const TextStyle(fontWeight: FontWeight.w900),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    Text(
                      wallSavingMessage,
                      style: const TextStyle(fontSize: 13),
                    ),
                    if (!wallSavingDone) ...[
                      const SizedBox(height: 16),
                      Center(
                        child: SizedBox(
                          width: 88,
                          height: 88,
                          child: Stack(
                            alignment: Alignment.center,
                            children: [
                              SizedBox.expand(
                                child: CircularProgressIndicator(
                                  value: wallSavingProgress,
                                  strokeWidth: 8,
                                  backgroundColor: const Color(0xFFE4E7EC),
                                  color: const Color(0xFF155EEF),
                                ),
                              ),
                              Text(
                                '${(wallSavingProgress * 100).round()}%',
                                style: const TextStyle(
                                  color: Color(0xFF101828),
                                  fontSize: 20,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            );
          },
        ),
        barrierDismissible: false,
      );
    }

    Future<void> updateWallSavingDialog({
      required String title,
      required String message,
      bool failed = false,
      Duration hold = const Duration(milliseconds: 900),
    }) async {
      if (!wallSavingDialogOpen) return;
      wallSavingDone = true;
      wallSavingFailed = failed;
      wallSavingTitle = title;
      wallSavingMessage = message;
      wallSavingSetState?.call(() {});
      await Future.delayed(hold);
    }

    Future<void> setWallSavingProgress(double progress, String message) async {
      if (!wallSavingDialogOpen || wallSavingDone) return;
      wallSavingProgress = progress.clamp(0.0, 1.0).toDouble();
      wallSavingMessage = message;
      wallSavingSetState?.call(() {});
      await Future<void>.delayed(const Duration(milliseconds: 80));
    }

    void hideWallSavingDialog() {
      if (!wallSavingDialogOpen) return;
      if (Get.isDialogOpen == true) {
        Get.back<void>();
      }
      wallSavingDialogOpen = false;
      wallSavingSetState = null;
    }

    Future<void> finishWallSavingDialog() async {
      await setWallSavingProgress(1, 'Wall measurement saved successfully.');
      await updateWallSavingDialog(
        title: 'Wall measurement saved',
        message: 'Saved successfully.',
      );
      hideWallSavingDialog();
    }

    Future<void> failWallSavingDialog(Object error) async {
      await updateWallSavingDialog(
        title: 'Wall save failed',
        message: '$error',
        failed: true,
        hold: const Duration(milliseconds: 1400),
      );
      hideWallSavingDialog();
    }

    // ---------- SAVE (batch) ----------
    try {
      final batch = FirebaseFirestore.instance.batch();

      // walling net (m2) -> ✅ value stored as TOTAL
      if (includeWalling && boqWalling != null && netAll > 0) {
        batch.set(measurementsRef.doc('$segmentId-wall'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'wallingNet',
          'unit': 'm2',
          'value': netAll,
          'valuePerBuilding': netAllPerBuilding,
          'label': '$wallTypeLabel - Walling',
          'internalFaces': intFaces,
          'externalFaces': extFaces,
          'boqItemId': boqWalling!.id,
          'boqCode': boqWalling!.code,
          'boqDescription': boqWalling!.description,
        });
      }

      // finishes (existing) -> ✅ value TOTAL
      if (includeIntPlaster && boqIntPlaster != null && intFinishM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-intPl'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishInternalPlaster',
          'unit': 'm2',
          'value': intFinishM2,
          'valuePerBuilding': intFinishPerBuildingM2,
          'faces': intFaces,
          'label': '$wallTypeLabel - Internal plaster',
          'boqItemId': boqIntPlaster!.id,
          'boqCode': boqIntPlaster!.code,
          'boqDescription': boqIntPlaster!.description,
        });
      }

      if (includeIntPaint && boqIntPaint != null && intFinishM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-intPt'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishInternalPaint',
          'unit': 'm2',
          'value': intFinishM2,
          'valuePerBuilding': intFinishPerBuildingM2,
          'faces': intFaces,
          'label': '$wallTypeLabel - Internal paint',
          'boqItemId': boqIntPaint!.id,
          'boqCode': boqIntPaint!.code,
          'boqDescription': boqIntPaint!.description,
        });
      }

      if (includeExtRender && boqExtRender != null && extFinishM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-extRd'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishExternalRender',
          'unit': 'm2',
          'value': extFinishM2,
          'valuePerBuilding': extFinishPerBuildingM2,
          'faces': extFaces,
          'label': '$wallTypeLabel - External render',
          'boqItemId': boqExtRender!.id,
          'boqCode': boqExtRender!.code,
          'boqDescription': boqExtRender!.description,
        });
      }

      if (includeExtPaint && boqExtPaint != null && extFinishM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-extPt'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishExternalPaint',
          'unit': 'm2',
          'value': extFinishM2,
          'valuePerBuilding': extFinishPerBuildingM2,
          'faces': extFaces,
          'label': '$wallTypeLabel - External paint',
          'boqItemId': boqExtPaint!.id,
          'boqCode': boqExtPaint!.code,
          'boqDescription': boqExtPaint!.description,
        });
      }

      // ✅ tiles (TOTAL)
      if (includeIntTiles && boqIntTiles != null && intTilesM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-intTl'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishInternalTiles',
          'finish': 'tiles',
          'unit': 'm2',
          'value': intTilesM2,
          'valuePerBuilding': intTilesPerBuildingM2,
          'faces': intTileFacesClamped,
          'label':
              '$wallTypeLabel - Internal tiles (${intTileFacesClamped} face${intTileFacesClamped == 1 ? '' : 's'})',
          'boqItemId': boqIntTiles!.id,
          'boqCode': boqIntTiles!.code,
          'boqDescription': boqIntTiles!.description,
        });
      }

      if (includeIntTiles &&
          includeIntTileBacking &&
          boqIntTileBacking != null &&
          intTilesM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-intTlBacking'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'tileBackingBed',
          'finish': 'tileBacking',
          'surface': 'internal',
          'backingType': 'internalWallTileBacking',
          'unit': 'm2',
          'value': intTilesM2,
          'valuePerBuilding': intTilesPerBuildingM2,
          'faces': intTileFacesClamped,
          'label': '$wallTypeLabel - Internal tile backing',
          'boqItemId': boqIntTileBacking!.id,
          'boqCode': boqIntTileBacking!.code,
          'boqDescription': boqIntTileBacking!.description,
        });
      }

      if (includeExtTiles && boqExtTiles != null && extTilesM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-extTl'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'finishExternalTiles',
          'finish': 'tiles',
          'unit': 'm2',
          'value': extTilesM2,
          'valuePerBuilding': extTilesPerBuildingM2,
          'faces': 1,
          'label': '$wallTypeLabel - External tiles',
          'boqItemId': boqExtTiles!.id,
          'boqCode': boqExtTiles!.code,
          'boqDescription': boqExtTiles!.description,
        });
      }

      if (includeExtTiles &&
          includeExtTileBacking &&
          boqExtTileBacking != null &&
          extTilesM2 > 0) {
        batch.set(measurementsRef.doc('$segmentId-extTlBacking'), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'tileBackingBed',
          'finish': 'tileBacking',
          'surface': 'external',
          'backingType': 'externalWallTileBacking',
          'unit': 'm2',
          'value': extTilesM2,
          'valuePerBuilding': extTilesPerBuildingM2,
          'faces': 1,
          'label': '$wallTypeLabel - External tile backing',
          'boqItemId': boqExtTileBacking!.id,
          'boqCode': boqExtTileBacking!.code,
          'boqDescription': boqExtTileBacking!.description,
        });
      }

      // Opening deductions only. Door/window leaf, frames, glazing and
      // ironmongery belong to the dedicated Door and Window take-off tools.
      for (int idx = 0; idx < openings.length; idx++) {
        final e = openings[idx];
        final totalQty = e.qtyPerWall * qtyWalls * factor;
        final openId = '$segmentId-ded$idx';
        final openAreaTotal = (e.w * e.h) * totalQty;
        if (openAreaTotal <= 0) continue;
        batch.set(measurementsRef.doc(openId), {
          ...commonMeta(),
          'measureType': 'walling',
          'type': 'openingDeduction',
          'unit': 'm2',
          'value': openAreaTotal,
          'openingName': 'Deduction ${idx + 1}',
          'category': 'deduction',
          'widthM': e.w,
          'heightM': e.h,
          'qtyPerWall': e.qtyPerWall,
          'totalQty': totalQty,
        });
      }

      showWallSavingDialog();
      await setWallSavingProgress(
        35 / 100,
        'Preparing the grouped wall records…',
      );
      await setWallSavingProgress(
        70 / 100,
        'Saving measurements and BOQ selections…',
      );
      await batch.commit();
      await setWallSavingProgress(90 / 100, 'Remembering the wall settings…');

      // ---------- AUTO-REMEMBER (✅ do NOT remember Length) ----------
      lastWallDefaults = {
        'buildingFactor': factor,
        'wallHeightM': H,
        'qtyWalls': qtyWalls,
        'wallName': wallNameCtrl.text.trim(),
        'wallThicknessMm': wallThicknessMm,

        'internalFaces': intFaces,
        'externalFaces': extFaces,

        'internalTileFaces': includeIntTiles ? intTileFacesClamped : 0,
        'externalTileFaces': includeExtTiles ? 1 : 0,
        'includeIntTiles': includeIntTiles,
        'includeExtTiles': includeExtTiles,
        'includeIntTileBacking': includeIntTileBacking,
        'includeExtTileBacking': includeExtTileBacking,
        'boqIntTiles': pickToMap(boqIntTiles),
        'boqExtTiles': pickToMap(boqExtTiles),
        'boqIntTileBacking': pickToMap(boqIntTileBacking),
        'boqExtTileBacking': pickToMap(boqExtTileBacking),

        'includeWalling': includeWalling,
        'includeIntPlaster': includeIntPlaster,
        'includeIntPaint': includeIntPaint,
        'includeExtRender': includeExtRender,
        'includeExtPaint': includeExtPaint,

        'boqWalling': pickToMap(boqWalling),
        'boqIntPlaster': pickToMap(boqIntPlaster),
        'boqIntPaint': pickToMap(boqIntPaint),
        'boqExtRender': pickToMap(boqExtRender),
        'boqExtPaint': pickToMap(boqExtPaint),
      };

      lastWallTemplate = WallTemplate(
        heightM: H,
        qtyWalls: qtyWalls,
        internalFaces: intFaces,
        externalFaces: extFaces,
        includeWalling: includeWalling,
        includeInternalPlaster: includeIntPlaster,
        includeInternalPaint: includeIntPaint,
        includeExternalRender: includeExtRender,
        includeExternalPaint: includeExtPaint,
        boqWalling: pickToMap(boqWalling),
        boqIntPlaster: pickToMap(boqIntPlaster),
        boqIntPaint: pickToMap(boqIntPaint),
        boqExtRender: pickToMap(boqExtRender),
        boqExtPaint: pickToMap(boqExtPaint),
        openings: openings.map((e) => {
          'typeName': e.type.name,
          'qtyPerWall': e.qtyPerWall,
          'w': e.w,
          'h': e.h,
          'inclLeaf': false,
          'inclFrame': false,
          'inclIron': false,
          'inclGlazing': false,
        }).toList(),
      );

      if (action == WallSaveAction.finish) {
        onCloseDraft();
        draftWallGroupId = null;
      }
      await finishWallSavingDialog();
      return action;
    } catch (e) {
      await failWallSavingDialog(e);
      return WallSaveAction.cancel;
    } finally {
      hideWallSavingDialog();
      lengthCtrl.dispose();
      heightCtrl.dispose();
      qtyWallsCtrl.dispose();
      wallNameCtrl.dispose();
      factorCtrl.dispose();
    }
  }

