  Future<bool?> openWallingEditorDialog({
    required String groupId,
    required String label,
    required double grossLengthM,
    required double grossAreaM2,
    required double initialHeightM,
    required String initialWallBoqCode,
    required List<DoorInput> doors,
    required List<WindowInput> windows,
    WallingFinishInput? finishes,
  }) async {
    finishes ??= WallingFinishInput();
    bool rememberAsDefault = true; // ✅ user can toggle

    final heightCtrl = TextEditingController(
      text: initialHeightM.toStringAsFixed(2),
    );

    // Wall BOQ pickers (code + description)
    final wallBoqCodeCtrl = TextEditingController(text: initialWallBoqCode);
    final wallBoqDescCtrl = TextEditingController(text: '');
    WallingFinishInput lastWallingFinish = WallingFinishInput();
    String lastWallingBoqCode = '';

    lastWallingBoqCode = lastWallingBoqCode.trim();
    if (wallBoqCodeCtrl.text.trim().isEmpty && lastWallingBoqCode.isNotEmpty) {
      wallBoqCodeCtrl.text = lastWallingBoqCode;
    }

    // finishes: if not provided, use remembered values
    finishes = (finishes ?? lastWallingFinish.copy());

    // wall type
    WallType wallType = finishes.wallType;

    // Finish controllers
    final plasterBoqCtrl = TextEditingController(text: finishes.plasterBoqCode);
    final plasterDecoCtrl = TextEditingController(
      text: finishes.plasterDecoBoqCode,
    );
    final renderBoqCtrl = TextEditingController(text: finishes.renderBoqCode);
    final renderDecoCtrl = TextEditingController(
      text: finishes.renderDecoBoqCode,
    );

    // Optional desc controllers (read-only)
    final plasterDescCtrl = TextEditingController(text: '');
    final plasterDecoDescCtrl = TextEditingController(text: '');
    final renderDescCtrl = TextEditingController(text: '');
    final renderDecoDescCtrl = TextEditingController(text: '');

    final deletedOpeningKeys = <String>{};

    double doorsArea() =>
        doors.fold(0.0, (s, d) => s + (d.widthM * d.heightM * d.qty));
    double windowsArea() =>
        windows.fold(0.0, (s, w) => s + (w.widthM * w.heightM * w.qty));
    double openingArea() => doorsArea() + windowsArea();
    double netArea() =>
        (grossAreaM2 - openingArea()).clamp(0.0, double.infinity);

    // ✅ finishes qty rules
    double internalFinishArea() =>
        netArea() * 2; // plaster + decoration (both sides)
    double externalInsidePlasterArea() => netArea(); // inside face
    double externalOutsideRenderArea() => netArea(); // outside face

    // draggable offset
    Offset dialogOffset = const Offset(24, 80);

    bool isSaving = false;
    String? errorText;

    Future<void> _pickWallBoq(StateSetter setState) async {
      final ctx = Get.context;
      if (ctx == null) return;

      final picked = await showBoqPickerDialog(context: ctx);
      if (picked != null) {
        wallBoqCodeCtrl.text = picked.code.trim();
        wallBoqDescCtrl.text = picked.description.trim();
      }

      // setState(() {
      //   wallBoqCodeCtrl.text = picked.code.trim();
      //   wallBoqDescCtrl.text = picked.description.trim();
      // });
    }

