      final picked = await showBoqPickerDialog(context: ctx);
      if (picked != null) {
        plasterBoqCtrl.text = picked.code.trim();
        plasterDecoDescCtrl.text = picked.description.trim();
      }

      // setState(() {
      //   wallBoqCodeCtrl.text = picked.code.trim();
