                                                              x.openingKey ==
                                                              w.openingKey,
                                                        );
                                                      });
                                                    },
                                          ),
                                        ],
                                      ),
                                    );
                                  }),

                                  if (errorText != null) ...[
                                    const SizedBox(height: 10),
                                    Text(
                                      errorText!,
                                      style: const TextStyle(
                                        color: Colors.red,
                                        fontSize: 12,
                                      ),
                                    ),
                                  ],
                                ],
                              ),
                            ),
                          ),

                          // ✅ ACTIONS
                          Container(
                            padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
                            decoration: BoxDecoration(
                              color: Theme.of(context).colorScheme.surface,
                              border: Border(
                                top: BorderSide(
                                  color: Colors.black.withOpacity(0.08),
                                ),
                              ),
                            ),
                            child: Row(
                              children: [
                                Expanded(
                                  child: TextButton(
                                    onPressed:
                                        isSaving
                                            ? null
                                            : () => Get.back(result: false),
                                    child: const Text('Cancel'),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: FilledButton(
                                    onPressed:
                                        isSaving
                                            ? null
                                            : () async {
                                              setState(() {
                                                isSaving = true;
                                                errorText = null;
                                              });

                                              // validate quickly
                                              final h = double.tryParse(
                                                heightCtrl.text.trim(),
                                              );
                                              if (h == null || h <= 0) {
                                                setState(() {
                                                  isSaving = false;
                                                  errorText =
                                                      'Invalid wall height.';
                                                });
                                                return;
                                              }
                                              if (wallBoqCodeCtrl.text
                                                  .trim()
                                                  .isEmpty) {
                                                setState(() {
                                                  isSaving = false;
                                                  errorText =
                                                      'Pick walling BOQ code.';
                                                });
                                                return;
                                              }

                                              Get.back(result: true);
                                            },
                                    child: const Text('Save'),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
      barrierDismissible: false,
    );

    if (result != true) return false;
    if (rememberAsDefault) {
      lastWallType = wallType;

      lastWallBoq = wallBoqCodeCtrl.text.trim();

      lastPlasterBoq = plasterBoqCtrl.text.trim();
      lastPlasterDecoBoq = plasterDecoCtrl.text.trim();

      lastRenderBoq = renderBoqCtrl.text.trim();
      lastRenderDecoBoq = renderDecoCtrl.text.trim();
    }

    final newHeight = double.tryParse(heightCtrl.text.trim()) ?? initialHeightM;
    final newWallBoq = wallBoqCodeCtrl.text.trim();

    finishes.wallType = wallType;
    finishes.plasterBoqCode = plasterBoqCtrl.text.trim();
    finishes.plasterDecoBoqCode = plasterDecoCtrl.text.trim();
    finishes.renderBoqCode = renderBoqCtrl.text.trim();
    finishes.renderDecoBoqCode = renderDecoCtrl.text.trim();

    // ✅ remember defaults for next wall measurement
    lastWallingBoqCode = newWallBoq;
    lastWallingFinish = finishes.copy();

    try {
      await _saveWallingGroupAndOpenings(
        wallGroupId: groupId,
        newHeightM: newHeight,
        newWallBoqCode: newWallBoq,
        wallType: wallType.name, // "internal"/"external"
        finishes: {
          'plasterBoqCode': finishes.plasterBoqCode,
          'plasterDecoBoqCode': finishes.plasterDecoBoqCode,
          'renderBoqCode': finishes.renderBoqCode,
          'renderDecoBoqCode': finishes.renderDecoBoqCode,
        },
        doors: doors,
        windows: windows,
        deletedOpeningKeys: deletedOpeningKeys,
      );

      Get.snackbar(
        'Saved',
        'Walling updated successfully',
        snackPosition: SnackPosition.BOTTOM,
      );
      return true;
    } catch (e) {
      Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
      return false;
    }
  }

