  Future<bool> handleWallViewTap(
    Offset imagePos,
    List<MeasuredSegment> segments,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    foundationWallCompositeDocsByWallId,
    Map<String, dynamic> drawingData,
  ) async {
    // only consider foundationWall segments
    final fwSegments =
        segments.where((s) {
          final mt = (s.measureType ?? '').toLowerCase().trim();
          return mt == 'walling';
        }).toList();

    if (fwSegments.isEmpty) return false;

    // hit test: find closest segment within tolerance
    final tolPx = _tapTolerancePx(drawingData); // zoom-aware if you want
    final hit = _hitTestSegment(imagePos, fwSegments, tolPx: tolPx);
    if (hit == null) return false;

    final wallGroupId = (hit.groupId ?? '').trim();
    if (wallGroupId.isEmpty) return false;

    // optional: use provided cached docs first if present
    final cached = foundationWallCompositeDocsByWallId[wallGroupId];

    await openWallDetailsDialog(wallGroupId: wallGroupId, cachedDocs: cached);

    return true;
  }

  Future<bool> handlelineViewTap(
    Offset imagePos,
    List<MeasuredSegment> segments,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    foundationWallCompositeDocsByWallId,
    Map<String, dynamic> drawingData,
  ) async {
    // only consider foundationWall segments
    final fwSegments =
        segments.where((s) {
          final mt = (s.measureType ?? '').toLowerCase().trim();
          return mt == 'length';
        }).toList();

    if (fwSegments.isEmpty) return false;

    // hit test: find closest segment within tolerance
    final tolPx = _tapTolerancePx(drawingData); // zoom-aware if you want
    final hit = _hitTestSegment(imagePos, fwSegments, tolPx: tolPx);
    if (hit == null) return false;

    final wallGroupId = (hit.groupId ?? '').trim();
    if (wallGroupId.isEmpty) return false;

    // optional: use provided cached docs first if present
    final cached = foundationWallCompositeDocsByWallId[wallGroupId];

    await openLineDetailsDialog(wallGroupId: wallGroupId, cachedDocs: cached);

    return true;
  }

  // ------------------------------------------------------------
  // 2) Hit test helpers
  // ------------------------------------------------------------
  double _tapTolerancePx(Map<String, dynamic> drawingData) {
    // If you store zoomScale in drawingData, you can make it scale.
    final zRaw = drawingData['zoomScale'];
    final z = (zRaw is num) ? zRaw.toDouble() : double.tryParse('$zRaw') ?? 1.0;

    // About 14px on screen feeling:
    // if your imagePos is in image coords and zoom affects it, adjust if needed.
    // Use clamp so it doesn’t become too tiny/huge.
    final t = 14.0 / (z <= 0 ? 1.0 : z);
    return t.clamp(6.0, 22.0);
  }

  MeasuredSegment? _hitTestSegment(
    Offset p,
    List<MeasuredSegment> segs, {
    required double tolPx,
  }) {
    MeasuredSegment? best;
    double bestDist = double.infinity;

    for (final s in segs) {
      final d = _distancePointToSegment(p, s.p1, s.p2);
      if (d <= tolPx && d < bestDist) {
        bestDist = d;
        best = s;
      }
    }
    return best;
  }

  double _distancePointToSegment(Offset p, Offset a, Offset b) {
    final ab = b - a;
    final ap = p - a;
    final abLen2 = ab.dx * ab.dx + ab.dy * ab.dy;
    if (abLen2 == 0) return (p - a).length;

    final t = ((ap.dx * ab.dx) + (ap.dy * ab.dy)) / abLen2;
    final tt = t.clamp(0.0, 1.0);
    final proj = Offset(a.dx + ab.dx * tt, a.dy + ab.dy * tt);
    return (p - proj).length;
  }

  // ------------------------------------------------------------
  // 3) Details dialog (Change BOQ / Remove)
  // ------------------------------------------------------------
  String _s(dynamic v) => (v ?? '').toString();
  double _d(dynamic v) =>
      (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

  Future<void> openLineDetailsDialog({
    required String wallGroupId,
    List<QueryDocumentSnapshot<Map<String, dynamic>>>? cachedDocs,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return;

    await showDialog(
      context: ctx,
      barrierDismissible: true,
      builder: (dCtx) {
        Widget buildFromDocs(List<Map<String, dynamic>> docs) {
          if (docs.isEmpty) {
            return const Text('No records found for this wall.');
          }

          // totals
          double totalLenM = 0.0;
          for (final m in docs) {
            // your docs store baseLengthM/lengthM/wallLengthM often equal
            // We'll sum unique segments by segmentId to avoid multiplying lines.
            // simplest: take max length among lines per segmentId.
          }

          // group by segmentId => max baseLengthM
          final segLen = <String, double>{};
          for (final m in docs) {
            final sid = _s(m['segmentId']).trim();
            if (sid.isEmpty) continue;
            final L = _d(m['baseLengthM']);
            if (L <= 0) continue;
            segLen[sid] = math.max(segLen[sid] ?? 0.0, L);
          }
          totalLenM = segLen.values.fold(0.0, (a, b) => a + b);

          // group BOQ lines: (type + boqCode + unit)
          String keyOf(Map<String, dynamic> m) {
            final type = _s(m['type']).trim();
            final code = _s(m['boqCode']).trim();
            final unit = _s(m['unit']).trim();
            return '$type|$code|$unit';
          }

          final grouped = <String, FoundationWallLine>{};

          for (final m in docs) {
            final boqCode = _s(m['boqCode']).trim();
            if (boqCode.isEmpty) continue;

            final type = _s(m['type']).trim();
            final unit = _s(m['unit']).trim();
            final qty = _d(m['value']);
            final desc = _s(m['boqDescription']).trim();

            final k = keyOf(m);
            final prev = grouped[k];
            if (prev == null) {
              grouped[k] = FoundationWallLine(
                type: type,
                boqCode: boqCode,
                boqDesc: desc,
                unit: unit,
                qty: qty,
              );
            } else {
              grouped[k] = FoundationWallLine(
                type: prev.type,
                boqCode: prev.boqCode,
                boqDesc: prev.boqDesc,
                unit: prev.unit,
                qty: prev.qty + qty,
              );
            }
          }

          final rows =
              grouped.values.toList()..sort((a, b) => a.type.compareTo(b.type));

          Future<void> changeBoqForLine({
            required String type,
            required String oldBoqCode,
            required BoqPick newPick,
          }) async {
            final snap =
                await measurementsRef
                    .where('lengthGroupId', isEqualTo: wallGroupId)
                    .where('type', isEqualTo: type)
                    .where('boqCode', isEqualTo: oldBoqCode)
                    .get();

            if (snap.docs.isEmpty) return;

            final batch = FirebaseFirestore.instance.batch();
            for (final d in snap.docs) {
              batch.update(d.reference, {
                'boqItemId': newPick.id,
                'boqCode': newPick.code,
                'boqDescription': newPick.description,
                'updatedAt': FieldValue.serverTimestamp(),
              });
            }
            await batch.commit();
          }

          Future<void> removeLine({
            required String type,
            required String boqCode,
          }) async {
            final snap =
                await measurementsRef
                    .where('lengthGroupId', isEqualTo: wallGroupId)
                    .where('type', isEqualTo: type)
                    .where('boqCode', isEqualTo: boqCode)
                    .get();

            if (snap.docs.isEmpty) return;

            final batch = FirebaseFirestore.instance.batch();
            for (final d in snap.docs) {
              batch.delete(d.reference);
            }
            await batch.commit();
          }

          return SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Line group: $wallGroupId',
                          style: const TextStyle(fontSize: 12),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          'Total length: ${totalLenM.toStringAsFixed(3)} m',
                          style: const TextStyle(
                            fontWeight: FontWeight.w800,
                            fontSize: 14,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),

                const SizedBox(height: 10),
                const Text(
                  'BOQ lines attached to this wall:',
                  style: TextStyle(fontWeight: FontWeight.w800),
                ),
                const SizedBox(height: 8),

                if (rows.isEmpty)
                  const Text('No BOQ lines found (boqCode empty).')
                else
                  ...rows.map((r) {
                    return Card(
                      child: Padding(
                        padding: const EdgeInsets.all(10),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    '${r.type} — ${r.boqCode}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                      fontSize: 13,
                                    ),
                                  ),
                                ),
                                Text(
                                  '${r.qty.toStringAsFixed(3)} ${r.unit}',
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ],
                            ),
                            if (r.boqDesc.trim().isNotEmpty) ...[
                              const SizedBox(height: 6),
                              Text(
                                r.boqDesc,
                                style: const TextStyle(fontSize: 12),
                              ),
                            ],
                            const SizedBox(height: 10),
                            Row(
                              children: [
                                OutlinedButton.icon(
                                  onPressed: () async {
                                    final pick = await showBoqPickerDialog(
                                      context: dCtx,
                                    );
                                    if (pick == null) return;

                                    await changeBoqForLine(
                                      type: r.type,
                                      oldBoqCode: r.boqCode,
                                      newPick: pick,
                                    );

                                    if (dCtx.mounted) {
                                      ScaffoldMessenger.of(dCtx).showSnackBar(
                                        const SnackBar(
                                          content: Text('BOQ updated'),
                                        ),
                                      );
                                    }
                                  },
                                  icon: const Icon(Icons.edit, size: 18),
                                  label: const Text('Change BOQ'),
                                ),
                                const SizedBox(width: 10),
                                OutlinedButton.icon(
                                  onPressed: () async {
                                    final ok = await showDialog<bool>(
                                      context: dCtx,
                                      builder:
                                          (c2) => AlertDialog(
                                            title: const Text('Remove line?'),
                                            content: Text(
                                              'Remove "${r.type} — ${r.boqCode}"?',
                                            ),
                                            actions: [
                                              TextButton(
                                                onPressed:
                                                    () => Navigator.pop(
                                                      c2,
                                                      false,
                                                    ),
                                                child: const Text('Cancel'),
                                              ),
                                              FilledButton(
                                                onPressed:
                                                    () =>
                                                        Navigator.pop(c2, true),
                                                child: const Text('Remove'),
                                              ),
                                            ],
                                          ),
                                    );

                                    if (ok != true) return;

                                    await removeLine(
                                      type: r.type,
                                      boqCode: r.boqCode,
                                    );

                                    if (dCtx.mounted) {
                                      ScaffoldMessenger.of(dCtx).showSnackBar(
                                        const SnackBar(
                                          content: Text('Line removed'),
                                        ),
                                      );
                                    }
                                  },
                                  icon: const Icon(
                                    Icons.delete_outline,
                                    size: 18,
                                  ),
                                  label: const Text('Remove'),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    );
                  }),
              ],
            ),
          );
        }

        // If cachedDocs provided, show immediately; also allow live updates via stream.
        // Best: always stream by wallGroupId so edits reflect instantly.
        return AlertDialog(
          title: const Text('Line details'),
          content: SizedBox(
            width: 760,
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream:
                  measurementsRef
                      .where('lengthGroupId', isEqualTo: wallGroupId)
                      .stateSnapshots(),
              builder: (ctx, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  // show cached while loading (optional)
                  if (cachedDocs != null && cachedDocs!.isNotEmpty) {
                    final docs =
                        cachedDocs!
                            .map((d) => Map<String, dynamic>.from(d.data()))
                            .toList();
                    return buildFromDocs(docs);
                  }
                  return const Padding(
                    padding: EdgeInsets.all(16),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }

                final docs =
                    snap.data!.docs.map((d) {
                      final m = Map<String, dynamic>.from(d.data());
                      m['__id'] = d.id;
                      return m;
                    }).toList();

                return buildFromDocs(docs);
              },
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dCtx),
              child: const Text('Close'),
            ),
          ],
        );
      },
    );
  }

  Future<void> openWallDetailsDialog({
    required String wallGroupId,
    List<QueryDocumentSnapshot<Map<String, dynamic>>>? cachedDocs,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return;

    await showDialog(
      context: ctx,
      barrierDismissible: true,
      builder: (dCtx) {
        Widget buildFromDocs(List<Map<String, dynamic>> docs) {
          if (docs.isEmpty) {
            return const Text('No records found for this wall.');
          }

          // totals
          double totalLenM = 0.0;
          for (final m in docs) {
            // your docs store baseLengthM/lengthM/wallLengthM often equal
            // We'll sum unique segments by segmentId to avoid multiplying lines.
            // simplest: take max length among lines per segmentId.
          }

          // group by segmentId => max baseLengthM
          final segLen = <String, double>{};
          for (final m in docs) {
            final sid = _s(m['segmentId']).trim();
            if (sid.isEmpty) continue;
            final L = _d(m['baseLengthM']);
            if (L <= 0) continue;
            segLen[sid] = math.max(segLen[sid] ?? 0.0, L);
          }
          totalLenM = segLen.values.fold(0.0, (a, b) => a + b);

          // group BOQ lines: (type + boqCode + unit)
          String keyOf(Map<String, dynamic> m) {
            final type = _s(m['type']).trim();
            final code = _s(m['boqCode']).trim();
            final unit = _s(m['unit']).trim();
            return '$type|$code|$unit';
          }

          final grouped = <String, FoundationWallLine>{};

          for (final m in docs) {
            final boqCode = _s(m['boqCode']).trim();
            if (boqCode.isEmpty) continue;

            final type = _s(m['type']).trim();
            final unit = _s(m['unit']).trim();
            final qty = _d(m['value']);
            final desc = _s(m['boqDescription']).trim();

            final k = keyOf(m);
            final prev = grouped[k];
            if (prev == null) {
              grouped[k] = FoundationWallLine(
                type: type,
                boqCode: boqCode,
                boqDesc: desc,
                unit: unit,
                qty: qty,
              );
            } else {
              grouped[k] = FoundationWallLine(
                type: prev.type,
                boqCode: prev.boqCode,
                boqDesc: prev.boqDesc,
                unit: prev.unit,
                qty: prev.qty + qty,
              );
            }
          }

          final rows =
              grouped.values.toList()..sort((a, b) => a.type.compareTo(b.type));

          Future<void> changeBoqForLine({
            required String type,
            required String oldBoqCode,
            required BoqPick newPick,
          }) async {
            final snap =
                await measurementsRef
                    .where('wallGroupId', isEqualTo: wallGroupId)
                    .where('type', isEqualTo: type)
                    .where('boqCode', isEqualTo: oldBoqCode)
                    .get();

            if (snap.docs.isEmpty) return;

            final batch = FirebaseFirestore.instance.batch();
            for (final d in snap.docs) {
              batch.update(d.reference, {
                'boqItemId': newPick.id,
                'boqCode': newPick.code,
                'boqDescription': newPick.description,
                'updatedAt': FieldValue.serverTimestamp(),
              });
            }
            await batch.commit();
          }

          Future<void> removeLine({
            required String type,
            required String boqCode,
          }) async {
            final snap =
                await measurementsRef
                    .where('wallGroupId', isEqualTo: wallGroupId)
                    .where('type', isEqualTo: type)
                    .where('boqCode', isEqualTo: boqCode)
                    .get();

            if (snap.docs.isEmpty) return;

            final batch = FirebaseFirestore.instance.batch();
            for (final d in snap.docs) {
              batch.delete(d.reference);
            }
            await batch.commit();
          }

          return SingleChildScrollView(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Foundation wall group: $wallGroupId',
                          style: const TextStyle(fontSize: 12),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          'Total length: ${totalLenM.toStringAsFixed(3)} m',
                          style: const TextStyle(
                            fontWeight: FontWeight.w800,
                            fontSize: 14,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),

                const SizedBox(height: 10),
                const Text(
                  'BOQ lines attached to this wall:',
                  style: TextStyle(fontWeight: FontWeight.w800),
                ),
                const SizedBox(height: 8),

                if (rows.isEmpty)
                  const Text('No BOQ lines found (boqCode empty).')
                else
                  ...rows.map((r) {
                    return Card(
                      child: Padding(
                        padding: const EdgeInsets.all(10),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    '${r.type} — ${r.boqCode}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                      fontSize: 13,
                                    ),
                                  ),
                                ),
                                Text(
                                  '${r.qty.toStringAsFixed(3)} ${r.unit}',
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ],
                            ),
                            if (r.boqDesc.trim().isNotEmpty) ...[
                              const SizedBox(height: 6),
                              Text(
                                r.boqDesc,
                                style: const TextStyle(fontSize: 12),
                              ),
                            ],
                            const SizedBox(height: 10),
                            Row(
                              children: [
                                OutlinedButton.icon(
                                  onPressed: () async {
                                    final pick = await showBoqPickerDialog(
                                      context: dCtx,
                                    );
                                    if (pick == null) return;

                                    await changeBoqForLine(
                                      type: r.type,
                                      oldBoqCode: r.boqCode,
                                      newPick: pick,
                                    );

                                    if (dCtx.mounted) {
                                      ScaffoldMessenger.of(dCtx).showSnackBar(
                                        const SnackBar(
                                          content: Text('BOQ updated'),
                                        ),
                                      );
                                    }
                                  },
                                  icon: const Icon(Icons.edit, size: 18),
                                  label: const Text('Change BOQ'),
                                ),
                                const SizedBox(width: 10),
                                OutlinedButton.icon(
                                  onPressed: () async {
                                    final ok = await showDialog<bool>(
                                      context: dCtx,
                                      builder:
                                          (c2) => AlertDialog(
                                            title: const Text('Remove line?'),
                                            content: Text(
                                              'Remove "${r.type} — ${r.boqCode}"?',
                                            ),
                                            actions: [
                                              TextButton(
                                                onPressed:
                                                    () => Navigator.pop(
                                                      c2,
                                                      false,
                                                    ),
                                                child: const Text('Cancel'),
                                              ),
                                              FilledButton(
                                                onPressed:
                                                    () =>
                                                        Navigator.pop(c2, true),
                                                child: const Text('Remove'),
                                              ),
                                            ],
                                          ),
                                    );

                                    if (ok != true) return;

                                    await removeLine(
                                      type: r.type,
                                      boqCode: r.boqCode,
                                    );

                                    if (dCtx.mounted) {
                                      ScaffoldMessenger.of(dCtx).showSnackBar(
                                        const SnackBar(
                                          content: Text('Line removed'),
                                        ),
                                      );
                                    }
                                  },
                                  icon: const Icon(
                                    Icons.delete_outline,
                                    size: 18,
                                  ),
                                  label: const Text('Remove'),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    );
                  }),
              ],
            ),
          );
        }

        // If cachedDocs provided, show immediately; also allow live updates via stream.
        // Best: always stream by wallGroupId so edits reflect instantly.
        return AlertDialog(
          title: const Text('wall details'),
          content: SizedBox(
            width: 760,
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream:
                  measurementsRef
                      .where('wallGroupId', isEqualTo: wallGroupId)
                      .stateSnapshots(),
              builder: (ctx, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  // show cached while loading (optional)
                  if (cachedDocs != null && cachedDocs!.isNotEmpty) {
                    final docs =
                        cachedDocs!
                            .map((d) => Map<String, dynamic>.from(d.data()))
                            .toList();
                    return buildFromDocs(docs);
                  }
                  return const Padding(
                    padding: EdgeInsets.all(16),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }

                final docs =
                    snap.data!.docs.map((d) {
                      final m = Map<String, dynamic>.from(d.data());
                      m['__id'] = d.id;
                      return m;
                    }).toList();

                return buildFromDocs(docs);
              },
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dCtx),
              child: const Text('Close'),
            ),
          ],
        );
      },
    );
  }

  Future<void> openFoundationWallingDetailsDialog({
    required BuildContext context,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId,
    required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,
  }) async {
    String _s(dynamic v) => (v ?? '').toString();
    double _d(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    // helper: group key for UI rows
    String _keyOf(Map<String, dynamic> m) {
      final type = _s(m['type']).trim();
      final code = _s(m['boqCode']).trim();
      final unit = _s(m['unit']).trim();
      return '$type|$code|$unit';
    }

    // helper: update BOQ fields for all docs matching (type + old boqCode) in this wallGroupId
    Future<void> _changeBoqForLine({
      required String type,
      required String oldBoqCode,
      required BoqPick newPick,
    }) async {
      final snap =
          await measurementsRef
              .where('wallGroupId', isEqualTo: wallGroupId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: oldBoqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.update(d.reference, {
          'boqItemId': newPick.id,
          'boqCode': newPick.code,
          'boqDescription': newPick.description,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      await b.commit();
    }

    // helper: delete all docs matching (type + boqCode) in this wallGroupId
    Future<void> _removeLine({
      required String type,
      required String boqCode,
    }) async {
      final snap =
          await measurementsRef
              .where('wallGroupId', isEqualTo: wallGroupId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: boqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.delete(d.reference);
      }
      await b.commit();
    }

    await showDialog(
      context: context,
      barrierDismissible: true,
      builder: (ctx) {
        return AlertDialog(
          title: const Text('Wall details'),
          content: SizedBox(
            width: 760,
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream:
                  measurementsRef
                      .where('wallGroupId', isEqualTo: wallGroupId)
                      .stateSnapshots(),
              builder: (ctx, snap) {
                if (snap.hasError) {
                  return Text('Error: ${snap.error}');
                }
                if (!snap.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(20),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }

                final docs =
                    snap.data!.docs.map((e) {
                      final m = Map<String, dynamic>.from(e.data());
                      m['__id'] = e.id;
                      return m;
                    }).toList();

                if (docs.isEmpty) {
                  return const Text(
                    'No wall records found for this wallGroupId.',
                  );
                }

                // ---------------------------
                // 1) compute totals (m2)
                // ---------------------------
                // You can adjust these type names to match your save logic.
                double grossM2 = 0;
                double openingsM2 = 0;
                double netM2 = 0;

                for (final m in docs) {
                  final type = _s(m['type']).toLowerCase().trim();
                  final unit = _s(m['unit']).toLowerCase().trim();
                  final v = _d(m['value']);

                  if (unit == 'm2') {
                    if (type.contains('gross') ||
                        type == 'wallcore' ||
                        type == 'walling') {
                      grossM2 += v;
                    }
                    if (type.contains('opening') || type.contains('deduct')) {
                      openingsM2 += v;
                    }
                  }
                }
                netM2 = (grossM2 - openingsM2).clamp(0.0, double.infinity);

                // ---------------------------
                // 2) group BOQs + qty
                // ---------------------------
                final grouped = <String, Map<String, dynamic>>{};
                for (final m in docs) {
                  final type = _s(m['type']).trim();
                  final boqCode = _s(m['boqCode']).trim();
                  final boqDesc = _s(m['boqDescription']).trim();
                  final unit = _s(m['unit']).trim();
                  final v = _d(m['value']);

                  // skip rows that don’t have BOQ (optional)
                  if (boqCode.isEmpty) continue;

                  final key = _keyOf(m);

                  final g = grouped.putIfAbsent(key, () {
                    return {
                      'type': type,
                      'boqCode': boqCode,
                      'boqDesc': boqDesc,
                      'unit': unit,
                      'qty': 0.0,
                    };
                  });

                  g['qty'] = (_d(g['qty']) + v);
                }

                final rows =
                    grouped.values.toList()
                      ..sort((a, b) => _s(a['type']).compareTo(_s(b['type'])));

                return SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // totals
                      Card(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Wall group: $wallGroupId',
                                style: const TextStyle(fontSize: 12),
                              ),
                              const SizedBox(height: 8),
                              Wrap(
                                spacing: 18,
                                runSpacing: 8,
                                children: [
                                  Text(
                                    'Gross: ${grossM2.toStringAsFixed(3)} m²',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  Text(
                                    'Openings: ${openingsM2.toStringAsFixed(3)} m²',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  Text(
                                    'Net: ${netM2.toStringAsFixed(3)} m²',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ),

                      const SizedBox(height: 10),
                      const Text(
                        'BOQ lines attached to this wall:',
                        style: TextStyle(fontWeight: FontWeight.w800),
                      ),
                      const SizedBox(height: 8),

                      if (rows.isEmpty)
                        const Text('No BOQ lines found (boqCode is empty).')
                      else
                        ...rows.map((r) {
                          final type = _s(r['type']);
                          final boqCode = _s(r['boqCode']);
                          final boqDesc = _s(r['boqDesc']);
                          final unit = _s(r['unit']);
                          final qty = _d(r['qty']);

                          return Card(
                            child: Padding(
                              padding: const EdgeInsets.all(10),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Row(
                                    children: [
                                      Expanded(
                                        child: Text(
                                          '$type — $boqCode',
                                          style: const TextStyle(
                                            fontWeight: FontWeight.w700,
                                            fontSize: 13,
                                          ),
                                        ),
                                      ),
                                      Text(
                                        '${qty.toStringAsFixed(3)} $unit',
                                        style: const TextStyle(
                                          fontWeight: FontWeight.w800,
                                        ),
                                      ),
                                    ],
                                  ),
                                  if (boqDesc.isNotEmpty) ...[
                                    const SizedBox(height: 6),
                                    Text(
                                      boqDesc,
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                  ],
                                  const SizedBox(height: 10),

                                  Row(
                                    children: [
                                      OutlinedButton.icon(
                                        onPressed: () async {
                                          final pick =
                                              await showBoqPickerDialog(ctx);
                                          if (pick == null) return;

                                          await _changeBoqForLine(
                                            type: type,
                                            oldBoqCode: boqCode,
                                            newPick: pick,
                                          );

                                          if (ctx.mounted) {
                                            ScaffoldMessenger.of(
                                              ctx,
                                            ).showSnackBar(
                                              const SnackBar(
                                                content: Text('BOQ updated'),
                                              ),
                                            );
                                          }
                                        },
                                        icon: const Icon(Icons.edit, size: 18),
                                        label: const Text('Change BOQ'),
                                      ),
                                      const SizedBox(width: 10),
                                      OutlinedButton.icon(
                                        onPressed: () async {
                                          final ok = await showDialog<bool>(
                                            context: ctx,
                                            builder:
                                                (_) => AlertDialog(
                                                  title: const Text(
                                                    'Remove line?',
                                                  ),
                                                  content: Text(
                                                    'Remove "$type — $boqCode"?',
                                                  ),
                                                  actions: [
                                                    TextButton(
                                                      onPressed:
                                                          () => Navigator.pop(
                                                            ctx,
                                                            false,
                                                          ),
                                                      child: const Text(
                                                        'Cancel',
                                                      ),
                                                    ),
                                                    FilledButton(
                                                      onPressed:
                                                          () => Navigator.pop(
                                                            ctx,
                                                            true,
                                                          ),
                                                      child: const Text(
                                                        'Remove',
                                                      ),
                                                    ),
                                                  ],
                                                ),
                                          );

                                          if (ok != true) return;

                                          await _removeLine(
                                            type: type,
                                            boqCode: boqCode,
                                          );

                                          if (ctx.mounted) {
                                            ScaffoldMessenger.of(
                                              ctx,
                                            ).showSnackBar(
                                              const SnackBar(
                                                content: Text('Line removed'),
                                              ),
                                            );
                                          }
                                        },
                                        icon: const Icon(
                                          Icons.delete_outline,
                                          size: 18,
                                        ),
                                        label: const Text('Remove'),
                                      ),
                                    ],
                                  ),
                                ],
                              ),
                            ),
                          );
                        }),
                    ],
                  ),
                );
              },
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(ctx),
              child: const Text('Close'),
            ),
          ],
        );
      },
    );
  }

  Future<void> _saveWallingGroupAndOpenings({
    required String wallGroupId,
    required double newHeightM,
    required String newWallBoqCode,
    required List<DoorInput> doors,
    required List<WindowInput> windows,
    required Set<String> deletedOpeningKeys,
    required String wallType, // "internal" | "external"
    required Map<String, String>
    finishes, // plasterBoqCode, plasterDecoBoqCode, renderBoqCode, renderDecoBoqCode
  }) async {
    final fs = FirebaseFirestore.instance;
    final batch = fs.batch();
    final now = FieldValue.serverTimestamp();

    double _num(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    // helper to upsert deterministic docs
    void upsert(String id, Map<String, dynamic> data) {
      batch.set(measurementsRef.doc(id), data, SetOptions(merge: true));
    }

    // helper delete deterministic docs
    void del(String id) => batch.delete(measurementsRef.doc(id));

    final isInternalWall = wallType.toLowerCase().trim() == 'internal';
    final isExternalWall = wallType.toLowerCase().trim() == 'external';

    // ---- finish boq codes ----
    final plasterBoq = (finishes['plasterBoqCode'] ?? '').trim();
    final plasterDecoBoq = (finishes['plasterDecoBoqCode'] ?? '').trim();
    final renderBoq = (finishes['renderBoqCode'] ?? '').trim();
    final renderDecoBoq = (finishes['renderDecoBoqCode'] ?? '').trim();

    // ---- compute opening deductions per face (IMPORTANT) ----
    // rule:
    // - opening scope INTERNAL: deduct internal plaster only
    // - opening scope EXTERNAL: deduct internal plaster + external rendering
    double doorsDeductInternalM2 = 0.0;
    double doorsDeductExternalM2 = 0.0;

    for (final d in doors) {
      final scope = scopeFrom(
        d.scope,
      ); // if you already store enum, replace with d.scope directly
      final a = d.widthM * d.heightM * d.qty.toDouble();
      doorsDeductInternalM2 += a;
      if (scope == OpeningScope.external) doorsDeductExternalM2 += a;
    }

    double windowsDeductInternalM2 = 0.0;
    double windowsDeductExternalM2 = 0.0;

    for (final w in windows) {
      final scope = scopeFrom(w.scope);
      final a = w.widthM * w.heightM * w.qty.toDouble();
      windowsDeductInternalM2 += a;
      if (scope == OpeningScope.external) windowsDeductExternalM2 += a;
    }

    final openingsDeductInternalM2 =
        doorsDeductInternalM2 + windowsDeductInternalM2;
    final openingsDeductExternalM2 =
        doorsDeductExternalM2 + windowsDeductExternalM2;

    // 1) Update wall segments in group + compute gross totals
    double grossLenM = 0.0;

    final wallSnap =
        await measurementsRef
            .where('measureType', isEqualTo: 'walling')
            .where('wallGroupId', isEqualTo: wallGroupId)
            .where('drawingId', isEqualTo: drawingId)
            .get();

    for (final doc in wallSnap.docs) {
      final m = doc.data();
      final baseLen = _num(m['baseLengthM']);
      grossLenM += baseLen;

      final newArea = baseLen * newHeightM;

      batch.update(doc.reference, {
        'heightM': newHeightM,
        'boqCode': newWallBoqCode,
        'unit': 'm2',
        'value': newArea,

        // store group configuration so you can reopen easily
        'wallType': wallType,
        'finishes': finishes,

        'updatedAt': now,
      });
    }

    final grossAreaM2 = grossLenM * newHeightM;

    // ---- FINISH QTY LOGIC (your rules) ----
    // internal wall: plaster + internal decoration = 2 faces
    // external wall: plaster inside = 1 face, render outside = 1 face (+ render deco)
    double plasterQtyM2 = 0.0;
    double plasterDecoQtyM2 = 0.0;
    double renderQtyM2 = 0.0;
    double renderDecoQtyM2 = 0.0;

    if (isInternalWall) {
      // two faces, openings pass through => deduct both faces
      final grossTwoFaces = grossAreaM2 * 2;
      final deductTwoFaces = openingsDeductInternalM2 * 2;

      plasterQtyM2 = (grossTwoFaces - deductTwoFaces).clamp(
        0.0,
        double.infinity,
      );
      plasterDecoQtyM2 = plasterQtyM2; // internal decoration follows plaster
      // render remains 0
    } else if (isExternalWall) {
      // inside plaster face (deduct ALL openings on this wall: internal + external)
      plasterQtyM2 = (grossAreaM2 - openingsDeductInternalM2).clamp(
        0.0,
        double.infinity,
      );

      // outside render face (deduct ONLY openings marked external)
      renderQtyM2 = (grossAreaM2 - openingsDeductExternalM2).clamp(
        0.0,
        double.infinity,
      );
      renderDecoQtyM2 = renderQtyM2;

      plasterDecoQtyM2 = 0.0; // not used for external per your spec
    }

    // Net area “walling” (single face) for reference/audit
    final netWallFaceM2 = (grossAreaM2 - openingsDeductInternalM2).clamp(
      0.0,
      double.infinity,
    );

    // 1b) Save group meta doc (totals + audit)
    upsert('$wallGroupId-meta', {
      'type': 'wallGroupMeta',
      'measureType': 'wallingGroup',
      'wallGroupId': wallGroupId,
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,

      'wallType': wallType,
      'wallBoqCode': newWallBoqCode,
      'heightM': newHeightM,

      'grossLengthM': grossLenM,
      'grossAreaM2': grossAreaM2,

      // deductions
      'openingsDeductInternalM2': openingsDeductInternalM2,
      'openingsDeductExternalM2': openingsDeductExternalM2,

      // reference "net wall face" (inside face for external, single-face for internal ref)
      'netWallFaceM2': netWallFaceM2,

      // finish quantities (these are the important totals)
      'plasterQtyM2': plasterQtyM2,
      'plasterDecoQtyM2': plasterDecoQtyM2,
      'renderQtyM2': renderQtyM2,
      'renderDecoQtyM2': renderDecoQtyM2,

      'finishes': finishes,

      'unit': 'group',
      'value': 1,
      'updatedAt': now,
      'createdAt': now,
    });

    // Optional: computed docs for easy querying in summaries
    upsert('$wallGroupId-computed-plaster', {
      'type': 'wallComputed',
      'measureType': 'wallingComputed',
      'wallGroupId': wallGroupId,
      'kind': 'plaster',
      'unit': 'm2',
      'value': plasterQtyM2,
      'boqCode': plasterBoq,
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,
      'wallType': wallType,
      'updatedAt': now,
      'createdAt': now,
    });

    upsert('$wallGroupId-computed-render', {
      'type': 'wallComputed',
      'measureType': 'wallingComputed',
      'wallGroupId': wallGroupId,
      'kind': 'render',
      'unit': 'm2',
      'value': renderQtyM2,
      'boqCode': renderBoq,
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,
      'wallType': wallType,
      'updatedAt': now,
      'createdAt': now,
    });

    // 2) Delete removed openings (chunk whereIn by 10)
    if (deletedOpeningKeys.isNotEmpty) {
      final keys = deletedOpeningKeys.toList();
      for (int i = 0; i < keys.length; i += 10) {
        final chunk = keys.sublist(
          i,
          (i + 10 > keys.length) ? keys.length : i + 10,
        );

        final delSnap =
            await measurementsRef
                .where('measureType', isEqualTo: 'wallingOpening')
                .where('wallGroupId', isEqualTo: wallGroupId)
                .where('drawingId', isEqualTo: drawingId)
                .where('openingKey', whereIn: chunk)
                .get();

        for (final doc in delSnap.docs) {
          batch.delete(doc.reference);
        }
      }
    }

    // 3) Save doors (components)
    for (final d in doors) {
      final openingKey = (d.openingKey ?? measurementsRef.doc().id).trim();
      d.openingKey = openingKey;

      final width = d.widthM;
      final height = d.heightM;
      final qty = d.qty;
      final leafCount = d.leafCount == 2 ? 2 : 1;
      final shutterQty = qty * (d.shutterBoqPerLeaf ? leafCount : 1);

      final areaM2 = width * height * qty.toDouble();
      final scope = scopeFrom(d.scope);
      final deductInternalM2 =
          areaM2; // both internal+external openings deduct internal plaster
      final deductExternalM2 = (scope == OpeningScope.external) ? areaM2 : 0.0;

      // Frame rule (no sill): 2H + W
      final frameLM = (2 * height + width) * qty.toDouble();
      final transomLM = width * qty.toDouble();
      final archLM =
          (2 * height + width) * d.architraveSides.toDouble() * qty.toDouble();

      final meta = <String, dynamic>{
        'measureType': 'wallingOpening',
        'openingKind': 'door',
        'openingKey': openingKey,
        'wallGroupId': wallGroupId,
        'scope': scopeName(scope),

        'name': d.name,
        'widthM': width,
        'heightM': height,
        'qty': qty,
        'doorLeafCount': leafCount,
        'doorArrangement': leafCount == 2 ? 'doubleSwing' : 'single',
        'shutterBoqPerLeaf': d.shutterBoqPerLeaf,
        'ironmongeryPerLeaf': d.ironmongeryPerLeaf,

        'boqShutter': d.boqShutter,
        'boqFrame': d.boqFrame,
        'boqTransom': d.boqTransom,
        'boqArchitrave': d.boqArchitrave,
        'includeTransom': d.includeTransom,
        'includeArchitrave': d.includeArchitrave,
        'architraveSides': d.architraveSides,

        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'wallType': wallType,
        'updatedAt': now,
        'createdAt': now,
      };

      // Deduction
      upsert('$openingKey-ded', {
        ...meta,
        'type': 'openingDeduction',
        'component': 'deduction',
        'unit': 'm2',
        'value': areaM2,
        'deductInternalM2': deductInternalM2,
        'deductExternalM2': deductExternalM2,
        'boqCode': '',
      });

      // Shutter (No.)
      upsert('$openingKey-shutter', {
        ...meta,
        'type': 'doorShutter',
        'component': 'shutter',
        'unit': 'No.',
        'value': shutterQty,
        'boqCode': d.boqShutter,
        'quantityBasis': d.shutterBoqPerLeaf ? 'perLeaf' : 'perOpening',
        'sizeLabel':
            '${width.toStringAsFixed(2)} x ${height.toStringAsFixed(2)} m',
      });

      // Frame (m)
      upsert('$openingKey-frame', {
        ...meta,
        'type': 'doorFrame',
        'component': 'frame',
        'unit': 'm',
        'value': frameLM,
        'boqCode': d.boqFrame,
      });

      // Transom optional (m)
      if (d.includeTransom && d.boqTransom.trim().isNotEmpty) {
        upsert('$openingKey-transom', {
          ...meta,
          'type': 'doorTransom',
          'component': 'transom',
          'unit': 'm',
          'value': transomLM,
          'boqCode': d.boqTransom.trim(),
        });
      } else {
        // optional: delete if existed
        // del('$openingKey-transom');
      }

      // Architrave optional (m)
      if (d.includeArchitrave && d.boqArchitrave.trim().isNotEmpty) {
        upsert('$openingKey-arch', {
          ...meta,
          'type': 'doorArchitrave',
          'component': 'architrave',
          'unit': 'm',
          'value': archLM,
          'boqCode': d.boqArchitrave.trim(),
        });
      } else {
        // optional: delete if existed
        // del('$openingKey-arch');
      }

      for (final item in d.ironmongery) {
        final itemKey = (item['key'] ?? '').toString().trim();
        final boqCode = (item['boqCode'] ?? '').toString().trim();
        if (itemKey.isEmpty || boqCode.isEmpty) continue;
        final perDoorQty =
            item['qty'] is num
                ? (item['qty'] as num).toDouble()
                : double.tryParse('${item['qty']}') ?? 1.0;
        final multiplier = d.ironmongeryPerLeaf ? leafCount : 1;
        upsert('$openingKey-iron-$itemKey', {
          ...meta,
          'type': 'ironmongery',
          'component': 'ironmongery',
          'ironmongeryKey': itemKey,
          'label': (item['title'] ?? 'Door ironmongery').toString(),
          'unit': (item['unit'] ?? 'item').toString(),
          'value': perDoorQty * qty * multiplier,
          'boqCode': boqCode,
          'boqItemId': (item['boqItemId'] ?? '').toString().trim(),
          'quantityPerDoor': perDoorQty,
          'doorLeafCount': leafCount,
          'quantityBasis': d.ironmongeryPerLeaf ? 'perLeaf' : 'perOpening',
        });
      }
    }

    // 4) Save windows (m2) + deductions
    for (final w in windows) {
      final openingKey = (w.openingKey ?? measurementsRef.doc().id).trim();
      w.openingKey = openingKey;

      final areaM2 = w.widthM * w.heightM * w.qty.toDouble();
      final scope = scopeFrom(w.scope);
      final deductInternalM2 = areaM2;
      final deductExternalM2 = (scope == OpeningScope.external) ? areaM2 : 0.0;

      // Main window area doc (you may treat this as opening record)
      upsert('$openingKey-window', {
        'type': 'windowArea',
        'measureType': 'wallingOpening',
        'openingKind': 'window',
        'component': 'window',
        'openingKey': openingKey,
        'wallGroupId': wallGroupId,
        'scope': scopeName(scope),

        'name': w.name,
        'widthM': w.widthM,
        'heightM': w.heightM,
        'qty': w.qty,

        'unit': 'm2',
        'value': areaM2,
        'boqCode': w.boqCode,

        // ✅ save face deductions for audit
        'deductInternalM2': deductInternalM2,
        'deductExternalM2': deductExternalM2,

        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'wallType': wallType,
        'updatedAt': now,
        'createdAt': now,
      });

      // Optional: also create a separate deterministic deduction doc (if you prefer)
      upsert('$openingKey-window-ded', {
        'type': 'openingDeduction',
        'measureType': 'wallingOpening',
        'openingKind': 'window',
        'component': 'deduction',
        'openingKey': openingKey,
        'wallGroupId': wallGroupId,
        'scope': scopeName(scope),
        'unit': 'm2',
        'value': areaM2,
        'deductInternalM2': deductInternalM2,
        'deductExternalM2': deductExternalM2,
        'boqCode': '',
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'wallType': wallType,
        'updatedAt': now,
        'createdAt': now,
      });
    }

    // 5) FINISH docs (deterministic ids)
    Map<String, dynamic> finishMeta({
      required String finishType,
      required String boqCode,
      required double qtyM2,
    }) {
      return {
        'type': 'wallFinish',
        'measureType': 'wallingFinish',
        'wallGroupId': wallGroupId,
        'finishType': finishType,

        'boqCode': boqCode,
        'unit': 'm2',
        'value': qtyM2,

        // audit
        'grossAreaM2': grossAreaM2,
        'openingsDeductInternalM2': openingsDeductInternalM2,
        'openingsDeductExternalM2': openingsDeductExternalM2,

        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'wallType': wallType,
        'updatedAt': now,
        'createdAt': now,
      };
    }

    final finishPlasterId = '$wallGroupId-finish-plaster';
    final finishPlasterDecoId = '$wallGroupId-finish-plasterDeco';
    final finishRenderId = '$wallGroupId-finish-render';
    final finishRenderDecoId = '$wallGroupId-finish-renderDeco';

    if (isInternalWall) {
      upsert(
        finishPlasterId,
        finishMeta(
          finishType: 'plaster',
          boqCode: plasterBoq,
          qtyM2: plasterQtyM2,
        ),
      );

      upsert(
        finishPlasterDecoId,
        finishMeta(
          finishType: 'plasterDeco',
          boqCode: plasterDecoBoq,
          qtyM2: plasterDecoQtyM2,
        ),
      );

      del(finishRenderId);
      del(finishRenderDecoId);
    } else if (isExternalWall) {
      upsert(
        finishPlasterId,
        finishMeta(
          finishType: 'plaster_inside',
          boqCode: plasterBoq,
          qtyM2: plasterQtyM2,
        ),
      );

      upsert(
        finishRenderId,
        finishMeta(
          finishType: 'render_outside',
          boqCode: renderBoq,
          qtyM2: renderQtyM2,
        ),
      );

      upsert(
        finishRenderDecoId,
        finishMeta(
          finishType: 'renderDeco_outside',
          boqCode: renderDecoBoq,
          qtyM2: renderDecoQtyM2,
        ),
      );

      del(finishPlasterDecoId);
    } else {
      // unknown wallType => remove all finish docs
      del(finishPlasterId);
      del(finishPlasterDecoId);
      del(finishRenderId);
      del(finishRenderDecoId);
    }

    await batch.commit();
  }

  Future<DoorInput?> _editDoorDialog({DoorInput? existing}) async {
    final nameCtrl = TextEditingController(text: existing?.name ?? 'D01 Door');
    final wCtrl = TextEditingController(
      text: (existing?.widthM ?? 0.9).toString(),
    );
    final hCtrl = TextEditingController(
      text: (existing?.heightM ?? 2.1).toString(),
    );
    final qtyCtrl = TextEditingController(
      text: (existing?.qty ?? 1).toString(),
    );
    int leafCount = existing?.leafCount == 2 ? 2 : 1;
    bool shutterBoqPerLeaf = existing?.shutterBoqPerLeaf ?? false;
    bool ironmongeryPerLeaf = existing?.ironmongeryPerLeaf ?? false;

    // ✅ NEW: internal/external scope
    String scope =
        (existing is dynamic && existing?.scope != null)
            ? (existing!.scope ?? 'internal').toString()
            : 'internal';

    // ✅ opening key safe for Add
    final openingKey =
        (existing?.openingKey.trim().isNotEmpty == true)
            ? existing!.openingKey
            : measurementsRef.doc().id;

    // --- Main door BOQs ---
    String boqShutter = existing?.boqShutter ?? '';
    String boqShutterId =
        (existing is dynamic) ? (existing?.boqShutterId ?? '') : '';
    String boqShutterDesc = '';

    String boqFrame = existing?.boqFrame ?? '';
    String boqFrameId =
        (existing is dynamic) ? (existing?.boqFrameId ?? '') : '';
    String boqFrameDesc = '';

    String boqTransom = existing?.boqTransom ?? '';
    String boqTransomId =
        (existing is dynamic) ? (existing?.boqTransomId ?? '') : '';
    String boqTransomDesc = '';

    String boqArch = existing?.boqArchitrave ?? '';
    String boqArchId =
        (existing is dynamic) ? (existing?.boqArchitraveId ?? '') : '';
    String boqArchDesc = '';

    bool includeTransom = existing?.includeTransom ?? false;
    bool includeArch = existing?.includeArchitrave ?? false;
    int sides = existing?.architraveSides ?? 2;

    // --- NEW door parts ---
    String boqFrameDecor =
        (existing is dynamic) ? (existing?.boqFrameDecor ?? '') : '';
    String boqFrameDecorId =
        (existing is dynamic) ? (existing?.boqFrameDecorId ?? '') : '';
    String boqFrameDecorDesc = '';

    String boqDoorShutterPanel =
        (existing is dynamic) ? (existing?.boqDoorShutterPanel ?? '') : '';
    String boqDoorShutterPanelId =
        (existing is dynamic) ? (existing?.boqDoorShutterPanelId ?? '') : '';
    String boqDoorShutterPanelDesc = '';

    bool includeDoorGrill =
        (existing is dynamic) ? (existing?.includeDoorGrill ?? false) : false;
    String boqDoorGrill =
        (existing is dynamic) ? (existing?.boqDoorGrill ?? '') : '';
    String boqDoorGrillId =
        (existing is dynamic) ? (existing?.boqDoorGrillId ?? '') : '';
    String boqDoorGrillDesc = '';

    // Ironmongery list
    List<Map<String, dynamic>> iron =
        (existing is dynamic && existing?.ironmongery != null)
            ? List<Map<String, dynamic>>.from(existing!.ironmongery)
            : <Map<String, dynamic>>[];

    Future<void> pickBoq(void Function(BoqPick p) apply) async {
      final pick = await showBoqPickerDialog(context: Get.context!);
      if (pick == null) return;
      apply(pick);
    }

    // ---- ironmongery editor stays same ----
    Future<Map<String, dynamic>?> _editIronItem({
      Map<String, dynamic>? existingItem,
    }) async {
      final titleCtrl = TextEditingController(
        text: (existingItem?['title'] ?? '').toString(),
      );
      final qtyCtrl2 = TextEditingController(
        text: (existingItem?['qty'] ?? 1).toString(),
      );
      final unitCtrl = TextEditingController(
        text: (existingItem?['unit'] ?? 'item').toString(),
      );

      String code = (existingItem?['boqCode'] ?? '').toString();
      String id = (existingItem?['boqItemId'] ?? '').toString();
      String desc = '';

      final res = await Get.dialog<Map<String, dynamic>>(
        StatefulBuilder(
          builder: (ctx, setState) {
            return AlertDialog(
              title: Text(
                existingItem == null ? 'Add ironmongery' : 'Edit ironmongery',
              ),
              content: SizedBox(
                width: 520,
                child: SingleChildScrollView(
                  child: Column(
                    children: [
                      TextField(
                        controller: titleCtrl,
                        decoration: const InputDecoration(
                          labelText: 'Item title (e.g. Lockset)',
