                      desc: boqDoorShutterPanelDesc,
                      onPick: () async {
                        await pickBoq((p) {
                          setState(() {
                            boqDoorShutterPanel = p.code;
                            boqDoorShutterPanelId = p.id;
                            boqDoorShutterPanelDesc = p.description;
                          });
                        });
                      },
                      onClear:
                          () => setState(() {
                            boqDoorShutterPanel = '';
                            boqDoorShutterPanelId = '';
                            boqDoorShutterPanelDesc = '';
                          }),
                    ),

                    const Divider(height: 22),

                    CheckboxListTile(
                      value: includeTransom,
                      onChanged:
                          (v) => setState(() => includeTransom = v ?? false),
                      title: const Text('Include transom (m)'),
                      contentPadding: EdgeInsets.zero,
                    ),
                    if (includeTransom)
                      boqPickRow(
                        context: ctx,
                        title: 'Transom (m)',
                        code: boqTransom,
                        desc: boqTransomDesc,
                        onPick: () async {
                          await pickBoq((p) {
                            setState(() {
                              boqTransom = p.code;
                              boqTransomId = p.id;
                              boqTransomDesc = p.description;
                            });
                          });
                        },
                        onClear:
                            () => setState(() {
                              boqTransom = '';
                              boqTransomId = '';
                              boqTransomDesc = '';
                            }),
                      ),

                    const Divider(height: 22),

                    CheckboxListTile(
                      value: includeArch,
                      onChanged:
                          (v) => setState(() => includeArch = v ?? false),
                      title: const Text('Include architrave (m)'),
                      contentPadding: EdgeInsets.zero,
                    ),
                    if (includeArch) ...[
                      boqPickRow(
                        context: ctx,
                        title: 'Architrave (m)',
                        code: boqArch,
                        desc: boqArchDesc,
                        onPick: () async {
                          await pickBoq((p) {
                            setState(() {
                              boqArch = p.code;
                              boqArchId = p.id;
                              boqArchDesc = p.description;
                            });
                          });
                        },
                        onClear:
                            () => setState(() {
                              boqArch = '';
                              boqArchId = '';
                              boqArchDesc = '';
                            }),
                      ),
                      const SizedBox(height: 8),
                      Row(
                        children: [
                          const Text('Sides:'),
                          const SizedBox(width: 12),
                          DropdownButton<int>(
                            value: sides,
                            items: const [
                              DropdownMenuItem(value: 1, child: Text('1 side')),
                              DropdownMenuItem(
                                value: 2,
                                child: Text('2 sides'),
                              ),
                            ],
                            onChanged: (v) => setState(() => sides = v ?? 2),
                          ),
                        ],
                      ),
                    ],

                    const Divider(height: 22),

                    CheckboxListTile(
                      value: includeDoorGrill,
                      onChanged:
                          (v) => setState(() => includeDoorGrill = v ?? false),
                      title: const Text('Include metal grill (m²)'),
                      contentPadding: EdgeInsets.zero,
                    ),
                    if (includeDoorGrill)
                      boqPickRow(
                        context: ctx,
                        title: 'Door grill (m²)',
                        code: boqDoorGrill,
                        desc: boqDoorGrillDesc,
                        onPick: () async {
                          await pickBoq((p) {
                            setState(() {
                              boqDoorGrill = p.code;
                              boqDoorGrillId = p.id;
                              boqDoorGrillDesc = p.description;
                            });
                          });
                        },
                        onClear:
                            () => setState(() {
                              boqDoorGrill = '';
                              boqDoorGrillId = '';
                              boqDoorGrillDesc = '';
                            }),
                      ),

                    const Divider(height: 22),

                    // --- ironmongery list ---
                    Row(
                      children: [
                        const Expanded(
                          child: Text(
                            'Ironmongery (optional)',
                            style: TextStyle(fontWeight: FontWeight.w700),
                          ),
                        ),
                        TextButton(
                          onPressed: () async {
                            final m = await _editIronItem();
                            if (m == null) return;
                            setState(() => iron = [...iron, m]);
                          },
                          child: const Text('+ Add'),
                        ),
                      ],
                    ),
                    if (iron.isEmpty)
                      const Align(
                        alignment: Alignment.centerLeft,
                        child: Text(
                          'No ironmongery added',
                          style: TextStyle(fontSize: 12),
                        ),
                      )
                    else
                      ...iron.map((m) {
                        final title = (m['title'] ?? '').toString();
                        final unit = (m['unit'] ?? '').toString();
                        final qv = (m['qty'] ?? 0).toString();
                        final bc = (m['boqCode'] ?? '').toString();
                        return ListTile(
                          dense: true,
                          contentPadding: EdgeInsets.zero,
                          title: Text(title),
                          subtitle: Text('Qty: $qv $unit   |   BOQ: $bc'),
                          trailing: Wrap(
                            spacing: 8,
                            children: [
                              IconButton(
                                icon: const Icon(Icons.edit),
                                onPressed: () async {
                                  final edited = await _editIronItem(
                                    existingItem: m,
                                  );
                                  if (edited == null) return;
                                  setState(() {
                                    iron =
                                        iron
                                            .map(
                                              (x) =>
                                                  (x['key'] == m['key'])
                                                      ? edited
                                                      : x,
                                            )
                                            .toList();
                                  });
                                },
                              ),
                              IconButton(
                                icon: const Icon(Icons.delete),
                                onPressed:
                                    () => setState(() {
                                      iron =
                                          iron
                                              .where(
                                                (x) => x['key'] != m['key'],
                                              )
                                              .toList();
                                    }),
                              ),
                            ],
                          ),
                        );
                      }),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(result: null),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () {
                  final width = double.tryParse(wCtrl.text.trim()) ?? 0.9;
                  final height = double.tryParse(hCtrl.text.trim()) ?? 2.1;
                  final q = int.tryParse(qtyCtrl.text.trim()) ?? 1;

                  if (width <= 0 || height <= 0 || q <= 0) {
                    Get.snackbar('Invalid', 'Check width/height/qty');
                    return;
                  }

                  Get.back(
                    result: DoorInput(
                      openingKey: openingKey,
                      name:
                          nameCtrl.text.trim().isEmpty
                              ? 'Door'
                              : nameCtrl.text.trim(),
                      widthM: width,
                      heightM: height,
                      qty: q,
                      leafCount: leafCount,
                      shutterBoqPerLeaf: shutterBoqPerLeaf,
                      ironmongeryPerLeaf: ironmongeryPerLeaf,

                      // ✅ NEW
                      scope: scope, // "internal" or "external"

                      boqShutter: boqShutter,
                      boqFrame: boqFrame,
                      boqTransom: boqTransom,
                      boqArchitrave: boqArch,

                      boqShutterId: boqShutterId,
                      boqFrameId: boqFrameId,
                      boqTransomId: boqTransomId,
                      boqArchitraveId: boqArchId,

                      includeTransom: includeTransom,
                      includeArchitrave: includeArch,
                      architraveSides: sides,

                      boqFrameDecor: boqFrameDecor,
                      boqDoorShutterPanel: boqDoorShutterPanel,
                      includeDoorGrill: includeDoorGrill,
                      boqDoorGrill: boqDoorGrill,

                      boqFrameDecorId: boqFrameDecorId,
                      boqDoorShutterPanelId: boqDoorShutterPanelId,
                      boqDoorGrillId: boqDoorGrillId,

                      ironmongery: iron,
                    ),
                  );
                },
                child: const Text('OK'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    nameCtrl.dispose();
    wCtrl.dispose();
    hCtrl.dispose();
    qtyCtrl.dispose();
    return result;
  }

  Future<WindowInput?> _editWindowDialog({WindowInput? existing}) async {
    final name = TextEditingController(text: existing?.name ?? 'W01 Window');
    final w = TextEditingController(text: (existing?.widthM ?? 1.2).toString());
    final h = TextEditingController(
      text: (existing?.heightM ?? 1.2).toString(),
    );
    final qty = TextEditingController(text: (existing?.qty ?? 1).toString());

    // ✅ FIX: opening key safe for Add
    final openingKey =
        (existing?.openingKey.trim().isNotEmpty == true)
            ? existing!.openingKey
            : measurementsRef.doc().id;

    // ✅ NEW: internal/external scope
    String scope =
        (existing is dynamic && existing?.scope != null)
            ? (existing!.scope ?? 'internal').toString()
            : 'internal';

    // BOQ
    String boq = existing?.boqCode ?? '';
    String boqDesc = '';

    Future<void> _pickBoq(StateSetter setState) async {
      final pick = await showBoqPickerDialog(context: Get.context!);
      if (pick == null) return;
      setState(() {
        boq = pick.code.trim();
        boqDesc = pick.description.trim();
      });
    }

    final result = await Get.dialog<WindowInput>(
      StatefulBuilder(
        builder: (context, setState) {
          return AlertDialog(
            title: Text(existing == null ? 'Add window' : 'Edit window'),
            content: SizedBox(
              width: 520,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    // ✅ NEW: internal/external selector
                    Align(
                      alignment: Alignment.centerLeft,
                      child: Text(
                        'Window location',
                        style: TextStyle(
                          fontWeight: FontWeight.w700,
                          color: Theme.of(context).colorScheme.onSurface,
                        ),
                      ),
                    ),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        Expanded(
                          child: RadioListTile<String>(
                            dense: true,
                            contentPadding: EdgeInsets.zero,
                            value: 'internal',
                            groupValue: scope,
                            title: const Text('Internal'),
                            onChanged:
                                (v) => setState(() => scope = v ?? 'internal'),
                          ),
                        ),
                        Expanded(
                          child: RadioListTile<String>(
                            dense: true,
                            contentPadding: EdgeInsets.zero,
                            value: 'external',
                            groupValue: scope,
                            title: const Text('External'),
                            onChanged:
                                (v) => setState(() => scope = v ?? 'internal'),
                          ),
                        ),
                      ],
                    ),

                    const Divider(height: 22),

                    TextField(
                      controller: name,
                      decoration: const InputDecoration(
                        labelText: 'Window name',
                      ),
                    ),
                    const SizedBox(height: 8),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: w,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Width (m)',
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: TextField(
                            controller: h,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Height (m)',
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: qty,
                      keyboardType: TextInputType.number,
                      decoration: const InputDecoration(labelText: 'Qty (No.)'),
                    ),

                    const SizedBox(height: 14),

                    // ✅ BOQ picker row
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            readOnly: true,
                            controller: TextEditingController(text: boq),
                            decoration: const InputDecoration(
                              labelText: 'Window BOQ code (m²)',
                              border: OutlineInputBorder(),
                              isDense: true,
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        OutlinedButton.icon(
                          onPressed: () => _pickBoq(setState),
                          icon: const Icon(Icons.search, size: 18),
                          label: const Text('Pick'),
                        ),
                        const SizedBox(width: 6),
                        IconButton(
                          tooltip: 'Clear',
                          onPressed:
                              () => setState(() {
                                boq = '';
                                boqDesc = '';
                              }),
                          icon: const Icon(Icons.clear),
                        ),
                      ],
                    ),
                    if (boqDesc.trim().isNotEmpty) ...[
                      const SizedBox(height: 8),
                      Align(
                        alignment: Alignment.centerLeft,
                        child: Text(
                          boqDesc,
                          style: const TextStyle(fontSize: 12),
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(result: null),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () {
                  final width = double.tryParse(w.text.trim()) ?? 1.2;
                  final height = double.tryParse(h.text.trim()) ?? 1.2;
                  final q = int.tryParse(qty.text.trim()) ?? 1;

                  if (name.text.trim().isEmpty) {
                    Get.snackbar('Missing', 'Enter window name');
                    return;
                  }
                  if (width <= 0 || height <= 0 || q <= 0) {
                    Get.snackbar('Invalid', 'Check width/height/qty');
                    return;
                  }

                  Get.back(
                    result: WindowInput(
                      openingKey: openingKey,
                      name: name.text.trim(),
                      widthM: width,
                      heightM: height,
                      qty: q,
                      boqCode: boq.trim(),

                      // ✅ NEW
                      scope: scope, // "internal" | "external"
                    ),
                  );
                },
                child: const Text('OK'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    name.dispose();
    w.dispose();
    h.dispose();
    qty.dispose();
    return result;
  }

  Future<void> _showWallingSingleSegmentDialog(
    String id,
    Map<String, dynamic> m,
  ) async {
    double _num(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    final len = _num(m['baseLengthM']);
    final h = _num(m['heightM']);
    double grossArea = _num(m['value']);
    final label = (m['label'] ?? '').toString();

    if (grossArea == 0 && len > 0 && h > 0) {
      grossArea = len * h;
    }

    // 👇 fallback group id for legacy segment (so openings can attach)
    final legacyGroupId = id;

    // Load existing openings
    final openSnap =
        await measurementsRef
            .where('drawingId', isEqualTo: drawingId)
            .where('measureType', isEqualTo: 'wallingOpening')
            .where('wallGroupId', isEqualTo: legacyGroupId)
            .get();

    final doors = <DoorInput>[];
    final windows = <WindowInput>[];

    final byKey = <String, List<Map<String, dynamic>>>{};
    for (final d in openSnap.docs) {
      final data = d.data();
      final key = (data['openingKey'] ?? '').toString().trim();
      if (key.isEmpty) continue;
      byKey.putIfAbsent(key, () => []).add({...data, '_id': d.id});
    }

    for (final e in byKey.entries) {
      final key = e.key;
      final list = e.value;
      final kind = (list.first['openingKind'] ?? '').toString();

      if (kind == 'door') {
        final any = list.first;
        doors.add(
          DoorInput(
            openingKey: key,
            scope: 'internal',
            name: (any['name'] ?? 'Door').toString(),
            widthM:
                (any['widthM'] is num)
                    ? (any['widthM'] as num).toDouble()
                    : 0.9,
            heightM:
                (any['heightM'] is num)
                    ? (any['heightM'] as num).toDouble()
                    : 2.1,
            qty: (any['qty'] is num) ? (any['qty'] as num).toInt() : 1,
            leafCount:
                (any['doorLeafCount'] is num &&
                        (any['doorLeafCount'] as num).toInt() == 2)
                    ? 2
                    : 1,
            shutterBoqPerLeaf: any['shutterBoqPerLeaf'] == true,
            ironmongeryPerLeaf: any['ironmongeryPerLeaf'] == true,
            boqShutter: (any['boqShutter'] ?? '').toString(),
            boqFrame: (any['boqFrame'] ?? '').toString(),
            boqTransom: (any['boqTransom'] ?? '').toString(),
            boqArchitrave: (any['boqArchitrave'] ?? '').toString(),
            includeTransom: (any['includeTransom'] == true),
            includeArchitrave: (any['includeArchitrave'] == true),
            architraveSides:
                (any['architraveSides'] is num)
                    ? (any['architraveSides'] as num).toInt()
                    : 2,
            ironmongery:
                list
                    .where(
                      (row) =>
                          (row['component'] ?? '').toString() == 'ironmongery',
                    )
                    .map(
                      (row) => <String, dynamic>{
                        'key':
                            (row['ironmongeryKey'] ?? row['_id'] ?? '')
                                .toString(),
                        'title':
                            (row['label'] ?? 'Door ironmongery').toString(),
                        'qty':
                            row['quantityPerDoor'] is num
                                ? row['quantityPerDoor']
                                : 1,
                        'unit': (row['unit'] ?? 'item').toString(),
                        'boqCode': (row['boqCode'] ?? '').toString(),
                        'boqItemId': (row['boqItemId'] ?? '').toString(),
                      },
                    )
                    .toList(),
          ),
        );
      } else if (kind == 'window') {
        final any = list.first;
        windows.add(
          WindowInput(
            openingKey: key,
            scope: 'internal',
            name: (any['name'] ?? 'Window').toString(),
            widthM:
                (any['widthM'] is num)
                    ? (any['widthM'] as num).toDouble()
                    : 1.2,
            heightM:
                (any['heightM'] is num)
                    ? (any['heightM'] as num).toDouble()
                    : 1.2,
            qty: (any['qty'] is num) ? (any['qty'] as num).toInt() : 1,
            boqCode: (any['boqCode'] ?? '').toString(),
          ),
        );
      }
    }

    double doorsArea() =>
        doors.fold(0.0, (s, d) => s + (d.widthM * d.heightM * d.qty));
    double windowsArea() =>
        windows.fold(0.0, (s, w) => s + (w.widthM * w.heightM * w.qty));
    double openingsArea() => doorsArea() + windowsArea();
    double netArea() =>
        (grossArea - openingsArea()).clamp(0.0, double.infinity);

    final deletedKeys = <String>{};
    Offset dialogOffset = const Offset(24, 80); // initial position (tweak)

    final save = await Get.dialog<bool>(
      StatefulBuilder(
        builder: (ctx, setState) {
          final size = MediaQuery.of(ctx).size;

          const dialogWidth = 520.0;
          // approximate height; we clamp so it doesn't go off screen too far
          const minTopPadding = 24.0;
          const minLeftPadding = 12.0;
          const bottomPadding = 24.0;

          // Clamp X within screen
          final maxLeft = (size.width - dialogWidth - minLeftPadding).clamp(
            0.0,
            double.infinity,
          );
          final left = dialogOffset.dx.clamp(minLeftPadding, maxLeft);

          // Clamp Y within screen (allow some freedom, but keep it usable)
          final maxTop = (size.height - 220.0 - bottomPadding).clamp(
            minTopPadding,
            double.infinity,
          );
          final top = dialogOffset.dy.clamp(minTopPadding, maxTop);

          return Material(
            type: MaterialType.transparency,
            child: Stack(
              children: [
                Positioned(
                  left: left,
                  top: top,
                  child: Material(
                    elevation: 10,
                    borderRadius: BorderRadius.circular(14),
                    clipBehavior: Clip.antiAlias,
                    child: SizedBox(
                      width: dialogWidth,
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          // ✅ DRAG HEADER (only drag from here)
                          GestureDetector(
                            behavior: HitTestBehavior.opaque,
                            onPanUpdate: (details) {
                              setState(() {
                                dialogOffset += details.delta;
                              });
                            },
                            child: Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 12,
                                vertical: 10,
                              ),
                              decoration: BoxDecoration(
                                color: Theme.of(ctx).colorScheme.surface,
                                border: Border(
                                  bottom: BorderSide(
                                    color: Colors.black.withOpacity(0.08),
                                  ),
                                ),
                              ),
                              child: Row(
                                children: [
                                  Container(
                                    width: 34,
                                    height: 4,
                                    decoration: BoxDecoration(
                                      color: Colors.black26,
                                      borderRadius: BorderRadius.circular(99),
                                    ),
                                  ),
                                  const SizedBox(width: 10),
                                  const Expanded(
                                    child: Text(
                                      'Walling (single segment)',
                                      style: TextStyle(
                                        fontSize: 15,
                                        fontWeight: FontWeight.w700,
                                      ),
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                  IconButton(
                                    tooltip: 'Close',
                                    onPressed: () => Get.back(result: false),
                                    icon: const Icon(Icons.close),
                                  ),
                                ],
                              ),
                            ),
                          ),

                          // ✅ CONTENT (scrolls)
                          Flexible(
                            child: SingleChildScrollView(
                              padding: const EdgeInsets.fromLTRB(
                                14,
                                12,
                                14,
                                12,
                              ),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text('ID: $id'),
                                  if (label.trim().isNotEmpty)
                                    Text('Label: ${label.trim()}'),
                                  Text('Length: ${len.toStringAsFixed(3)} m'),
                                  if (h > 0)
                                    Text('Height: ${h.toStringAsFixed(2)} m'),
                                  Text(
                                    'Gross area: ${grossArea.toStringAsFixed(3)} m²',
                                  ),
                                  const SizedBox(height: 6),
                                  Text(
                                    'Openings: ${openingsArea().toStringAsFixed(3)} m²',
                                  ),
                                  Text(
                                    'Net area: ${netArea().toStringAsFixed(3)} m²',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  const SizedBox(height: 10),
                                  const Text(
                                    'Note: This item has no wallGroupId saved. Openings are attached to this segment.',
                                    style: TextStyle(
                                      fontSize: 12,
                                      color: Colors.black54,
                                    ),
                                  ),

                                  const Divider(height: 22),

                                  // Doors
                                  Row(
                                    children: [
                                      const Expanded(
                                        child: Text(
                                          'Doors',
                                          style: TextStyle(
                                            fontWeight: FontWeight.w700,
                                          ),
                                        ),
                                      ),
                                      TextButton(
                                        onPressed: () async {
                                          final d = await _editDoorDialog();
                                          if (d != null)
                                            setState(() => doors.add(d));
                                        },
                                        child: const Text('+ Add door'),
                                      ),
                                    ],
                                  ),
                                  ...doors.map((d) {
                                    final area = d.widthM * d.heightM * d.qty;
                                    return ListTile(
                                      dense: true,
                                      contentPadding: EdgeInsets.zero,
                                      title: Text(
                                        '${d.name} (${d.qty} No.) • ${d.scope == OpeningScope.external ? "External" : "Internal"}',
                                      ),
                                      subtitle: Text(
                                        'Deduction: ${area.toStringAsFixed(3)} m²',
                                      ),
                                      trailing: Wrap(
                                        spacing: 8,
                                        children: [
                                          IconButton(
                                            icon: const Icon(Icons.edit),
                                            onPressed: () async {
                                              final edited =
                                                  await _editDoorDialog(
                                                    existing: d,
                                                  );
                                              if (edited != null) {
                                                setState(() {
                                                  final idx = doors.indexOf(d);
                                                  doors[idx] = edited;
                                                });
                                              }
                                            },
                                          ),
                                          IconButton(
                                            icon: const Icon(Icons.delete),
                                            onPressed: () {
                                              setState(() {
                                                if (d.openingKey != null) {
                                                  deletedKeys.add(d.openingKey);
                                                }
                                                doors.remove(d);
                                              });
                                            },
                                          ),
                                        ],
                                      ),
                                    );
                                  }),

                                  const Divider(height: 22),

                                  // Windows
                                  Row(
                                    children: [
                                      const Expanded(
                                        child: Text(
                                          'Windows',
                                          style: TextStyle(
                                            fontWeight: FontWeight.w700,
                                          ),
                                        ),
                                      ),
                                      TextButton(
                                        onPressed: () async {
                                          final w = await _editWindowDialog();
                                          if (w != null)
                                            setState(() => windows.add(w));
                                        },
                                        child: const Text('+ Add window'),
                                      ),
                                    ],
                                  ),
                                  ...windows.map((w) {
                                    final area = w.widthM * w.heightM * w.qty;
                                    return ListTile(
                                      dense: true,
                                      contentPadding: EdgeInsets.zero,
                                      title: Text('${w.name} (${w.qty} No.)'),
                                      subtitle: Text(
                                        'Area: ${area.toStringAsFixed(3)} m²',
                                      ),
                                      trailing: Wrap(
                                        spacing: 8,
                                        children: [
                                          IconButton(
                                            icon: const Icon(Icons.edit),
                                            onPressed: () async {
                                              final edited =
                                                  await _editWindowDialog(
                                                    existing: w,
                                                  );
                                              if (edited != null) {
                                                setState(() {
                                                  final idx = windows.indexOf(
                                                    w,
                                                  );
                                                  windows[idx] = edited;
                                                });
                                              }
                                            },
                                          ),
                                          IconButton(
                                            icon: const Icon(Icons.delete),
                                            onPressed: () {
                                              setState(() {
                                                if (w.openingKey != null) {
                                                  deletedKeys.add(w.openingKey);
                                                }
                                                windows.remove(w);
                                              });
                                            },
                                          ),
                                        ],
                                      ),
                                    );
                                  }),
                                ],
                              ),
                            ),
                          ),

                          // ✅ ACTIONS (fixed)
                          Container(
                            padding: const EdgeInsets.fromLTRB(12, 10, 12, 12),
                            decoration: BoxDecoration(
                              color: Theme.of(ctx).colorScheme.surface,
                              border: Border(
                                top: BorderSide(
                                  color: Colors.black.withOpacity(0.08),
                                ),
                              ),
                            ),
                            child: Row(
                              children: [
                                Expanded(
                                  child: TextButton(
                                    onPressed: () => Get.back(result: false),
                                    child: const Text('Close'),
                                  ),
                                ),
                                const SizedBox(width: 8),
                                Expanded(
                                  child: FilledButton(
                                    onPressed: () => Get.back(result: true),
                                    child: const Text('Save openings'),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
      barrierDismissible: true,
    );

    if (save != true) return;

    // Save openings (components) attached to legacyGroupId (=segment id)
    await _saveOpeningsOnly(
      wallGroupId: legacyGroupId,
      doors: doors,
      windows: windows,
      deletedOpeningKeys: deletedKeys,
    );

    Get.snackbar('Saved', 'Openings saved.');
    update(['viewer', 'summary']);
  }

  Future<void> _saveOpeningsOnly({
    required String wallGroupId,
    required List<DoorInput> doors,
    required List<WindowInput> windows,
    required Set<String> deletedOpeningKeys,
  }) async {
    final db = FirebaseFirestore.instance;
    final batch = db.batch();
    final now = FieldValue.serverTimestamp();

    // ---- helper: delete a doc by id ----
    void delById(String id) {
      batch.delete(measurementsRef.doc(id));
    }

    // ---- helper: set/merge ----
    void upsert(String id, Map<String, dynamic> data) {
      batch.set(measurementsRef.doc(id), data, SetOptions(merge: true));
    }

    // ---- 1) Delete removed openings (chunk whereIn by 10) ----
    if (deletedOpeningKeys.isNotEmpty) {
      final keys = deletedOpeningKeys.toList();
      for (int i = 0; i < keys.length; i += 10) {
        final chunk = keys.sublist(
          i,
          (i + 10 > keys.length) ? keys.length : i + 10,
        );

        final delSnap =
            await measurementsRef
                .where('measureType', isEqualTo: 'wallingOpening')
                .where('wallGroupId', isEqualTo: wallGroupId)
                .where('drawingId', isEqualTo: drawingId)
                .where('openingKey', whereIn: chunk)
                .get();

        for (final doc in delSnap.docs) {
          batch.delete(doc.reference);
        }
      }
    }

    // ---- 2) Doors ----
    for (final d in doors) {
      final openingKey = (d.openingKey ?? measurementsRef.doc().id).trim();

      final width = d.widthM;
      final height = d.heightM;
      final qty = d.qty;
      final leafCount = d.leafCount == 2 ? 2 : 1;
      final shutterQty = qty * (d.shutterBoqPerLeaf ? leafCount : 1);

      final deductionArea = width * height * qty.toDouble();
      final frameLM = (2 * height + width) * qty.toDouble();
      final transomLM = width * qty.toDouble();
      final archLM =
          (2 * height + width) * d.architraveSides.toDouble() * qty.toDouble();

      final meta = <String, dynamic>{
        'measureType': 'wallingOpening',
        'openingKind': 'door',
        'openingKey': openingKey,
        'wallGroupId': wallGroupId,
        'name': d.name,
        'widthM': width,
        'heightM': height,
        'qty': qty,
        'doorLeafCount': leafCount,
        'doorArrangement': leafCount == 2 ? 'doubleSwing' : 'single',
        'shutterBoqPerLeaf': d.shutterBoqPerLeaf,
        'ironmongeryPerLeaf': d.ironmongeryPerLeaf,
        'includeTransom': d.includeTransom,
        'includeArchitrave': d.includeArchitrave,
        'architraveSides': d.architraveSides,
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'updatedAt': now,
        // (optional) keep createdAt only if you want; merge=true will override if provided
        // 'createdAt': now,
      };

      // Deduction (no BOQ link => keep boqItemId empty)
      upsert('$openingKey-ded', {
        ...meta,
        'type': 'openingDeduction',
        'component': 'deduction',
        'unit': 'm2',
        'value': deductionArea,
        'boqCode': '',
        'boqItemId': '', // ✅ function will ignore
      });

      // Shutter (BOQ link)
      upsert('$openingKey-shutter', {
        ...meta,
        'type': 'doorShutter',
        'component': 'shutter',
        'unit': 'No.',
        'value': shutterQty,
        'boqCode': (d.boqShutter ?? '').trim(),
        'boqItemId': (d.boqShutterId ?? '').trim(), // ✅ IMPORTANT
        'sizeLabel':
            '${width.toStringAsFixed(2)} x ${height.toStringAsFixed(2)} m',
        'quantityBasis': d.shutterBoqPerLeaf ? 'perLeaf' : 'perOpening',
      });

      // Frame (BOQ link)
      upsert('$openingKey-frame', {
        ...meta,
        'type': 'doorFrame',
        'component': 'frame',
        'unit': 'm',
        'value': frameLM,
        'boqCode': (d.boqFrame ?? '').trim(),
        'boqItemId': (d.boqFrameId ?? '').trim(), // ✅ IMPORTANT
      });

      // Transom (create/update OR delete)
      final transomDocId = '$openingKey-transom';
      if (d.includeTransom && (d.boqTransom ?? '').trim().isNotEmpty) {
        upsert(transomDocId, {
          ...meta,
          'type': 'doorTransom',
          'component': 'transom',
          'unit': 'm',
          'value': transomLM,
          'boqCode': (d.boqTransom ?? '').trim(),
          'boqItemId': (d.boqTransomId ?? '').trim(), // ✅ IMPORTANT
        });
      } else {
        // ✅ delete old transom doc if previously existed (so BOQ totals reduce)
        delById(transomDocId);
      }

      // Architrave (create/update OR delete)
      final archDocId = '$openingKey-arch';
      if (d.includeArchitrave && (d.boqArchitrave ?? '').trim().isNotEmpty) {
        upsert(archDocId, {
          ...meta,
          'type': 'doorArchitrave',
          'component': 'architrave',
          'unit': 'm',
          'value': archLM,
          'boqCode': (d.boqArchitrave ?? '').trim(),
          'boqItemId': (d.boqArchitraveId ?? '').trim(), // ✅ IMPORTANT
        });
      } else {
        // ✅ delete old arch doc if previously existed
        delById(archDocId);
      }

      for (final item in d.ironmongery) {
        final itemKey = (item['key'] ?? '').toString().trim();
        final boqCode = (item['boqCode'] ?? '').toString().trim();
        if (itemKey.isEmpty || boqCode.isEmpty) continue;
        final perDoorQty =
            item['qty'] is num
                ? (item['qty'] as num).toDouble()
                : double.tryParse('${item['qty']}') ?? 1.0;
        final multiplier = d.ironmongeryPerLeaf ? leafCount : 1;
        upsert('$openingKey-iron-$itemKey', {
          ...meta,
          'type': 'ironmongery',
          'component': 'ironmongery',
          'ironmongeryKey': itemKey,
          'label': (item['title'] ?? 'Door ironmongery').toString(),
          'unit': (item['unit'] ?? 'item').toString(),
          'value': perDoorQty * qty * multiplier,
          'boqCode': boqCode,
          'boqItemId': (item['boqItemId'] ?? '').toString().trim(),
          'quantityPerDoor': perDoorQty,
          'doorLeafCount': leafCount,
          'quantityBasis': d.ironmongeryPerLeaf ? 'perLeaf' : 'perOpening',
        });
      }
    }

    // ---- 3) Windows ----
    for (final w in windows) {
      final openingKey = (w.openingKey ?? measurementsRef.doc().id).trim();

      final area = w.widthM * w.heightM * w.qty.toDouble();

      upsert('$openingKey-window', {
        'type': 'windowArea',
        'measureType': 'wallingOpening',
        'openingKind': 'window',
        'component': 'window',
        'openingKey': openingKey,
        'wallGroupId': wallGroupId,
        'name': w.name,
        'widthM': w.widthM,
        'heightM': w.heightM,
        'qty': w.qty,
        'unit': 'm2',
        'value': area,

        'boqCode': (w.boqCode ?? '').trim(),
        'boqItemId': (w.boqItemId ?? '').trim(), // ✅ IMPORTANT

        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'updatedAt': now,
        // 'createdAt': now,
      });
    }

    await batch.commit();
  }

  final editTool = SegmentEditTool.move.obs;

