  Future<bool> handleAreaViewTap(
    BuildContext ctx,
    Offset imagePos,
    List<SavedArea> areas,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    slabCompositeDocsBySlabId,
    // Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    // footingCompositeDocsByGroupId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    rebarSlabDocsBySlabId, {
    // Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    // rebarFootingDocsByGroupId,
    // Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    // rebarColumnDocsByGroupId,
    required String drawingId,
  }) async {
    const edgeTolerancePx = 12.0;

    // 1) HIT TEST
    SavedArea? hit;
    double best = double.infinity;

    for (final a in areas) {
      final pts = a.points;
      if (pts.length < 3) continue;

      final inside = _pointInPolygon(imagePos, pts);
      final edgeDist = _distancePointToPolyline(imagePos, pts, closed: true);

      if (!inside && edgeDist > edgeTolerancePx) continue;

      if (edgeDist < best) {
        best = edgeDist;
        hit = a;
      }
    }

    if (hit == null) return false;

    final id = hit.id;

    // 2) ROUTE COMPOSITES FIRST (using maps)
    final hasSlab = slabCompositeDocsBySlabId.containsKey(id);
    // final hasFooting = footingCompositeDocsByGroupId.containsKey(id);

    // NOTE: if your column key == columnId/polygonId, this works.
    // If keys mismatch, pass columnDocsByColumnId instead of rebarColumnDocsByGroupId.
    // final hasColumn = rebarColumnDocsByGroupId.containsKey(id);

    // if (hasColumn) {
    //   // ✅ IMPORTANT: DO NOT handle here → let handleColumnViewTap open the proper dialog
    //   return false; // 👈 so onImageTap continues to column handler
    // }

    if (hasSlab) {
      final docs = slabCompositeDocsBySlabId[id] ?? const [];
      if (docs.isEmpty) {
        Get.snackbar('Slab', 'No docs found for slabId=$id');
        return true;
      }

      // open slab details (your dialog)
      await showSlabCompositeDetailsDialog(
        context: ctx,
        measurementsRef: measurementsRef,
        drawingId: drawingId,
        slabId: id,
        showBoqPickerDialog: (ctx) => showBoqPickerDialog(context: ctx),
      );
      return true;
    }

    // if (hasFooting) {
    //   final docs = footingCompositeDocsByGroupId[id] ?? const [];
    //   if (docs.isEmpty) {
    //     Get.snackbar('Footing', 'No docs found for groupId=$id');
    //     return true;
    //   }

    //   await showFootingCompositeDetailsDialog(footingGroupId: id, docs: docs);
    //   return true;
    // }

    // 3) GENERIC AREA (tiling/hardcore/pavement...)
    final snap = await measurementsRef.doc(id).get();
    if (!snap.exists) {
      // If this happens for some composites, it means SavedArea.id != docId.
      Get.snackbar('Area', 'Area doc not found for id=$id');
      return true;
    }

    final data = snap.data()!;
    final mt = (data['measureType'] ?? '').toString().trim().toLowerCase();

    // Extra safety: if someone saved composite as docId==polygonId, stop generic
    if (mt == 'compositecolumn' || mt == 'columncomposite') {
      return false; // let column handler open
    }
    if (mt == 'compositeslab' || mt == 'slabcomposite') {
      return false; // let slab handler open (or open here)
    }
    if (mt == 'compositefooting' || mt == 'footingcomposite') {
      return false;
    }

    await _showGenericAreaDetailsDialog(
      context: ctx,
      measurementsRef: measurementsRef,
      id: id,
      m: data,
      polygonPoints: hit.points,
      // showBoqPickerDialog: (ctx) => it.showBoqPickerDialog(context: ctx),
    );

    return true;
  }

  Future<void> _showGenericAreaDetailsDialog({
    required BuildContext context,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String id,
    required Map<String, dynamic> m,
    required List<Offset> polygonPoints,
    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,
  }) async {
    String _s(dynamic v) => (v ?? '').toString();
    double _d(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    final measureType = _s(m['measureType']).trim();
    final label = _s(m['label']).trim();
    final unit = _s(m['unit']).trim();
    final createdAt = m['createdAt'];

    // group support (if you saved multiple docs per area)
    final areaGroupIdRaw = _s(m['areaGroupId']).trim(); // may be empty

    final polyAreaPx2 = _polygonAreaAbs(polygonPoints);
    final perimeterPx = _polylinePerimeter(polygonPoints, closed: true);

    // helper: group key for UI rows
    String _keyOf(Map<String, dynamic> mm) {
      final type = _s(mm['type']).trim();
      final code = _s(mm['boqCode']).trim();
      final u = _s(mm['unit']).trim();
      return '$type|$code|$u';
    }

    // helper: stream docs
    Stream<QuerySnapshot<Map<String, dynamic>>> _streamDocs() {
      if (areaGroupIdRaw.isNotEmpty) {
        return measurementsRef
            .where('areaGroupId', isEqualTo: areaGroupIdRaw)
            .stateSnapshots();
      }
      return measurementsRef
          .where(FieldPath.documentId, isEqualTo: id)
          .stateSnapshots();
    }

    // ✅ ensure we have a group id we can attach into
    Future<String> _ensureAreaGroupId() async {
      final gid = areaGroupIdRaw.isNotEmpty ? areaGroupIdRaw : id;

      // if the doc doesn't have areaGroupId, set it to its own id (so we can attach new lines)
      if (areaGroupIdRaw.isEmpty) {
        try {
          await measurementsRef.doc(id).update({
            'areaGroupId': gid,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        } catch (_) {}
      }
      return gid;
    }

    // ✅ attach NEW BOQ line into this area group
    Future<void> _attachNewBoqLine({
      required String areaGroupId,
      required Map<String, dynamic> baseDoc,
      required BoqPick pick,
    }) async {
      final now = FieldValue.serverTimestamp();

      // Copy a safe “base” (no FieldValue.delete in set!)
      final base = Map<String, dynamic>.from(baseDoc);

      // remove internal/meta
      base.remove('__id');

      // ensure group id
      base['areaGroupId'] = areaGroupId;

      // overwrite BOQ fields
      base['boqItemId'] = pick.id;
      base['boqCode'] = pick.code;
      base['boqDescription'] = pick.description;

      // label: keep existing label if meaningful, otherwise use boq description
      final lbl = _s(base['label']).trim();
      if (lbl.isEmpty ||
          lbl.toLowerCase() == 'area' ||
          lbl.toLowerCase() == 'area item') {
        base['label'] =
            pick.description.trim().isNotEmpty
                ? pick.description.trim()
                : 'Area item';
      }

      // timestamps
      base['createdAt'] = now;
      base['updatedAt'] = now;

      // write new doc
      await measurementsRef.doc().set(base);
    }

    // helper: update BOQ fields for all docs matching (type + old boqCode) in this areaGroupId
    Future<void> _changeBoqForLine({
      required String areaGroupId,
      required String type,
      required String oldBoqCode,
      required BoqPick newPick,
    }) async {
      final snap =
          await measurementsRef
              .where('areaGroupId', isEqualTo: areaGroupId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: oldBoqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.update(d.reference, {
          'boqItemId': newPick.id,
          'boqCode': newPick.code,
          'boqDescription': newPick.description,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      await b.commit();
    }

    // helper: delete all docs matching (type + boqCode) in this areaGroupId
    Future<void> _removeLine({
      required String areaGroupId,
      required String type,
      required String boqCode,
    }) async {
      final snap =
          await measurementsRef
              .where('areaGroupId', isEqualTo: areaGroupId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: boqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.delete(d.reference);
      }
      await b.commit();
    }

    await showDialog(
      context: context,
      barrierDismissible: true,
      builder: (ctx) {
        return AlertDialog(
          title: Text(
            label.isNotEmpty
                ? '$label details'
                : (measureType.isNotEmpty
                    ? '$measureType details'
                    : 'Area details'),
          ),
          content: SizedBox(
            width: 760,
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: _streamDocs(),
              builder: (ctx, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(20),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }

                final docs =
                    snap.data!.docs.map((e) {
                      final mm = Map<String, dynamic>.from(e.data());
                      mm['__id'] = e.id;
                      return mm;
                    }).toList();

                if (docs.isEmpty) return const Text('No area record found.');

                // use first doc as base template
                final baseDoc = Map<String, dynamic>.from(docs.first);

                // compute totals
                double totalValue = 0.0;
                String bestUnit = unit;

                for (final mm in docs) {
                  totalValue += _d(mm['value']);
                  final u = _s(mm['unit']).trim();
                  if (u.isNotEmpty) bestUnit = u;
                }

                // group BOQ lines
                final grouped = <String, Map<String, dynamic>>{};
                for (final mm in docs) {
                  final type = _s(mm['type']).trim();
                  final boqCode = _s(mm['boqCode']).trim();
                  final boqDesc = _s(mm['boqDescription']).trim();
                  final u = _s(mm['unit']).trim();
                  final v = _d(mm['value']);

                  if (boqCode.isEmpty) continue;

                  final key = _keyOf(mm);
                  final g = grouped.putIfAbsent(key, () {
                    return {
                      'type': type,
                      'boqCode': boqCode,
                      'boqDesc': boqDesc,
                      'unit': u,
                      'qty': 0.0,
                    };
                  });
                  g['qty'] = (_d(g['qty']) + v);
                }

                final rows =
                    grouped.values.toList()..sort(
                      (a, b) => _s(a['boqCode']).compareTo(_s(b['boqCode'])),
                    );

                // current group id (may be empty if legacy)
                final gidLive = _s(baseDoc['areaGroupId']).trim();
                final displayGroupId =
                    gidLive.isNotEmpty
                        ? gidLive
                        : (areaGroupIdRaw.isNotEmpty ? areaGroupIdRaw : id);

                return SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Card(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Area group: $displayGroupId',
                                style: const TextStyle(fontSize: 12),
                              ),
                              const SizedBox(height: 8),
                              Wrap(
                                spacing: 18,
                                runSpacing: 8,
                                children: [
                                  Text(
                                    'Value: ${totalValue.toStringAsFixed(3)} ${_prettyUnit(bestUnit)}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                  Text(
                                    'Points: ${polygonPoints.length}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  Text(
                                    'Area(px²): ${polyAreaPx2.toStringAsFixed(1)}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                  Text(
                                    'Perimeter(px): ${perimeterPx.toStringAsFixed(1)}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ],
                              ),
                              if (createdAt != null) ...[
                                const SizedBox(height: 6),
                                Text(
                                  'CreatedAt: $createdAt',
                                  style: const TextStyle(fontSize: 12),
                                ),
                              ],
                            ],
                          ),
                        ),
                      ),

                      const SizedBox(height: 10),
                      if (measureType.trim().toLowerCase() == 'pavement') ...[
                        Align(
                          alignment: Alignment.centerLeft,
