  String _prettyUnit(String u) {
    switch (u) {
      case 'm2':
        return 'm²';
      case 'm3':
        return 'm³';
      default:
        return u;
    }
  }

  bool _pointInPolygon(Offset p, List<Offset> poly) {
    bool inside = false;
    for (int i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      final xi = poly[i].dx, yi = poly[i].dy;
      final xj = poly[j].dx, yj = poly[j].dy;

      final intersect =
          ((yi > p.dy) != (yj > p.dy)) &&
          (p.dx <
              (xj - xi) * (p.dy - yi) / ((yj - yi) == 0 ? 1e-9 : (yj - yi)) +
                  xi);
      if (intersect) inside = !inside;
    }
    return inside;
  }

  double _distancePointToPolyline(
    Offset p,
    List<Offset> pts, {
    bool closed = true,
  }) {
    if (pts.length < 2) return double.infinity;
    double best = double.infinity;

    for (int i = 0; i < pts.length - 1; i++) {
      best = math.min(best, _distancePointToSegment(p, pts[i], pts[i + 1]));
    }
    if (closed) {
      best = math.min(best, _distancePointToSegment(p, pts.last, pts.first));
    }
    return best;
  }

  double _polygonAreaAbs(List<Offset> pts) {
    if (pts.length < 3) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < pts.length; i++) {
      final j = (i + 1) % pts.length;
      sum += pts[i].dx * pts[j].dy - pts[j].dx * pts[i].dy;
    }
    return sum.abs() * 0.5;
  }

  Future<bool> handleColumnViewTap(
    Offset imagePos,
    List<SavedArea> areas,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    columnDocsByColumnId,
    CollectionReference<Map<String, dynamic>> measurementsRef, {
    required String projectId,
    required String buildingId,
    required String drawingId,
    // required Color currentColor,
    String? activeLabel,
  }) async {
    // measureType variants for PURE COLUMN composites only
    const columnMt = <String>[
      'compositeColumn',
      'columnComposite',
      'compositecolumn',
      'columncomposite',
    ];

    bool isPureColumnDoc(QueryDocumentSnapshot<Map<String, dynamic>> doc) {
      final mt =
          (doc.data()['measureType'] ?? '').toString().trim().toLowerCase();
      // Accept only column composite measureTypes (reject compositeFooting etc.)
      return mt == 'compositecolumn' || mt == 'columncomposite';
    }

    Future<List<QueryDocumentSnapshot<Map<String, dynamic>>>> queryBy(
      String field,
      String value,
    ) async {
      final qs =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where(field, isEqualTo: value)
              .where('measureType', whereIn: columnMt)
              .limit(300)
              .get();
      return qs.docs;
    }

    for (final a in areas) {
      if (a.points.length < 3) continue;
      if (!pointInPolygon(imagePos, a.points)) continue;

      debugPrint('✅ ColumnTap candidate polygon id=${a.id}');

      // 1) from prepared map
      var docs =
          columnDocsByColumnId[a.id] ??
          <QueryDocumentSnapshot<Map<String, dynamic>>>[];

      // 2) Firestore fallback (polygon/area id first)
      if (docs.isEmpty) {
        docs = await queryBy('polygonId', a.id);
        if (docs.isEmpty) docs = await queryBy('areaId', a.id);
        if (docs.isEmpty) docs = await queryBy('columnId', a.id);
        if (docs.isEmpty) docs = await queryBy('groupId', a.id);
        if (docs.isEmpty) docs = await queryBy('areaGroupId', a.id);

        debugPrint('🔎 Column fallback docs found: ${docs.length}');
      }

      // 3) Filter to PURE column docs only
      final pureDocs = docs.where(isPureColumnDoc).toList();

      if (pureDocs.isEmpty) {
        // ❗IMPORTANT: don't consume the tap; let other handlers (footing) process it
        debugPrint(
          '⏭️ Not a pure column composite for polygon id=${a.id}. Passing tap to next handler.',
        );
        return false;
      }

      // 4) Open column details
      await Get.dialog(
        ColumnCompositeDetailsDialog(
          columnId: a.id,
          initialDocs: pureDocs,
          measurementsRef: measurementsRef,
          projectId: projectId,
          buildingId: buildingId,
          drawingId: drawingId,
          currentColor: currentColor,
          defaultLabel: activeLabel,
        ),
        barrierDismissible: true,
      );

      return true;
    }

    return false;
  }

  double _polylinePerimeter(List<Offset> pts, {bool closed = true}) {
    if (pts.length < 2) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < pts.length - 1; i++) {
      sum += (pts[i + 1] - pts[i]).distance;
    }
    if (closed) sum += (pts.first - pts.last).distance;
    return sum;
  }

  Future<void> handleCompositeAreaTap(
    BuildContext ctx,
    Offset imagePos,
    List<SavedArea> areas,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    slabCompositeDocsBySlabId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    footingCompositeDocsByGroupId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    rebarSlabDocsBySlabId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    rebarColumnDocsBySlabId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    rebarFootingDocsByGroupId,
    // Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    // columnCompositeDocsByColumnId,
  ) async {
    // Tap near boundary should still count
    const edgeTolerancePx = 12.0;

    // 1) Pick best hit polygon (inside OR near edge)
    SavedArea? hit;
    double bestScore = double.infinity;

    for (final a in areas) {
      final pts = a.points;
      if (pts.length < 3) continue;

      final inside = pointInPolygon(imagePos, pts);
      final edgeDist = distancePointToPolyline(imagePos, pts, closed: true);

      if (!inside && edgeDist > edgeTolerancePx) continue;

      // Prefer smaller edgeDist; slight bias for smaller polygon helps when overlapping
      final areaAbs = polygonAreaAbs(pts); // px²
      final score = edgeDist + (areaAbs / 1e9);

      if (score < bestScore) {
        bestScore = score;
        hit = a;
      }
    }

    if (hit == null) return;

    // 2) Route based on flags
    // IMPORTANT: in your code, slab composite polygon is represented by isRebarSlab==true
    // and footing composite polygon is represented by isRebarFooting==true.
    // (If you also have isSlabComposite/isFootingComposite fields, keep both.)

    // ---- SLAB COMPOSITE (concrete/formwork family) ----
    if (hit.isSlabComposite == true || hit.isRebarSlab == true) {
      final slabId = hit.id;

      // Prefer full slab composite docs if provided
      final slabDocs = slabCompositeDocsBySlabId[slabId] ?? const [];
      final rebarDocs = rebarSlabDocsBySlabId[slabId] ?? const [];

      if (slabDocs.isEmpty && rebarDocs.isEmpty) {
        // Nothing to show -> let other handlers run
        return;
      }

      // If you want a single dialog showing everything, pass both lists (recommended).
      // If you only have one dialog, call what you have.
      // ✅ Example: open slab composite dialog if slabDocs exist; otherwise open rebar-only dialog.
      if (slabDocs.isNotEmpty) {
        // non-blocking is ok
        await showSlabCompositeDetailsDialog(
          context: ctx,
          measurementsRef: measurementsRef,
          drawingId: drawingId,
          slabId: slabId,
          showBoqPickerDialog: (ctx) => showBoqPickerDialog(context: ctx),
        );
        return;
      }

      showRebarSlabDetailsDialog(slabId: slabId, docs: rebarDocs);
      return;
    }

    // ---- FOOTING COMPOSITE ----
    if (hit.isFootingComposite == true || hit.isRebarFooting == true) {
      final groupId = hit.id;

      final footingDocs = footingCompositeDocsByGroupId[groupId] ?? const [];
      final rebarDocs = rebarFootingDocsByGroupId[groupId] ?? const [];

      if (footingDocs.isEmpty && rebarDocs.isEmpty) {
        return;
      }

      // If you have a footing composite dialog, call it.
      // Otherwise fallback to rebar-only.
      if (footingDocs.isNotEmpty) {
        showFootingCompositeDetailsDialog(
          footingGroupId: groupId,
          docs: footingDocs,
        );
        return;
      }

      showRebarFootingDetailsDialog(footingGroupId: groupId, docs: rebarDocs);
      return;
    }

    return;
  }

  Future<void> showFootingCompositeDetailsDialog({
    required String footingGroupId,
    required List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
  }) async {
    double numv(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    String strv(dynamic v) => (v ?? '').toString().trim();

    // ---------- aggregate ----------
    double concreteM3 = 0.0;
    double formworkM2 = 0.0;

    double rebarLenM = 0.0; // if available
    double rebarWtKg = 0.0; // if available

    final rows = <Map<String, dynamic>>[];

    // Try to pre-fill BOQ codes for each family
    String concreteBoq = '';
    String formworkBoq = '';
    String rebarBoq = '';

    for (final d in docs) {
      final m = d.data();
      final type = strv(m['type']);
      final boq = strv(m['boqCode']);
      final unit = strv(m['unit']);
      final value = numv(m['value']);

      rows.add({
        '_id': d.id,
        'type': type,
        'boqCode': boq,
        'unit': unit,
        'value': value,
        'raw': m,
      });

      if (type == 'footingConcrete') {
        concreteM3 += value;
        if (concreteBoq.isEmpty && boq.isNotEmpty) concreteBoq = boq;
      } else if (type == 'footingFormwork') {
        formworkM2 += value;
        if (formworkBoq.isEmpty && boq.isNotEmpty) formworkBoq = boq;
      } else if (type == 'rebarFooting') {
        // Support multiple field names you used before
        rebarLenM += numv(
          m['lengthAllFootingsM'] ??
              m['totalLengthAllBarsM'] ??
              m['totalLengthM'],
        );
        rebarWtKg += numv(
          m['weightAllFootingsKg'] ?? m['totalWeightKg'] ?? m['value'],
        );
        if (rebarBoq.isEmpty && boq.isNotEmpty) rebarBoq = boq;
      }
    }

    rows.sort((a, b) => (a['type'] as String).compareTo(b['type'] as String));

    // ---------- controllers ----------
    final concreteBoqCtrl = TextEditingController(text: concreteBoq);
    final formworkBoqCtrl = TextEditingController(text: formworkBoq);
    final rebarBoqCtrl = TextEditingController(text: rebarBoq);

    bool editingBoq = false;

    Future<void> deleteOneById(String id) async {
      final ok =
          await Get.dialog<bool>(
            AlertDialog(
              title: const Text('Delete item?'),
              content: Text('Delete this record?\nID: $id'),
              actions: [
                TextButton(
                  onPressed: () => Get.back(result: false),
                  child: const Text('Cancel'),
                ),
                FilledButton(
                  onPressed: () => Get.back(result: true),
                  child: const Text('Delete'),
                ),
              ],
            ),
          ) ??
          false;

      if (!ok) return;

      await measurementsRef.doc(id).delete();
      update(['viewer', 'summary']);
      Get.snackbar('Deleted', 'Item deleted.');
    }

    Future<void> deleteGroup() async {
      final ok =
          await Get.dialog<bool>(
            AlertDialog(
              title: const Text('Delete footing group?'),
              content: Text(
                'Delete ALL items under footingGroupId:\n$footingGroupId ?',
              ),
              actions: [
                TextButton(
                  onPressed: () => Get.back(result: false),
                  child: const Text('Cancel'),
                ),
                FilledButton(
                  onPressed: () => Get.back(result: true),
                  child: const Text('Delete group'),
                ),
              ],
            ),
          ) ??
          false;

      if (!ok) return;

      // safest: query by groupId + drawingId (ensures you delete all docs even if not in "docs" list)
      final qs =
          await measurementsRef
              .where('footingGroupId', isEqualTo: footingGroupId)
              .get();

      final batch = FirebaseFirestore.instance.batch();
      for (final d in qs.docs) {
        batch.delete(d.reference);
      }
      await batch.commit();

      update(['viewer', 'summary']);
      Get.snackbar('Deleted', 'Footing group deleted.');
    }

    Future<void> saveBoqUpdates() async {
      final newConcreteBoq = concreteBoqCtrl.text.trim();
      final newFormworkBoq = formworkBoqCtrl.text.trim();
      final newRebarBoq = rebarBoqCtrl.text.trim();

      // update only those types that exist
      final batch = FirebaseFirestore.instance.batch();
      int count = 0;

      for (final r in rows) {
        final id = (r['_id'] ?? '').toString();
        final type = (r['type'] ?? '').toString();

        String? newBoq;
        if (type == 'footingConcrete') newBoq = newConcreteBoq;
        if (type == 'footingFormwork') newBoq = newFormworkBoq;
        if (type == 'rebarFooting') newBoq = newRebarBoq;

        if (newBoq == null) continue;
        if (newBoq.isEmpty) continue;

        batch.update(measurementsRef.doc(id), {'boqCode': newBoq});
        count++;
      }

      if (count == 0) {
        Get.snackbar('BOQ', 'Nothing to update.');
        return;
      }

      await batch.commit();
      update(['viewer', 'summary']);
      Get.snackbar('Saved', 'BOQ codes updated.');
    }

    // ---------- show movable dialog ----------
    await Get.dialog(
      StatefulBuilder(
        builder: (context, setState) {
          return MovableDialog(
            child: AlertDialog(
              title: Text('Footing details - Group $footingGroupId'),
              content: SizedBox(
                width: 580,
                child: SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // Summary
                      Text('Items: ${rows.length}'),
                      const SizedBox(height: 8),

                      if (concreteM3 > 0)
                        Text(
                          'Concrete: ${concreteM3.toStringAsFixed(3)} m³',
                          style: const TextStyle(fontWeight: FontWeight.w600),
                        ),
                      if (formworkM2 > 0)
                        Text(
                          'Formwork: ${formworkM2.toStringAsFixed(3)} m²',
                          style: const TextStyle(fontWeight: FontWeight.w600),
                        ),
                      if (rebarWtKg > 0 || rebarLenM > 0) ...[
                        const SizedBox(height: 4),
                        Text(
                          'Rebar: ${rebarWtKg.toStringAsFixed(2)} kg',
                          style: const TextStyle(fontWeight: FontWeight.w600),
                        ),
                        if (rebarLenM > 0)
                          Text(
                            'Rebar length: ${rebarLenM.toStringAsFixed(3)} m',
                          ),
                      ],

                      const Divider(height: 22),

                      // BOQ edit toggle
                      Row(
                        children: [
                          const Expanded(
                            child: Text(
                              'BOQ Codes',
                              style: TextStyle(fontWeight: FontWeight.w700),
                            ),
                          ),
                          TextButton(
                            onPressed:
                                () => setState(() => editingBoq = !editingBoq),
                            child: Text(editingBoq ? 'Hide' : 'Edit'),
                          ),
                        ],
                      ),

                      if (editingBoq) ...[
                        TextField(
                          controller: concreteBoqCtrl,
                          decoration: const InputDecoration(
                            labelText: 'Concrete BOQ code',
                            isDense: true,
                            border: OutlineInputBorder(),
                          ),
                        ),
                        const SizedBox(height: 8),
                        TextField(
                          controller: formworkBoqCtrl,
                          decoration: const InputDecoration(
                            labelText: 'Formwork BOQ code',
                            isDense: true,
                            border: OutlineInputBorder(),
                          ),
                        ),
                        const SizedBox(height: 8),
                        TextField(
                          controller: rebarBoqCtrl,
                          decoration: const InputDecoration(
                            labelText: 'Rebar BOQ code',
                            isDense: true,
                            border: OutlineInputBorder(),
                          ),
                        ),
                        const SizedBox(height: 10),
                        Align(
                          alignment: Alignment.centerRight,
                          child: FilledButton(
                            onPressed: () async {
                              await saveBoqUpdates();
                              setState(() => editingBoq = false);
                            },
                            child: const Text('Save BOQ codes'),
                          ),
                        ),
                        const Divider(height: 22),
                      ],

                      // Items list
                      const Text(
                        'Items',
                        style: TextStyle(fontWeight: FontWeight.w700),
                      ),
                      const SizedBox(height: 6),

                      ListView.separated(
                        shrinkWrap: true,
                        physics: const NeverScrollableScrollPhysics(),
                        itemCount: rows.length,
                        separatorBuilder: (_, __) => const Divider(height: 10),
                        itemBuilder: (_, i) {
                          final r = rows[i];
                          final id = (r['_id'] ?? '').toString();
                          final type = (r['type'] ?? '').toString();
                          final boq = (r['boqCode'] ?? '').toString();
                          final unit = (r['unit'] ?? '').toString();
                          final value = (r['value'] as double);

                          return ListTile(
                            dense: true,
                            title: Text(
                              type,
                              style: const TextStyle(
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                            subtitle: Text(
                              '${value.toStringAsFixed(3)} ${_prettyUnit(unit)}'
                              '${boq.isNotEmpty ? '  (BOQ: $boq)' : ''}',
                            ),
                            trailing: IconButton(
                              icon: const Icon(Icons.delete_outline),
                              onPressed: () async => deleteOneById(id),
                            ),
                          );
                        },
                      ),
                    ],
                  ),
                ),
              ),
              actions: [
                TextButton(
                  onPressed: () {
                    concreteBoqCtrl.dispose();
                    formworkBoqCtrl.dispose();
                    rebarBoqCtrl.dispose();
                    Get.back();
                  },
                  child: const Text('Close'),
                ),
                TextButton(
                  onPressed: () async => deleteGroup(),
                  child: const Text('Delete group'),
                ),
              ],
            ),
          );
        },
      ),
      barrierDismissible: true,
    );
  }

  String prettyUnit(String u) {
    switch (u) {
      case 'm2':
        return 'm²';
      case 'm3':
        return 'm³';
      default:
        return u;
    }
  }

  Future<bool> handleCompositeBeamTap(
    Offset imagePos,
    List<MeasuredSegment> segments,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    beamCompositeDocsByBeamId,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    rebarDocsByBeamType,
  ) async {
    String norm(dynamic v) => (v ?? '').toString().trim().toLowerCase();

    const maxDist = 10.0;

    // 1) Find closest composite beam segment
    MeasuredSegment? closest;
    double best = double.infinity;

    for (final s in segments) {
      final mt = norm(s.measureType);
      final isCompositeBeam =
          mt == 'compositebeam' ||
          mt == 'beamcomposite' ||
          mt == 'compositeBeam' ||
          mt == 'composite_beam';
      if (!isCompositeBeam) continue;

      final d = distancePointToSegment(imagePos, s.p1, s.p2);
      if (d < best) {
        best = d;
        closest = s;
      }
    }

    if (closest == null || best > maxDist) return false;

    final String beamId = closest.groupId.toString();

    // 2) Load latest docs for this beam from Firestore (preferred)
    List<QueryDocumentSnapshot<Map<String, dynamic>>> docs = [];
    try {
      final qs =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('beamId', isEqualTo: beamId)
              .get();

      docs =
          qs.docs.where((d) {
            final m = d.data();
            final mt = norm(m['measureType']);
            if (mt != 'compositebeam' &&
                mt != 'beamcomposite' &&
                mt != 'compositeBeam' &&
                mt != 'columncomposite' &&
                mt != 'compositecolumn' &&
                mt != 'composite_beam') {
              return false;
            }
            final type = (m['type'] ?? '').toString();
            return type == 'beamConcrete' ||
                type == 'beamFormworkSide' ||
                type == 'beamFormworkSoffit' ||
                type.toLowerCase().startsWith(
                  'rebarbeam',
                ); // includes rebarBeamMain, etc
          }).toList();
    } catch (_) {
      // ignore -> fallback below
    }

    // 3) Fallback to pre-built grouped docs
    if (docs.isEmpty) {
      docs =
          beamCompositeDocsByBeamId[beamId] ??
          <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    }

    if (docs.isEmpty) {
      Get.snackbar('Beam', 'No measurement docs found for beamId=$beamId');
      return true;
    }

    // 4) Resolve beamType SAFELY (old beams might not have it)
    String beamType = '';

    // 4a) Try from docs
    for (final d in docs) {
      final bt = (d.data()['beamType'] ?? '').toString().trim();
      if (bt.isNotEmpty) {
        beamType = bt;
        break;
      }
    }

    // 4b) Try from segment label (if you store label like "GB01")
    if (beamType.isEmpty) {
      final segLabel = (closest.label ?? '').toString().trim();
      if (segLabel.isNotEmpty) beamType = segLabel;
    }

    // 4c) Final fallback: generate from geometry (B x D) if available
    // Example: "B250xD450" (you can change format)
    if (beamType.isEmpty) {
      double w = 0, d = 0;
      for (final doc in docs) {
        final m = doc.data();
        w =
            (m['beamWidthM'] as num?)?.toDouble() ??
            (m['widthM'] as num?)?.toDouble() ??
            0;
        d =
            (m['beamDepthM'] as num?)?.toDouble() ??
            (m['depthM'] as num?)?.toDouble() ??
            0;
        if (w > 0 && d > 0) break;
      }
      if (w > 0 && d > 0) {
        beamType = 'B${(w * 1000).round()}xD${(d * 1000).round()}';
      } else {
        beamType = 'UNKNOWN'; // still allow dialog
      }
    }

    // 5) Same-type totals: only compute if beamType is not UNKNOWN
    BeamTypeTotals? sameTotals;
    if (beamType.trim().toUpperCase() != 'UNKNOWN') {
      // For accuracy after edits, rebuild fresh maps from Firestore if possible
      try {
        final all =
            await measurementsRef
                .where('drawingId', isEqualTo: drawingId)
                .get();

        final freshBeamDocsByBeamId =
            <String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>{};
        final freshRebarDocsByBeamType =
            <String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>{};

        for (final doc in all.docs) {
          final m = doc.data();
          final mt = norm(m['measureType']);
          if (mt != 'compositebeam' &&
              mt != 'compositeBeam' &&
              mt != 'beamcomposite' &&
              mt != 'composite_beam') {
            continue;
          }

          final bId = (m['beamId'] ?? '').toString().trim();
          if (bId.isNotEmpty) {
            freshBeamDocsByBeamId.putIfAbsent(bId, () => []).add(doc);
          }

          final type = (m['type'] ?? '').toString();
          final isRebar = type.toLowerCase().startsWith('rebarbeam');
          final bType = (m['beamType'] ?? '').toString().trim();
          if (isRebar && bType.isNotEmpty) {
            freshRebarDocsByBeamType
                .putIfAbsent(bType.toLowerCase(), () => [])
                .add(doc);
          }
        }

        sameTotals = computeSameTypeTotals(
          beamType: beamType,
          beamDocsByBeamId: freshBeamDocsByBeamId,
          rebarDocsByBeamType: freshRebarDocsByBeamType,
        );
      } catch (_) {
        // fallback to passed maps
        sameTotals = computeSameTypeTotals(
          beamType: beamType,
          beamDocsByBeamId: beamCompositeDocsByBeamId,
          rebarDocsByBeamType: rebarDocsByBeamType,
        );
      }
    }

    // 6) Open dialog even if beamType is UNKNOWN
    await showBeamCompositeDetailsDialog(
      beamId: beamId,
      docs: docs,
      beamType: beamType,
      sameTotals: sameTotals,
    );

    return true;
  }

  Future<void> openRebarSlabFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
  }) async {
    // 1) Check calibration
    final calibrated = drawingData['calibrated'] == true;
    final pxPerUnit = (drawingData['pixelsPerUnit'] ?? 0).toDouble();

    final ctx = Get.context;
    if (!calibrated || pxPerUnit <= 0) {
      if (ctx != null) {
        ScaffoldMessenger.of(ctx).showSnackBar(
          const SnackBar(
            content: Text(
              'Drawing not calibrated – cannot compute slab spans.',
            ),
          ),
        );
      }
      return;
    }

    // 2) Bounding box in image coords
    double minX = polygon.first.dx;
    double maxX = polygon.first.dx;
    double minY = polygon.first.dy;
    double maxY = polygon.first.dy;

    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }

    final widthPx = maxX - minX;
    final heightPx = maxY - minY;

    if (widthPx <= 0 || heightPx <= 0) {
      if (ctx != null) {
        ScaffoldMessenger.of(ctx).showSnackBar(
          const SnackBar(
            content: Text('Invalid slab polygon – zero width or height.'),
          ),
        );
      }
      return;
    }

    // 3) Convert to meters (pxPerUnit = px per meter)
    final spanXM = widthPx / pxPerUnit;
    final spanYM = heightPx / pxPerUnit;

    final lengthM = math.max(spanXM, spanYM);
    final widthM = math.min(spanXM, spanYM);

    final centerX = (minX + maxX) / 2;
    final centerY = (minY + maxY) / 2;

    final polyData = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    // 4) Multi-mark state
    final List<RebarSet> sets = [];

    final markController = TextEditingController();
    final embedController = TextEditingController(text: '0.30');
    final extraController = TextEditingController(text: '0.00');
    String direction = 'horizontal';
    String? errorText;

    // initial dialog position
    Offset dialogOffset = const Offset(40, 80);

    final ok =
        await Get.dialog<bool>(
          StatefulBuilder(
            builder: (dialogCtx, setStateDialog) {
              void addCurrentMark() {
                final raw = markController.text.trim();
                if (raw.isEmpty) {
                  setStateDialog(() {
                    errorText = 'Please enter rebar mark.';
                  });
                  return;
                }

                final embed =
                    double.tryParse(embedController.text.trim()) ?? 0.0;
                final extra =
                    double.tryParse(extraController.text.trim()) ?? 0.0;

                try {
                  final m = RebarMark.parse(raw);

                  final clearSpanM =
                      (direction == 'horizontal') ? lengthM : widthM;

                  final Lbar = clearSpanM + 2 * embed + extra;
                  final Ltotal = m.quantity * Lbar;
                  final uw = rebarUnitWeightKgPerM(m.diameterMm);
                  final wTotal = Ltotal * uw;

                  sets.add(
                    RebarSet(
                      rawMark: raw,
                      mark: m,
                      direction: direction,
                      clearSpanM: clearSpanM,
                      embedEachEndM: embed,
                      extraLengthM: extra,
                      barLengthM: Lbar,
                      totalLengthM: Ltotal,
                      unitWeightKgPerM: uw,
                      totalWeightKg: wTotal,
                    ),
                  );

                  markController.clear();
                  setStateDialog(() {
                    errorText = null;
                  });
                } catch (e) {
                  setStateDialog(() {
                    errorText = e.toString();
                  });
                }
              }

              return Stack(
                children: [
                  // tap outside to cancel
                  Positioned.fill(
                    child: GestureDetector(
                      onTap: () => Get.back(result: false),
                      child: Container(color: Colors.black.withOpacity(0.2)),
                    ),
                  ),

                  Positioned(
                    left: dialogOffset.dx,
                    top: dialogOffset.dy,
                    child: GestureDetector(
                      onPanUpdate: (details) {
                        setStateDialog(() {
                          dialogOffset += details.delta;
                        });
                      },
                      child: Material(
                        color: Colors.transparent,
                        child: AlertDialog(
                          title: Row(
                            children: const [
                              Icon(Icons.drag_indicator, size: 18),
                              SizedBox(width: 6),
                              Text('Slab rebar (multiple marks)'),
                            ],
                          ),
                          content: SizedBox(
                            width: 420,
                            child: Column(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Text(
                                  'Slab spans: L ≈ ${lengthM.toStringAsFixed(3)} m, '
                                  'W ≈ ${widthM.toStringAsFixed(3)} m',
                                  style: const TextStyle(fontSize: 12),
                                ),
                                const SizedBox(height: 8),
                                Row(
                                  children: [
                                    const Text(
                                      'Bars lay:',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w600,
                                        fontSize: 12,
                                      ),
                                    ),
                                    const SizedBox(width: 8),
                                    ChoiceChip(
                                      label: const Text('Horizontal'),
                                      selected: direction == 'horizontal',
                                      onSelected: (_) {
                                        setStateDialog(() {
                                          direction = 'horizontal';
                                        });
                                      },
                                    ),
                                    const SizedBox(width: 4),
                                    ChoiceChip(
                                      label: const Text('Vertical'),
                                      selected: direction == 'vertical',
                                      onSelected: (_) {
                                        setStateDialog(() {
                                          direction = 'vertical';
                                        });
                                      },
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 8),
                                TextField(
                                  controller: markController,
                                  decoration: const InputDecoration(
                                    labelText:
                                        'Rebar mark (e.g. 38Y12-01-150B2)',
                                    border: OutlineInputBorder(),
                                    isDense: true,
                                  ),
                                  style: const TextStyle(fontSize: 12),
                                ),
                                const SizedBox(height: 6),
                                Row(
                                  children: [
                                    Expanded(
                                      child: TextField(
                                        controller: embedController,
                                        keyboardType:
                                            const TextInputType.numberWithOptions(
                                              decimal: true,
                                            ),
                                        decoration: const InputDecoration(
                                          labelText: 'Embed each end (m)',
                                          border: OutlineInputBorder(),
                                          isDense: true,
                                        ),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                    const SizedBox(width: 6),
                                    Expanded(
                                      child: TextField(
                                        controller: extraController,
                                        keyboardType:
                                            const TextInputType.numberWithOptions(
                                              decimal: true,
                                            ),
                                        decoration: const InputDecoration(
                                          labelText:
                                              'Extra length (laps/hooks, m)',
                                          border: OutlineInputBorder(),
                                          isDense: true,
                                        ),
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                    ),
                                  ],
                                ),
                                if (errorText != null) ...[
                                  const SizedBox(height: 4),
                                  Text(
                                    errorText!,
                                    style: const TextStyle(
                                      color: Colors.red,
                                      fontSize: 11,
                                    ),
                                  ),
                                ],
                                const SizedBox(height: 6),
                                Align(
                                  alignment: Alignment.centerRight,
                                  child: TextButton.icon(
                                    onPressed: addCurrentMark,
                                    icon: const Icon(Icons.add, size: 16),
                                    label: const Text('Add mark'),
                                  ),
                                ),
                                const Divider(),
                                if (sets.isEmpty)
                                  const Text(
                                    'No rebar marks added yet.',
                                    style: TextStyle(fontSize: 12),
                                  )
                                else
                                  SizedBox(
                                    height: 140,
                                    child: ListView.builder(
                                      itemCount: sets.length,
                                      itemBuilder: (ctx, i) {
                                        final s = sets[i];
                                        return ListTile(
                                          dense: true,
                                          contentPadding: EdgeInsets.zero,
                                          title: Text(
                                            '${s.rawMark} '
                                            '(${s.direction == "horizontal" ? "Horizontal" : "Vertical"})',
                                            style: const TextStyle(
                                              fontSize: 12,
                                            ),
                                          ),
                                          subtitle: Text(
                                            'L/bar: ${s.barLengthM.toStringAsFixed(3)} m, '
                                            'Total: ${s.totalLengthM!.toStringAsFixed(3)} m, '
                                            'Wt: ${s.totalWeightKg!.toStringAsFixed(1)} kg',
                                            style: const TextStyle(
                                              fontSize: 11,
                                            ),
                                          ),
                                          trailing: IconButton(
                                            icon: const Icon(
                                              Icons.delete_outline,
                                              size: 18,
                                            ),
                                            onPressed: () {
                                              setStateDialog(() {
                                                sets.removeAt(i);
                                              });
                                            },
                                          ),
                                        );
                                      },
                                    ),
                                  ),
                              ],
                            ),
                          ),
                          actions: [
                            TextButton(
                              onPressed: () => Get.back(result: false),
                              child: const Text('Cancel'),
                            ),
                            FilledButton(
                              onPressed:
                                  sets.isEmpty
                                      ? null
                                      : () => Get.back(result: true),
                              child: const Text('Save'),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ],
              );
            },
          ),
          barrierDismissible: false,
        ) ??
        false;

    if (!ok || sets.isEmpty) return;

    // 5) Save all marks under one slabId
    final slabId =
        measurementsRef.doc().id; // measurementsRef in your controller

    for (final s in sets) {
      late final Offset p1;
      late final Offset p2;

      if (s.direction == 'horizontal') {
        p1 = Offset(minX, centerY);
        p2 = Offset(maxX, centerY);
      } else {
        p1 = Offset(centerX, minY);
        p2 = Offset(centerX, maxY);
      }

      await _saveRebarSlabMeasurement(
        mark: s.mark,
        markRawString: s.rawMark,
        clearSpanM: s.clearSpanM,
        embedEachEndM: s.embedEachEndM,
        extraLengthM: s.extraLengthM,
        barLengthM: s.barLengthM,
        totalLengthM: s.totalLengthM!,
        unitWeightKgPerM: s.unitWeightKgPerM,
        totalWeightKg: s.totalWeightKg!,
        p1: p1,
        p2: p2,
        polygon: polyData,
        slabId: slabId,
        direction: s.direction,
      );
    }
  }

  String? draftFootingGroupId;

  Future<void> openFootingCompositeFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,

    // required CollectionReference<Map<String, dynamic>> measurementsRef,
    VoidCallback? onUpdateViewer, // optional
  }) async {
    if (polygon.length < 3) return;

    // ---------- calibration (match your column pattern) ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM =
        (drawingData['pixelsPerUnit'] is num)
            ? (drawingData['pixelsPerUnit'] as num).toDouble()
            : double.tryParse('${drawingData['pixelsPerUnit']}') ?? 0.0;

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar('Not calibrated', 'Calibrate drawing to measure footing.');
      return;
    }

    // ---------- geometry: bbox -> default L/B ----------
    double minX = polygon.first.dx, maxX = polygon.first.dx;
    double minY = polygon.first.dy, maxY = polygon.first.dy;
    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }

    final centerX = (minX + maxX) / 2;
    final centerY = (minY + maxY) / 2;

    final measuredLm = distanceInMeters(
      Offset(minX, centerY),
      Offset(maxX, centerY),
      drawingData,
    );
    final measuredBm = distanceInMeters(
      Offset(centerX, minY),
      Offset(centerX, maxY),
      drawingData,
    );

    if (measuredLm == null ||
        measuredBm == null ||
        measuredLm <= 0 ||
        measuredBm <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Drawing not calibrated – cannot compute footing L/B.',
      );
      return;
    }

    final polyData = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    // ---------- helpers ----------
    TextEditingController ctrlNum(String key, String fallback) {
      final v = lastFootingDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    TextEditingController ctrlText(String key, String fallback) {
      final v = lastFootingDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    double d(TextEditingController c, [double fb = 0.0]) =>
        double.tryParse(c.text.trim()) ?? fb;

    int i(TextEditingController c, [int fb = 1]) =>
        int.tryParse(c.text.trim()) ?? fb;

    int _barsFromSpacing(double clearM, double spacingM) {
      if (clearM <= 0 || spacingM <= 0) return 0;
      final n = (clearM / spacingM).floor() + 1;
      return n.clamp(1, 999999);
    }

    Future<void> pickBoqInto(
      BuildContext dialogCtx,
      TextEditingController code,
      TextEditingController desc,
    ) async {
      final picked = await showBoqPickerDialog(context: dialogCtx);
      if (picked == null) return;
      code.text = (picked.code ?? '').toString().trim();
      desc.text = (picked.description ?? '').toString().trim();
    }

    InputDecoration deco(String label) => InputDecoration(
      labelText: label,
      border: const OutlineInputBorder(),
      isDense: true,
    );

    // ---------- controllers (AUTO remember) ----------
    final nameCtrl = ctrlText('name', activeLabel ?? 'Footing');
    final buildingFactorCtrl = ctrlNum('buildingFactor', '1');
    final qtyCtrl = ctrlNum('nFootings', '1'); // qty per building

    final lengthCtrl = TextEditingController(
      text:
          (lastFootingDefaults['Lm'] != null)
              ? '${lastFootingDefaults['Lm']}'
              : measuredLm.toStringAsFixed(3),
    );
    final widthCtrl = TextEditingController(
      text:
          (lastFootingDefaults['Bm'] != null)
              ? '${lastFootingDefaults['Bm']}'
              : measuredBm.toStringAsFixed(3),
    );

    final thicknessCtrl = ctrlNum('thicknessM', '0.30');

    final workingSpaceCtrl = ctrlNum('ws', '0.15');
    final excavationDepthCtrl = ctrlNum('excDepth', '0.35');
    final blindingThkCtrl = ctrlNum('blindT', '0.05');

    // BOQs
    final boqConcCodeCtrl = ctrlText('boqFootConcreteCode', '');
    final boqConcDescCtrl = ctrlText('boqFootConcreteDesc', '');

    final boqFwkCodeCtrl = ctrlText('boqFootFormworkCode', '');
    final boqFwkDescCtrl = ctrlText('boqFootFormworkDesc', '');

    const maxFootingExcavationBands = 20;
    final boqExcBandCodeCtrls = List.generate(
      maxFootingExcavationBands,
      (index) => ctrlText(
        index == 0 ? 'boqExcCode' : 'boqExcBand${index + 1}Code',
        '',
      ),
    );
    final boqExcBandDescCtrls = List.generate(
      maxFootingExcavationBands,
      (index) => ctrlText(
        index == 0 ? 'boqExcDesc' : 'boqExcBand${index + 1}Desc',
        '',
      ),
    );

    final boqBlindCodeCtrl = ctrlText('boqBlindCode', '');
    final boqBlindDescCtrl = ctrlText('boqBlindDesc', '');

    final boqBackfillCodeCtrl = ctrlText('boqBackfillCode', '');
    final boqBackfillDescCtrl = ctrlText('boqBackfillDesc', '');

    final boqDispCodeCtrl = ctrlText('boqDispCode', '');
    final boqDispDescCtrl = ctrlText('boqDispDesc', '');

    // ✅ Footing rebar AUTO (single BOQ)
    final boqRebarCodeCtrl = ctrlText('boqFootRebarCode', '');
    final boqRebarDescCtrl = ctrlText('boqFootRebarDesc', '');

    final ftgDiaCtrl = ctrlNum('ftgDia', '16'); // mm
    final ftgSpWidthCtrl = ctrlNum(
      'ftgSpWidth',
      '0.20',
    ); // spacing across WIDTH
    final ftgSpLengthCtrl = ctrlNum(
      'ftgSpLength',
      '0.20',
    ); // spacing across LENGTH
    final ftgCoverCtrl = ctrlNum('ftgCover', '0.05');
    final ftgEmbedCtrl = ctrlNum('ftgEmbed', '0.30'); // each end
    final ftgExtraCtrl = ctrlNum('ftgExtra', '0.00');

    // Optional foundation column, measured as part of this footing/excavation.
    final foundationColumnLengthCtrl = ctrlNum(
      'foundationColumnLengthM',
      '0.23',
    );
    final foundationColumnWidthCtrl = ctrlNum('foundationColumnWidthM', '0.23');
    final foundationMainDiaCtrl = ctrlNum('foundationMainDiaMm', '16');
    final foundationMainBarsCtrl = ctrlNum('foundationMainBars', '4');
    final foundationMainEmbedTopCtrl = ctrlNum(
      'foundationMainEmbedTopM',
      '0.30',
    );
    final foundationMainEmbedBottomCtrl = ctrlNum(
      'foundationMainEmbedBottomM',
      '0.30',
    );
    final foundationMainExtraCtrl = ctrlNum('foundationMainExtraM', '0.00');
    final foundationStirrupDiaCtrl = ctrlNum('foundationStirrupDiaMm', '10');
    final foundationStirrupSpacingCtrl = ctrlNum(
      'foundationStirrupSpacingM',
      '0.20',
    );
    final foundationStirrupCoverCtrl = ctrlNum(
      'foundationStirrupCoverM',
      '0.04',
    );
    final foundationStirrupHookCtrl = ctrlNum('foundationStirrupHookM', '0.20');

    final boqFoundationConcCodeCtrl = ctrlText('boqFoundationConcreteCode', '');
    final boqFoundationConcDescCtrl = ctrlText('boqFoundationConcreteDesc', '');
    final boqFoundationFwkCodeCtrl = ctrlText('boqFoundationFormworkCode', '');
    final boqFoundationFwkDescCtrl = ctrlText('boqFoundationFormworkDesc', '');
    final boqFoundationMainCodeCtrl = ctrlText('boqFoundationMainCode', '');
    final boqFoundationMainDescCtrl = ctrlText('boqFoundationMainDesc', '');
    final boqFoundationStirrupCodeCtrl = ctrlText(
      'boqFoundationStirrupCode',
      '',
    );
    final boqFoundationStirrupDescCtrl = ctrlText(
      'boqFoundationStirrupDesc',
      '',
    );

    // optional toggles
    bool saveConc = true;
    bool saveFwk = true;
    bool saveRebar = true;
    bool saveExc = true;
    bool saveBlind = true;
    bool saveBackfill = true;
    bool saveDisposal = true;
    bool includeFoundationColumn =
        lastFootingDefaults['includeFoundationColumn'] == true;
    bool saveFoundationConc = true;
    bool saveFoundationFwk = true;
    bool saveFoundationMain = true;
    bool saveFoundationStirrups = true;

    String? errorText;

    // group id across multiple footings (same idea as columns)
    draftFootingGroupId ??= measurementsRef.doc().id;
    final footingGroupId = draftFootingGroupId!;
    final segmentId = measurementsRef.doc().id;

    ColumnSaveAction action;
    do {
      action =
          await Get.dialog<ColumnSaveAction>(
            StatefulBuilder(
              builder: (ctx, setState) {
                final factor = i(buildingFactorCtrl, 1).clamp(1, 999999);
                final qtyPerBuilding = i(qtyCtrl, 1).clamp(1, 999999);

                final Lm = d(lengthCtrl, measuredLm);
                final Bm = d(widthCtrl, measuredBm);
                final t = d(thicknessCtrl, 0.0);

                final ws = d(workingSpaceCtrl, 0.0);
                final excDepth = d(excavationDepthCtrl, 0.0);
                final blindT = d(blindingThkCtrl, 0.05);

                final foundationL = d(foundationColumnLengthCtrl, 0.0);
                final foundationW = d(foundationColumnWidthCtrl, 0.0);
                final foundationH =
                    includeFoundationColumn
                        ? (excDepth - t).clamp(0.0, double.infinity)
                        : 0.0;
                final foundationConcOne =
                    foundationL * foundationW * foundationH;
                final foundationFwkOne =
                    2 * (foundationL + foundationW) * foundationH;
                final foundationMainDia =
                    int.tryParse(foundationMainDiaCtrl.text.trim()) ?? 0;
                final foundationMainBars =
                    int.tryParse(foundationMainBarsCtrl.text.trim()) ?? 0;
                final foundationMainLength =
                    foundationH +
                    d(foundationMainEmbedTopCtrl, 0.0) +
                    d(foundationMainEmbedBottomCtrl, 0.0) +
                    d(foundationMainExtraCtrl, 0.0);
                final foundationMainKgOne =
                    foundationMainBars *
                    foundationMainLength *
                    (foundationMainDia > 0
                        ? rebarUnitWeightKgPerM(foundationMainDia)
                        : 0.0);
                final foundationStirrupDia =
                    int.tryParse(foundationStirrupDiaCtrl.text.trim()) ?? 0;
                final foundationStirrupSpacing = d(
                  foundationStirrupSpacingCtrl,
                  0.0,
                );
                final foundationStirrupCover = d(
                  foundationStirrupCoverCtrl,
                  0.0,
                );
                final foundationStirrupCount =
                    foundationH > 0 && foundationStirrupSpacing > 0
                        ? (foundationH / foundationStirrupSpacing).floor() + 1
                        : 0;
                final foundationStirrupLength =
                    2 *
                        ((foundationL - 2 * foundationStirrupCover).clamp(
                              0.0,
                              double.infinity,
                            ) +
                            (foundationW - 2 * foundationStirrupCover).clamp(
                              0.0,
                              double.infinity,
                            )) +
                    d(foundationStirrupHookCtrl, 0.0);
                final foundationStirrupKgOne =
                    foundationStirrupCount *
                    foundationStirrupLength *
                    (foundationStirrupDia > 0
                        ? rebarUnitWeightKgPerM(foundationStirrupDia)
                        : 0.0);

                final totalFootings = qtyPerBuilding * factor;

                // per footing
                final concM3One =
                    (Lm > 0 && Bm > 0 && t > 0) ? (Lm * Bm * t) : 0.0;
                final perim = (Lm > 0 && Bm > 0) ? (2 * (Lm + Bm)) : 0.0;
                final fwkM2One = (perim > 0 && t > 0) ? (perim * t) : 0.0;

                final blindAreaOne = (Lm > 0 && Bm > 0) ? (Lm * Bm) : 0.0;
                final blindVolOne = blindAreaOne * blindT;

                final excL = Lm + 2 * ws;
                final excB = Bm + 2 * ws;
                final excM3One =
                    (excL > 0 && excB > 0 && excDepth > 0)
                        ? (excL * excB * excDepth)
                        : 0.0;
                final excavationBandCount =
                    excDepth > 0
                        ? (excDepth / 1.5)
                            .ceil()
                            .clamp(1, maxFootingExcavationBands)
                            .toInt()
                        : 0;

                // backfill/disposal
                // Foundation column displaces excavated material, reducing backfill
                // and increasing the removal/disposal quantity.
                final occupiedOne = concM3One + blindVolOne + foundationConcOne;
                final backfillOne = (excM3One - occupiedOne).clamp(
                  0.0,
                  double.infinity,
                );
                final disposalOne = (excM3One - backfillOne).clamp(
                  0.0,
                  double.infinity,
                );

                // ✅ rebar AUTO
                final dia = int.tryParse(ftgDiaCtrl.text.trim()) ?? 0;
                final spW = d(ftgSpWidthCtrl, 0.0);
                final spL = d(ftgSpLengthCtrl, 0.0);
                final cover = d(ftgCoverCtrl, 0.0);
                final embed = d(ftgEmbedCtrl, 0.0);
                final extra = d(ftgExtraCtrl, 0.0);

                final clearAcrossWidth = (Bm - 2 * cover).clamp(
                  0.0,
                  double.infinity,
                );
                final nBarsAlongLength = _barsFromSpacing(
                  clearAcrossWidth,
                  spW,
                );
                final barLenAlongLength = (Lm + 2 * embed + extra).clamp(
                  0.0,
                  double.infinity,
                );
                final totalLenAlongLength =
                    nBarsAlongLength * barLenAlongLength;

                final clearAcrossLength = (Lm - 2 * cover).clamp(
                  0.0,
                  double.infinity,
                );
                final nBarsAlongWidth = _barsFromSpacing(
                  clearAcrossLength,
                  spL,
                );
                final barLenAlongWidth = (Bm + 2 * embed + extra).clamp(
                  0.0,
                  double.infinity,
                );
                final totalLenAlongWidth = nBarsAlongWidth * barLenAlongWidth;

                final uw = (dia > 0) ? rebarUnitWeightKgPerM(dia) : 0.0;
                final rebarKgOne =
                    (saveRebar && uw > 0)
                        ? (totalLenAlongLength + totalLenAlongWidth) * uw
                        : 0.0;

                // per building
                final concPerB = concM3One * qtyPerBuilding;
                final fwkPerB = fwkM2One * qtyPerBuilding;
                final blindAreaPerB = blindAreaOne * qtyPerBuilding;
                final blindVolPerB = blindVolOne * qtyPerBuilding;
                final excPerB = excM3One * qtyPerBuilding;
                final backfillPerB = backfillOne * qtyPerBuilding;
                final disposalPerB = disposalOne * qtyPerBuilding;
                final rebarPerB = rebarKgOne * qtyPerBuilding;

                // totals (x factor)
                final concAll = concPerB * factor;
                final fwkAll = fwkPerB * factor;
                final blindAreaAll = blindAreaPerB * factor;
                final blindVolAll = blindVolPerB * factor;
                final excAll = excPerB * factor;
                final backfillAll = backfillPerB * factor;
                final disposalAll = disposalPerB * factor;
                final rebarAll = rebarPerB * factor;
                final foundationConcAll =
                    foundationConcOne * qtyPerBuilding * factor;
                final foundationFwkAll =
                    foundationFwkOne * qtyPerBuilding * factor;
                final foundationMainAll =
                    foundationMainKgOne * qtyPerBuilding * factor;
                final foundationStirrupAll =
                    foundationStirrupKgOne * qtyPerBuilding * factor;

                Widget footingMetric(
                  String label,
                  String value,
                  IconData icon,
                ) {
                  return Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      color: const Color(0xFFF8FAFC),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(color: const Color(0xFFE2E8F0)),
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 34,
                          height: 34,
                          decoration: BoxDecoration(
                            color: const Color(0xFFEFF6FF),
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Icon(
                            icon,
                            color: const Color(0xFF155EEF),
                            size: 18,
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
