  Future<void> showSlabCompositeDetailsDialog({
    required BuildContext context,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String drawingId,
    required String slabId,
    required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,
  }) async {
    String _s(dynamic v) => (v ?? '').toString();
    double _d(dynamic v) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? 0.0;

    // ---- group key (for UI rows) ----
    String _keyOf(Map<String, dynamic> mm) {
      final type = _s(mm['type']).trim();
      final code = _s(mm['boqCode']).trim();
      final u = _s(mm['unit']).trim();
      return '$type|$code|$u';
    }

    // ---- stream docs by slabId group ----
    Stream<QuerySnapshot<Map<String, dynamic>>> _streamDocs() {
      return measurementsRef
          .where('drawingId', isEqualTo: drawingId)
          .where('slabId', isEqualTo: slabId)
          .stateSnapshots();
    }

    // ✅ ensure slabId exists on docs (legacy safety)
    Future<String> _ensureSlabId() async {
      // slabId is the group id; ensure at least one doc has it (normally yes)
      final qs =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('slabId', isEqualTo: slabId)
              .limit(1)
              .get();

      if (qs.docs.isNotEmpty) return slabId;

      // If nothing found, try fallback: maybe old field 'slabGroupId'
      final qs2 =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('slabGroupId', isEqualTo: slabId)
              .get();

      if (qs2.docs.isNotEmpty) {
        final b = FirebaseFirestore.instance.batch();
        for (final d in qs2.docs) {
          b.update(d.reference, {
            'slabId': slabId,
            'updatedAt': FieldValue.serverTimestamp(),
          });
        }
        await b.commit();
        return slabId;
      }

      return slabId;
    }

    // ---- safe clone for set() ----
    Map<String, dynamic> _safeCloneForSet(Map<String, dynamic> input) {
      final out = <String, dynamic>{};
      input.forEach((k, v) {
        if (k == '__id') return;
        // Avoid copying FieldValue.* into set() payload
        if (v is FieldValue) return;
        out[k] = v;
      });
      return out;
    }

    // ✅ attach NEW BOQ line into this slab group
    Future<void> _attachNewBoqLine({
      required String slabId,
      required Map<String, dynamic> baseDoc,
      required BoqPick pick,
    }) async {
      final now = FieldValue.serverTimestamp();

      final base = _safeCloneForSet(baseDoc);

      // force group keys
      base['slabId'] = slabId;
      base['drawingId'] = drawingId;

      // overwrite BOQ fields
      base['boqItemId'] = pick.id;
      base['boqCode'] = pick.code;
      base['boqDescription'] = pick.description;

      // label fallback
      final lbl = _s(base['label']).trim();
      if (lbl.isEmpty ||
          lbl.toLowerCase() == 'slab' ||
          lbl.toLowerCase() == 'item') {
        base['label'] =
            pick.description.trim().isNotEmpty
                ? pick.description.trim()
                : 'Slab item';
      }

      // timestamps
      base['createdAt'] = now;
      base['updatedAt'] = now;

      // write new doc
      await measurementsRef.doc().set(base);
    }

    // helper: update BOQ fields for all docs matching (type + old boqCode) in this slabId
    Future<void> _changeBoqForLine({
      required String slabId,
      required String type,
      required String oldBoqCode,
      required BoqPick newPick,
    }) async {
      final snap =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('slabId', isEqualTo: slabId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: oldBoqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.update(d.reference, {
          'boqItemId': newPick.id,
          'boqCode': newPick.code,
          'boqDescription': newPick.description,
          'updatedAt': FieldValue.serverTimestamp(),
        });
      }
      await b.commit();
    }

    // helper: delete all docs matching (type + boqCode) in this slabId
    Future<void> _removeLine({
      required String slabId,
      required String type,
      required String boqCode,
    }) async {
      final snap =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('slabId', isEqualTo: slabId)
              .where('type', isEqualTo: type)
              .where('boqCode', isEqualTo: boqCode)
              .get();

      if (snap.docs.isEmpty) return;

      final b = FirebaseFirestore.instance.batch();
      for (final d in snap.docs) {
        b.delete(d.reference);
      }
      await b.commit();
    }

    // helper: delete one doc
    Future<void> _deleteOne(String id) async {
      final ok =
          await showDialog<bool>(
            context: context,
            builder:
                (_) => AlertDialog(
                  title: const Text('Delete item?'),
                  content: Text('Delete this record?\nID: $id'),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.pop(context, false),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () => Navigator.pop(context, true),
                      child: const Text('Delete'),
                    ),
                  ],
                ),
          ) ??
          false;

      if (!ok) return;

      await measurementsRef.doc(id).delete();
      if (context.mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Item deleted')));
      }
      update(['viewer', 'summary']);
    }

    // helper: delete whole group
    Future<void> _deleteGroup() async {
      final ok =
          await showDialog<bool>(
            context: context,
            builder:
                (_) => AlertDialog(
                  title: const Text('Delete slab group?'),
                  content: Text('Delete ALL items under slabId:\n$slabId ?'),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.pop(context, false),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () => Navigator.pop(context, true),
                      child: const Text('Delete group'),
                    ),
                  ],
                ),
          ) ??
          false;

      if (!ok) return;

      final qs =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('slabId', isEqualTo: slabId)
              .get();

      final batch = FirebaseFirestore.instance.batch();
      for (final d in qs.docs) {
        batch.delete(d.reference);
      }
      await batch.commit();

      update(['viewer', 'summary']);
      if (context.mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Slab group deleted')));
        Navigator.pop(context); // close details dialog
      }
    }

    await showDialog(
      context: context,
      barrierDismissible: true,
      builder: (ctx) {
        return AlertDialog(
          title: Text('Slab details — $slabId'),
          content: SizedBox(
            width: 760,
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: _streamDocs(),
              builder: (ctx, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(20),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }

                final docs =
                    snap.data!.docs.map((e) {
                      final mm = Map<String, dynamic>.from(e.data());
                      mm['__id'] = e.id;
                      return mm;
                    }).toList();

                if (docs.isEmpty) {
                  return const Text('No slab records found for this slabId.');
                }

                // base doc template
                final baseDoc = Map<String, dynamic>.from(docs.first);

                // totals
                double panelAreaM2 = 0.0;
                double concreteM3 = 0.0;
                double soffitM2 = 0.0;
                double edgeM2 = 0.0;
                double rebarKg = 0.0;
                double rebarLenM = 0.0;

                for (final mm in docs) {
                  final type = _s(mm['type']).trim();
                  final v = _d(mm['value']);

                  // panel area: take from any doc that stores areaM2
                  final a = _d(mm['areaM2']);
                  if (panelAreaM2 <= 0 && a > 0) panelAreaM2 = a;

                  if (type == 'slabConcrete') concreteM3 += v;
                  if (type == 'slabFormworkSoffit' ||
                      type == 'slabSoffitFormwork') {
                    soffitM2 += v;
                  }
                  if (type == 'slabFormworkEdge' ||
                      type == 'slabEdgeFormwork') {
                    edgeM2 += v;
                  }
                  if (type == 'rebarSlab' || type == 'rebarSlabExtraSegment') {
                    rebarKg += _d(mm['totalWeightKg'] ?? mm['value']);
                    rebarLenM += _d(
                      mm['totalLengthAllBarsM'] ?? mm['totalLengthM'],
                    );
                  }
                }

                // group BOQ lines (like area dialog)
                final grouped = <String, Map<String, dynamic>>{};
                for (final mm in docs) {
                  final type = _s(mm['type']).trim();
                  final boqCode = _s(mm['boqCode']).trim();
                  final boqDesc = _s(mm['boqDescription']).trim();
                  final u = _s(mm['unit']).trim();
                  final v = _d(mm['value']);

                  if (boqCode.isEmpty) continue;

                  final key = _keyOf(mm);
                  final g = grouped.putIfAbsent(key, () {
                    return {
                      'type': type,
                      'boqCode': boqCode,
                      'boqDesc': boqDesc,
                      'unit': u,
                      'qty': 0.0,
                    };
                  });
                  g['qty'] = (_d(g['qty']) + v);
                }

                final rows =
                    grouped.values.toList()..sort(
                      (a, b) => _s(a['boqCode']).compareTo(_s(b['boqCode'])),
                    );

                return SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Card(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                'Slab group: $slabId',
                                style: const TextStyle(fontSize: 12),
                              ),
                              const SizedBox(height: 8),
                              Wrap(
                                spacing: 18,
                                runSpacing: 8,
                                children: [
                                  if (panelAreaM2 > 0)
                                    Text(
                                      'Panel area: ${panelAreaM2.toStringAsFixed(3)} m²',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                  if (concreteM3 > 0)
                                    Text(
                                      'Concrete: ${concreteM3.toStringAsFixed(3)} m³',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  if (soffitM2 > 0)
                                    Text(
                                      'Soffit FW: ${soffitM2.toStringAsFixed(3)} m²',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  if (edgeM2 > 0)
                                    Text(
                                      'Edge FW: ${edgeM2.toStringAsFixed(3)} m²',
