  Future<SlabExtraRebarSegmentDraft?> editSlabExtraSegmentDialog({
    SlabExtraRebarSegmentDraft? existing,
  }) async {
    final markCtrl = TextEditingController(text: existing?.rawMark ?? '');
    final clearCtrl = TextEditingController(
      text: existing?.clearLengthM.toString() ?? '',
    );
    final embedCtrl = TextEditingController(
      text: (existing?.embedEachEndM ?? 0.30).toString(),
    );
    final extraCtrl = TextEditingController(
      text: (existing?.extraLengthM ?? 0.00).toString(),
    );
    final countCtrl = TextEditingController(
      text: (existing?.segmentCount ?? 1).toString(),
    );
    final boqCtrl = TextEditingController(text: existing?.boqCode ?? '');
    final noteCtrl = TextEditingController(text: existing?.note ?? '');

    String? err;

    SlabExtraRebarSegmentDraft?
    result = await Get.dialog<SlabExtraRebarSegmentDraft>(
      StatefulBuilder(
        builder: (context, setState) {
          return AlertDialog(
            title: Text(
              existing == null
                  ? 'Add extra rebar segment'
                  : 'Edit extra rebar segment',
            ),
            content: SizedBox(
              width: 520,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  TextField(
                    controller: markCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Mark (e.g. 3Y12-ES1)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: clearCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: const InputDecoration(
                            labelText: 'Clear length (m)',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: countCtrl,
                          keyboardType: TextInputType.number,
                          decoration: const InputDecoration(
                            labelText: 'No. of segments',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: embedCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: const InputDecoration(
                            labelText: 'Embed each end (m)',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: extraCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: const InputDecoration(
                            labelText: 'Extra length (m)',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: boqCtrl,
                    decoration: const InputDecoration(
                      labelText: 'BOQ code',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: noteCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Note (optional)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                  ),
                  if (err != null) ...[
                    const SizedBox(height: 8),
                    Text(err!, style: const TextStyle(color: Colors.red)),
                  ],
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () {
                  try {
                    final raw = markCtrl.text.trim();
                    final boq = boqCtrl.text.trim();
                    final clear = double.tryParse(clearCtrl.text.trim()) ?? 0;
                    final embed =
                        double.tryParse(embedCtrl.text.trim()) ?? 0.30;
                    final extra = double.tryParse(extraCtrl.text.trim()) ?? 0.0;
                    final segCount = int.tryParse(countCtrl.text.trim()) ?? 0;

                    if (raw.isEmpty || boq.isEmpty) {
                      setState(() => err = 'Mark and BOQ code are required.');
                      return;
                    }
                    if (clear <= 0) {
                      setState(() => err = 'Clear length must be > 0.');
                      return;
                    }
                    if (segCount <= 0) {
                      setState(() => err = 'No. of segments must be ≥ 1.');
                      return;
                    }

                    final parsed = parseBarsMark(raw);
                    final barsPerSeg = parsed['barsPerSegment'] as int;
                    final dia = parsed['diameterMm'] as int;

                    final barLen = clear + 2 * embed + extra;
                    final totalBars = barsPerSeg * segCount;
                    final totalLen = totalBars * barLen;

                    final uw = unitWeightKgPerM(dia);
                    final totalWt = totalLen * uw;

                    Get.back(
                      result: SlabExtraRebarSegmentDraft(
                        rawMark: raw,
                        clearLengthM: clear,
                        embedEachEndM: embed,
                        extraLengthM: extra,
                        segmentCount: segCount,
                        boqCode: boq,
                        note: noteCtrl.text.trim(),
                        barsPerSegment: barsPerSeg,
                        diameterMm: dia,
                        barLengthM: barLen,
                        totalBars: totalBars,
                        totalLengthM: totalLen,
                        totalWeightKg: totalWt,
                        unitWeightKgPerM: uw,
                      ),
                    );
                  } catch (e) {
                    setState(() => err = e.toString());
                  }
                },
                child: const Text('OK'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    markCtrl.dispose();
    clearCtrl.dispose();
    embedCtrl.dispose();
    extraCtrl.dispose();
    countCtrl.dispose();
    boqCtrl.dispose();
    noteCtrl.dispose();

    return result;
  }

  Future<void> showRebarSlabDetailsDialog({
    required String slabId,
    required List<QueryDocumentSnapshot> docs,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return;

    await showDialog(
      context: ctx,
      builder: (dialogCtx) {
        return AlertDialog(
          title: const Text('Slab rebar details'),
          content: SizedBox(
            width: 380,
            child: SizedBox(
              height: 320,
              child: ListView.builder(
                shrinkWrap: true,
                itemCount: docs.length,
                itemBuilder: (rowCtx, i) {
                  final d = docs[i];
                  final m = d.data() as Map<String, dynamic>;

                  final markRaw = (m['markRaw'] ?? '') as String;

                  // If you store direction explicitly, prefer that:
                  // final dir = (m['direction'] ?? '') as String;
                  // Here I keep your original "H/V" heuristic:
                  final clearSpanM = (m['clearSpanM'] as num? ?? 0).toDouble();
                  final widthM = (m['widthM'] as num? ?? -9999).toDouble();
                  final dir = (clearSpanM == widthM) ? 'H' : 'V';

                  final barLen = (m['barLengthM'] as num? ?? 0).toDouble();
                  final totalLen = (m['totalLengthM'] as num? ?? 0).toDouble();
                  final totalKg = (m['totalWeightKg'] as num? ?? 0).toDouble();

                  return Card(
                    margin: const EdgeInsets.symmetric(
                      vertical: 4,
                      horizontal: 0,
                    ),
                    child: Padding(
                      padding: const EdgeInsets.all(6.0),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          // Text side
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  markRaw.isNotEmpty
                                      ? markRaw
                                      : 'Rebar set ${i + 1}',
                                  style: const TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  'Dir: $dir, '
                                  'Clear span: ${clearSpanM.toStringAsFixed(3)} m, '
                                  'L/bar: ${barLen.toStringAsFixed(3)} m',
                                  style: const TextStyle(fontSize: 11),
                                ),
                                Text(
                                  'Total length: ${totalLen.toStringAsFixed(3)} m, '
                                  'Weight: ${totalKg.toStringAsFixed(1)} kg',
                                  style: const TextStyle(fontSize: 11),
                                ),
                              ],
                            ),
                          ),

                          // Actions
                          Column(
                            children: [
                              IconButton(
                                tooltip: 'Edit',
                                icon: const Icon(Icons.edit, size: 18),
                                onPressed: () async {
                                  // Close this dialog first
                                  Navigator.pop(dialogCtx);

                                  // Then open your edit dialog.
                                  // Implement this method in the controller
                                  // or rename to match your existing one.
                                  await editRebarSlabMark(doc: d);
                                },
                              ),
                              IconButton(
                                tooltip: 'Delete',
                                icon: const Icon(
                                  Icons.delete_outline,
                                  size: 18,
                                ),
                                onPressed: () async {
                                  await d.reference.delete();
                                },
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogCtx),
              child: const Text('Close'),
            ),
          ],
        );
      },
    );
  }

