  Future<void> showRebarFootingDetailsDialog({
    required String footingGroupId,
    required List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
  }) async {
    if (docs.isEmpty) return;

    final ctxRoot = Get.context;
    if (ctxRoot == null) return;

    // mutable copy so we can update after deletions
    List<QueryDocumentSnapshot<Map<String, dynamic>>> localDocs = List.of(docs);

    double _asDouble(dynamic v) => v is num ? v.toDouble() : 0.0;
    int _asInt(dynamic v) => v is int ? v : (v is num ? v.toInt() : 0);

    await showDialog<void>(
      context: ctxRoot,
      builder: (dialogCtx) {
        return StatefulBuilder(
          builder: (dialogCtx, setStateDialog) {
            if (localDocs.isEmpty) {
              return AlertDialog(
                title: const Text('Footing composite details'),
                content: const Text(
                  'No measurements remain for this footing group.',
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(dialogCtx),
                    child: const Text('Close'),
                  ),
                ],
              );
            }

            // ---- split into concrete / formwork / rebar Footing ----
            final concreteDocs =
                localDocs.where((d) {
                  final m = d.data();
                  return (m['type'] ?? '') == 'footingConcrete';
                }).toList();

            final formworkDocs =
                localDocs.where((d) {
                  final m = d.data();
                  return (m['type'] ?? '') == 'footingFormwork';
                }).toList();

            final rebarDocs =
                localDocs.where((d) {
                  final m = d.data();
                  return (m['type'] ?? '') == 'rebarFooting';
                }).toList();

            // ---- read nFootings & a baseData from any of the docs ----
            int nFootings = 0;
            Map<String, dynamic>? baseData;
            if (concreteDocs.isNotEmpty) {
              baseData = concreteDocs.first.data();
            } else if (formworkDocs.isNotEmpty) {
              baseData = formworkDocs.first.data();
            } else if (rebarDocs.isNotEmpty) {
              baseData = rebarDocs.first.data();
            }

            if (baseData != null) {
              nFootings = _asInt(
                baseData['nFootings'] ?? baseData['footingCount'],
              );
            }

            // ---- totals ----
            final totalConcreteM3 = concreteDocs.fold<double>(
              0.0,
              (sum, d) => sum + _asDouble(d.data()['value']),
            );

            final totalFormworkM2 = formworkDocs.fold<double>(
              0.0,
              (sum, d) => sum + _asDouble(d.data()['value']),
            );

            final totalRebarKg = rebarDocs.fold<double>(0.0, (sum, d) {
              final m = d.data();
              return sum +
                  _asDouble(
                    m['weightAllFootingsKg'] ?? m['totalWeightAllFootingsKg'],
                  );
            });

            return AlertDialog(
              title: const Text('Footing composite details'),
              content: SizedBox(
                width: 440,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      // ---- SUMMARY HEADER ----
                      Align(
                        alignment: Alignment.centerLeft,
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            if (nFootings > 0)
                              Text(
                                'Footings in this group: $nFootings',
                                style: const TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            if (totalConcreteM3 > 0)
                              Text(
                                'Concrete: ${totalConcreteM3.toStringAsFixed(3)} m³',
                                style: const TextStyle(fontSize: 11),
                              ),
                            if (totalFormworkM2 > 0)
                              Text(
                                'Formwork: ${totalFormworkM2.toStringAsFixed(3)} m²',
                                style: const TextStyle(fontSize: 11),
                              ),
                            if (totalRebarKg > 0)
                              Text(
                                'Rebar: ${totalRebarKg.toStringAsFixed(2)} kg',
                                style: const TextStyle(fontSize: 11),
                              ),
                          ],
                        ),
                      ),
                      const SizedBox(height: 8),
                      const Divider(),

                      // ---- DETAILS LIST ----
                      SingleChildScrollView(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            // --- Concrete section ---
                            if (concreteDocs.isNotEmpty) ...[
                              const Text(
                                'Concrete',
                                style: TextStyle(
                                  fontSize: 13,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                              const SizedBox(height: 4),
                              ...concreteDocs.map((d) {
                                final m = d.data();
                                final vTotal = _asDouble(m['value']);
                                final boqCode = (m['boqCode'] ?? '') as String;
                                final vPerFoot = _asDouble(
                                  m['valuePerFooting'],
                                );
                                final L = _asDouble(m['lengthM']);
                                final B = _asDouble(m['widthM']);
                                final t = _asDouble(m['thicknessM']);

                                return ListTile(
                                  dense: true,
                                  contentPadding: EdgeInsets.zero,
                                  title: const Text(
                                    'Footing concrete',
                                    style: TextStyle(
                                      fontSize: 12,
                                      fontWeight: FontWeight.w600,
                                    ),
                                  ),
                                  subtitle: Text(
                                    'Size ~ ${L.toStringAsFixed(3)}m × '
                                    '${B.toStringAsFixed(3)}m × '
                                    '${t.toStringAsFixed(3)}m\n'
                                    'Per footing: ${vPerFoot.toStringAsFixed(3)} m³, '
                                    'Total: ${vTotal.toStringAsFixed(3)} m³\n'
                                    'BoQ Code: $boqCode',
                                    style: const TextStyle(fontSize: 11),
                                  ),
                                  trailing: IconButton(
                                    icon: const Icon(
                                      Icons.delete_outline,
                                      size: 18,
                                    ),
                                    onPressed: () async {
                                      final confirm = await showDialog<bool>(
                                        context: dialogCtx,
                                        builder: (ctx2) {
                                          return AlertDialog(
                                            title: const Text(
                                              'Delete concrete measurement?',
                                            ),
                                            content: const Text(
                                              'This will remove the concrete entry for this footing group.',
                                            ),
                                            actions: [
                                              TextButton(
                                                onPressed:
                                                    () => Navigator.pop(
                                                      ctx2,
                                                      false,
                                                    ),
                                                child: const Text('Cancel'),
                                              ),
                                              FilledButton(
                                                onPressed:
                                                    () => Navigator.pop(
                                                      ctx2,
                                                      true,
                                                    ),
                                                child: const Text('Delete'),
                                              ),
                                            ],
                                          );
                                        },
                                      );

                                      if (confirm == true) {
                                        await measurementsRef
                                            .doc(d.id)
                                            .delete();
                                        setStateDialog(() {
                                          localDocs.removeWhere(
                                            (x) => x.id == d.id,
                                          );
                                        });
                                      }
                                    },
                                  ),
                                );
                              }).toList(),
                              const Divider(),
                            ],

                            // --- Formwork section ---
                            if (formworkDocs.isNotEmpty) ...[
                              const Text(
                                'Formwork',
                                style: TextStyle(
                                  fontSize: 13,
                                  fontWeight: FontWeight.w600,
                                ),
