  Future<bool> _prepareManualSlabRebarCapture({
    required List<Offset> polygon,
    required String drawingImageUrl,
    required double drawingImageWidth,
    required double drawingImageHeight,
  }) async {
    final markController = TextEditingController();
    final occurrencesController = TextEditingController(text: '1');
    final embedController = TextEditingController(text: '0.30');
    final extraController = TextEditingController(text: '0.00');
    String? validationMessage;
    String? ocrMessage;
    var isReadingMark = true;
    var ocrStarted = false;

    var minX = polygon.first.dx;
    var maxX = polygon.first.dx;
    var minY = polygon.first.dy;
    var maxY = polygon.first.dy;
    for (final point in polygon.skip(1)) {
      minX = math.min(minX, point.dx);
      maxX = math.max(maxX, point.dx);
      minY = math.min(minY, point.dy);
      maxY = math.max(maxY, point.dy);
    }

    Widget capturedMarkPreview() {
      final cropWidth = math.max(1.0, maxX - minX);
      final cropHeight = math.max(1.0, maxY - minY);
      return Container(
        height: 170,
        width: double.infinity,
        decoration: BoxDecoration(
          color: const Color(0xFFF3F6FC),
          border: Border.all(color: const Color(0xFFCAD3E3)),
          borderRadius: BorderRadius.circular(14),
        ),
        clipBehavior: Clip.antiAlias,
        child: LayoutBuilder(
          builder: (context, constraints) {
            final validImageSize =
                drawingImageWidth > 0 && drawingImageHeight > 0;
            if (!validImageSize) {
              return Image.network(
                drawingImageUrl,
                fit: BoxFit.cover,
                errorBuilder:
                    (_, __, ___) => const Center(
                      child: Text('Captured mark preview unavailable'),
                    ),
              );
            }
            final scale = math.min(
              constraints.maxWidth / cropWidth,
              constraints.maxHeight / cropHeight,
            );
            return Stack(
              clipBehavior: Clip.hardEdge,
              children: [
                Positioned(
                  left: -minX * scale,
                  top: -minY * scale,
                  width: drawingImageWidth * scale,
                  height: drawingImageHeight * scale,
                  child: Image.network(
                    drawingImageUrl,
                    fit: BoxFit.fill,
                    errorBuilder: (_, __, ___) => const SizedBox.shrink(),
                  ),
                ),
              ],
            );
          },
        ),
      );
    }

    final accepted = await Get.dialog<bool>(
      StatefulBuilder(
        builder: (context, setState) {
          if (!ocrStarted) {
            ocrStarted = true;
            WidgetsBinding.instance.addPostFrameCallback((_) async {
              try {
                final recognized =
                    (await recognizeRebarMark(
                      imageUrl: drawingImageUrl,
                      minX: minX,
                      minY: minY,
                      maxX: maxX,
                      maxY: maxY,
                      drawingWidth: drawingImageWidth,
                      drawingHeight: drawingImageHeight,
                    )).trim();
                if (!context.mounted) return;
                setState(() {
                  isReadingMark = false;
                  if (recognized.isNotEmpty) {
                    markController.text = recognized;
                    markController.selection = TextSelection.collapsed(
                      offset: recognized.length,
                    );
                    ocrMessage = 'Bar mark filled from the captured drawing.';
                  } else {
                    ocrMessage =
                        'The mark was not clear enough to read. Please enter it manually.';
                  }
                });
              } catch (_) {
                if (!context.mounted) return;
                setState(() {
                  isReadingMark = false;
                  ocrMessage =
                      'The mark was not clear enough to read. Please enter it manually.';
                });
              }
            });
          }
          return AlertDialog(
            title: const Text('Record captured bar mark'),
            content: SizedBox(
              width: 620,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Confirm the notation shown in the captured drawing region. '
                      'Next, tap the two ends of one bar to measure its length.',
                    ),
                    const SizedBox(height: 12),
                    const Text(
                      'CAPTURED FROM DRAWING',
                      style: TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF5F6F89),
                      ),
                    ),
                    const SizedBox(height: 6),
                    capturedMarkPreview(),
                    const SizedBox(height: 16),
                    TextField(
                      controller: markController,
                      autofocus: false,
                      decoration: const InputDecoration(
                        labelText: 'Captured bar mark',
                        hintText: 'e.g. 8Y16-13-200',
                      ),
                    ),
                    const SizedBox(height: 8),
                    Row(
                      children: [
                        if (isReadingMark) ...[
                          const SizedBox(
                            width: 16,
                            height: 16,
                            child: CircularProgressIndicator(strokeWidth: 2),
                          ),
                          const SizedBox(width: 8),
                          const Text('Reading bar mark from the snapshot…'),
                        ] else if (ocrMessage != null) ...[
                          Icon(
                            markController.text.trim().isNotEmpty
                                ? Icons.check_circle_outline
                                : Icons.info_outline,
                            size: 18,
                            color:
                                markController.text.trim().isNotEmpty
                                    ? const Color(0xFF16A34A)
                                    : const Color(0xFFF59E0B),
                          ),
                          const SizedBox(width: 8),
                          Flexible(child: Text(ocrMessage!)),
                        ],
                      ],
                    ),
                    const SizedBox(height: 12),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: occurrencesController,
                            keyboardType: TextInputType.number,
                            decoration: const InputDecoration(
                              labelText: 'Occurrences',
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: TextField(
                            controller: embedController,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Embed each end (m)',
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: TextField(
                            controller: extraController,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Hooks/laps (m)',
                            ),
                          ),
                        ),
                      ],
                    ),
                    if (validationMessage != null) ...[
                      const SizedBox(height: 10),
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Colors.red),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(result: false),
                child: const Text('Cancel'),
              ),
              FilledButton.icon(
                onPressed:
                    isReadingMark
                        ? null
                        : () {
                          try {
                            final rawMark = markController.text.trim();
                            final mark = RebarMark.parse(rawMark);
                            final occurrences = int.tryParse(
                              occurrencesController.text.trim(),
                            );
                            final embed = double.tryParse(
                              embedController.text.trim(),
                            );
                            final extra = double.tryParse(
                              extraController.text.trim(),
                            );
                            if (occurrences == null || occurrences < 1) {
                              throw const FormatException(
                                'Occurrences must be at least 1.',
                              );
                            }
                            if (embed == null ||
                                embed < 0 ||
                                extra == null ||
                                extra < 0) {
                              throw const FormatException(
                                'Lengths cannot be negative.',
                              );
                            }
                            _pendingSlabRebarCapture = PendingSlabRebarCapture(
                              rawMark: rawMark,
                              mark: mark,
                              occurrences: occurrences,
                              embedEachEndM: embed,
                              extraLengthM: extra,
                              markPolygon: List<Offset>.from(polygon),
                            );
                            Get.back(result: true);
                          } catch (error) {
                            setState(() {
                              validationMessage =
                                  error is FormatException &&
                                          error.message.toString().isNotEmpty
                                      ? error.message.toString()
                                      : 'Check the bar mark, for example 8Y16-13-200.';
                            });
                          }
                        },
                icon: const Icon(Icons.straighten),
                label: const Text('Measure bar length'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    // On Flutter Web the dialog future can complete while its reverse route
    // transition still owns TextField dependants. Disposing these controllers
    // immediately can make the input subtree unmount out of order and trigger
    // framework.dart's `_dependents.isEmpty` assertion. Let the outgoing route
    // finish before releasing the form controllers.
    await WidgetsBinding.instance.endOfFrame;
    await Future<void>.delayed(const Duration(milliseconds: 300));
    markController.dispose();
    occurrencesController.dispose();
    embedController.dispose();
    extraController.dispose();
    if (accepted == true) {
      update(['viewr', 'viewer', 'overlay']);
    }
    return accepted == true;
  }

  Future<bool> completePendingSlabRebarLength({
    required Offset p1,
    required Offset p2,
    required double measuredLengthM,
  }) async {
    final pending = _pendingSlabRebarCapture;
    final context = Get.context;
    if (pending == null || context == null || measuredLengthM <= 0)
      return false;

    final barLength =
        measuredLengthM + (2 * pending.embedEachEndM) + pending.extraLengthM;
    final barsCount = pending.mark.quantity * pending.occurrences;
    final totalLength = barLength * barsCount;
    final unitWeight = rebarUnitWeightKgPerM(pending.mark.diameterMm);
    final weight = totalLength * unitWeight;

    Widget summaryRow(String label, String value, {bool total = false}) {
      final style =
          total
              ? const TextStyle(fontSize: 18, fontWeight: FontWeight.w800)
              : const TextStyle(fontSize: 15, fontWeight: FontWeight.w600);
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Expanded(
              child: Text(
                label,
                style: TextStyle(
                  fontSize: total ? 18 : 15,
                  color: total ? null : Colors.blueGrey.shade700,
                  fontWeight: total ? FontWeight.w800 : FontWeight.w500,
                ),
              ),
            ),
            const SizedBox(width: 16),
            Text(value, textAlign: TextAlign.right, style: style),
          ],
        ),
      );
    }

    final proceedToBoq = await Get.dialog<bool>(
      AlertDialog(
        title: const Text('Rebar calculation summary'),
        content: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                summaryRow('Bar mark', pending.rawMark),
                summaryRow(
                  'Bar size',
                  '${pending.mark.diameterMm.toStringAsFixed(0)} mm',
                ),
                summaryRow(
                  'Unit weight',
                  '${unitWeight.toStringAsFixed(3)} kg/m',
                ),
                summaryRow('Total bars', '$barsCount'),
                summaryRow(
                  'Measured length',
                  '${measuredLengthM.toStringAsFixed(3)} m',
                ),
                summaryRow(
                  'Embed allowance',
                  '2 × ${pending.embedEachEndM.toStringAsFixed(2)} m',
                ),
                summaryRow(
                  'Hooks / laps',
                  '${pending.extraLengthM.toStringAsFixed(2)} m',
                ),
                summaryRow(
                  'Length per bar',
                  '${barLength.toStringAsFixed(3)} m',
                ),
                summaryRow(
                  'Total bar length',
                  '${totalLength.toStringAsFixed(3)} m',
                ),
                const Divider(height: 28),
                summaryRow(
                  'Total reinforcement',
                  '${weight.toStringAsFixed(2)} kg',
                  total: true,
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Get.back(result: false),
            child: const Text('Cancel'),
          ),
          FilledButton.icon(
            onPressed: () => Get.back(result: true),
            icon: const Icon(Icons.receipt_long_outlined),
            label: const Text('Pick BOQ code'),
          ),
        ],
      ),
      barrierDismissible: false,
    );
    if (proceedToBoq != true) return false;

    BoqPick? selectedBoq;
    final lastBoq = _lastSlabRebarBoq;
    if (lastBoq != null) {
      final useLast = await Get.dialog<bool>(
        AlertDialog(
          title: const Text('Assign reinforcement BOQ'),
          content: Text(
            'Use ${lastBoq.code} — ${lastBoq.description} for this bar group?',
          ),
          actions: [
            TextButton(
              onPressed: () => Get.back<bool>(),
              child: const Text('Cancel'),
            ),
            OutlinedButton(
              onPressed: () => Get.back(result: false),
              child: const Text('Choose another'),
            ),
            FilledButton.icon(
              onPressed: () => Get.back(result: true),
              icon: const Icon(Icons.history),
              label: const Text('Use last BOQ'),
            ),
          ],
        ),
        barrierDismissible: false,
      );
      if (useLast == null) return false;
      selectedBoq =
          useLast ? lastBoq : await showBoqPickerDialog(context: context);
    } else {
      selectedBoq = await showBoqPickerDialog(context: context);
    }
    if (selectedBoq == null) return false;

    final capturedPolygon =
        pending.markPolygon
            .map((point) => {'x': point.dx, 'y': point.dy})
            .toList();
    unawaited(
      Get.dialog<void>(
        PopScope(
          canPop: false,
          child: AlertDialog(
            title: const Text('Saving reinforcement'),
            content: Row(
              children: [
                const SizedBox(
                  width: 34,
                  height: 34,
                  child: CircularProgressIndicator(),
                ),
                const SizedBox(width: 20),
                Expanded(
                  child: Text(
                    'Saving ${pending.rawMark} and updating the slab summary…',
                  ),
                ),
              ],
            ),
          ),
        ),
        barrierDismissible: false,
      ),
    );
    await Future<void>.delayed(const Duration(milliseconds: 60));

    try {
      await measurementsRef.add({
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'type': 'rebarSlabManual',
        'measureType': 'slabRebarAi',
        'label': 'Slab reinforcement',
        'unit': 'kg',
        'value': weight,
        'boqItemId': selectedBoq.id,
        'boqCode': selectedBoq.code,
        'boqDescription': selectedBoq.description,
        'rawMark': pending.rawMark,
        ...pending.mark.toMap(),
        'occurrences': pending.occurrences,
        'barsCount': barsCount,
        'measuredLengthM': measuredLengthM,
        'embedEachEndM': pending.embedEachEndM,
        'extraLengthM': pending.extraLengthM,
        'barLengthM': barLength,
        'totalLengthM': totalLength,
        'totalLengthAllBarsM': totalLength,
        'unitWeightKgPerM': unitWeight,
        'totalWeightKg': weight,
        'captureMethod': 'markSnapshotAndPointToPoint',
        'aiVerified': false,
        'markPolygon': capturedPolygon,
        'polygon': capturedPolygon,
        'p1': {'x': p1.dx, 'y': p1.dy},
        'p2': {'x': p2.dx, 'y': p2.dy},
        'color': currentColor.value,
        'createdAt': FieldValue.serverTimestamp(),
      });

      _lastSlabRebarBoq = selectedBoq;
      _pendingSlabRebarCapture = null;
      if (Get.isDialogOpen == true) Get.back<void>();
      update(['viewr', 'viewer', 'overlay', 'summary']);
      await Get.dialog<void>(
        AlertDialog(
          title: const Text('Rebar group saved'),
          content: Text(
            '${pending.rawMark}\n'
            'Measured bar: ${measuredLengthM.toStringAsFixed(2)} m\n'
            'Total reinforcement: ${weight.toStringAsFixed(2)} kg\n\n'
            'The captured mark is highlighted and the slab summary has been updated.',
          ),
          actions: [
            FilledButton(
              onPressed: () => Get.back(),
              child: const Text('Done'),
            ),
          ],
        ),
        barrierDismissible: false,
      );
      return true;
    } catch (error, stackTrace) {
      debugPrint('Failed to save manual slab reinforcement: $error');
      debugPrintStack(stackTrace: stackTrace);
      if (Get.isDialogOpen == true) Get.back<void>();
      await Get.dialog<void>(
        AlertDialog(
          title: const Text('Could not save reinforcement'),
          content: Text(
            'The bar group was not saved. Your captured mark and measured '
            'length are still available, so you can try again.\n\n'
            'Details: $error',
          ),
          actions: [
            FilledButton(
              onPressed: () => Get.back<void>(),
              child: const Text('Try again'),
            ),
          ],
        ),
        barrierDismissible: false,
      );
      return false;
    }
  }

  Future<void> _commitFastSlabRebarSession() async {
    if (_fastSlabRebarSession.isEmpty) return;
    final batch = FirebaseFirestore.instance.batch();
    final sessionId = measurementsRef.doc().id;
    for (var i = 0; i < _fastSlabRebarSession.length; i++) {
      final item = _fastSlabRebarSession[i];
      final docRef = measurementsRef.doc();
      final spacingLabel =
          item.spacingMm == item.spacingMm.roundToDouble()
              ? item.spacingMm.toStringAsFixed(0)
              : item.spacingMm.toStringAsFixed(1);
      final rawMark =
          '${item.numberOfBars}Y${item.diameterMm}-${item.mark}-$spacingLabel${item.layer}';
      batch.set(docRef, {
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'type': 'rebarSlabManual',
        'measureType': 'slabRebarAi',
        'groupId': sessionId,
        'sessionId': sessionId,
        'sessionItemIndex': i,
        'sessionItemCount': _fastSlabRebarSession.length,
        'label': 'Slab reinforcement - ${item.mark}',
        'description': 'Slab reinforcement - ${item.mark}',
        'unit': 'kg',
        'value': item.totalWeightKg,
        'boqItemId': item.boq.id.toString(),
        'boqCode': item.boq.code.toString(),
        'boqDescription': item.boq.description.toString(),
        'rawMark': rawMark,
        'barMark': item.mark,
        'diameterMm': item.diameterMm,
        'numberOfBars': item.numberOfBars,
        'barsCount': item.numberOfBars,
        'groupFactor': item.groupFactor,
        'multiplyingFactor': item.groupFactor,
        'effectiveBarsCount': item.numberOfBars * item.groupFactor,
        'bundleCount': item.bundleCountPoints.length,
        'bundleCountPoints':
            item.bundleCountPoints
                .map((point) => {'x': point.dx, 'y': point.dy})
                .toList(),
        'spacingMm': item.spacingMm,
        'spacingM': item.spacingMm / 1000,
        'layer': item.layer,
        'position': item.layer,
        'direction': item.direction,
        'quantityMode': item.quantityMode,
        if (item.distributionWidthM != null)
          'distributionWidthM': item.distributionWidthM,
        'measuredLengthM': item.measuredLengthM,
        'lengthM': item.measuredLengthM,
        'barLengthM': item.measuredLengthM,
        'lengthOneM': item.measuredLengthM,
        'baseTotalLengthM': item.baseTotalLengthM,
        'segment': {
          'p1': {'x': item.p1.dx, 'y': item.p1.dy},
          'p2': {'x': item.p2.dx, 'y': item.p2.dy},
        },
        'totalLengthM': item.totalLengthM,
        'totalLengthAllBarsM': item.totalLengthM,
        'unitWeightKgPerM': item.unitWeightKgPerM,
        'totalWeightKg': item.totalWeightKg,
        'captureMethod':
            item.captureStyle == 'segments'
                ? 'independentSegmentsFastTrackSession'
                : 'continuousPolylineFastTrackSession',
        'captureStyle': item.captureStyle,
        'segmentCount': item.geometrySegments.length,
        'polylineSegments': item.geometrySegments,
        'aiVerified': false,
        'p1': {'x': item.p1.dx, 'y': item.p1.dy},
        'p2': {'x': item.p2.dx, 'y': item.p2.dy},
        'color': currentColor.value,
        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });
    }
    await batch.commit();
  }

  Future<SlabRebarLengthSaveAction> finishFastSlabRebarBundleCount(
    List<Offset> points,
  ) async {
    final pending = _pendingFastSlabRebarBundleItem;
    if (pending == null || points.isEmpty) {
      return SlabRebarLengthSaveAction.cancel;
    }
    final countedItem = pending.withBundleCount(points);
    final action =
        await Get.dialog<SlabRebarLengthSaveAction>(
          AlertDialog(
            title: Text('Bundle count – bar mark ${pending.mark}'),
            content: Text(
              '${points.length} related rebar bundle${points.length == 1 ? '' : 's'} counted.\n\n'
              'The group quantity will be multiplied by ×${points.length}, giving '
              '${countedItem.totalWeightKg.toStringAsFixed(2)} kg.',
            ),
            actions: [
              TextButton(
                onPressed:
                    () => Get.back(result: SlabRebarLengthSaveAction.cancel),
                child: const Text('Keep counting'),
              ),
              OutlinedButton.icon(
                onPressed:
                    () => Get.back(
                      result: SlabRebarLengthSaveAction.measureAnother,
                    ),
                icon: const Icon(Icons.add_rounded),
                label: const Text('Save temporary & measure another'),
              ),
              FilledButton.icon(
                onPressed:
                    () => Get.back(result: SlabRebarLengthSaveAction.finish),
                icon: const Icon(Icons.save_rounded),
                label: Text('Commit all (${_fastSlabRebarSession.length + 1})'),
              ),
            ],
          ),
          barrierDismissible: false,
        ) ??
        SlabRebarLengthSaveAction.cancel;

    if (action == SlabRebarLengthSaveAction.cancel) return action;
    _fastSlabRebarSession.add(countedItem);
    if (action == SlabRebarLengthSaveAction.finish) {
      try {
        await _commitFastSlabRebarSession();
        _fastSlabRebarSession.clear();
      } catch (_) {
        _fastSlabRebarSession.remove(countedItem);
        rethrow;
      }
    }
    _pendingFastSlabRebarBundleItem = null;
    update(['viewr', 'viewer', 'overlay', 'summary']);
    return action;
  }

  void cancelFastSlabRebarBundleCount() {
    _pendingFastSlabRebarBundleItem = null;
    update(['viewr', 'viewer', 'overlay', 'summary']);
  }

  Future<SlabRebarLengthSaveAction> saveFastSlabRebarLength({
    required Offset p1,
    required Offset p2,
    required double measuredLengthM,
    List<Map<String, dynamic>> geometrySegments =
        const <Map<String, dynamic>>[],
    String captureStyle = 'continuous',
  }) async {
    final context = Get.context;
    if (context == null || measuredLengthM <= 0) {
      return SlabRebarLengthSaveAction.cancel;
    }

    final markController = TextEditingController(text: '01');
    final diameterController = TextEditingController(
      text: '$_lastFastSlabRebarDiameterMm',
    );
    final countController = TextEditingController(
      text: '$_lastFastSlabRebarCount',
    );
    final spacingController = TextEditingController(
      text: _lastFastSlabRebarSpacingMm.toStringAsFixed(0),
    );
    final distributionWidthController = TextEditingController(
      text: _lastFastSlabRebarDistributionWidthM.toStringAsFixed(3),
    );
    var selectedBoq = _lastSlabRebarBoq;
    var layer = _lastFastSlabRebarLayer;
    var direction = _lastFastSlabRebarDirection;
    var quantityMode = _lastFastSlabRebarQuantityMode;
    String? errorMessage;
    var isSaving = false;

    int calculatedBars() {
      if (quantityMode == 'count') {
        return int.tryParse(countController.text.trim()) ?? 0;
      }
      final spacingMm = double.tryParse(spacingController.text.trim()) ?? 0;
      final widthM =
          double.tryParse(distributionWidthController.text.trim()) ?? 0;
      if (spacingMm <= 0 || widthM <= 0) return 0;
      return (widthM / (spacingMm / 1000.0)).floor() + 1;
    }

    Future<void> commitSession() => _commitFastSlabRebarSession();

    var action = SlabRebarLengthSaveAction.cancel;
    do {
      action =
          await Get.dialog<SlabRebarLengthSaveAction>(
          StatefulBuilder(
            builder: (dialogContext, setState) {
              Future<void> save(SlabRebarLengthSaveAction result) async {
                if (isSaving) return;
                final mark = markController.text.trim();
                final diameter = int.tryParse(diameterController.text.trim());
                final spacing = double.tryParse(spacingController.text.trim());
                final numberOfBars = calculatedBars();
                final distributionWidth =
                    quantityMode == 'spacing'
                        ? double.tryParse(
                          distributionWidthController.text.trim(),
                        )
                        : null;

                if (mark.isEmpty) {
                  setState(() => errorMessage = 'Enter the bar mark.');
                  return;
                }
                if (diameter == null || diameter <= 0) {
                  setState(() => errorMessage = 'Enter a valid bar size.');
                  return;
                }
                if (spacing == null || spacing <= 0) {
                  setState(() => errorMessage = 'Enter valid spacing.');
                  return;
                }
                if (quantityMode == 'count' && numberOfBars <= 0) {
                  setState(() => errorMessage = 'Enter the number of bars.');
                  return;
                }
                if (quantityMode == 'spacing' &&
                    (distributionWidth == null || distributionWidth <= 0)) {
                  setState(
                    () => errorMessage = 'Enter the distribution width.',
                  );
                  return;
                }
                if (numberOfBars <= 0) {
                  setState(
                    () => errorMessage = 'Calculated bar quantity is invalid.',
                  );
                  return;
                }
                if (selectedBoq == null || selectedBoq!.code.trim().isEmpty) {
                  setState(() => errorMessage = 'Pick a reinforcement BOQ.');
                  return;
                }

                final item = _FastSlabRebarItem(
                  p1: p1,
                  p2: p2,
                  geometrySegments: geometrySegments,
                  captureStyle: captureStyle,
                  measuredLengthM: measuredLengthM,
                  mark: mark,
                  diameterMm: diameter,
                  numberOfBars: numberOfBars,
                  groupFactor: 1,
                  spacingMm: spacing,
                  layer: layer,
                  direction: direction,
                  quantityMode: quantityMode,
                  distributionWidthM: distributionWidth,
                  boq: selectedBoq!,
                );

                setState(() {
                  isSaving = true;
                  errorMessage = null;
                });

                _lastSlabRebarBoq = selectedBoq;
                _lastFastSlabRebarDiameterMm = diameter;
                _lastFastSlabRebarCount = numberOfBars;
                _lastFastSlabRebarSpacingMm = spacing;
                _lastFastSlabRebarLayer = layer;
                _lastFastSlabRebarDirection = direction;
                _lastFastSlabRebarQuantityMode = quantityMode;
                if (distributionWidth != null) {
                  _lastFastSlabRebarDistributionWidthM = distributionWidth;
                }

                if (result == SlabRebarLengthSaveAction.countBundles) {
                  _pendingFastSlabRebarBundleItem = item;
                  if (dialogContext.mounted) {
                    Navigator.of(dialogContext).pop(result);
                  }
                  update(['viewr', 'viewer', 'overlay', 'summary']);
                  return;
                }

                _fastSlabRebarSession.add(item);
                if (result == SlabRebarLengthSaveAction.finish) {
                  try {
                    await commitSession();
                  } catch (error, stackTrace) {
                    debugPrint(
                      'Could not commit slab reinforcement session: $error',
                    );
                    debugPrintStack(stackTrace: stackTrace);
                    _fastSlabRebarSession.remove(item);
                    if (!dialogContext.mounted) return;
                    setState(() {
                      isSaving = false;
                      errorMessage =
                          'Could not save reinforcement session: $error';
                    });
                    return;
                  }
                  _fastSlabRebarSession.clear();
                }
                if (dialogContext.mounted) {
                  Navigator.of(dialogContext).pop(result);
                }
                update(['viewr', 'viewer', 'overlay', 'summary']);
              }

              final diameter =
                  int.tryParse(diameterController.text.trim()) ?? 0;
              final numberOfBars = calculatedBars();
              final unitWeight =
                  diameter > 0 ? rebarUnitWeightKgPerM(diameter) : 0.0;
              final totalLengthM = measuredLengthM * numberOfBars;
              final totalWeightKg = totalLengthM * unitWeight;
              final pendingLengthM = _fastSlabRebarSession.fold<double>(
                0.0,
                (sum, item) => sum + item.totalLengthM,
              );
              final pendingWeightKg = _fastSlabRebarSession.fold<double>(
                0.0,
                (sum, item) => sum + item.totalWeightKg,
              );

              return PopScope(
                canPop: !isSaving,
                child: AlertDialog(
                  title: const Text('Slab rebar take-off'),
                  content: AbsorbPointer(
                    absorbing: isSaving,
                    child: SizedBox(
                      width: 720,
                      child: SingleChildScrollView(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Measured bar length: ${measuredLengthM.toStringAsFixed(3)} m',
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            const SizedBox(height: 4),
                            const Text(
                              'Measure one representative bar, enter its mark/details, then continue with the next bar group.',
                            ),
                            if (_fastSlabRebarSession.isNotEmpty) ...[
                              const SizedBox(height: 12),
                              Container(
                                width: double.infinity,
                                padding: const EdgeInsets.all(12),
                                decoration: BoxDecoration(
                                  color: const Color(0xFFF7F9FC),
                                  border: Border.all(
                                    color: const Color(0xFFDCE3EE),
                                  ),
                                  borderRadius: BorderRadius.circular(12),
                                ),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      'Temporary session - ${_fastSlabRebarSession.length} item(s)',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                    const SizedBox(height: 6),
                                    for (final item in _fastSlabRebarSession
                                        .take(6))
                                      Padding(
                                        padding: const EdgeInsets.only(
                                          bottom: 3,
                                        ),
                                        child: Text(
                                          '${item.mark}  Y${item.diameterMm}  ${item.layer}/${item.direction}  '
                                          '${item.numberOfBars} bars x ${item.measuredLengthM.toStringAsFixed(2)} m x${item.groupFactor.toStringAsFixed(item.groupFactor == item.groupFactor.roundToDouble() ? 0 : 2)}  '
                                          '= ${item.totalWeightKg.toStringAsFixed(2)} kg',
                                        ),
                                      ),
                                    if (_fastSlabRebarSession.length > 6)
                                      Text(
                                        '+ ${_fastSlabRebarSession.length - 6} more item(s)',
                                      ),
                                    const SizedBox(height: 6),
                                    Text(
                                      'Pending total: ${pendingLengthM.toStringAsFixed(3)} m / ${pendingWeightKg.toStringAsFixed(2)} kg',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                            const SizedBox(height: 16),
                            Wrap(
                              spacing: 12,
                              runSpacing: 12,
                              children: [
                                SizedBox(
                                  width: 220,
                                  child: TextField(
                                    controller: markController,
                                    autofocus: true,
                                    onChanged: (_) => setState(() {}),
                                    decoration: const InputDecoration(
                                      labelText: 'Bar mark / reference',
                                      hintText: 'e.g. 01',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                                SizedBox(
                                  width: 140,
                                  child: TextField(
                                    controller: diameterController,
                                    keyboardType: TextInputType.number,
                                    onChanged: (_) => setState(() {}),
                                    decoration: const InputDecoration(
                                      labelText: 'Bar size (mm)',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                                SizedBox(
                                  width: 145,
                                  child: DropdownButtonFormField<String>(
                                    value: layer,
                                    decoration: const InputDecoration(
                                      labelText: 'Layer',
                                      border: OutlineInputBorder(),
                                    ),
                                    items: const [
                                      DropdownMenuItem(
                                        value: 'T1',
                                        child: Text('T1'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'T2',
                                        child: Text('T2'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'B1',
                                        child: Text('B1'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'B2',
                                        child: Text('B2'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'Other',
                                        child: Text('Other'),
                                      ),
                                    ],
                                    onChanged:
                                        (v) =>
                                            setState(() => layer = v ?? 'T1'),
                                  ),
                                ),
                                SizedBox(
                                  width: 145,
                                  child: DropdownButtonFormField<String>(
                                    value: direction,
                                    decoration: const InputDecoration(
                                      labelText: 'Direction',
                                      border: OutlineInputBorder(),
                                    ),
                                    items: const [
                                      DropdownMenuItem(
                                        value: 'X',
                                        child: Text('X'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'Y',
                                        child: Text('Y'),
                                      ),
                                      DropdownMenuItem(
                                        value: 'Other',
                                        child: Text('Other'),
                                      ),
                                    ],
                                    onChanged:
                                        (v) => setState(
                                          () => direction = v ?? 'X',
                                        ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 14),
                            const Text(
                              'Bar quantity',
                              style: TextStyle(fontWeight: FontWeight.w800),
                            ),
                            const SizedBox(height: 6),
                            Wrap(
                              spacing: 8,
                              children: [
                                ChoiceChip(
                                  label: const Text('Enter number'),
                                  selected: quantityMode == 'count',
                                  onSelected:
                                      (_) => setState(
                                        () => quantityMode = 'count',
                                      ),
                                ),
                                ChoiceChip(
                                  label: const Text('Calculate from spacing'),
                                  selected: quantityMode == 'spacing',
                                  onSelected:
                                      (_) => setState(
                                        () => quantityMode = 'spacing',
                                      ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 10),
                            Wrap(
                              spacing: 12,
                              runSpacing: 12,
                              children: [
                                if (quantityMode == 'count')
                                  SizedBox(
                                    width: 180,
                                    child: TextField(
                                      controller: countController,
                                      keyboardType: TextInputType.number,
                                      onChanged: (_) => setState(() {}),
                                      decoration: const InputDecoration(
                                        labelText: 'Number of bars',
                                        border: OutlineInputBorder(),
                                      ),
                                    ),
                                  ),
                                SizedBox(
                                  width: 180,
                                  child: TextField(
                                    controller: spacingController,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                          decimal: true,
                                        ),
                                    onChanged: (_) => setState(() {}),
                                    decoration: const InputDecoration(
                                      labelText: 'Spacing (mm c/c)',
                                      border: OutlineInputBorder(),
                                    ),
                                  ),
                                ),
                                if (quantityMode == 'spacing')
                                  SizedBox(
                                    width: 210,
                                    child: TextField(
                                      controller: distributionWidthController,
                                      keyboardType:
                                          const TextInputType.numberWithOptions(
                                            decimal: true,
                                          ),
                                      onChanged: (_) => setState(() {}),
                                      decoration: const InputDecoration(
                                        labelText: 'Distribution width (m)',
                                        border: OutlineInputBorder(),
                                      ),
                                    ),
                                  ),
                                if (quantityMode == 'spacing')
                                  Container(
                                    constraints: const BoxConstraints(
                                      minHeight: 56,
                                    ),
                                    alignment: Alignment.centerLeft,
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 12,
                                    ),
                                    child: Text(
                                      'Calculated: $numberOfBars bars',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w800,
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                            const SizedBox(height: 14),
                            Row(
                              children: [
                                Expanded(
                                  child: InputDecorator(
                                    decoration: const InputDecoration(
                                      labelText: 'Reinforcement BOQ',
                                      border: OutlineInputBorder(),
                                    ),
                                    child: Text(
                                      selectedBoq == null
                                          ? 'Not linked'
                                          : '${selectedBoq!.code} - ${selectedBoq!.description}',
                                      maxLines: 2,
                                      overflow: TextOverflow.ellipsis,
                                    ),
                                  ),
                                ),
                                const SizedBox(width: 10),
                                OutlinedButton.icon(
                                  onPressed: () async {
                                    final picked = await showBoqPickerDialog(
                                      context: dialogContext,
                                    );
                                    if (picked == null ||
                                        !dialogContext.mounted)
                                      return;
                                    setState(() {
                                      selectedBoq = picked;
                                      errorMessage = null;
                                    });
                                  },
                                  icon: const Icon(Icons.search_rounded),
                                  label: const Text('Pick'),
                                ),
                              ],
                            ),
                            const SizedBox(height: 14),
                            Container(
                              width: double.infinity,
                              padding: const EdgeInsets.all(12),
                              decoration: BoxDecoration(
                                color: const Color(0xFFF3F6FC),
                                borderRadius: BorderRadius.circular(12),
                              ),
                              child: Text(
                                'Current (${captureStyle == 'segments' ? 'segment' : 'continuous'}): '
                                '$numberOfBars bars x ${measuredLengthM.toStringAsFixed(3)} m = '
                                '${totalLengthM.toStringAsFixed(3)} m  -  ${totalWeightKg.toStringAsFixed(2)} kg',
                                style: const TextStyle(
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                            ),
                            if (errorMessage != null) ...[
                              const SizedBox(height: 10),
                              Text(
                                errorMessage!,
                                style: const TextStyle(color: Colors.red),
                              ),
                            ],
                          ],
                        ),
                      ),
                    ),
                  ),
                  actions: [
                    TextButton(
                      onPressed:
                          isSaving
                              ? null
                              : () => Navigator.of(
                                dialogContext,
                              ).pop(SlabRebarLengthSaveAction.cancel),
                      child: const Text('Cancel'),
                    ),
                    OutlinedButton.icon(
                      onPressed:
                          isSaving
                              ? null
                              : () => Navigator.of(dialogContext).pop(
                                SlabRebarLengthSaveAction.minimize,
                              ),
                      icon: const Icon(Icons.minimize_rounded),
                      label: const Text('Minimize'),
                    ),
                    OutlinedButton.icon(
                      onPressed:
                          isSaving
                              ? null
                              : () =>
                                  save(SlabRebarLengthSaveAction.countBundles),
                      icon: const Icon(Icons.touch_app_rounded),
                      label: const Text('Count bundles on drawing'),
                    ),
                    OutlinedButton.icon(
                      onPressed:
                          isSaving
                              ? null
                              : () => save(
                                SlabRebarLengthSaveAction.measureAnother,
                              ),
                      icon: const Icon(Icons.add_rounded),
                      label: const Text('Save temporary & measure another'),
                    ),
                    FilledButton.icon(
                      onPressed:
                          isSaving
                              ? null
                              : () => save(SlabRebarLengthSaveAction.finish),
                      icon:
                          isSaving
                              ? const SizedBox(
                                width: 16,
                                height: 16,
                                child: CircularProgressIndicator(
                                  strokeWidth: 2,
                                ),
                              )
                              : const Icon(Icons.save_rounded),
                      label: Text(
                        'Commit all (${_fastSlabRebarSession.length + 1})',
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
            barrierDismissible: false,
          ) ??
          SlabRebarLengthSaveAction.cancel;

      if (action == SlabRebarLengthSaveAction.minimize) {
        await _waitForMeasurementDialogRestore(
          title: 'slab rebar take-off',
          icon: Icons.open_in_full_rounded,
        );
      }
    } while (action == SlabRebarLengthSaveAction.minimize);

    await WidgetsBinding.instance.endOfFrame;
    await Future<void>.delayed(const Duration(milliseconds: 150));
    markController.dispose();
    diameterController.dispose();
    countController.dispose();
    spacingController.dispose();
    distributionWidthController.dispose();
    return action;
  }

  Future<bool> openAiSlabRebarFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
  }) async {
    double number(dynamic value, [double fallback = 0]) {
      if (value is num) return value.toDouble();
      return double.tryParse('${value ?? ''}') ?? fallback;
    }

    final pxPerM = number(drawingData['pixelsPerUnit']);
    final calibrated = drawingData['calibrated'] == true || pxPerM > 0;
    if (!calibrated || pxPerM <= 0 || polygon.length < 3) {
      Get.snackbar(
        'Calibration required',
        'Calibrate the drawing, then outline the slab panel again.',
      );
      return false;
    }

    final imageUrl = (drawingData['imageUrl'] ?? '').toString().trim();
    if (imageUrl.isEmpty) {
      Get.snackbar(
        'Drawing unavailable',
        'The drawing image is not ready yet.',
      );
      return false;
    }

    double minX = polygon.first.dx;
    double maxX = polygon.first.dx;
    double minY = polygon.first.dy;
    double maxY = polygon.first.dy;
    for (final point in polygon.skip(1)) {
      minX = math.min(minX, point.dx);
      maxX = math.max(maxX, point.dx);
      minY = math.min(minY, point.dy);
      maxY = math.max(maxY, point.dy);
    }
    final horizontalSpanM = (maxX - minX) / pxPerM;
    final verticalSpanM = (maxY - minY) / pxPerM;

    final useAi = await Get.dialog<bool>(
      AlertDialog(
        title: const Text('Slab reinforcement take-off'),
        content: const SizedBox(
          width: 520,
          child: Text(
            'Choose how to capture the bar marks. Manual entry does not use '
            'AI quota and AQS will still calculate the bar lengths, quantities '
            'and total weight automatically.',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Get.back<bool>(),
            child: const Text('Cancel'),
          ),
          OutlinedButton.icon(
            onPressed: () => Get.back(result: false),
            icon: const Icon(Icons.edit_outlined),
            label: const Text('Enter marks manually'),
          ),
          FilledButton.icon(
            onPressed: () => Get.back(result: true),
            icon: const Icon(Icons.auto_awesome),
            label: const Text('Scan with AI'),
          ),
        ],
      ),
      barrierDismissible: false,
    );
    if (useAi == null) return false;

    if (!useAi) {
      return _prepareManualSlabRebarCapture(
        polygon: polygon,
        drawingImageUrl: imageUrl,
        drawingImageWidth: number(drawingData['imageW']),
        drawingImageHeight: number(drawingData['imageH']),
      );
    }

    final drafts = <_AiSlabBarDraft>[];
    String? aiWarning;
    if (useAi) {
      Get.dialog<void>(
        PopScope(
          canPop: false,
          child: AlertDialog(
            title: Text('Reading slab reinforcement'),
            content: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                CircularProgressIndicator(),
                SizedBox(width: 20),
                Flexible(child: Text('AQS AI is reading the bar marks…')),
              ],
            ),
          ),
        ),
        barrierDismissible: false,
      );

      try {
        final callable = FirebaseFunctions.instanceFor(
          region: 'us-central1',
        ).httpsCallable('analyseSlabRebarMarks');
        final response = await callable.call<Map<String, dynamic>>({
          'imageUrl': imageUrl,
          'polygon': polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList(),
          'imageWidth': number(drawingData['imageW']),
          'imageHeight': number(drawingData['imageH']),
        });
        final rawMarks = response.data['marks'];
        if (rawMarks is List) {
          for (final raw in rawMarks) {
            if (raw is! Map) continue;
            final item = Map<String, dynamic>.from(raw);
            final mark = (item['rawMark'] ?? '').toString().trim();
            if (mark.isEmpty) continue;
            drafts.add(
              _AiSlabBarDraft(
                rawMark: TextEditingController(text: mark),
                direction:
                    item['direction'] == 'vertical' ? 'vertical' : 'horizontal',
                confidence:
                    number(item['confidence'], .5).clamp(0, 1).toDouble(),
                occurrences: math.max(
                  1,
                  number(item['occurrences'], 1).round(),
                ),
              ),
            );
          }
        }
      } on FirebaseFunctionsException catch (error) {
        String? diagnosticCode;
        final details = error.details;
        if (details is Map) {
          diagnosticCode = details['diagnosticCode']?.toString().trim();
        }
        final code =
            diagnosticCode?.isNotEmpty == true
                ? diagnosticCode!
                : 'FUNCTION_${error.code.toUpperCase().replaceAll('-', '_')}';
        final message =
            error.message?.trim().isNotEmpty == true
                ? error.message!.trim()
                : 'The AI service could not complete the scan.';
        aiWarning =
            '$message\nError code: $code\n'
            'You can still enter the visible bar mark manually.';
        debugPrint(
          'Slab rebar AI callable failed: '
          'firebaseCode=${error.code}, diagnosticCode=$code, '
          'message=${error.message}',
        );
      } catch (error, stackTrace) {
        aiWarning =
            'The app could not complete the AI scan.\n'
            'Error code: CLIENT_SCAN_FAILED\n'
            'You can still enter the visible bar mark manually.';
        debugPrint('Slab rebar AI client failure: $error\n$stackTrace');
      } finally {
        if (Get.isDialogOpen == true) Get.back();
      }
    }

    if (drafts.isEmpty) {
      drafts.add(
        _AiSlabBarDraft(
          rawMark: TextEditingController(),
          direction: 'horizontal',
          confidence: 0,
        ),
      );
      aiWarning ??= 'No clear bar mark was found inside the selected panel.';
    }

    final embedController = TextEditingController(text: '0.30');
    final extraController = TextEditingController(text: '0.00');
    BoqPick? selectedBoq;
    String? validationMessage;

    final save = await Get.dialog<bool>(
      StatefulBuilder(
        builder: (context, setState) {
          String calculation(_AiSlabBarDraft draft) {
            try {
              final mark = RebarMark.parse(draft.rawMark.text.trim());
              final span =
                  draft.direction == 'horizontal'
                      ? horizontalSpanM
                      : verticalSpanM;
              final embed = number(embedController.text);
              final extra = number(extraController.text);
              final length = span + (2 * embed) + extra;
              final weight =
                  length *
                  mark.quantity *
                  draft.occurrences *
                  rebarUnitWeightKgPerM(mark.diameterMm);
              return '${weight.toStringAsFixed(2)} kg';
            } catch (_) {
              return 'Check mark';
            }
          }

          return AlertDialog(
            title: const Text('Verify slab reinforcement'),
            content: SizedBox(
              width: 720,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Panel spans: ${horizontalSpanM.toStringAsFixed(2)} m horizontal × '
                      '${verticalSpanM.toStringAsFixed(2)} m vertical',
                    ),
                    if (aiWarning != null) ...[
                      const SizedBox(height: 10),
                      Text(
                        aiWarning!,
                        style: const TextStyle(color: Colors.orange),
                      ),
                    ],
                    const SizedBox(height: 12),
                    ...drafts.asMap().entries.map((entry) {
                      final index = entry.key;
                      final draft = entry.value;
                      return Card(
                        margin: const EdgeInsets.only(bottom: 10),
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            children: [
                              Row(
                                children: [
                                  Checkbox(
                                    value: draft.selected,
                                    onChanged:
                                        (v) => setState(
                                          () => draft.selected = v ?? false,
                                        ),
                                  ),
                                  Expanded(
                                    child: TextField(
                                      controller: draft.rawMark,
                                      onChanged: (_) => setState(() {}),
                                      decoration: InputDecoration(
                                        labelText: 'Bar mark ${index + 1}',
                                        hintText: 'e.g. 36Y12-08-150T1',
                                      ),
                                    ),
                                  ),
                                  const SizedBox(width: 10),
                                  Text(calculation(draft)),
                                ],
                              ),
                              const SizedBox(height: 8),
                              Row(
                                children: [
                                  Expanded(
                                    child: DropdownButtonFormField<String>(
                                      value: draft.direction,
                                      decoration: const InputDecoration(
                                        labelText: 'Bar direction',
                                      ),
                                      items: const [
                                        DropdownMenuItem(
                                          value: 'horizontal',
                                          child: Text('Horizontal span'),
                                        ),
                                        DropdownMenuItem(
                                          value: 'vertical',
                                          child: Text('Vertical span'),
                                        ),
                                      ],
                                      onChanged:
                                          (v) => setState(
                                            () =>
                                                draft.direction =
                                                    v ?? 'horizontal',
                                          ),
                                    ),
                                  ),
                                  const SizedBox(width: 10),
                                  SizedBox(
                                    width: 130,
                                    child: TextFormField(
                                      initialValue: '${draft.occurrences}',
                                      keyboardType: TextInputType.number,
                                      decoration: const InputDecoration(
                                        labelText: 'Occurrences',
                                      ),
                                      onChanged:
                                          (v) => setState(() {
                                            draft.occurrences = math.max(
                                              1,
                                              int.tryParse(v) ?? 1,
                                            );
                                          }),
                                    ),
                                  ),
                                  const SizedBox(width: 10),
                                  Text(
                                    '${(draft.confidence * 100).round()}% confidence',
                                    style: TextStyle(
                                      color:
                                          draft.confidence >= .75
                                              ? Colors.green
                                              : Colors.orange,
                                    ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      );
                    }),
                    TextButton.icon(
                      onPressed:
                          () => setState(() {
                            drafts.add(
                              _AiSlabBarDraft(
                                rawMark: TextEditingController(),
                                direction: 'horizontal',
                                confidence: 0,
                              ),
                            );
                          }),
                      icon: const Icon(Icons.add),
                      label: const Text('Add another bar group'),
                    ),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: embedController,
                            onChanged: (_) => setState(() {}),
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Embed each end (m)',
                            ),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: TextField(
                            controller: extraController,
                            onChanged: (_) => setState(() {}),
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            decoration: const InputDecoration(
                              labelText: 'Extra for hooks/laps (m)',
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    OutlinedButton.icon(
                      onPressed: () async {
                        final pick = await showBoqPickerDialog(
                          context: context,
                        );
                        if (pick != null) setState(() => selectedBoq = pick);
                      },
                      icon: const Icon(Icons.receipt_long_outlined),
                      label: Text(
                        selectedBoq == null
                            ? 'Select reinforcement BOQ item'
                            : '${selectedBoq!.code} — ${selectedBoq!.description}',
                      ),
                    ),
                    if (validationMessage != null) ...[
                      const SizedBox(height: 8),
                      Text(
                        validationMessage!,
                        style: const TextStyle(color: Colors.red),
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(result: false),
                child: const Text('Cancel'),
              ),
              FilledButton.icon(
                onPressed: () {
                  final selected = drafts.where((d) => d.selected).toList();
                  if (selectedBoq == null) {
                    setState(() => validationMessage = 'Select a BOQ item.');
                    return;
                  }
                  try {
                    for (final draft in selected) {
                      RebarMark.parse(draft.rawMark.text.trim());
                    }
                  } catch (_) {
                    setState(
                      () => validationMessage = 'Correct the invalid bar mark.',
                    );
                    return;
                  }
                  if (selected.isEmpty) {
                    setState(
                      () =>
                          validationMessage = 'Select at least one bar group.',
                    );
                    return;
                  }
                  Get.back(result: true);
                },
                icon: const Icon(Icons.save_outlined),
                label: const Text('Save groups'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    if (save == true && selectedBoq != null) {
      final batch = FirebaseFirestore.instance.batch();
      final groupId = measurementsRef.doc().id;
      final embed = number(embedController.text);
      final extra = number(extraController.text);
      final polyMap = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();
      for (final draft in drafts.where((d) => d.selected)) {
        final markRaw = draft.rawMark.text.trim();
        final mark = RebarMark.parse(markRaw);
        final horizontal = draft.direction == 'horizontal';
        final span = horizontal ? horizontalSpanM : verticalSpanM;
        final barLength = span + (2 * embed) + extra;
        final count = mark.quantity * draft.occurrences;
        final totalLength = barLength * count;
        final unitWeight = rebarUnitWeightKgPerM(mark.diameterMm);
        final weight = totalLength * unitWeight;
        final ref = measurementsRef.doc();
        batch.set(ref, {
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,
          'type': 'rebarSlabAi',
          'measureType': 'slabRebarAi',
          'label': 'Slab reinforcement',
          'unit': 'kg',
          'value': weight,
          'boqItemId': selectedBoq!.id,
          'boqCode': selectedBoq!.code,
          'boqDescription': selectedBoq!.description,
          'rawMark': markRaw,
          ...mark.toMap(),
          'occurrences': draft.occurrences,
          'barsCount': count,
          'direction': draft.direction,
          'clearSpanM': span,
          'embedEachEndM': embed,
          'extraLengthM': extra,
          'barLengthM': barLength,
          'totalLengthM': totalLength,
          'unitWeightKgPerM': unitWeight,
          'totalWeightKg': weight,
          'aiConfidence': draft.confidence,
          'aiVerified': true,
          'groupId': groupId,
          'polygon': polyMap,
          'p1': {
            'x': horizontal ? minX : (minX + maxX) / 2,
            'y': horizontal ? (minY + maxY) / 2 : minY,
          },
          'p2': {
            'x': horizontal ? maxX : (minX + maxX) / 2,
            'y': horizontal ? (minY + maxY) / 2 : maxY,
          },
          'color': currentColor.value,
          'createdAt': FieldValue.serverTimestamp(),
        });
      }
      await batch.commit();
      Get.snackbar('Saved', 'Slab reinforcement groups saved successfully.');
    }

    for (final draft in drafts) {
      draft.rawMark.dispose();
    }
    embedController.dispose();
    extraController.dispose();
    return false;
  }

  Future<void> _saveRebarSlabMeasurement({
    required RebarMark mark,
    required String markRawString, // 👈 NEW
    required double clearSpanM,
    required double embedEachEndM,
    required double extraLengthM,
    required double barLengthM,
    required double totalLengthM,
    required double unitWeightKgPerM,
    required double totalWeightKg,
    required Offset p1,
    required Offset p2,
    List<Map<String, double>>? polygon, // 👈 for slab polygons
    String? slabId, // 👈 group multiple sets
    String? direction, // 👈 'horizontal' / 'vertical'
  }) async {
    if (activeBoqCode == null || activeBoqCode!.trim().isEmpty) return;

    final unit = activeUnit ?? 'kg';
    final value =
        (unit == 'kg' || unit == 'tonne') ? totalWeightKg : totalLengthM;

    await measurementsRef.add({
      'projectId': projectId,
      'drawingId': drawingId,
      'buildingId': buildingId,
      'type': 'rebarSlab',
      'measureType': 'compositeSlab',
      'label': activeLabel,
      'boqCode': activeBoqCode,
      'unit': unit,

      // 🔹 full raw marking exactly as typed: "38Y12-01-150B2"
      'markRaw': markRawString,

      // structured pieces
      'quantity': mark.quantity,
      'barType': mark.barType,
      'diameterMm': mark.diameterMm,
      'spacingMm': mark.spacingMm,
      'layer': mark.layer,

      'clearSpanM': clearSpanM,
      'embedEachEndM': embedEachEndM,
      'extraLengthM': extraLengthM,
      'barLengthM': barLengthM,
      'totalLengthM': totalLengthM,

      'unitWeightKgPerM': unitWeightKgPerM,
      'totalWeightKg': totalWeightKg,
      'value': value,

      'direction': direction ?? 'horizontal',

      'color': currentColor,
      'p1': {'x': p1.dx, 'y': p1.dy},
      'p2': {'x': p2.dx, 'y': p2.dy},

      if (polygon != null) 'polygon': polygon,
      if (slabId != null) 'slabId': slabId,

      'createdAt': FieldValue.serverTimestamp(),
    });
  }

  Future<void> addOrEditSlabRebarMark({
    required String slabId,
    required Map<String, dynamic> baseData,
    QueryDocumentSnapshot<Map<String, dynamic>>? existingDoc,
  }) async {
    double _asDouble(dynamic v) => v is num ? v.toDouble() : 0.0;

    // ---- Basic geometry from slab concrete doc ----
    final projectId = (baseData['projectId'] ?? '') as String;
    final buildingId = (baseData['buildingId'] ?? '') as String;
    final drawingId = (baseData['drawingId'] ?? '') as String;

    final lengthM = _asDouble(baseData['lengthM']);
    final widthM = _asDouble(baseData['widthM']);

    // polygon for locating the bar line
    final rawPoly = (baseData['polygon'] ?? baseData['points'] ?? []) as List;
    final List<Offset> polygon = [];
    for (final p in rawPoly) {
      if (p is Map) {
        polygon.add(Offset(_asDouble(p['x']), _asDouble(p['y'])));
      }
    }

    if (polygon.length < 3) {
      // Polygon missing, we still can save values but p1/p2 will be dummy
      // If you prefer, you can bail here instead.
    }

    // Compute bounding box for positioning the "rebar line"
    double minX = polygon.isNotEmpty ? polygon.first.dx : 0.0;
    double maxX = minX;
    double minY = polygon.isNotEmpty ? polygon.first.dy : 0.0;
    double maxY = minY;

    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }

    final centerX = (minX + maxX) / 2;
    final centerY = (minY + maxY) / 2;

    // ---- Controllers / initial values ----
    final markCtrl = TextEditingController();
    final embedCtrl = TextEditingController(text: '0.30'); // m
    final extraCtrl = TextEditingController(text: '0.00'); // m
    final boqCtrl = TextEditingController();
    String direction = 'horizontal'; // or 'vertical'
    String? errorText;

    // If editing existing doc, pre-fill
    if (existingDoc != null) {
      final data = existingDoc.data();
      markCtrl.text = (data['rawMark'] ?? '') as String;
      embedCtrl.text = _asDouble(data['embedEachEndM']).toStringAsFixed(3);
      extraCtrl.text = _asDouble(data['extraLengthM']).toStringAsFixed(3);
      boqCtrl.text = (data['boqCode'] ?? '') as String;
      direction = (data['direction'] ?? 'horizontal') as String;
    }

    final ok = await Get.dialog<bool>(
      StatefulBuilder(
        builder: (dialogCtx, setStateDialog) {
          return AlertDialog(
            title: Text(
              existingDoc == null
                  ? 'Add slab rebar mark'
                  : 'Edit slab rebar mark',
            ),
            content: SizedBox(
              width: 440,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text(
                    'Slab spans: L ≈ ${lengthM.toStringAsFixed(3)} m, '
                    'W ≈ ${widthM.toStringAsFixed(3)} m',
                    style: const TextStyle(fontSize: 12),
                  ),
                  const SizedBox(height: 8),
                  Row(
                    children: [
                      const Text(
                        'Bars lay:',
                        style: TextStyle(
                          fontWeight: FontWeight.w600,
                          fontSize: 12,
                        ),
                      ),
                      const SizedBox(width: 8),
                      ChoiceChip(
                        label: const Text('Horizontal'),
                        selected: direction == 'horizontal',
                        onSelected: (_) {
                          setStateDialog(() {
                            direction = 'horizontal';
                          });
                        },
                      ),
                      const SizedBox(width: 4),
                      ChoiceChip(
                        label: const Text('Vertical'),
                        selected: direction == 'vertical',
                        onSelected: (_) {
                          setStateDialog(() {
                            direction = 'vertical';
                          });
                        },
                      ),
                    ],
                  ),
                  const SizedBox(height: 8),
                  TextField(
                    controller: markCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Rebar mark (e.g. 38Y12-01-150B2)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                    style: const TextStyle(fontSize: 12),
                  ),
                  const SizedBox(height: 6),
                  Row(
                    children: [
                      Expanded(
                        child: TextField(
                          controller: embedCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: const InputDecoration(
                            labelText: 'Embed each end (m)',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                          style: const TextStyle(fontSize: 12),
                        ),
                      ),
                      const SizedBox(width: 6),
                      Expanded(
                        child: TextField(
                          controller: extraCtrl,
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          decoration: const InputDecoration(
                            labelText: 'Extra length (laps/hooks, m)',
                            border: OutlineInputBorder(),
                            isDense: true,
                          ),
                          style: const TextStyle(fontSize: 12),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  TextField(
                    controller: boqCtrl,
                    decoration: const InputDecoration(
                      labelText: 'BOQ code (rebar, kg)',
                      border: OutlineInputBorder(),
                      isDense: true,
                    ),
                    style: const TextStyle(fontSize: 12),
                  ),
                  if (errorText != null) ...[
                    const SizedBox(height: 4),
                    Text(
                      errorText!,
                      style: const TextStyle(color: Colors.red, fontSize: 11),
                    ),
                  ],
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Get.back(result: false),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () {
                  final raw = markCtrl.text.trim();
                  if (raw.isEmpty) {
                    setStateDialog(() {
                      errorText = 'Please enter rebar mark.';
                    });
                    return;
                  }
                  // basic numeric validation
                  final embed = double.tryParse(embedCtrl.text.trim()) ?? 0.0;
                  final extra = double.tryParse(extraCtrl.text.trim()) ?? 0.0;
                  if (embed < 0 || extra < 0) {
                    setStateDialog(() {
                      errorText = 'Embed and extra must be ≥ 0.';
                    });
                    return;
                  }

                  try {
                    // try parsing mark – if fails, show exception text
                    RebarMark.parse(raw);
                  } catch (e) {
                    setStateDialog(() {
                      errorText = e.toString();
                    });
                    return;
                  }

                  Get.back(result: true);
                },
                child: const Text('Save'),
              ),
            ],
          );
        },
      ),
    );

    if (ok != true) return;

    // ---- Final calc & save/update ----
    final rawMark = markCtrl.text.trim();
    final embedM = double.tryParse(embedCtrl.text.trim()) ?? 0.0;
    final extraM = double.tryParse(extraCtrl.text.trim()) ?? 0.0;
    final rebarBoq = boqCtrl.text.trim();

    final parsed = RebarMark.parse(rawMark);
    final diaMm = parsed.diameterMm;
    final barsCount = parsed.quantity;

    // choose span based on direction
    final clearSpanM = direction == 'horizontal' ? lengthM : widthM;

    final barLengthM = clearSpanM + 2 * embedM + extraM;
    final totalLengthM = barLengthM * barsCount;
    final unitWeightKgPerM = rebarUnitWeightKgPerM(diaMm);
    final totalWeightKg = totalLengthM * unitWeightKgPerM;

    // p1 / p2 purely for visual line on drawing
    final Offset p1;
    final Offset p2;

    if (direction == 'horizontal') {
      p1 = Offset(minX, centerY);
      p2 = Offset(maxX, centerY);
    } else {
      p1 = Offset(centerX, minY);
      p2 = Offset(centerX, maxY);
    }

    final p1Map = {'x': p1.dx, 'y': p1.dy};
    final p2Map = {'x': p2.dx, 'y': p2.dy};
    final polyData = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    final dataMap = <String, dynamic>{
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,
      'slabId': slabId,
      'type': 'rebarSlab',
      'measureType': 'slabComposite', // keep consistent
      'unit': 'kg',
      'value': totalWeightKg,
      'totalWeightKg': totalWeightKg,
      'totalLengthAllBarsM': totalLengthM,
      'barLengthM': barLengthM,
      'clearSpanM': clearSpanM,
      'embedEachEndM': embedM,
      'extraLengthM': extraM,
      'barsCount': barsCount,
      'rawMark': rawMark,
      'diameterMm': diaMm,
      'direction': direction,
      'boqCode': rebarBoq,
      'polygon': polyData,
      'p1': p1Map,
      'p2': p2Map,
      'createdAt': FieldValue.serverTimestamp(),
    };

    if (existingDoc == null) {
      // ADD
      await measurementsRef.add(dataMap);
    } else {
      // UPDATE
      await measurementsRef.doc(existingDoc.id).update(dataMap);
    }
  }

