  Future<bool> handleRetainingWallViewTap(
    Offset imagePos,
    List<MeasuredSegment> segments,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    retainingWallDocsByWallId,

    Map<String, dynamic> drawingData,
  ) async {
    const tolPx = 12.0;

    MeasuredSegment? hit;
    double best = double.infinity;

    for (final s in segments) {
      final mt = (s.measureType ?? '').toString().trim();
      final isRW =
          mt == 'compositeretainingWall' ||
          mt == 'retainingwallcomposite' ||
          mt == 'compositeRetainingWall';
      if (!isRW) continue;

      final d = distancePointToSegment(imagePos, s.p1, s.p2);
      if (d <= tolPx && d < best) {
        best = d;
        hit = s;
      }
    }

    if (hit == null) return false;

    final wallId = hit.groupId.toString();
    // (hit.groupId ?? '').trim().isNotEmpty
    //     ? (hit.groupId ?? '').trim()
    //     : hit.docId; // you already set id = retainingWallId in parser
    var docs = retainingWallDocsByWallId[wallId] ?? const [];

    // Fallback query if map is empty
    if (docs.isEmpty) {
      final qs =
          await measurementsRef
              .where('drawingId', isEqualTo: drawingId)
              .where('wallGroupId', isEqualTo: wallId)
              .limit(200)
              .get();
      docs = qs.docs;
    }

    if (docs.isEmpty) {
      Get.snackbar(
        'Retaining wall',
        'No docs found for retainingWallId=$wallId',
      );
      return true;
    }

    await Get.dialog(
      RetainingWallCompositeDetailsDialog(
        wallId: wallId,
        initialDocs: docs,
        measurementsRef: measurementsRef,
        projectId: projectId,
        buildingId: buildingId,
        drawingId: drawingId,
        drawingData: drawingData,
        currentColor: currentColor,
        activeSegmentDocId: hit.docId,
        // defaultLabel: 'Retaining wall',
      ),
      barrierDismissible: true,
    );

    return true;
  }

