  Future<bool> handleFoundationWallViewTap(
    Offset imagePos,
    List<MeasuredSegment> segments,
    Map<String, List<QueryDocumentSnapshot<Map<String, dynamic>>>>
    foundationWallDocsByWallId,
    Map<String, dynamic> drawingData,
  ) async {
    const tolPx = 12.0;

    MeasuredSegment? hit;
    double best = double.infinity;

    bool isFoundationMeasureType(String mtRaw) {
      final mt = mtRaw.trim().toLowerCase();
      return mt == 'foundationwall' ||
          mt == 'compositefoundationwall' ||
          mt == 'foundationwallcomposite' ||
          mt == 'foundation_wall' ||
          mt == 'foundation';
    }

    for (final s in segments) {
      final mt = (s.measureType ?? '').toString();
      if (!isFoundationMeasureType(mt)) continue;

      final d = distancePointToSegment(imagePos, s.p1, s.p2);
      if (d <= tolPx && d < best) {
        best = d;
        hit = s;
      }
    }

    if (hit == null) return false;

    final wallId =
        (hit.groupId.toString().trim().isNotEmpty)
            ? hit.groupId.toString().trim()
            : hit.docId;

    // Optional: use map for quick existence check (not mandatory)
    var docs = foundationWallDocsByWallId[wallId] ?? const [];
    if (docs.isEmpty) {
      // fallback quick check to avoid opening an empty dialog
      final qs =
          await measurementsRef
              .where('buildingId', isEqualTo: buildingId)
              .where('foundationGroupId', isEqualTo: wallId)
              .limit(1)
              .get();

      if (qs.docs.isEmpty) {
        Get.snackbar('Foundation wall', 'No docs found for wallId=$wallId');
        return true;
      }
    }

    // ✅ NEW: open draggable details dialog
    await openFoundationWallDetailsDialog(
      measurementsRef: measurementsRef,
      wallGroupId: wallId,
      projectId: projectId,
      buildingId: buildingId,
      drawingId: drawingId,
    );

    return true;
  }

  Future<void> openFoundationWallDetailsDialog({
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId,
    required String projectId,
    required String buildingId,
    required String drawingId,
  }) async {
    await showDraggableDialog2<void>(
      width: 780,
      height: 720,
      builder: (ctx, setState, offset, setOffset) {
        return Column(
          children: [
            // Drag header
            GestureDetector(
              behavior: HitTestBehavior.opaque,
              onPanUpdate: (d) => setOffset(offset + d.delta),
              child: Container(
                color: Colors.grey.shade100,
                padding: const EdgeInsets.symmetric(
                  horizontal: 12,
                  vertical: 10,
                ),
                child: Row(
                  children: [
                    const Icon(Icons.drag_indicator),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        'Foundation Wall Details ($wallGroupId)',
                        style: const TextStyle(fontWeight: FontWeight.w800),
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    IconButton(
                      onPressed: () => Get.back(),
                      icon: const Icon(Icons.close),
                    ),
                  ],
                ),
              ),
            ),

            Expanded(
              child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                stream:
                    measurementsRef
                        .where('foundationGroupId', isEqualTo: wallGroupId)
                        .stateSnapshots(),
                builder: (_, snap) {
                  if (snap.hasError) {
                    return Padding(
                      padding: const EdgeInsets.all(12),
                      child: Text('Load error: ${snap.error}'),
                    );
                  }
                  if (!snap.hasData) {
                    return const Center(child: CircularProgressIndicator());
                  }

                  final docs = snap.data!.docs;

                  // ✅ if empty, do fallback query ONCE with FutureBuilder
                  if (docs.isEmpty) {
                    return FutureBuilder<QuerySnapshot<Map<String, dynamic>>>(
                      future: _loadFoundationWallFallbackDocs(
                        measurementsRef: measurementsRef,
                        wallGroupId: wallGroupId,
                        drawingId: drawingId, // optional filter if you want
                      ),
                      builder: (_, fsnap) {
                        if (fsnap.hasError) {
                          return Padding(
                            padding: const EdgeInsets.all(12),
                            child: Text('Load error: ${fsnap.error}'),
                          );
                        }
                        if (!fsnap.hasData) {
                          return const Center(
                            child: CircularProgressIndicator(),
                          );
                        }

                        final fdocs = fsnap.data!.docs;
                        if (fdocs.isEmpty) {
                          return const Padding(
                            padding: EdgeInsets.all(12),
                            child: Text(
                              'No docs found for this foundation wall group.',
                            ),
                          );
                        }

                        return _foundationDetailsBody(
                          docs: fdocs,
                          measurementsRef: measurementsRef,
                          wallGroupId: wallGroupId,
                          projectId: projectId,
                          buildingId: buildingId,
                          drawingId: drawingId,
                        );
                      },
                    );
                  }

                  // ✅ normal body
                  return _foundationDetailsBody(
                    docs: docs,
                    measurementsRef: measurementsRef,
                    wallGroupId: wallGroupId,
                    projectId: projectId,
                    buildingId: buildingId,
                    drawingId: drawingId,
                  );
                },
              ),
            ),

            Padding(
              padding: const EdgeInsets.all(12),
              child: Align(
                alignment: Alignment.centerRight,
                child: TextButton(
                  onPressed: () => Get.back(),
                  child: const Text('Close'),
                ),
              ),
            ),
          ],
        );
      },
    );
  }

  Future<QuerySnapshot<Map<String, dynamic>>> _loadFoundationWallFallbackDocs({
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId,
    required String drawingId,
  }) async {
    // If you want to keep fallback within the same drawing, add drawingId filter.
    // If foundation spans multiple drawings, remove drawingId conditions.

    // 1) wallGroupId
    var qs =
        await measurementsRef
            // .where('drawingId', isEqualTo: drawingId)
            .where('wallGroupId', isEqualTo: wallGroupId)
            .limit(300)
            .get();
    if (qs.docs.isNotEmpty) return qs;

    // 2) foundationWallId
    qs =
        await measurementsRef
            // .where('drawingId', isEqualTo: drawingId)
            .where('foundationWallId', isEqualTo: wallGroupId)
            .limit(300)
            .get();
    if (qs.docs.isNotEmpty) return qs;

    // 3) generic groupId (legacy)
    qs =
        await measurementsRef
            // .where('drawingId', isEqualTo: drawingId)
            .where('groupId', isEqualTo: wallGroupId)
            .limit(300)
            .get();
    return qs;
  }

  /// Fallback loader: if "foundationGroupId" stream returns empty,
  /// we query common variants (wallGroupId / foundationWallId) once.
  Widget _foundationFallbackLoader({
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId,
    required String projectId,
    required String buildingId,
    required String drawingId,
  }) {
    return FutureBuilder<List<QueryDocumentSnapshot<Map<String, dynamic>>>>(
      future: () async {
        // Try wallGroupId
        var qs =
            await measurementsRef
                .where('wallGroupId', isEqualTo: wallGroupId)
                .limit(300)
                .get();
        if (qs.docs.isNotEmpty) return qs.docs;

        // Try foundationWallId
        qs =
            await measurementsRef
                .where('foundationWallId', isEqualTo: wallGroupId)
                .limit(300)
                .get();
        if (qs.docs.isNotEmpty) return qs.docs;

        // Try legacy "groupId"
        qs =
            await measurementsRef
                .where('groupId', isEqualTo: wallGroupId)
                .limit(300)
                .get();
        return qs.docs;
      }(),
      builder: (_, fsnap) {
        if (fsnap.hasError) {
          return Padding(
            padding: const EdgeInsets.all(12),
            child: Text('Load error: ${fsnap.error}'),
          );
        }
        if (!fsnap.hasData) {
          return const Center(child: CircularProgressIndicator());
        }

        final docs = fsnap.data!;
        if (docs.isEmpty) {
          return const Padding(
            padding: EdgeInsets.all(12),
            child: Text('No docs found for this foundation wall group.'),
          );
        }

        return _foundationDetailsBody(
          docs: docs,
          measurementsRef: measurementsRef,
          wallGroupId: wallGroupId,
          projectId: projectId,
          buildingId: buildingId,
          drawingId: drawingId,
        );
      },
    );
  }

  Widget _foundationDetailsBody({
    required List<QueryDocumentSnapshot<Map<String, dynamic>>> docs,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId,
    required String projectId,
    required String buildingId,
    required String drawingId,
  }) {
    final wall = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    final earth = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    final concrete = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    final formwork = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    final rebar = <QueryDocumentSnapshot<Map<String, dynamic>>>[];
    final other = <QueryDocumentSnapshot<Map<String, dynamic>>>[];

    for (final doc in docs) {
      final d = doc.data();
      switch (sectionOfFoundation(d)) {
        case FoundationWallSection.wall:
          wall.add(doc);
          break;
        case FoundationWallSection.earthworks:
          earth.add(doc);
          break;
        case FoundationWallSection.concrete:
          concrete.add(doc);
          break;
        case FoundationWallSection.formwork:
          formwork.add(doc);
          break;
        case FoundationWallSection.rebar:
          rebar.add(doc);
          break;
        case FoundationWallSection.other:
          other.add(doc);
          break;
      }
    }

    wall.sort(
      (a, b) =>
          orderOfFoundation(a.data()).compareTo(orderOfFoundation(b.data())),
    );
    earth.sort(
      (a, b) =>
          orderOfFoundation(a.data()).compareTo(orderOfFoundation(b.data())),
    );
    concrete.sort(
      (a, b) =>
          orderOfFoundation(a.data()).compareTo(orderOfFoundation(b.data())),
    );
    formwork.sort(
      (a, b) =>
          orderOfFoundation(a.data()).compareTo(orderOfFoundation(b.data())),
    );
    rebar.sort(
      (a, b) =>
          orderOfFoundation(a.data()).compareTo(orderOfFoundation(b.data())),
    );

    return ListView(
      padding: const EdgeInsets.all(12),
      children: [
        sectionTile(
          title: 'Wall items',
          docs: wall,
          onAdd:
              () => addFoundationPartDialog(
                measurementsRef: measurementsRef,
                wallGroupId: wallGroupId,
                projectId: projectId,
                buildingId: buildingId,
                drawingId: drawingId,
                defaultSection: FoundationWallSection.wall,
                sampleDoc: docs.isNotEmpty ? docs.first : null,
              ),
        ),
        const SizedBox(height: 8),

        sectionTile(
          title: 'Earthworks',
          docs: earth,
          onAdd:
              () => addFoundationPartDialog(
                measurementsRef: measurementsRef,
                wallGroupId: wallGroupId,
                projectId: projectId,
                buildingId: buildingId,
                drawingId: drawingId,
                defaultSection: FoundationWallSection.earthworks,
                sampleDoc: docs.isNotEmpty ? docs.first : null,
              ),
        ),
        const SizedBox(height: 8),

        sectionTile(
          title: 'Concrete / Blinding',
          docs: concrete,
          onAdd:
              () => addFoundationPartDialog(
                measurementsRef: measurementsRef,
                wallGroupId: wallGroupId,
                projectId: projectId,
                buildingId: buildingId,
                drawingId: drawingId,
                defaultSection: FoundationWallSection.concrete,
                sampleDoc: docs.isNotEmpty ? docs.first : null,
              ),
        ),
        const SizedBox(height: 8),

        sectionTile(
          title: 'Formwork',
          docs: formwork,
          onAdd:
              () => addFoundationPartDialog(
                measurementsRef: measurementsRef,
                wallGroupId: wallGroupId,
                projectId: projectId,
                buildingId: buildingId,
                drawingId: drawingId,
                defaultSection: FoundationWallSection.formwork,
                sampleDoc: docs.isNotEmpty ? docs.first : null,
              ),
        ),
        const SizedBox(height: 8),

        sectionTile(
          title: 'Rebar',
          docs: rebar,
          onAdd:
              () => addFoundationPartDialog(
                measurementsRef: measurementsRef,
                wallGroupId: wallGroupId,
                projectId: projectId,
                buildingId: buildingId,
                drawingId: drawingId,
                defaultSection: FoundationWallSection.rebar,
                sampleDoc: docs.isNotEmpty ? docs.first : null,
              ),
        ),

        if (other.isNotEmpty) ...[
          const SizedBox(height: 8),
          sectionTile(title: 'Other', docs: other, onAdd: null),
        ],
      ],
    );
  }

  Future<void> addFoundationPartDialog({
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required String wallGroupId, // same as foundationGroupId
    required String projectId,
    required String buildingId,
    required String drawingId,
    required FoundationWallSection defaultSection,
    required QueryDocumentSnapshot<Map<String, dynamic>>? sampleDoc,
  }) async {
    // allowed types per section
    final List<PartOption> options = switch (defaultSection) {
      FoundationWallSection.wall => const [
        // ✅ Foundation wall area (faces) if you track it as m2 (height × length)
        PartOption(
          type: 'foundationWall',
          unit: 'm2',
          label: 'Foundation wall (area)',
        ),
      ],

      FoundationWallSection.earthworks => const [
        PartOption(
          type: 'excavation',
          unit: 'm3',
          label: 'Earthworks - Excavation',
        ),
        PartOption(
          type: 'backfill',
          unit: 'm3',
          label: 'Earthworks - Backfill',
        ),
        PartOption(
          type: 'disposal',
          unit: 'm3',
          label: 'Earthworks - Disposal',
        ),
        PartOption(type: 'blinding', unit: 'm2', label: 'Blinding - Area'),
      ],

      FoundationWallSection.concrete => const [
        // ✅ NEW: strip foundation concrete (m³) - not footingConcrete
        PartOption(
          type: 'foundationStripConcrete',
          unit: 'm3',
          label: 'Foundation strip concrete',
        ),
        // optional: lean/blinding concrete volume if you measure it
        PartOption(
          type: 'blindingConcrete',
          unit: 'm3',
          label: 'Blinding concrete (volume)',
        ),
      ],

      FoundationWallSection.formwork => const [
        // ✅ two sides of foundation thickness (m²)
        PartOption(
          type: 'foundationFormwork2Sides',
          unit: 'm2',
          label: 'Foundation formwork (2 sides)',
        ),
        // optional: one side if ever needed
        PartOption(
          type: 'foundationFormwork1Side',
          unit: 'm2',
          label: 'Foundation formwork (1 side)',
        ),
      ],

      FoundationWallSection.rebar => const [
        PartOption(
          type: 'rebarFoundation',
          unit: 'kg',
          label: 'Foundation - Rebar',
        ),
        PartOption(
          type: 'rebarFoundationMain',
          unit: 'kg',
          label: 'Foundation - Main bars',
        ),
        PartOption(
          type: 'rebarFoundationLinks',
          unit: 'kg',
          label: 'Foundation - Links/stirrups',
        ),
      ],

      _ => const [],
    };

    if (options.isEmpty) return;

    PartOption selected = options.first;

    final valueCtrl = TextEditingController(text: '0');
    final boqCodeCtrl = TextEditingController();
    final boqDescCtrl = TextEditingController();

    final ok =
        await Get.dialog<bool>(
          StatefulBuilder(
            builder: (ctx, setState) {
              return AlertDialog(
                title: const Text('Add measurement part'),
                content: SizedBox(
                  width: 520,
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      DropdownButtonFormField<PartOption>(
                        value: selected,
                        items:
                            options.map((o) {
                              return DropdownMenuItem<PartOption>(
                                value: o,
                                child: Text('${o.label} (${o.unit})'),
                              );
                            }).toList(),
                        onChanged: (v) {
                          if (v == null) return;
                          setState(() => selected = v);
                        },
                        decoration: const InputDecoration(labelText: 'Part'),
                      ),
                      const SizedBox(height: 10),

                      TextField(
                        controller: valueCtrl,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: const InputDecoration(labelText: 'Value'),
                      ),
                      const SizedBox(height: 10),

                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: boqCodeCtrl,
                              decoration: const InputDecoration(
                                labelText: 'BOQ code',
                              ),
                              readOnly: true,
                            ),
                          ),
                          const SizedBox(width: 8),
                          OutlinedButton(
                            onPressed: () async {
                              final picked = await showBoqPickerDialog(
                                context: ctx,
                              );
                              if (picked != null) {
                                boqCodeCtrl.text = picked.code;
                                boqDescCtrl.text = picked.description;
                                setState(() {});
                              }
                            },
                            child: const Text('Pick'),
                          ),
                        ],
                      ),
                      const SizedBox(height: 8),

                      TextField(
                        controller: boqDescCtrl,
                        decoration: const InputDecoration(
                          labelText: 'BOQ description',
                        ),
                        readOnly: true,
                        maxLines: 2,
                      ),
                    ],
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed: () => Get.back(result: false),
                    child: const Text('Cancel'),
                  ),
                  FilledButton(
                    onPressed: () => Get.back(result: true),
                    child: const Text('Add'),
                  ),
                ],
              );
            },
          ),
        ) ??
        false;

    if (!ok) return;

    final val = double.tryParse(valueCtrl.text.trim());
    if (val == null) {
      Get.snackbar('Invalid', 'Value must be a number');
      return;
    }

    try {
      final sample = sampleDoc?.data() ?? <String, dynamic>{};

      // copy visuals/geometry so it remains linked to same segment/line
      final p1 = sample['p1'];
      final p2 = sample['p2'];
      final baseLengthM = sample['baseLengthM'];
      final segmentId = sample['segmentId'];
      final color = sample['color'];

      await measurementsRef.add({
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,

        // ✅ use a consistent key for foundation wall group measurement
        'measureType': 'foundationWall',
        'type': selected.type,
        'unit': selected.unit,
        'value': val,
        'label': selected.label,

        // BOQ
        'boqCode': boqCodeCtrl.text.trim(),
        'boqDescription': boqDescCtrl.text.trim(),

        // group id
        'foundationGroupId': wallGroupId,
        // also store an alias if you want easier querying (optional)
        'wallGroupId': wallGroupId,

        // copy line refs (if present)
        'p1': p1,
        'p2': p2,
        'baseLengthM': baseLengthM,
        'segmentId': segmentId,
        'color': color,

        'createdAt': FieldValue.serverTimestamp(),
        'updatedAt': FieldValue.serverTimestamp(),
      });

      Get.snackbar('Added', 'New part added');
    } catch (e) {
      Get.snackbar('Error', '$e', snackPosition: SnackPosition.BOTTOM);
    } finally {
      valueCtrl.dispose();
      boqCodeCtrl.dispose();
      boqDescCtrl.dispose();
    }
  }

  Future<RWAction> openRetainingWallCompositeFromSegments({
    required Offset p1,
    required Offset p2,
    required Map<String, dynamic> drawingData,
    // required String projectId,
    // required String buildingId,
    // required String drawingId,
    // required Color currentColor,
    // String? activeLabel,

    // required CollectionReference<Map<String, dynamic>> measurementsRef,
    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    // remember map (store in your controller)
    // required Map<String, dynamic> lastRetainingWallDefaults,

    // optional for UI refresh
    VoidCallback? onUpdateViewer,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return RWAction.cancel;

    // --------- calibration guard ----------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0);
    if (!calibrated || pxPerM <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Calibrate drawing first (pixelsPerUnit).',
      );
      return RWAction.cancel;
    }

    // length from p1/p2
    final baseLengthM = distM(p1, p2, drawingData);
    if (baseLengthM <= 0) {
      Get.snackbar('Invalid', 'Length is zero. Check points/calibration.');
      return RWAction.cancel;
    }

    // -------- helpers for remembered defaults ----------
    TextEditingController nCtrl(String key, String fallback) {
      final v = lastRetainingWallDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    bool bVal(String key, bool fb) {
      final v = lastRetainingWallDefaults[key];
      if (v is bool) return v;
      if (v is num) return v != 0;
      if (v is String) {
        final s = v.trim().toLowerCase();
        return s == 'true' || s == '1' || s == 'yes' || s == 'y';
      }
      return fb;
    }

    double parseD(TextEditingController c, double fallback) =>
        double.tryParse(c.text.trim()) ?? fallback;

    int parseI(TextEditingController c, int fallback) =>
        int.tryParse(c.text.trim()) ?? fallback;

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    // -------- controllers (REMEMBERED) ----------
    final nameCtrl = nCtrl('rwName', (activeLabel ?? 'Retaining wall').trim());
    final typeCtrl = nCtrl('rwType', 'RW1');

    // length NOT remembered (always from p1/p2; but user can override if needed)
    final lengthCtrl = TextEditingController(
      text: baseLengthM.toStringAsFixed(3),
    );

    final heightCtrl = nCtrl('rwHeightM', '2.40');
    final thickCtrl = nCtrl('rwThicknessM', '0.20');

    final qtyCtrl = nCtrl('qtyEach', '1'); // qty per building
    final factorCtrl = nCtrl('buildingFactor', '1'); // multiplier for buildings

    bool includeConcrete = bVal('includeConcrete', true);
    bool includeFormwork = bVal('includeFormwork', true);
    bool formworkTwoSides = bVal('formworkTwoSides', true);

    bool includeRebars = bVal('includeRebars', true);

    // rebar: vertical
    final vDiaCtrl = nCtrl('vDiaMm', '12');
    final vSpacingCtrl = nCtrl('vSpacingM', '0.20');
    final vCoverCtrl = nCtrl('vCoverM', '0.04');
    final vExtraCtrl = nCtrl('vExtraM', '0.30'); // hooks/laps add per bar

    // rebar: horizontal
    final hDiaCtrl = nCtrl('hDiaMm', '10');
    final hSpacingCtrl = nCtrl('hSpacingM', '0.20');
    final hCoverCtrl = nCtrl('hCoverM', '0.04');
    final hExtraCtrl = nCtrl('hExtraM', '0.30');

    // BOQs remembered
    BoqPick? boqConcrete = pickFromMap(
      lastRetainingWallDefaults['boqConcrete'],
    );
    BoqPick? boqFormwork = pickFromMap(
      lastRetainingWallDefaults['boqFormwork'],
    );
    BoqPick? boqRebarV = pickFromMap(lastRetainingWallDefaults['boqRebarV']);
    BoqPick? boqRebarH = pickFromMap(lastRetainingWallDefaults['boqRebarH']);

    Future<void> pickBoq(
      BuildContext context,
      void Function(BoqPick p) apply,
      StateSetter setState,
    ) async {
      final p = await showBoqPickerDialog(context: context);
      if (p == null) return;
      setState(() => apply(p));
    }

    InputDecoration deco(String label) => InputDecoration(
      labelText: label,
      border: const OutlineInputBorder(),
      isDense: true,
    );

    Widget boqLine({
      required String title,
      required BoqPick? pick,
      required VoidCallback onPick,
      VoidCallback? onClear,
    }) {
      return Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: const Color(0xFFF8FAFC),
          borderRadius: BorderRadius.circular(18),
          border: Border.all(color: const Color(0xFFE2E8F0)),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              title,
              style: const TextStyle(
                fontWeight: FontWeight.w900,
                color: Color(0xFF0F172A),
              ),
            ),
            const SizedBox(height: 6),
            Row(
              children: [
                Expanded(
                  child: InputDecorator(
                    decoration: const InputDecoration(
                      border: OutlineInputBorder(),
                      isDense: true,
                      labelText: 'BOQ code',
                    ),
                    child: Text(
                      (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ),
                const SizedBox(width: 8),
                OutlinedButton.icon(
                  onPressed: onPick,
                  icon: const Icon(Icons.search, size: 18),
                  label: const Text('Pick'),
                ),
                if (onClear != null) ...[
                  const SizedBox(width: 8),
                  OutlinedButton(
                    onPressed: onClear,
                    child: const Text('Clear'),
                  ),
                ],
              ],
            ),
            if ((pick?.description ?? '').trim().isNotEmpty) ...[
              const SizedBox(height: 6),
              Text(
                pick!.description,
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(fontSize: 12, color: Color(0xFF475569)),
              ),
            ],
          ],
        ),
      );
    }

    bool saving = false;

    // -------- show dialog ----------
    final RWAction action =
        await Get.dialog<RWAction>(
          StatefulBuilder(
            builder: (dialogCtx, setState) {
              // read inputs
              final L = parseD(lengthCtrl, baseLengthM).clamp(0.0, 1e9);
              final H = parseD(heightCtrl, 2.4).clamp(0.0, 1e9);
              final T = parseD(thickCtrl, 0.2).clamp(0.0, 1e9);

              final qtyEach = parseI(qtyCtrl, 1).clamp(1, 999999);
              final factor = parseI(factorCtrl, 1).clamp(1, 999999);
              final qtyTotal = qtyEach * factor;

              // concrete
              final concM3_one = L * H * T;
              final concM3_total = concM3_one * qtyTotal;

              // formwork (area): sides only (H x L)
              // 1 side: H*L
              // 2 sides: 2*H*L
              final fwFactor = formworkTwoSides ? 2.0 : 1.0;
              final fwM2_one = H * L * fwFactor;
              final fwM2_total = fwM2_one * qtyTotal;

              // rebars calc (simple QS takeoff):
              // Vertical bars: spaced along length => count = floor(L/spacing)+1
              // each bar length = (H - 2*cover) + extra
              // Horizontal bars: spaced along height => count = floor(H/spacing)+1
              // each bar length = (L - 2*cover) + extra
              final vDia = int.tryParse(vDiaCtrl.text.trim()) ?? 12;
              final vSp = parseD(vSpacingCtrl, 0.2).clamp(0.001, 1e9);
              final vCover = parseD(vCoverCtrl, 0.04).clamp(0.0, 1e9);
              final vExtra = parseD(vExtraCtrl, 0.30).clamp(0.0, 1e9);

              final hDia = int.tryParse(hDiaCtrl.text.trim()) ?? 10;
              final hSp = parseD(hSpacingCtrl, 0.2).clamp(0.001, 1e9);
              final hCover = parseD(hCoverCtrl, 0.04).clamp(0.0, 1e9);
              final hExtra = parseD(hExtraCtrl, 0.30).clamp(0.0, 1e9);

              int vCountOne = (L / vSp).floor() + 1;
              int hCountOne = (H / hSp).floor() + 1;

              // protect negative clear
              final vBarLenOne = ((H - 2 * vCover).clamp(0.0, 1e9)) + vExtra;
              final hBarLenOne = ((L - 2 * hCover).clamp(0.0, 1e9)) + hExtra;

              final vTotalLenOne = vCountOne * vBarLenOne;
              final hTotalLenOne = hCountOne * hBarLenOne;

              final vKgOne = vTotalLenOne * rebarUnitWeightKgPerM(vDia);
              final hKgOne = hTotalLenOne * rebarUnitWeightKgPerM(hDia);

              final vKgTotal = vKgOne * qtyTotal;
              final hKgTotal = hKgOne * qtyTotal;

              Future<void> doSave(RWAction after) async {
                if (saving) return;

                // validate
                if (L <= 0 || H <= 0 || T <= 0) {
                  Get.snackbar('Invalid', 'Enter valid L, H and thickness.');
                  return;
                }

                if (includeConcrete && boqConcrete == null) {
                  Get.snackbar('Missing', 'Pick Concrete BOQ.');
                  return;
                }
                if (includeFormwork && boqFormwork == null) {
                  Get.snackbar('Missing', 'Pick Formwork BOQ.');
                  return;
                }
                if (includeRebars) {
                  if (boqRebarV == null) {
                    Get.snackbar('Missing', 'Pick Vertical rebar BOQ.');
                    return;
                  }
                  if (boqRebarH == null) {
                    Get.snackbar('Missing', 'Pick Horizontal rebar BOQ.');
                    return;
                  }
                }

                setState(() => saving = true);

                final now = FieldValue.serverTimestamp();
                final groupId =
                    measurementsRef.doc().id; // group id for this wall

                int colorVal = currentColor.value;

                Map<String, dynamic> baseDoc({
                  required String type,
                  required String unit,
                  required double valueTotal,
                  required BoqPick boq,
                }) {
                  return {
                    'projectId': projectId,
                    'buildingId': buildingId,
                    'drawingId': drawingId,

                    'measureType': 'retainingWall',
                    'type': type,
                    'unit': unit,
                    'value': valueTotal,

                    'boqItemId': boq.id,
                    'boqCode': boq.code,
                    'boqDescription': boq.description,

                    'groupId': groupId,
                    'label': nameCtrl.text.trim(),
                    'lineLabel':
                        '${nameCtrl.text.trim()} • ${typeCtrl.text.trim()}',
                    'rwType': typeCtrl.text.trim(),

                    // qty
                    'qtyEach': qtyEach,
                    'buildingFactor': factor,
                    'qtyTotal': qtyTotal,

                    // geometry
                    'lengthM': L,
                    'heightM': H,
                    'thicknessM': T,
                    'p1': {'x': p1.dx, 'y': p1.dy},
                    'p2': {'x': p2.dx, 'y': p2.dy},

                    // meta
                    'color': colorVal,
                    'createdAt': now,
                    'updatedAt': now,
                  };
                }

                try {
                  final batch = FirebaseFirestore.instance.batch();

                  // Concrete
                  if (includeConcrete) {
                    batch.set(measurementsRef.doc('$groupId-conc'), {
                      ...baseDoc(
                        type: 'rwConcrete',
                        unit: 'm3',
                        valueTotal: concM3_total,
                        boq: boqConcrete!,
                      ),
                      'valueOne': concM3_one,
                    });
                  }

                  // Formwork
                  if (includeFormwork) {
                    batch.set(measurementsRef.doc('$groupId-fwk'), {
                      ...baseDoc(
                        type: 'rwFormwork',
                        unit: 'm2',
                        valueTotal: fwM2_total,
                        boq: boqFormwork!,
                      ),
                      'valueOne': fwM2_one,
                      'formworkTwoSides': formworkTwoSides,
                      'formworkSides': formworkTwoSides ? 2 : 1,
                    });
                  }

                  // Rebars Vertical
                  if (includeRebars) {
                    batch.set(measurementsRef.doc('$groupId-rbv'), {
                      ...baseDoc(
                        type: 'rwRebarVertical',
                        unit: 'kg',
                        valueTotal: vKgTotal,
                        boq: boqRebarV!,
                      ),
                      'valueOne': vKgOne,
                      'diameterMm': vDia,
                      'spacingM': vSp,
                      'coverM': vCover,
                      'extraM': vExtra,
                      'barsCountOne': vCountOne,
                      'barLenOneM': vBarLenOne,
                      'totalLenOneM': vTotalLenOne,
                      'unitWeightKgPerM': rebarUnitWeightKgPerM(vDia),
                    });

                    // Rebars Horizontal
                    batch.set(measurementsRef.doc('$groupId-rbh'), {
                      ...baseDoc(
                        type: 'rwRebarHorizontal',
                        unit: 'kg',
                        valueTotal: hKgTotal,
                        boq: boqRebarH!,
                      ),
                      'valueOne': hKgOne,
                      'diameterMm': hDia,
                      'spacingM': hSp,
                      'coverM': hCover,
                      'extraM': hExtra,
                      'barsCountOne': hCountOne,
                      'barLenOneM': hBarLenOne,
                      'totalLenOneM': hTotalLenOne,
                      'unitWeightKgPerM': rebarUnitWeightKgPerM(hDia),
                    });
                  }

                  await batch.commit();

                  // ✅ remember (NO length)
                  lastRetainingWallDefaults
                    ..['rwName'] = nameCtrl.text.trim()
                    ..['rwType'] = typeCtrl.text.trim()
                    ..['rwHeightM'] = H
                    ..['rwThicknessM'] = T
                    ..['qtyEach'] = qtyEach
                    ..['buildingFactor'] = factor
                    ..['includeConcrete'] = includeConcrete
                    ..['includeFormwork'] = includeFormwork
                    ..['formworkTwoSides'] = formworkTwoSides
                    ..['includeRebars'] = includeRebars
                    ..['vDiaMm'] = vDia
                    ..['vSpacingM'] = vSp
                    ..['vCoverM'] = vCover
                    ..['vExtraM'] = vExtra
                    ..['hDiaMm'] = hDia
                    ..['hSpacingM'] = hSp
                    ..['hCoverM'] = hCover
                    ..['hExtraM'] = hExtra
                    ..['boqConcrete'] = pickToMap(boqConcrete)
                    ..['boqFormwork'] = pickToMap(boqFormwork)
                    ..['boqRebarV'] = pickToMap(boqRebarV)
                    ..['boqRebarH'] = pickToMap(boqRebarH);

                  if (dialogCtx.mounted) {
                    Navigator.of(dialogCtx).pop(after);
                  }

                  Get.snackbar(
                    'Saved',
                    'Retaining wall saved (qty=$qtyTotal).',
                  );
                  onUpdateViewer?.call();
                } catch (e) {
                  // ✅ stay open, do not reset points outside
                  Get.snackbar(
                    'Save failed',
                    '$e',
                    snackPosition: SnackPosition.BOTTOM,
                  );
                  if (dialogCtx.mounted) setState(() => saving = false);
                }
              }

              Widget rwMetric(String label, String value, IconData icon) {
                return Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: const Color(0xFFF8FAFC),
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: const Color(0xFFE2E8F0)),
                  ),
                  child: Row(
                    children: [
                      Container(
                        width: 34,
                        height: 34,
                        decoration: BoxDecoration(
                          color: const Color(0xFFEFF6FF),
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Icon(
                          icon,
                          color: const Color(0xFF155EEF),
                          size: 18,
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              value,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 16,
                                fontWeight: FontWeight.w900,
                                color: Color(0xFF0F172A),
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              label,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 12,
                                fontWeight: FontWeight.w700,
                                color: Color(0xFF64748B),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                );
              }

              Widget rwPanel({
                required String title,
                required String subtitle,
                required IconData icon,
                required Widget child,
              }) {
                return Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(18),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(24),
                    border: Border.all(color: const Color(0xFFE2E8F0)),
                    boxShadow: const [
                      BoxShadow(
                        color: Color(0x0A0F172A),
                        blurRadius: 22,
                        offset: Offset(0, 10),
                      ),
                    ],
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Container(
                            width: 42,
                            height: 42,
                            decoration: BoxDecoration(
                              gradient: const LinearGradient(
                                colors: [Color(0xFF155EEF), Color(0xFF3B82F6)],
                              ),
                              borderRadius: BorderRadius.circular(15),
                            ),
                            child: Icon(icon, color: Colors.white, size: 22),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  title,
                                  style: const TextStyle(
                                    fontSize: 18,
                                    fontWeight: FontWeight.w900,
                                    color: Color(0xFF0F172A),
                                  ),
                                ),
                                const SizedBox(height: 2),
                                Text(
                                  subtitle,
                                  style: const TextStyle(
                                    fontSize: 12,
                                    fontWeight: FontWeight.w600,
                                    color: Color(0xFF64748B),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 16),
                      child,
                    ],
                  ),
                );
              }

              return AlertDialog(
                titlePadding: EdgeInsets.zero,
                contentPadding: EdgeInsets.zero,
                actionsPadding: const EdgeInsets.fromLTRB(24, 0, 24, 24),
                clipBehavior: Clip.antiAlias,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(28),
                ),
                title: Container(
                  padding: const EdgeInsets.fromLTRB(28, 26, 28, 24),
                  decoration: const BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                      colors: [Color(0xFF102A56), Color(0xFF155EEF)],
                    ),
                  ),
                  child: Row(
                    children: [
                      Container(
                        width: 54,
                        height: 54,
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.14),
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(color: Colors.white24),
                        ),
                        child: const Icon(
                          Icons.account_balance_rounded,
                          color: Colors.white,
                          size: 28,
                        ),
                      ),
                      const SizedBox(width: 16),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            const Text(
                              'Retaining wall',
                              style: TextStyle(
                                color: Colors.white,
                                fontWeight: FontWeight.w900,
                                fontSize: 28,
                              ),
                            ),
                            const SizedBox(height: 6),
                            Text(
                              'Concrete, formwork and reinforcement • ${baseLengthM.toStringAsFixed(3)} m',
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.78),
                                fontSize: 13,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                content: SizedBox(
                  width: 920,
                  child: SingleChildScrollView(
                    child: Container(
                      color: const Color(0xFFF8FAFC),
                      padding: const EdgeInsets.all(24),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          // progress bar
                          if (saving) ...[
                            const LinearProgressIndicator(),
                            const SizedBox(height: 10),
                          ],
                          rwPanel(
                            title: 'Wall geometry',
                            subtitle:
                                'Measured length, wall dimensions and total quantity',
                            icon: Icons.straighten_rounded,
                            child: Column(
                              children: [
                                Row(
                                  children: [
                                    Expanded(
                                      child: rwMetric(
                                        'Length from taps',
                                        '${baseLengthM.toStringAsFixed(3)} m',
                                        Icons.route_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rwMetric(
                                        'Concrete',
                                        '${concM3_total.toStringAsFixed(3)} m³',
                                        Icons.inventory_2_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rwMetric(
                                        'Total qty',
                                        '$qtyEach × $factor = $qtyTotal',
                                        Icons.functions_rounded,
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 12),
                                Row(
                                  children: [
                                    Expanded(
                                      child: rwMetric(
                                        'Formwork',
                                        '${fwM2_total.toStringAsFixed(3)} m²',
                                        Icons.view_sidebar_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rwMetric(
                                        'Vertical rebars',
                                        '${vKgTotal.toStringAsFixed(2)} kg',
                                        Icons.vertical_align_center_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rwMetric(
                                        'Horizontal rebars',
                                        '${hKgTotal.toStringAsFixed(2)} kg',
                                        Icons.horizontal_rule_rounded,
                                      ),
                                    ),
                                  ],
                                ),
                              ],
                            ),
                          ),
                          const SizedBox(height: 18),

                          Text(
                            'Length from taps: ${baseLengthM.toStringAsFixed(3)} m',
                            style: const TextStyle(fontSize: 12),
                          ),
                          const SizedBox(height: 8),

                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: nameCtrl,
                                  decoration: deco('Label'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: typeCtrl,
                                  decoration: deco('Type (RW1...)'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),

                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: lengthCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: deco(
                                    'Length (m) (not remembered)',
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: heightCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: deco('Height (m)'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: thickCtrl,
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  decoration: deco('Thickness (m)'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),

                          const SizedBox(height: 10),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: qtyCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: deco('Qty (per building)'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: factorCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: deco('Building factor (×)'),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),

                          const SizedBox(height: 6),
                          Text(
                            'Total qty used in BOQs = $qtyEach × $factor = $qtyTotal',
