  // FirebaseFirestore _db;
  Future<void> openOpeningsDialogFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,
    required CollectionReference<Map<String, dynamic>> measurementsRef,
    required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    // ✅ optional: pass known walls to select from
    List<WallPick> wallPicks = const [],
  }) async {
    if (polygon.length < 3) return;

    // ---------- calibration ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM =
        (drawingData['pixelsPerUnit'] is num)
            ? (drawingData['pixelsPerUnit'] as num).toDouble()
            : double.tryParse('${drawingData['pixelsPerUnit']}') ?? 0.0;

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar('Not calibrated', 'Calibrate drawing to measure openings.');
      return;
    }

    // ---------- geometry: bounding box spans ----------
    double minX = polygon.first.dx, maxX = polygon.first.dx;
    double minY = polygon.first.dy, maxY = polygon.first.dy;
    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }

    final measuredWm = (maxX - minX) / pxPerM;
    final measuredHm = (maxY - minY) / pxPerM;

    if (measuredWm <= 0 || measuredHm <= 0) {
      Get.snackbar('Opening', 'Invalid polygon size.');
      return;
    }

    // polygon for firestore
    final polyData = polygon.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    // ---------- helpers ----------
    double d(String s, [double fallback = 0.0]) =>
        double.tryParse(s.trim()) ?? fallback;
    int i(String s, [int fallback = 1]) => int.tryParse(s.trim()) ?? fallback;

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    Future<void> pickBoq(
      BuildContext ctx,
      void Function(BoqPick p) apply,
    ) async {
      final pick = await showBoqPickerDialog(ctx);
      if (pick == null) return;
      apply(pick);
    }

    // =========================================================
    // ✅ HOST WALL section (shared for both tabs)
    // =========================================================
    bool hostWallAttached =
        (lastWindowDefaults['hostWallAttached'] ??
            lastDoorDefaults['hostWallAttached'] ??
            true) ==
        true;

    String hostWallSide =
        (lastWindowDefaults['hostWallSide'] ??
                lastDoorDefaults['hostWallSide'] ??
                'internal')
            .toString()
            .toLowerCase();

    // if you pass wallPicks, allow dropdown. else allow manual id input.
    final hostWallIdCtrl = TextEditingController(
      text:
          (lastWindowDefaults['hostWallGroupId'] ??
                  lastDoorDefaults['hostWallGroupId'] ??
                  '')
              .toString(),
    );

    WallPick? selectedWall;
    if (wallPicks.isNotEmpty && hostWallIdCtrl.text.trim().isNotEmpty) {
      selectedWall = wallPicks.firstWhereOrNull(
        (w) => w.id == hostWallIdCtrl.text.trim(),
      );
    }

    // =========================================================
    // ✅ Door defaults
    // =========================================================
    final doorTypeCtrl = TextEditingController(
      text: (lastDoorDefaults['type'] ?? 'D1').toString(),
    );
    final doorNameCtrl = TextEditingController(
      text: (lastDoorDefaults['name'] ?? '').toString(),
    );

    final doorWCtrl = TextEditingController(
      text: ((lastDoorDefaults['wM'] ?? measuredWm) as num)
          .toDouble()
          .toStringAsFixed(3),
    );
    final doorHCtrl = TextEditingController(
      text: ((lastDoorDefaults['hM'] ?? measuredHm) as num)
          .toDouble()
          .toStringAsFixed(3),
    );
    final doorQtyCtrl = TextEditingController(
      text: (lastDoorDefaults['qty'] ?? 1).toString(),
    );

    bool doorMeasureAsNo = (lastDoorDefaults['measureAsNo'] ?? true) == true;
    bool doorIncludeFanlight =
        (lastDoorDefaults['incFanlight'] ?? false) == true;
    bool doorIncludeVent = (lastDoorDefaults['incVent'] ?? false) == true;
    bool doorIncludeIronmongery =
        (lastDoorDefaults['incIron'] ?? false) == true;

    final doorFanlightQtyCtrl = TextEditingController(
      text: (lastDoorDefaults['fanlightNr'] ?? 1).toString(),
    );
    final doorVentQtyCtrl = TextEditingController(
      text: (lastDoorDefaults['ventNr'] ?? 1).toString(),
    );
    final doorIronQtyCtrl = TextEditingController(
      text: (lastDoorDefaults['ironNr'] ?? 1).toString(),
    );

    BoqPick? boqDoorComplete = pickFromMap(lastDoorDefaults['boqComplete']);
    BoqPick? boqDoorFanlight = pickFromMap(lastDoorDefaults['boqFanlight']);
    BoqPick? boqDoorVent = pickFromMap(lastDoorDefaults['boqVent']);
    BoqPick? boqDoorIron = pickFromMap(lastDoorDefaults['boqIron']);

    // =========================================================
    // ✅ Window defaults (+ CILL)
    // =========================================================
    final winTypeCtrl = TextEditingController(
      text: (lastWindowDefaults['type'] ?? 'W1').toString(),
    );
    final winNameCtrl = TextEditingController(
      text: (lastWindowDefaults['name'] ?? '').toString(),
    );

    final winWCtrl = TextEditingController(
      text: ((lastWindowDefaults['wM'] ?? measuredWm) as num)
          .toDouble()
          .toStringAsFixed(3),
    );
    final winHCtrl = TextEditingController(
      text: ((lastWindowDefaults['hM'] ?? measuredHm) as num)
          .toDouble()
          .toStringAsFixed(3),
    );
    final winQtyCtrl = TextEditingController(
      text: (lastWindowDefaults['qty'] ?? 1).toString(),
    );

    bool winMeasureAsNo = (lastWindowDefaults['measureAsNo'] ?? true) == true;

    bool winIncludeGrille = (lastWindowDefaults['incGrille'] ?? false) == true;
    bool winIncludeFlyscreen = (lastWindowDefaults['incFly'] ?? false) == true;

    // ✅ NEW: Cill
    bool winIncludeCill = (lastWindowDefaults['incCill'] ?? false) == true;
    String winCillUnit =
        (lastWindowDefaults['cillUnit'] ?? 'm').toString(); // 'm' or 'nr'
    final winCillPerWindowCtrl = TextEditingController(
      text: (lastWindowDefaults['cillPerWin'] ?? 1).toString(),
    );

    final winGrilleQtyCtrl = TextEditingController(
      text: (lastWindowDefaults['grilleNr'] ?? 1).toString(),
    );
    final winFlyQtyCtrl = TextEditingController(
      text: (lastWindowDefaults['flyNr'] ?? 1).toString(),
    );

    BoqPick? boqWinComplete = pickFromMap(lastWindowDefaults['boqComplete']);
    BoqPick? boqWinGrille = pickFromMap(lastWindowDefaults['boqGrille']);
    BoqPick? boqWinFly = pickFromMap(lastWindowDefaults['boqFly']);

    // ✅ NEW: cill BOQ
    BoqPick? boqWinCill = pickFromMap(lastWindowDefaults['boqCill']);

    // group id
    draftOpeningsGroupId ??= measurementsRef.doc().id;
    final openingsGroupId = draftOpeningsGroupId!;

    // ---------- UI helpers ----------
    InputDecoration deco(String label) => InputDecoration(
      labelText: label,
      border: const OutlineInputBorder(),
      isDense: true,
    );

    Widget boqRow({
      required BuildContext ctx,
      required String label,
      required BoqPick? pick,
      required VoidCallback onPick,
      required VoidCallback onClear,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              const SizedBox(width: 8),
              OutlinedButton(onPressed: onClear, child: const Text('Clear')),
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    // ---------- dialog ----------
    final ok =
        await Get.dialog<bool>(
          StatefulBuilder(
            builder: (dCtx, setState) {
              // live preview sizes
              final dW = d(doorWCtrl.text, measuredWm);
              final dH = d(doorHCtrl.text, measuredHm);
              final dQty = i(doorQtyCtrl.text, 1);
              final doorSizeText =
                  '${(dW * 1000).round()}x${(dH * 1000).round()}mm';
              final doorAreaTotal = (dW * dH * dQty).clamp(
                0.0,
                double.infinity,
              );

              final wW = d(winWCtrl.text, measuredWm);
              final wH = d(winHCtrl.text, measuredHm);
              final wQty = i(winQtyCtrl.text, 1);
              final winSizeText =
                  '${(wW * 1000).round()}x${(wH * 1000).round()}mm';
              final winAreaTotal = (wW * wH * wQty).clamp(0.0, double.infinity);

              double cillTotalValuePreview() {
                if (!winIncludeCill) return 0.0;
                if (winCillUnit == 'm') {
                  return (wW * wQty).clamp(
                    0.0,
                    double.infinity,
                  ); // total length
                }
                final perWin = i(winCillPerWindowCtrl.text, 1);
                return (perWin * wQty).toDouble();
              }

              // Host wall deduce preview factors
              // internal wall: finishes both sides internal => 2 faces
              // external wall: internal face + external face => 1 + 1
              final internalFaces = (hostWallSide == 'internal') ? 2 : 1;
              final externalFaces = (hostWallSide == 'external') ? 1 : 0;

              Widget hostWallSection() {
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'Host wall (for deductions)',
                      style: TextStyle(fontWeight: FontWeight.w800),
                    ),
                    const SizedBox(height: 8),
                    CheckboxListTile(
                      value: hostWallAttached,
                      onChanged:
                          (v) => setState(() => hostWallAttached = v ?? true),
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                      title: const Text('This opening is attached to a wall'),
                      subtitle: const Text(
                        'If ON, deductions can be applied to walling + finishes/decoration.',
                        style: TextStyle(fontSize: 12),
                      ),
                    ),
                    if (hostWallAttached) ...[
                      Row(
                        children: [
                          Expanded(
                            child: DropdownButtonFormField<String>(
                              value: hostWallSide,
                              items: const [
                                DropdownMenuItem(
                                  value: 'internal',
                                  child: Text('Internal wall'),
                                ),
                                DropdownMenuItem(
                                  value: 'external',
                                  child: Text('External wall'),
                                ),
                              ],
                              onChanged:
                                  (v) => setState(
                                    () => hostWallSide = (v ?? 'internal'),
                                  ),
                              decoration: deco('Wall type'),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child:
                                (wallPicks.isNotEmpty)
                                    ? DropdownButtonFormField<WallPick>(
                                      value: selectedWall,
                                      items:
                                          wallPicks
                                              .map(
                                                (w) => DropdownMenuItem(
                                                  value: w,
                                                  child: Text(
                                                    '${w.name} (${w.side})',
                                                  ),
                                                ),
                                              )
                                              .toList(),
                                      onChanged: (v) {
                                        setState(() {
                                          selectedWall = v;
                                          hostWallIdCtrl.text = v?.id ?? '';
                                          // auto align side if wall pick has side
                                          if ((v?.side ?? '').isNotEmpty) {
                                            hostWallSide =
                                                v!.side.toLowerCase();
                                          }
                                        });
                                      },
                                      decoration: deco(
                                        'Select wall group (optional)',
                                      ),
                                    )
                                    : TextField(
                                      controller: hostWallIdCtrl,
                                      decoration: deco(
                                        'Wall group id (optional)',
                                      ),
                                      onChanged: (_) => setState(() {}),
                                    ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      Text(
                        'Deduction rule preview: internal finishes ×$internalFaces face(s), external finishes ×$externalFaces face(s).',
                        style: const TextStyle(fontSize: 12),
                      ),
                    ],
                  ],
                );
              }

              return DefaultTabController(
                length: 2,
                child: AlertDialog(
                  title: const Text('Openings (Doors & Windows)'),
                  content: SizedBox(
                    width: 760,
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        // ✅ shared host wall
                        hostWallSection(),
                        const SizedBox(height: 12),
                        const Divider(),

                        const TabBar(
                          tabs: [Tab(text: 'Doors'), Tab(text: 'Windows')],
                        ),
                        const SizedBox(height: 10),
                        Flexible(
                          child: TabBarView(
                            children: [
                              // ========================= DOORS TAB =========================
                              SingleChildScrollView(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      'Measured: W≈${measuredWm.toStringAsFixed(3)} m, H≈${measuredHm.toStringAsFixed(3)} m',
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                    const SizedBox(height: 10),

                                    Row(
                                      children: [
                                        Expanded(
                                          child: TextField(
                                            controller: doorTypeCtrl,
                                            decoration: deco(
                                              'Door type (e.g. D1)',
                                            ),
                                            onChanged: (_) => setState(() {}),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: TextField(
                                            controller: doorNameCtrl,
                                            decoration: deco(
                                              'Location/name (optional)',
                                            ),
                                            onChanged: (_) => setState(() {}),
                                          ),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 10),

                                    Row(
                                      children: [
                                        Expanded(
                                          child: TextField(
                                            controller: doorWCtrl,
                                            keyboardType:
                                                const TextInputType.numberWithOptions(
                                                  decimal: true,
                                                ),
                                            decoration: deco('Width W (m)'),
                                            onChanged: (_) => setState(() {}),
                                          ),
