                                    const SizedBox(height: 10),

                                    Row(
                                      children: [
                                        Expanded(
                                          child: TextField(
                                            controller: winWCtrl,
                                            keyboardType:
                                                const TextInputType.numberWithOptions(
                                                  decimal: true,
                                                ),
                                            decoration: deco('Width W (m)'),
                                            onChanged: (_) => setState(() {}),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: TextField(
                                            controller: winHCtrl,
                                            keyboardType:
                                                const TextInputType.numberWithOptions(
                                                  decimal: true,
                                                ),
                                            decoration: deco('Height H (m)'),
                                            onChanged: (_) => setState(() {}),
                                          ),
                                        ),
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: TextField(
                                            controller: winQtyCtrl,
                                            keyboardType: TextInputType.number,
                                            decoration: deco('Qty (No.)'),
                                            onChanged: (_) => setState(() {}),
                                          ),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 6),
                                    Text(
                                      'Size: $winSizeText',
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                    Text(
                                      'Area for deductions: ${winAreaTotal.toStringAsFixed(3)} m²',
                                      style: const TextStyle(fontSize: 12),
                                    ),

                                    const Divider(height: 24),

                                    CheckboxListTile(
                                      value: winMeasureAsNo,
                                      onChanged:
                                          (v) => setState(
                                            () => winMeasureAsNo = v ?? true,
                                          ),
                                      contentPadding: EdgeInsets.zero,
                                      dense: true,
                                      title: const Text(
                                        'Measure as No. (complete window)',
                                      ),
                                    ),

                                    if (winMeasureAsNo) ...[
                                      boqRow(
                                        ctx: dCtx,
                                        label: 'Window complete BOQ (No)',
                                        pick: boqWinComplete,
                                        onPick:
                                            () async => pickBoq(
                                              dCtx,
                                              (p) => setState(
                                                () => boqWinComplete = p,
                                              ),
                                            ),
                                        onClear:
                                            () => setState(
                                              () => boqWinComplete = null,
                                            ),
                                      ),
                                      const SizedBox(height: 12),
                                    ],

                                    CheckboxListTile(
                                      value: winIncludeGrille,
                                      onChanged:
                                          (v) => setState(
                                            () => winIncludeGrille = v ?? false,
                                          ),
                                      contentPadding: EdgeInsets.zero,
                                      dense: true,
                                      title: const Text(
                                        'Add burglar bars/grille (No)',
                                      ),
                                    ),
                                    if (winIncludeGrille) ...[
                                      boqRow(
                                        ctx: dCtx,
                                        label: 'Grille/burglar bars BOQ (No)',
                                        pick: boqWinGrille,
                                        onPick:
                                            () async => pickBoq(
                                              dCtx,
                                              (p) => setState(
                                                () => boqWinGrille = p,
                                              ),
                                            ),
                                        onClear:
                                            () => setState(
                                              () => boqWinGrille = null,
                                            ),
                                      ),
                                      const SizedBox(height: 8),
                                      TextField(
                                        controller: winGrilleQtyCtrl,
                                        keyboardType: TextInputType.number,
                                        decoration: deco(
                                          'Grille per window (No)',
                                        ),
                                        onChanged: (_) => setState(() {}),
                                      ),
                                      const SizedBox(height: 12),
                                    ],

                                    CheckboxListTile(
                                      value: winIncludeFlyscreen,
                                      onChanged:
                                          (v) => setState(
                                            () =>
                                                winIncludeFlyscreen =
                                                    v ?? false,
                                          ),
                                      contentPadding: EdgeInsets.zero,
                                      dense: true,
                                      title: const Text('Add flyscreen (No)'),
                                    ),
                                    if (winIncludeFlyscreen) ...[
                                      boqRow(
                                        ctx: dCtx,
                                        label: 'Flyscreen BOQ (No)',
                                        pick: boqWinFly,
                                        onPick:
                                            () async => pickBoq(
                                              dCtx,
                                              (p) =>
                                                  setState(() => boqWinFly = p),
                                            ),
                                        onClear:
                                            () => setState(
                                              () => boqWinFly = null,
                                            ),
                                      ),
                                      const SizedBox(height: 8),
                                      TextField(
                                        controller: winFlyQtyCtrl,
                                        keyboardType: TextInputType.number,
                                        decoration: deco(
                                          'Flyscreen per window (No)',
                                        ),
                                        onChanged: (_) => setState(() {}),
                                      ),
                                      const SizedBox(height: 12),
                                    ],

                                    // ✅ NEW: CILL
                                    CheckboxListTile(
                                      value: winIncludeCill,
                                      onChanged:
                                          (v) => setState(
                                            () => winIncludeCill = v ?? false,
                                          ),
                                      contentPadding: EdgeInsets.zero,
                                      dense: true,
                                      title: const Text('Add window cill'),
                                      subtitle: const Text(
                                        'Common BOQ: precast concrete cills measured in m or No.',
                                        style: TextStyle(fontSize: 12),
                                      ),
                                    ),
                                    if (winIncludeCill) ...[
                                      Row(
                                        children: [
                                          Expanded(
                                            child:
                                                DropdownButtonFormField<String>(
                                                  value: winCillUnit,
                                                  items: const [
                                                    DropdownMenuItem(
                                                      value: 'm',
                                                      child: Text(
                                                        'Unit: m (length)',
                                                      ),
                                                    ),
                                                    DropdownMenuItem(
                                                      value: 'nr',
                                                      child: Text('Unit: No'),
                                                    ),
                                                  ],
                                                  onChanged:
                                                      (v) => setState(
                                                        () =>
                                                            winCillUnit =
                                                                v ?? 'm',
                                                      ),
                                                  decoration: deco('Cill unit'),
                                                ),
                                          ),
                                          const SizedBox(width: 8),
                                          if (winCillUnit == 'nr')
                                            Expanded(
                                              child: TextField(
                                                controller:
                                                    winCillPerWindowCtrl,
                                                keyboardType:
                                                    TextInputType.number,
                                                decoration: deco(
                                                  'Cills per window (No)',
                                                ),
                                                onChanged:
                                                    (_) => setState(() {}),
                                              ),
                                            )
                                          else
                                            Expanded(
                                              child: InputDecorator(
                                                decoration: deco(
                                                  'Auto total length',
                                                ),
                                                child: Text(
                                                  '${(wW * wQty).toStringAsFixed(3)} m',
                                                  style: const TextStyle(
                                                    fontSize: 13,
                                                  ),
                                                ),
                                              ),
                                            ),
                                        ],
                                      ),
                                      const SizedBox(height: 10),
                                      boqRow(
                                        ctx: dCtx,
                                        label:
                                            'Window cill BOQ (${winCillUnit == 'm' ? 'm' : 'No'})',
                                        pick: boqWinCill,
                                        onPick:
                                            () async => pickBoq(
                                              dCtx,
                                              (p) => setState(
                                                () => boqWinCill = p,
                                              ),
                                            ),
                                        onClear:
                                            () => setState(
                                              () => boqWinCill = null,
                                            ),
                                      ),
                                      const SizedBox(height: 6),
                                      Text(
                                        'Cill preview value: ${cillTotalValuePreview().toStringAsFixed(3)} ${winCillUnit == 'm' ? 'm' : 'nr'}',
                                        style: const TextStyle(fontSize: 12),
                                      ),
                                      const SizedBox(height: 12),
                                    ],
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                  actions: [
                    TextButton(
                      onPressed: () => Get.back(result: false),
                      child: const Text('Cancel'),
                    ),
                    FilledButton(
                      onPressed: () => Get.back(result: true),
                      child: const Text('Save'),
                    ),
                  ],
                ),
              );
            },
          ),
          barrierDismissible: false,
        ) ??
        false;

    if (!ok) {
      // dispose controllers
      hostWallIdCtrl.dispose();

      doorTypeCtrl.dispose();
      doorNameCtrl.dispose();
      doorWCtrl.dispose();
      doorHCtrl.dispose();
      doorQtyCtrl.dispose();
      doorFanlightQtyCtrl.dispose();
      doorVentQtyCtrl.dispose();
      doorIronQtyCtrl.dispose();
      winTypeCtrl.dispose();
      winNameCtrl.dispose();
      winWCtrl.dispose();
      winHCtrl.dispose();
      winQtyCtrl.dispose();
      winGrilleQtyCtrl.dispose();
      winFlyQtyCtrl.dispose();
      winCillPerWindowCtrl.dispose();
      return;
    }

    // ---------- SAVE ----------
    try {
      final now = FieldValue.serverTimestamp();
      final groupId = openingsGroupId;
      final segmentId = measurementsRef.doc().id;

      // resolve host wall id from dropdown/manual
      final hostWallGroupId = (selectedWall?.id ?? hostWallIdCtrl.text.trim());

      // deduction factors
      final internalFaces = (hostWallSide == 'internal') ? 2 : 1;
      final externalFaces = (hostWallSide == 'external') ? 1 : 0;

      final docs = <Map<String, dynamic>>[];

      Map<String, dynamic> base({
        required String measureType,
        required String type,
        required String unit,
        required double value,
        required BoqPick boq,
        required String itemTypeCode,
        required String itemName,
        required double wM,
        required double hM,
        required int qty,
        required String sizeText,

        // ✅ host wall
        required bool hostAttached,
        required String hostSide,
        required String hostId,
        required double openingAreaM2Total,
        required double deductWallingM2,
        required double deductInternalFinishM2,
        required double deductExternalFinishM2,
      }) {
        return {
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,

          'measureType': measureType,
          'type': type,
          'unit': unit,
          'value': value,

          'qty': qty,
          'widthM': wM,
          'heightM': hM,
          'sizeText': sizeText,
          'itemTypeCode': itemTypeCode,
          'itemName': itemName,

          'openingAreaM2One': (wM * hM).clamp(0.0, double.infinity),
          'openingAreaM2Total': openingAreaM2Total,

          // ✅ host wall metadata for deductions
          'hostWallAttached': hostAttached,
          'hostWallSide': hostSide, // internal/external
          'hostWallGroupId': hostId, // can be blank if not provided
          'deductWallingM2': deductWallingM2,
          'deductInternalFinishM2': deductInternalFinishM2,
          'deductExternalFinishM2': deductExternalFinishM2,

          'boqItemId': boq.id,
          'boqCode': boq.code,
          'boqDescription': boq.description,

          'polygon': polyData,
          'color': currentColor.value,

          'openingsGroupId': groupId,
          'segmentId': segmentId,
          'createdAt': now,
          'updatedAt': now,
          'label': '${activeLabel ?? 'Openings'} - $type',
        };
      }

      // ---- DOOR ----
      final dW = d(doorWCtrl.text, measuredWm);
      final dH = d(doorHCtrl.text, measuredHm);
      final dQty = i(doorQtyCtrl.text, 1);
      final doorSizeText = '${(dW * 1000).round()}x${(dH * 1000).round()}mm';
      final doorAreaTotal = (dW * dH * dQty).clamp(0.0, double.infinity);

      // deductions (if attached)
      final doorDeductWalling = hostWallAttached ? doorAreaTotal : 0.0;
      final doorDeductInternal =
          hostWallAttached ? (doorAreaTotal * internalFaces) : 0.0;
      final doorDeductExternal =
          hostWallAttached ? (doorAreaTotal * externalFaces) : 0.0;

      if (doorMeasureAsNo) {
        if (boqDoorComplete != null && dW > 0 && dH > 0 && dQty > 0) {
          docs.add(
            base(
              measureType: 'compositeDoor',
              type: 'doorComplete',
              unit: 'nr',
              value: dQty.toDouble(),
              boq: boqDoorComplete!,
              itemTypeCode: doorTypeCtrl.text.trim(),
              itemName: doorNameCtrl.text.trim(),
              wM: dW,
              hM: dH,
              qty: dQty,
              sizeText: doorSizeText,

              hostAttached: hostWallAttached,
              hostSide: hostWallSide,
              hostId: hostWallGroupId,
              openingAreaM2Total: doorAreaTotal,
              deductWallingM2: doorDeductWalling,
              deductInternalFinishM2: doorDeductInternal,
              deductExternalFinishM2: doorDeductExternal,
            ),
          );

          if (doorIncludeIronmongery && boqDoorIron != null) {
            final perDoor = i(doorIronQtyCtrl.text, 1);
            final total = (perDoor * dQty).toDouble();
            if (total > 0) {
              docs.add(
                base(
                  measureType: 'compositeDoor',
                  type: 'doorIronmongery',
                  unit: 'nr',
                  value: total,
                  boq: boqDoorIron!,
                  itemTypeCode: doorTypeCtrl.text.trim(),
                  itemName: doorNameCtrl.text.trim(),
                  wM: dW,
                  hM: dH,
                  qty: dQty,
                  sizeText: doorSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: doorAreaTotal,
                  deductWallingM2: doorDeductWalling,
                  deductInternalFinishM2: doorDeductInternal,
                  deductExternalFinishM2: doorDeductExternal,
                ),
              );
            }
          }

          if (doorIncludeFanlight && boqDoorFanlight != null) {
            final perDoor = i(doorFanlightQtyCtrl.text, 1);
            final total = (perDoor * dQty).toDouble();
            if (total > 0) {
              docs.add(
                base(
                  measureType: 'compositeDoor',
                  type: 'doorFanlight',
                  unit: 'nr',
                  value: total,
                  boq: boqDoorFanlight!,
                  itemTypeCode: doorTypeCtrl.text.trim(),
                  itemName: doorNameCtrl.text.trim(),
                  wM: dW,
                  hM: dH,
                  qty: dQty,
                  sizeText: doorSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: doorAreaTotal,
                  deductWallingM2: doorDeductWalling,
                  deductInternalFinishM2: doorDeductInternal,
                  deductExternalFinishM2: doorDeductExternal,
                ),
              );
            }
          }

          if (doorIncludeVent && boqDoorVent != null) {
            final perDoor = i(doorVentQtyCtrl.text, 1);
            final total = (perDoor * dQty).toDouble();
            if (total > 0) {
              docs.add(
                base(
                  measureType: 'compositeDoor',
                  type: 'doorVent',
                  unit: 'nr',
                  value: total,
                  boq: boqDoorVent!,
                  itemTypeCode: doorTypeCtrl.text.trim(),
                  itemName: doorNameCtrl.text.trim(),
                  wM: dW,
                  hM: dH,
                  qty: dQty,
                  sizeText: doorSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: doorAreaTotal,
                  deductWallingM2: doorDeductWalling,
                  deductInternalFinishM2: doorDeductInternal,
                  deductExternalFinishM2: doorDeductExternal,
                ),
              );
            }
          }
        }
      }

      // ---- WINDOW ----
      final wW = d(winWCtrl.text, measuredWm);
      final wH = d(winHCtrl.text, measuredHm);
      final wQty = i(winQtyCtrl.text, 1);
      final winSizeText = '${(wW * 1000).round()}x${(wH * 1000).round()}mm';
      final winAreaTotal = (wW * wH * wQty).clamp(0.0, double.infinity);

      final winDeductWalling = hostWallAttached ? winAreaTotal : 0.0;
      final winDeductInternal =
          hostWallAttached ? (winAreaTotal * internalFaces) : 0.0;
      final winDeductExternal =
          hostWallAttached ? (winAreaTotal * externalFaces) : 0.0;

      if (winMeasureAsNo) {
        if (boqWinComplete != null && wW > 0 && wH > 0 && wQty > 0) {
          docs.add(
            base(
              measureType: 'compositeWindow',
              type: 'windowComplete',
              unit: 'nr',
              value: wQty.toDouble(),
              boq: boqWinComplete!,
              itemTypeCode: winTypeCtrl.text.trim(),
              itemName: winNameCtrl.text.trim(),
              wM: wW,
              hM: wH,
              qty: wQty,
              sizeText: winSizeText,

              hostAttached: hostWallAttached,
              hostSide: hostWallSide,
              hostId: hostWallGroupId,
              openingAreaM2Total: winAreaTotal,
              deductWallingM2: winDeductWalling,
              deductInternalFinishM2: winDeductInternal,
              deductExternalFinishM2: winDeductExternal,
            ),
          );

          if (winIncludeGrille && boqWinGrille != null) {
            final perWin = i(winGrilleQtyCtrl.text, 1);
            final total = (perWin * wQty).toDouble();
            if (total > 0) {
              docs.add(
                base(
                  measureType: 'compositeWindow',
                  type: 'windowGrille',
                  unit: 'nr',
                  value: total,
                  boq: boqWinGrille!,
                  itemTypeCode: winTypeCtrl.text.trim(),
                  itemName: winNameCtrl.text.trim(),
                  wM: wW,
                  hM: wH,
                  qty: wQty,
                  sizeText: winSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: winAreaTotal,
                  deductWallingM2: winDeductWalling,
                  deductInternalFinishM2: winDeductInternal,
                  deductExternalFinishM2: winDeductExternal,
                ),
              );
            }
          }

          if (winIncludeFlyscreen && boqWinFly != null) {
            final perWin = i(winFlyQtyCtrl.text, 1);
            final total = (perWin * wQty).toDouble();
            if (total > 0) {
              docs.add(
                base(
                  measureType: 'compositeWindow',
                  type: 'windowFlyscreen',
                  unit: 'nr',
                  value: total,
                  boq: boqWinFly!,
                  itemTypeCode: winTypeCtrl.text.trim(),
                  itemName: winNameCtrl.text.trim(),
                  wM: wW,
                  hM: wH,
                  qty: wQty,
                  sizeText: winSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: winAreaTotal,
                  deductWallingM2: winDeductWalling,
                  deductInternalFinishM2: winDeductInternal,
                  deductExternalFinishM2: winDeductExternal,
                ),
              );
            }
          }

          // ✅ CILL
          if (winIncludeCill && boqWinCill != null) {
            double cillValue = 0.0;
            String cillUnit = (winCillUnit == 'nr') ? 'nr' : 'm';

            if (cillUnit == 'm') {
              cillValue = (wW * wQty).clamp(0.0, double.infinity);
            } else {
              final perWin = i(winCillPerWindowCtrl.text, 1);
              cillValue = (perWin * wQty).toDouble();
            }

            if (cillValue > 0) {
              docs.add(
                base(
                  measureType: 'compositeWindow',
                  type: 'windowCill',
                  unit: cillUnit,
                  value: cillValue,
                  boq: boqWinCill!,
                  itemTypeCode: winTypeCtrl.text.trim(),
                  itemName: winNameCtrl.text.trim(),
                  wM: wW,
                  hM: wH,
                  qty: wQty,
                  sizeText: winSizeText,

                  hostAttached: hostWallAttached,
                  hostSide: hostWallSide,
                  hostId: hostWallGroupId,
                  openingAreaM2Total: winAreaTotal,
                  deductWallingM2: winDeductWalling,
                  deductInternalFinishM2: winDeductInternal,
                  deductExternalFinishM2: winDeductExternal,
                ),
              );
            }
          }
        }
      }

      if (docs.isEmpty) {
        Get.snackbar(
          'Nothing to save',
          'Pick at least one BOQ (Door or Window) and ensure values are valid.',
        );
        return;
      }

      // ✅ your existing batch helper
      await commitMeasurementBatchOrThrow(docs);

      // ✅ Remember automatically
      lastDoorDefaults = {
        'type': doorTypeCtrl.text.trim(),
        'name': doorNameCtrl.text.trim(),
        'wM': dW,
        'hM': dH,
        'qty': dQty,
        'measureAsNo': doorMeasureAsNo,
        'incFanlight': doorIncludeFanlight,
        'incVent': doorIncludeVent,
        'incIron': doorIncludeIronmongery,
        'fanlightNr': i(doorFanlightQtyCtrl.text, 1),
        'ventNr': i(doorVentQtyCtrl.text, 1),
        'ironNr': i(doorIronQtyCtrl.text, 1),
        'boqComplete': pickToMap(boqDoorComplete),
        'boqFanlight': pickToMap(boqDoorFanlight),
        'boqVent': pickToMap(boqDoorVent),
        'boqIron': pickToMap(boqDoorIron),
        // ✅ host wall
        'hostWallAttached': hostWallAttached,
        'hostWallSide': hostWallSide,
        'hostWallGroupId': hostWallGroupId,
      };

      lastWindowDefaults = {
        'type': winTypeCtrl.text.trim(),
        'name': winNameCtrl.text.trim(),
        'wM': wW,
        'hM': wH,
        'qty': wQty,
        'measureAsNo': winMeasureAsNo,
        'incGrille': winIncludeGrille,
        'incFly': winIncludeFlyscreen,
        'grilleNr': i(winGrilleQtyCtrl.text, 1),
        'flyNr': i(winFlyQtyCtrl.text, 1),
        'boqComplete': pickToMap(boqWinComplete),
        'boqGrille': pickToMap(boqWinGrille),
        'boqFly': pickToMap(boqWinFly),

        // ✅ Cill
        'incCill': winIncludeCill,
        'cillUnit': winCillUnit,
        'cillPerWin': i(winCillPerWindowCtrl.text, 1),
        'boqCill': pickToMap(boqWinCill),

        // ✅ host wall
        'hostWallAttached': hostWallAttached,
        'hostWallSide': hostWallSide,
        'hostWallGroupId': hostWallGroupId,
      };

      Get.snackbar('Saved', 'Openings saved (${docs.length} items).');
    } catch (e, st) {
      debugPrint('openOpeningsDialogFromPolygon save error: $e\n$st');
      Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
    } finally {
      hostWallIdCtrl.dispose();

      doorTypeCtrl.dispose();
      doorNameCtrl.dispose();
      doorWCtrl.dispose();
      doorHCtrl.dispose();
      doorQtyCtrl.dispose();
      doorFanlightQtyCtrl.dispose();
      doorVentQtyCtrl.dispose();
      doorIronQtyCtrl.dispose();
      winTypeCtrl.dispose();
      winNameCtrl.dispose();
      winWCtrl.dispose();
      winHCtrl.dispose();
      winQtyCtrl.dispose();
      winGrilleQtyCtrl.dispose();
      winFlyQtyCtrl.dispose();
      winCillPerWindowCtrl.dispose();
    }
  }

  double _num(dynamic v, double fb) =>
      (v is num) ? v.toDouble() : double.tryParse('$v') ?? fb;

  double _distPx(Offset a, Offset b) {
    final dx = b.dx - a.dx;
    final dy = b.dy - a.dy;
    return math.sqrt(dx * dx + dy * dy);
  }

  void setDraftRoofGroupId(String? v) {
    draftRoofGroupId = v;
    update(['viewer']); // or whatever you use to redraw
  }

  Future<RampSaveAction> openRampCompositeFromSegments({
    required Offset p1,
    required Offset p2,
    required Map<String, dynamic> drawingData,

    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,

    required CollectionReference<Map<String, dynamic>> measurementsRef,

    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    // Remembered defaults storage (keep as member in your controller)
    // required Map<String, dynamic> lastRampDefaults,

    // Draft group holder (keep as member)
    // required String? draftRampGroupId,
    // required void Function(String? v) setDraftRampGroupId,
    VoidCallback? onUpdateViewer,
  }) async {
    final ctx = Get.context;
    if (ctx == null) return RampSaveAction.cancel;

    // ---------------- calibration ----------------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0);
    if (!calibrated || pxPerM <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Calibrate drawing first (pixelsPerUnit).',
      );
      return RampSaveAction.cancel;
    }

    // you already have distM() in your project
    final double baseLengthM = distM(p1, p2, drawingData);
    if (baseLengthM <= 0) {
      Get.snackbar('Ramp', 'Invalid length (check calibration / points).');
      return RampSaveAction.cancel;
    }

    // ---------------- helpers ----------------
    String _partKey(RampPart p) =>
        p == RampPart.landing ? 'landing' : 'sloping';

    TextEditingController nCtrl(String key, String fallback) {
      final v = lastRampDefaults[key];
      return TextEditingController(text: (v == null) ? fallback : '$v');
    }

    bool bVal(String key, bool fb) {
      final v = lastRampDefaults[key];
      if (v is bool) return v;
      if (v is num) return v != 0;
      if (v is String) {
        final s = v.trim().toLowerCase();
        return s == 'true' || s == '1' || s == 'yes' || s == 'y';
      }
      return fb;
    }

    int parseI(TextEditingController c, int fb) =>
        int.tryParse(c.text.trim()) ?? fb;

    double parseD(TextEditingController c, double fb) =>
        double.tryParse(c.text.trim()) ?? fb;

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    Future<void> pickBoq(
      BuildContext context,
      void Function(BoqPick p) apply,
      StateSetter setState,
    ) async {
      final pick = await showBoqPickerDialog(context: context);
      if (pick == null) return;
      setState(() => apply(pick));
    }

    InputDecoration deco(String label) => InputDecoration(
      labelText: label,
      border: const OutlineInputBorder(),
      isDense: true,
    );

    Widget boqLine({
      required String title,
      required BoqPick? pick,
      required VoidCallback onPick,
      VoidCallback? onClear,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w800)),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              if (onClear != null) ...[
                const SizedBox(width: 8),
                OutlinedButton(onPressed: onClear, child: const Text('Clear')),
              ],
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    // rebar unit weight helper exists in your project
    double uw(int dia) => rebarUnitWeightKgPerM(dia);

    // ---------------- remembered: global (shared) ----------------
    // length NOT remembered (computed from p1-p2)
    final lengthCtrl = TextEditingController(
      text: baseLengthM.toStringAsFixed(3),
    );

    final rampWidthCtrl = nCtrl('rampWidthM', '3.00');
    final thicknessCtrl = nCtrl('thicknessM', '0.15');
    final qtyCtrl = nCtrl('qty', '1');
    final factorCtrl = nCtrl('buildingFactor', '1');

    // edge exposure: best for segment-based
    final exposedEdgeLenCtrl = nCtrl('exposedEdgeLenM', '0'); // allow user
    bool autoExposedEdge = bVal('autoExposedEdge', true);

    // ramp group
    final String rampGroupId =
        (draftRampGroupId?.trim().isNotEmpty == true)
            ? draftRampGroupId!.trim()
            : measurementsRef.doc().id;
    // if (draftRampGroupId == null || draftRampGroupId!.trim().isEmpty) {
    //   setDraftRampGroupId(rampGroupId);
    // }

    // which part default
    RampPart part =
        (() {
          final s =
              (lastRampDefaults['lastPart'] ?? 'landing')
                  .toString()
                  .toLowerCase()
                  .trim();
          return (s == 'sloping') ? RampPart.sloping : RampPart.landing;
        })();

    // ---------------- remembered: per-part BOQs ----------------
    BoqPick? boqConcreteLanding = pickFromMap(
      lastRampDefaults['boqConcrete_landing'],
    );
    BoqPick? boqSoffitLanding = pickFromMap(
      lastRampDefaults['boqSoffit_landing'],
    );
    BoqPick? boqEdgeLanding = pickFromMap(lastRampDefaults['boqEdge_landing']);

    BoqPick? boqConcreteSloping = pickFromMap(
      lastRampDefaults['boqConcrete_sloping'],
    );
    BoqPick? boqSoffitSloping = pickFromMap(
      lastRampDefaults['boqSoffit_sloping'],
    );
    BoqPick? boqEdgeSloping = pickFromMap(lastRampDefaults['boqEdge_sloping']);

    // Optional finishes per-part (if you want later, keep; can ignore)
    BoqPick? boqPlasterLanding = pickFromMap(
      lastRampDefaults['boqPlaster_landing'],
    );
    BoqPick? boqPaintLanding = pickFromMap(
      lastRampDefaults['boqPaint_landing'],
    );
    BoqPick? boqPlasterSloping = pickFromMap(
      lastRampDefaults['boqPlaster_sloping'],
    );
    BoqPick? boqPaintSloping = pickFromMap(
      lastRampDefaults['boqPaint_sloping'],
    );

    // ---------------- options (shared toggles) ----------------
    bool includeConcrete = bVal('includeConcrete', true);
    bool includeSoffitFormwork = bVal('includeSoffitFormwork', true);
    bool includeEdgeFormwork = bVal('includeEdgeFormwork', true);

    bool includeSoffitPlaster = bVal('includeSoffitPlaster', false);
    bool includeSoffitPaint = bVal('includeSoffitPaint', false);

    // rebars (shared) - you can later split per part if needed
    bool includeRebarMain = bVal('includeRebarMain', true);
    bool includeRebarDist = bVal('includeRebarDist', true);

    final mainDiaCtrl = nCtrl('mainDiaMm', '12');
    final mainSpacingCtrl = nCtrl('mainSpacingMm', '150');
    String mainPos =
        (lastRampDefaults['mainPos'] ?? 'bottom').toString().toLowerCase();
    if (mainPos != 'top') mainPos = 'bottom';

    final distDiaCtrl = nCtrl('distDiaMm', '10');
    final distSpacingCtrl = nCtrl('distSpacingMm', '200');
    String distPos =
        (lastRampDefaults['distPos'] ?? 'bottom').toString().toLowerCase();
    if (distPos != 'top') distPos = 'bottom';

    final embedCtrl = nCtrl('embedEachEndM', '0.30');
    final extraCtrl = nCtrl('extraLenM', '0.00');

    // Rebar BOQs per-part (recommended)
    BoqPick? boqMainRebarLanding = pickFromMap(
      lastRampDefaults['boqMainRebar_landing'],
    );
    BoqPick? boqDistRebarLanding = pickFromMap(
      lastRampDefaults['boqDistRebar_landing'],
    );
    BoqPick? boqMainRebarSloping = pickFromMap(
      lastRampDefaults['boqMainRebar_sloping'],
    );
    BoqPick? boqDistRebarSloping = pickFromMap(
      lastRampDefaults['boqDistRebar_sloping'],
    );

    bool saving = false;
    bool saveSucceeded = false;
    RampSaveAction result = RampSaveAction.cancel;

    BoqPick? _boqFor(String kind, RampPart p) {
      final k = _partKey(p);
      switch (kind) {
        case 'concrete':
          return (k == 'landing') ? boqConcreteLanding : boqConcreteSloping;
        case 'soffit':
          return (k == 'landing') ? boqSoffitLanding : boqSoffitSloping;
        case 'edge':
          return (k == 'landing') ? boqEdgeLanding : boqEdgeSloping;
        case 'plaster':
          return (k == 'landing') ? boqPlasterLanding : boqPlasterSloping;
        case 'paint':
          return (k == 'landing') ? boqPaintLanding : boqPaintSloping;
        case 'mainRebar':
          return (k == 'landing') ? boqMainRebarLanding : boqMainRebarSloping;
        case 'distRebar':
          return (k == 'landing') ? boqDistRebarLanding : boqDistRebarSloping;
      }
      return null;
    }

    void _setBoqFor(String kind, RampPart p, BoqPick? v) {
      final k = _partKey(p);
      switch (kind) {
        case 'concrete':
          if (k == 'landing') {
            boqConcreteLanding = v;
          } else {
            boqConcreteSloping = v;
          }
          return;
        case 'soffit':
          if (k == 'landing') {
            boqSoffitLanding = v;
          } else {
            boqSoffitSloping = v;
          }
          return;
        case 'edge':
          if (k == 'landing') {
            boqEdgeLanding = v;
          } else {
            boqEdgeSloping = v;
          }
          return;
        case 'plaster':
          if (k == 'landing') {
            boqPlasterLanding = v;
          } else {
            boqPlasterSloping = v;
          }
          return;
        case 'paint':
          if (k == 'landing') {
            boqPaintLanding = v;
          } else {
            boqPaintSloping = v;
          }
          return;
        case 'mainRebar':
          if (k == 'landing') {
            boqMainRebarLanding = v;
          } else {
            boqMainRebarSloping = v;
          }
          return;
        case 'distRebar':
          if (k == 'landing') {
            boqDistRebarLanding = v;
          } else {
            boqDistRebarSloping = v;
          }
          return;
      }
    }

    await Get.dialog<void>(
      StatefulBuilder(
        builder: (dialogCtx, setState) {
          final lenM = parseD(lengthCtrl, baseLengthM).clamp(0.0, 1e9);
          final wM = parseD(rampWidthCtrl, 3.0).clamp(0.0, 1e9);
          final tM = parseD(thicknessCtrl, 0.15).clamp(0.0, 1e9);

          final qtyEach = parseI(qtyCtrl, 1).clamp(1, 999999);
          final factor = parseI(factorCtrl, 1).clamp(1, 999999);
          final qtyTotal = qtyEach * factor;

          final areaOne = lenM * wM;
          final concM3Total = areaOne * tM * qtyTotal;
          final soffitM2Total = areaOne * qtyTotal;

          // Edge: use exposed edge length
          double exposedLen = parseD(exposedEdgeLenCtrl, 0.0).clamp(0.0, 1e9);

          // default suggestion (auto): 2 long sides = 2*len
          if (autoExposedEdge && (exposedLen <= 0)) {
            exposedLen = 2 * lenM;
          }
          final edgeM2Total = exposedLen * tM * qtyTotal;

          // finishes on soffit area
          final plasterM2Total = soffitM2Total;
          final paintM2Total = soffitM2Total;

          final int mainDia = int.tryParse(mainDiaCtrl.text.trim()) ?? 12;
          final double mainSpacingMm =
              double.tryParse(mainSpacingCtrl.text.trim()) ?? 150.0;

          final int distDia = int.tryParse(distDiaCtrl.text.trim()) ?? 10;
          final double distSpacingMm =
              double.tryParse(distSpacingCtrl.text.trim()) ?? 200.0;

          final double embed = parseD(embedCtrl, 0.30).clamp(0.0, 1e9);
          final double extra = parseD(extraCtrl, 0.0).clamp(0.0, 1e9);

          // Main bars: along length, spaced across width
          int mainBarsOne = 0;
          double mainBarLenOne = 0;
          double mainKgTotal = 0;
          if (includeRebarMain && wM > 0 && lenM > 0 && mainSpacingMm > 0) {
            final acrossMm = wM * 1000.0;
            mainBarsOne = (acrossMm / mainSpacingMm).floor() + 1;
            mainBarLenOne = lenM + 2 * embed + extra;
            final totalLen = mainBarsOne * mainBarLenOne * qtyTotal;
            mainKgTotal = totalLen * uw(mainDia);
          }

          // Dist bars: across width, spaced along length
          int distBarsOne = 0;
          double distBarLenOne = 0;
          double distKgTotal = 0;
          if (includeRebarDist && wM > 0 && lenM > 0 && distSpacingMm > 0) {
            final alongMm = lenM * 1000.0;
            distBarsOne = (alongMm / distSpacingMm).floor() + 1;
            distBarLenOne = wM + 2 * embed + extra;
            final totalLen = distBarsOne * distBarLenOne * qtyTotal;
            distKgTotal = totalLen * uw(distDia);
          }

          Future<void> doSave(RampSaveAction after) async {
            if (saving) return;

            // ----- validation -----
            if (lenM <= 0) {
              Get.snackbar('Invalid', 'Length must be > 0');
              return;
            }
            if (wM <= 0) {
              Get.snackbar('Invalid', 'Width must be > 0');
              return;
            }

            final wantsAnything =
                includeConcrete ||
                includeSoffitFormwork ||
                includeEdgeFormwork ||
                includeSoffitPlaster ||
                includeSoffitPaint ||
                includeRebarMain ||
                includeRebarDist;

            if (!wantsAnything) {
              Get.snackbar(
                'Nothing selected',
                'Select at least one item to save.',
              );
              return;
            }

            if (includeConcrete && tM <= 0) {
              Get.snackbar('Invalid', 'Thickness must be > 0 (for concrete).');
              return;
            }

            // Pick current part BOQs
            final boqConcrete = _boqFor('concrete', part);
            final boqSoffit = _boqFor('soffit', part);
            final boqEdge = _boqFor('edge', part);
            final boqPlaster = _boqFor('plaster', part);
            final boqPaint = _boqFor('paint', part);
            final boqMainRebar = _boqFor('mainRebar', part);
            final boqDistRebar = _boqFor('distRebar', part);

            if (includeConcrete && boqConcrete == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick CONCRETE BOQ for ${_partKey(part)}.',
              );
              return;
            }
            if (includeSoffitFormwork && boqSoffit == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick SOFFIT BOQ for ${_partKey(part)}.',
              );
              return;
            }
            if (includeEdgeFormwork && boqEdge == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick EDGE BOQ for ${_partKey(part)}.',
              );
              return;
            }
            if (includeSoffitPlaster && boqPlaster == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick PLASTER BOQ for ${_partKey(part)}.',
              );
              return;
            }
            if (includeSoffitPaint && boqPaint == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick PAINT BOQ for ${_partKey(part)}.',
              );
              return;
            }

            if (includeRebarMain && boqMainRebar == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick MAIN REBAR BOQ for ${_partKey(part)}.',
              );
              return;
            }
            if (includeRebarDist && boqDistRebar == null) {
              Get.snackbar(
                'Missing BOQ',
                'Pick DIST REBAR BOQ for ${_partKey(part)}.',
              );
              return;
            }

            setState(() => saving = true);

            final now = FieldValue.serverTimestamp();
            final segmentId = measurementsRef.doc().id;
            final partStr = _partKey(part);

            Map<String, dynamic> common() => {
              'projectId': projectId,
              'buildingId': buildingId,
              'drawingId': drawingId,

              'measureType': 'compositeRamp',
              'rampGroupId': rampGroupId,
              'segmentId': segmentId,
              'rampPart': partStr, // ✅ landing / sloping

              'color': currentColor.value,
              'createdAt': now,
              'updatedAt': now,

              'qtyEach': qtyEach,
              'buildingFactor': factor,
              'qtyTotal': qtyTotal,

              'baseLengthM': baseLengthM,
              'lengthM': lenM,
              'widthM': wM,
              'thicknessM': tM,

              'exposedEdgeLenM': exposedLen,

              'p1': {'x': p1.dx, 'y': p1.dy},
              'p2': {'x': p2.dx, 'y': p2.dy},

              'label': (activeLabel ?? 'Ramp').trim(),
            };

            Map<String, dynamic> baseLine({
              required String type,
              required String unit,
              required double value,
              required BoqPick boq,
            }) => {
              ...common(),
              'type': type,
              'unit': unit,
              'value': value,
              'boqItemId': boq.id,
              'boqCode': boq.code,
              'boqDescription': boq.description,
            };

            try {
              final batch = FirebaseFirestore.instance.batch();

              if (includeConcrete) {
                batch.set(
                  measurementsRef.doc('$segmentId-conc'),
                  baseLine(
                    type: 'ramp_${partStr}_concrete',
                    unit: 'm3',
                    value: concM3Total,
                    boq: boqConcrete!,
                  ),
                );
              }

              if (includeSoffitFormwork) {
                batch.set(
                  measurementsRef.doc('$segmentId-sof'),
                  baseLine(
                    type: 'ramp_${partStr}_soffit',
                    unit: 'm2',
                    value: soffitM2Total,
                    boq: boqSoffit!,
                  ),
                );
              }

              if (includeEdgeFormwork) {
                batch.set(
                  measurementsRef.doc('$segmentId-edge'),
                  baseLine(
                    type: 'ramp_${partStr}_edge',
                    unit: 'm2',
                    value: edgeM2Total,
                    boq: boqEdge!,
                  ),
                );
              }

              if (includeSoffitPlaster) {
                batch.set(
                  measurementsRef.doc('$segmentId-plast'),
                  baseLine(
                    type: 'ramp_${partStr}_soffit_plaster',
                    unit: 'm2',
                    value: plasterM2Total,
                    boq: boqPlaster!,
                  ),
                );
              }

              if (includeSoffitPaint) {
                batch.set(
                  measurementsRef.doc('$segmentId-paint'),
                  baseLine(
                    type: 'ramp_${partStr}_soffit_paint',
                    unit: 'm2',
                    value: paintM2Total,
                    boq: boqPaint!,
                  ),
                );
              }

              if (includeRebarMain) {
                batch.set(measurementsRef.doc('$segmentId-rm'), {
                  ...baseLine(
                    type: 'ramp_${partStr}_rebar_main',
                    unit: 'kg',
                    value: mainKgTotal,
                    boq: boqMainRebar!,
                  ),
                  'position': mainPos,
                  'diameterMm': mainDia,
                  'spacingMm': mainSpacingMm,
                  'barsPerRamp': mainBarsOne,
                  'barLenOneM': mainBarLenOne,
                  'embedEachEndM': embed,
                  'extraLenM': extra,
                  'unitWeightKgPerM': uw(mainDia),
                });
              }

              if (includeRebarDist) {
                batch.set(measurementsRef.doc('$segmentId-rd'), {
                  ...baseLine(
                    type: 'ramp_${partStr}_rebar_dist',
                    unit: 'kg',
                    value: distKgTotal,
                    boq: boqDistRebar!,
                  ),
                  'position': distPos,
                  'diameterMm': distDia,
                  'spacingMm': distSpacingMm,
                  'barsPerRamp': distBarsOne,
                  'barLenOneM': distBarLenOne,
                  'embedEachEndM': embed,
                  'extraLenM': extra,
                  'unitWeightKgPerM': uw(distDia),
                });
              }

              await batch.commit(); // ✅ REAL SAVE

              // ---- remember defaults ----
              lastRampDefaults
                ..['lastPart'] = partStr
                ..['rampWidthM'] = wM
                ..['thicknessM'] = tM
                ..['qty'] = qtyEach
                ..['buildingFactor'] = factor
                ..['includeConcrete'] = includeConcrete
                ..['includeSoffitFormwork'] = includeSoffitFormwork
                ..['includeEdgeFormwork'] = includeEdgeFormwork
                ..['includeSoffitPlaster'] = includeSoffitPlaster
                ..['includeSoffitPaint'] = includeSoffitPaint
                ..['exposedEdgeLenM'] = exposedLen
                ..['autoExposedEdge'] = autoExposedEdge
                ..['includeRebarMain'] = includeRebarMain
                ..['includeRebarDist'] = includeRebarDist
                ..['mainDiaMm'] = mainDia
                ..['mainSpacingMm'] = mainSpacingMm
                ..['mainPos'] = mainPos
                ..['distDiaMm'] = distDia
                ..['distSpacingMm'] = distSpacingMm
                ..['distPos'] = distPos
                ..['embedEachEndM'] = embed
                ..['extraLenM'] = extra
                // store BOQs per part
                ..['boqConcrete_landing'] = pickToMap(boqConcreteLanding)
                ..['boqSoffit_landing'] = pickToMap(boqSoffitLanding)
                ..['boqEdge_landing'] = pickToMap(boqEdgeLanding)
                ..['boqPlaster_landing'] = pickToMap(boqPlasterLanding)
                ..['boqPaint_landing'] = pickToMap(boqPaintLanding)
                ..['boqMainRebar_landing'] = pickToMap(boqMainRebarLanding)
                ..['boqDistRebar_landing'] = pickToMap(boqDistRebarLanding)
                ..['boqConcrete_sloping'] = pickToMap(boqConcreteSloping)
                ..['boqSoffit_sloping'] = pickToMap(boqSoffitSloping)
                ..['boqEdge_sloping'] = pickToMap(boqEdgeSloping)
                ..['boqPlaster_sloping'] = pickToMap(boqPlasterSloping)
                ..['boqPaint_sloping'] = pickToMap(boqPaintSloping)
                ..['boqMainRebar_sloping'] = pickToMap(boqMainRebarSloping)
                ..['boqDistRebar_sloping'] = pickToMap(boqDistRebarSloping);

              // if (after == RampSaveAction.finish) {
              //   setDraftRampGroupId(null);
              // } else {
              //   setDraftRampGroupId(rampGroupId); // keep group
              // }

              saveSucceeded = true;
              result = RampSaveAction.finish;
              if (dialogCtx.mounted) Navigator.of(dialogCtx).pop(result);
            } catch (e) {
              Get.snackbar(
                'Save failed',
                '$e',
                snackPosition: SnackPosition.BOTTOM,
              );
            } finally {
              if (!saveSucceeded && dialogCtx.mounted) {
                setState(() => saving = false);
              }
            }
          }

          // current part BOQ picks
          final boqConcreteCur = _boqFor('concrete', part);
          final boqSoffitCur = _boqFor('soffit', part);
          final boqEdgeCur = _boqFor('edge', part);
          final boqPlasterCur = _boqFor('plaster', part);
          final boqPaintCur = _boqFor('paint', part);
          final boqMainRebarCur = _boqFor('mainRebar', part);
          final boqDistRebarCur = _boqFor('distRebar', part);

          Widget rampMetric(String label, String value, IconData icon) {
            return Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
                color: const Color(0xFFF8FAFC),
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: const Color(0xFFE2E8F0)),
              ),
              child: Row(
                children: [
                  Container(
                    width: 34,
                    height: 34,
                    decoration: BoxDecoration(
                      color: const Color(0xFFEFF6FF),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: Icon(icon, color: const Color(0xFF155EEF), size: 18),
                  ),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          value,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w900,
                            color: Color(0xFF0F172A),
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          label,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF64748B),
                          ),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            );
          }

          Widget rampPanel({
            required String title,
            required String subtitle,
            required IconData icon,
            required Widget child,
          }) {
            return Container(
              width: double.infinity,
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(24),
                border: Border.all(color: const Color(0xFFE2E8F0)),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x0A0F172A),
                    blurRadius: 22,
                    offset: Offset(0, 10),
                  ),
                ],
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      Container(
                        width: 42,
                        height: 42,
                        decoration: BoxDecoration(
                          gradient: const LinearGradient(
                            colors: [Color(0xFF155EEF), Color(0xFF3B82F6)],
                          ),
                          borderRadius: BorderRadius.circular(15),
                        ),
                        child: Icon(icon, color: Colors.white, size: 22),
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.w900,
                                color: Color(0xFF0F172A),
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              subtitle,
                              style: const TextStyle(
                                fontSize: 12,
                                fontWeight: FontWeight.w600,
                                color: Color(0xFF64748B),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 16),
                  child,
                ],
              ),
            );
          }

          return Stack(
            children: [
              AlertDialog(
                titlePadding: EdgeInsets.zero,
                contentPadding: EdgeInsets.zero,
                actionsPadding: const EdgeInsets.fromLTRB(24, 0, 24, 24),
                clipBehavior: Clip.antiAlias,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(28),
                ),
                title: Container(
                  padding: const EdgeInsets.fromLTRB(28, 26, 28, 24),
                  decoration: const BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                      colors: [Color(0xFF102A56), Color(0xFF155EEF)],
                    ),
                  ),
                  child: Row(
                    children: [
                      Container(
                        width: 54,
                        height: 54,
                        decoration: BoxDecoration(
                          color: Colors.white.withOpacity(0.14),
                          borderRadius: BorderRadius.circular(18),
                          border: Border.all(color: Colors.white24),
                        ),
                        child: const Icon(
                          Icons.trending_up_rounded,
                          color: Colors.white,
                          size: 28,
                        ),
                      ),
                      const SizedBox(width: 16),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              '${(activeLabel ?? 'Ramp').trim()} composite',
                              style: const TextStyle(
                                color: Colors.white,
                                fontWeight: FontWeight.w900,
                                fontSize: 28,
                              ),
                            ),
                            const SizedBox(height: 6),
                            Text(
                              '${_partKey(part).toUpperCase()} • concrete, formwork, finishes and rebars',
                              style: TextStyle(
                                color: Colors.white.withOpacity(0.78),
                                fontSize: 13,
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                content: SizedBox(
                  width: 920,
                  child: SingleChildScrollView(
                    child: Container(
                      color: const Color(0xFFF8FAFC),
                      padding: const EdgeInsets.all(24),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          rampPanel(
                            title: 'Ramp geometry',
                            subtitle:
                                'Confirm part, measured length, width, thickness and repetition',
                            icon: Icons.straighten_rounded,
                            child: Column(
                              children: [
                                Row(
                                  children: [
                                    Expanded(
                                      child: rampMetric(
                                        'Measured length',
                                        '${baseLengthM.toStringAsFixed(3)} m',
                                        Icons.trending_up_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rampMetric(
                                        'Measured area',
                                        '${areaOne.toStringAsFixed(3)} m²',
                                        Icons.square_foot_rounded,
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: rampMetric(
                                        'Total ramps',
                                        '$qtyTotal',
                                        Icons.functions_rounded,
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 16),
                                Row(
                                  children: [
                                    const Text(
                                      'Part:',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w900,
                                        color: Color(0xFF0F172A),
                                      ),
                                    ),
                                    const SizedBox(width: 10),
                                    ChoiceChip(
                                      label: const Text('Landing'),
                                      selected: part == RampPart.landing,
                                      onSelected:
                                          saving
                                              ? null
                                              : (_) => setState(
                                                () => part = RampPart.landing,
                                              ),
                                    ),
                                    const SizedBox(width: 8),
                                    ChoiceChip(
                                      label: const Text('Sloping'),
                                      selected: part == RampPart.sloping,
                                      onSelected:
                                          saving
                                              ? null
                                              : (_) => setState(
                                                () => part = RampPart.sloping,
                                              ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 16),
                                Row(
                                  children: [
                                    Expanded(
                                      child: TextField(
                                        controller: lengthCtrl,
                                        enabled: !saving,
                                        keyboardType:
                                            const TextInputType.numberWithOptions(
                                              decimal: true,
                                            ),
                                        decoration: deco(
                                          'Length (m) (not remembered)',
                                        ),
                                        onChanged: (_) => setState(() {}),
                                      ),
                                    ),
                                    const SizedBox(width: 12),
                                    Expanded(
                                      child: TextField(
                                        controller: rampWidthCtrl,
                                        enabled: !saving,
                                        keyboardType:
                                            const TextInputType.numberWithOptions(
                                              decimal: true,
                                            ),
                                        decoration: deco('Ramp width (m)'),
                                        onChanged: (_) => setState(() {}),
                                      ),
