  Future<bool> openTrussTemplateFromLinework({
    // measured on drawing (image coordinates)
    required List<Offset> topChordPolyline,
    required List<Offset> bottomChordPolyline,
    required List<List<Offset>> strutsPolylines,

    required Map<String, dynamic> drawingData,

    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,

    /// Where you store measurements (can be a templates collection too).
    required CollectionReference<Map<String, dynamic>> measurementsRef,

    /// Your BOQ picker dialog
    required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    /// Persisted defaults cache (keep it wherever you keep lastRoofDefaults)
    required Map<String, dynamic> lastTrussDefaults,

    VoidCallback? onUpdateViewer,
  }) async {
    // ---------- helpers ----------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    int _int(dynamic v, int fb) {
      if (v is int) return v;
      if (v is num) return v.toInt();
      return int.tryParse('${v ?? ''}') ?? fb;
    }

    TextEditingController _ctrl(String key, String fallback) {
      final v = lastTrussDefaults[key] ?? fallback;
      return TextEditingController(text: '$v');
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    InputDecoration decoDense(String label) => const InputDecoration(
      border: OutlineInputBorder(),
      isDense: true,
    ).copyWith(labelText: label);

    double _distPx(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      return math.sqrt(dx * dx + dy * dy);
    }

    double _polylineLenM(List<Offset> pts, double pxPerM) {
      if (pts.length < 2) return 0.0;
      double sumPx = 0.0;
      for (int i = 0; i < pts.length - 1; i++) {
        sumPx += _distPx(pts[i], pts[i + 1]);
      }
      return sumPx / pxPerM;
    }

    List<Map<String, double>> _ptsToMaps(List<Offset> pts) =>
        pts.map((p) => {'x': p.dx, 'y': p.dy}).toList();

    // steel helpers
    const steelDensity = 7850.0; // kg/m3

    double kgPerM_CHS({required double odMm, required double tMm}) {
      final Do = odMm / 1000.0;
      final t = tMm / 1000.0;
      final Di = (Do - 2.0 * t);
      if (Do <= 0 || t <= 0 || Di <= 0) return 0.0;
      final area = (math.pi / 4.0) * (Do * Do - Di * Di);
      return area * steelDensity;
    }

    double d(TextEditingController c, double fb) =>
        double.tryParse(c.text.trim()) ?? fb;

    int ii(TextEditingController c, int fb) =>
        int.tryParse(c.text.trim()) ?? fb;

    // ---------- validation: calibration + measured lines ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0);

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Calibrate drawing first (pixelsPerUnit).',
      );
      return false;
    }

    if (topChordPolyline.length < 2) {
      Get.snackbar(
        'Missing line',
        'Top chord polyline must have at least 2 points.',
      );
      return false;
    }
    if (bottomChordPolyline.length < 2) {
      Get.snackbar(
        'Missing line',
        'Bottom chord polyline must have at least 2 points.',
      );
      return false;
    }

    // ---------- geometry from measured linework (ONE truss) ----------
    final topLenOneM = _polylineLenM(topChordPolyline, pxPerM);
    final bottomLenOneM = _polylineLenM(bottomChordPolyline, pxPerM);
    double strutsLenOneM = 0.0;
    for (final pl in strutsPolylines) {
      if (pl.length >= 2) strutsLenOneM += _polylineLenM(pl, pxPerM);
    }

    // ---------- controllers (remembered) ----------
    final templateCodeCtrl = _ctrl('templateCode', 'T1');
    final templateNameCtrl = _ctrl('templateName', 'Truss Type T1 (21–24m)');

    final multiplyingFactorCtrl = _ctrl(
      'multiplyingFactor',
      '1',
    ); // identical trusses/sets
    final trussCountCtrl = _ctrl(
      'trussCount',
      // if they often use 16, remember it
      (_int(lastTrussDefaults['trussCount'], 16)).toString(),
    );

    // top chord section
    bool includeTop = (lastTrussDefaults['includeTop'] ?? true) == true;
    bool topUseAutoKg = (lastTrussDefaults['topUseAutoKg'] ?? true) == true;
    final topOdCtrl = _ctrl('topOdMm', '42.4');
    final topThkCtrl = _ctrl('topThkMm', '3');
    final topKgPerMCtrl = _ctrl('topKgPerM', '2.915');

    // bottom chord section
    bool includeBottom = (lastTrussDefaults['includeBottom'] ?? true) == true;
    bool bottomUseAutoKg =
        (lastTrussDefaults['bottomUseAutoKg'] ?? true) == true;
    final bottomOdCtrl = _ctrl('bottomOdMm', '42.4');
    final bottomThkCtrl = _ctrl('bottomThkMm', '3');
    final bottomKgPerMCtrl = _ctrl('bottomKgPerM', '2.915');

    // struts/webs section
    bool includeStruts = (lastTrussDefaults['includeStruts'] ?? true) == true;
    bool strutsUseAutoKg =
        (lastTrussDefaults['strutsUseAutoKg'] ?? true) == true;
    final strutsOdCtrl = _ctrl('strutsOdMm', '42.4');
    final strutsThkCtrl = _ctrl('strutsThkMm', '3');
    final strutsKgPerMCtrl = _ctrl('strutsKgPerM', '2.915');

    // BOQ pick (for the whole truss line in kg)
    BoqPick? boqTrussKg = pickFromMap(lastTrussDefaults['boqTrussKg']);

    // extra description/spec (optional)
    final specCtrl = _ctrl(
      'steelSpec',
      (lastTrussDefaults['steelSpec'] ??
              'STRUCTURAL STEEL WORK; WELDABLE; GRADE 43; framed; bolted and welded site connections; '
                  'including two coats red oxide followed by two coats enamel paint after erection. '
                  'Roof trusses; CHS top, bottom chords and struts; type T1.')
          .toString(),
    );

    // ---------- dialog ----------
    final ctx = Get.context;
    if (ctx == null) return false;

    bool savedOk = false;

    void _disposeAll() {
      for (final c in [
        templateCodeCtrl,
        templateNameCtrl,
        multiplyingFactorCtrl,
        trussCountCtrl,
        topOdCtrl,
        topThkCtrl,
        topKgPerMCtrl,
        bottomOdCtrl,
        bottomThkCtrl,
        bottomKgPerMCtrl,
        strutsOdCtrl,
        strutsThkCtrl,
        strutsKgPerMCtrl,
        specCtrl,
      ]) {
        c.dispose();
      }
    }

    Widget boqLine({
      required BuildContext ctx,
      required String title,
      required BoqPick? pick,
      required VoidCallback onPick,
      required VoidCallback onClear,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              const SizedBox(width: 8),
              OutlinedButton(onPressed: onClear, child: const Text('Clear')),
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    await Get.dialog<void>(
      StatefulBuilder(
        builder: (dctx, setState) {
          final multiply = d(multiplyingFactorCtrl, 1).clamp(0.01, 999999.0);
          final trussCount = ii(trussCountCtrl, 16).clamp(1, 999999);

          // auto kg/m
          final topKgAuto = kgPerM_CHS(
            odMm: d(topOdCtrl, 42.4),
            tMm: d(topThkCtrl, 3),
          );
          final bottomKgAuto = kgPerM_CHS(
            odMm: d(bottomOdCtrl, 42.4),
            tMm: d(bottomThkCtrl, 3),
          );
          final strutsKgAuto = kgPerM_CHS(
            odMm: d(strutsOdCtrl, 42.4),
            tMm: d(strutsThkCtrl, 3),
          );

          final topKgPerM = (topUseAutoKg ? topKgAuto : d(topKgPerMCtrl, 2.915))
              .clamp(0.0, 99999.0);
          final bottomKgPerM = (bottomUseAutoKg
                  ? bottomKgAuto
                  : d(bottomKgPerMCtrl, 2.915))
              .clamp(0.0, 99999.0);
          final strutsKgPerM = (strutsUseAutoKg
                  ? strutsKgAuto
                  : d(strutsKgPerMCtrl, 2.915))
              .clamp(0.0, 99999.0);

          final topKgOne = includeTop ? (topLenOneM * topKgPerM) : 0.0;
          final bottomKgOne =
              includeBottom ? (bottomLenOneM * bottomKgPerM) : 0.0;
          final strutsKgOne =
              includeStruts ? (strutsLenOneM * strutsKgPerM) : 0.0;

          final oneTrussKg = topKgOne + bottomKgOne + strutsKgOne;

          // total kg for a set (No trusses × multiplier)
          final totalKg =
              oneTrussKg * trussCount.toDouble() * multiply; // scaled total

          return AlertDialog(
            title: const Text('Truss template (measure from linework)'),
            content: SizedBox(
              width: 820,
              child: SingleChildScrollView(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Measured (one truss): Top=${topLenOneM.toStringAsFixed(3)} m • '
                      'Bottom=${bottomLenOneM.toStringAsFixed(3)} m • '
                      'Struts=${strutsLenOneM.toStringAsFixed(3)} m',
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 12),

                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: templateCodeCtrl,
                            decoration: decoDense('Template code (e.g. T1)'),
                            onChanged: (_) => setState(() {}),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: TextField(
                            controller: templateNameCtrl,
                            decoration: decoDense('Template name'),
                            onChanged: (_) => setState(() {}),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),

                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: trussCountCtrl,
                            decoration: decoDense('No. of trusses (e.g. 16)'),
                            keyboardType: TextInputType.number,
                            onChanged: (_) => setState(() {}),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: TextField(
                            controller: multiplyingFactorCtrl,
                            decoration: decoDense(
                              'Multiplying factor (identical sets)',
                            ),
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            onChanged: (_) => setState(() {}),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),

                    InputDecorator(
                      decoration: decoDense('Computed totals'),
                      child: Text(
                        'One truss ≈ ${oneTrussKg.toStringAsFixed(3)} kg\n'
                        'Total = OneTruss × NoTrusses($trussCount) × Factor(${multiply.toStringAsFixed(2)})\n'
                        '→ ${totalKg.toStringAsFixed(3)} kg',
                        style: const TextStyle(fontSize: 12),
                      ),
                    ),

                    const Divider(height: 24),

                    TextField(
                      controller: specCtrl,
                      decoration: decoDense('Steelwork specification / notes'),
                      maxLines: 3,
                      onChanged: (_) => setState(() {}),
                    ),
                    const SizedBox(height: 12),

                    // ---- Top chord ----
                    SwitchListTile(
                      value: includeTop,
                      onChanged: (v) => setState(() => includeTop = v),
                      contentPadding: EdgeInsets.zero,
                      title: const Text('Include Top chord (CHS)'),
                      subtitle: Text(
                        'One truss length: ${topLenOneM.toStringAsFixed(3)} m • '
                        'kg/m=${topKgPerM.toStringAsFixed(3)} • '
                        'kg=${topKgOne.toStringAsFixed(3)}',
                        style: const TextStyle(fontSize: 12),
                      ),
                    ),
                    if (includeTop) ...[
                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: topOdCtrl,
                              decoration: decoDense('Top OD (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: TextField(
                              controller: topThkCtrl,
                              decoration: decoDense('Top Thk (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: InputDecorator(
                              decoration: decoDense('Auto kg/m'),
                              child: Text(topKgAuto.toStringAsFixed(3)),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      SwitchListTile(
                        value: topUseAutoKg,
                        onChanged: (v) => setState(() => topUseAutoKg = v),
                        contentPadding: EdgeInsets.zero,
                        title: const Text('Use auto kg/m (Top)'),
                      ),
                      if (!topUseAutoKg) ...[
                        TextField(
                          controller: topKgPerMCtrl,
                          decoration: decoDense('Top manual kg/m'),
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          onChanged: (_) => setState(() {}),
                        ),
                      ],
                      const Divider(height: 18),
                    ],

                    // ---- Bottom chord ----
                    SwitchListTile(
                      value: includeBottom,
                      onChanged: (v) => setState(() => includeBottom = v),
                      contentPadding: EdgeInsets.zero,
                      title: const Text('Include Bottom chord (CHS)'),
                      subtitle: Text(
                        'One truss length: ${bottomLenOneM.toStringAsFixed(3)} m • '
                        'kg/m=${bottomKgPerM.toStringAsFixed(3)} • '
                        'kg=${bottomKgOne.toStringAsFixed(3)}',
                        style: const TextStyle(fontSize: 12),
                      ),
                    ),
                    if (includeBottom) ...[
                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: bottomOdCtrl,
                              decoration: decoDense('Bottom OD (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: TextField(
                              controller: bottomThkCtrl,
                              decoration: decoDense('Bottom Thk (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: InputDecorator(
                              decoration: decoDense('Auto kg/m'),
                              child: Text(bottomKgAuto.toStringAsFixed(3)),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      SwitchListTile(
                        value: bottomUseAutoKg,
                        onChanged: (v) => setState(() => bottomUseAutoKg = v),
                        contentPadding: EdgeInsets.zero,
                        title: const Text('Use auto kg/m (Bottom)'),
                      ),
                      if (!bottomUseAutoKg) ...[
                        TextField(
                          controller: bottomKgPerMCtrl,
                          decoration: decoDense('Bottom manual kg/m'),
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          onChanged: (_) => setState(() {}),
                        ),
                      ],
                      const Divider(height: 18),
                    ],

                    // ---- Struts/webs ----
                    SwitchListTile(
                      value: includeStruts,
                      onChanged: (v) => setState(() => includeStruts = v),
                      contentPadding: EdgeInsets.zero,
                      title: const Text('Include Struts/Webs (CHS)'),
                      subtitle: Text(
                        'One truss length: ${strutsLenOneM.toStringAsFixed(3)} m • '
                        'kg/m=${strutsKgPerM.toStringAsFixed(3)} • '
                        'kg=${strutsKgOne.toStringAsFixed(3)}',
                        style: const TextStyle(fontSize: 12),
                      ),
                    ),
                    if (includeStruts) ...[
                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: strutsOdCtrl,
                              decoration: decoDense('Struts OD (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: TextField(
                              controller: strutsThkCtrl,
                              decoration: decoDense('Struts Thk (mm)'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: InputDecorator(
                              decoration: decoDense('Auto kg/m'),
                              child: Text(strutsKgAuto.toStringAsFixed(3)),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 6),
                      SwitchListTile(
                        value: strutsUseAutoKg,
                        onChanged: (v) => setState(() => strutsUseAutoKg = v),
                        contentPadding: EdgeInsets.zero,
                        title: const Text('Use auto kg/m (Struts)'),
                      ),
                      if (!strutsUseAutoKg) ...[
                        TextField(
                          controller: strutsKgPerMCtrl,
                          decoration: decoDense('Struts manual kg/m'),
                          keyboardType: const TextInputType.numberWithOptions(
                            decimal: true,
                          ),
                          onChanged: (_) => setState(() {}),
                        ),
                      ],
                      const Divider(height: 18),
                    ],

                    // ---- BOQ ----
                    boqLine(
                      ctx: dctx,
                      title: 'BOQ for Truss steelwork (kg)',
                      pick: boqTrussKg,
                      onPick: () async {
                        final pick = await showBoqPickerDialog(dctx);
                        if (pick != null) setState(() => boqTrussKg = pick);
                      },
                      onClear: () => setState(() => boqTrussKg = null),
                    ),
                    const SizedBox(height: 10),
                    Text(
                      'Tip: This template saves “kg per truss” from measured linework.\n'
                      'Later, your roof polygon tool multiplies by truss count (from spacing or override).',
                      style: const TextStyle(fontSize: 12),
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(dctx),
                child: const Text('Cancel'),
              ),
              FilledButton(
                onPressed: () async {
                  // validate BOQ
                  if (boqTrussKg == null) {
                    Get.snackbar(
                      'Missing',
                      'Pick BOQ item for Truss steelwork (kg).',
                    );
                    return;
                  }

                  final templateCode = templateCodeCtrl.text.trim();
                  final templateName = templateNameCtrl.text.trim();

                  if (templateCode.isEmpty) {
                    Get.snackbar(
                      'Missing',
                      'Template code is required (e.g. T1).',
                    );
                    return;
                  }

                  final multiply = d(
                    multiplyingFactorCtrl,
                    1,
                  ).clamp(0.01, 999999.0);
                  final trussCount = ii(trussCountCtrl, 16).clamp(1, 999999);

                  final topKgAuto = kgPerM_CHS(
                    odMm: d(topOdCtrl, 42.4),
                    tMm: d(topThkCtrl, 3),
                  );
                  final bottomKgAuto = kgPerM_CHS(
                    odMm: d(bottomOdCtrl, 42.4),
                    tMm: d(bottomThkCtrl, 3),
                  );
                  final strutsKgAuto = kgPerM_CHS(
                    odMm: d(strutsOdCtrl, 42.4),
                    tMm: d(strutsThkCtrl, 3),
                  );

                  final topKgPerM = (topUseAutoKg
                          ? topKgAuto
                          : d(topKgPerMCtrl, 2.915))
                      .clamp(0.0, 99999.0);
                  final bottomKgPerM = (bottomUseAutoKg
                          ? bottomKgAuto
                          : d(bottomKgPerMCtrl, 2.915))
                      .clamp(0.0, 99999.0);
                  final strutsKgPerM = (strutsUseAutoKg
                          ? strutsKgAuto
                          : d(strutsKgPerMCtrl, 2.915))
                      .clamp(0.0, 99999.0);

                  final topKgOne = includeTop ? (topLenOneM * topKgPerM) : 0.0;
                  final bottomKgOne =
                      includeBottom ? (bottomLenOneM * bottomKgPerM) : 0.0;
                  final strutsKgOne =
                      includeStruts ? (strutsLenOneM * strutsKgPerM) : 0.0;

                  final oneTrussKg = topKgOne + bottomKgOne + strutsKgOne;
                  final totalKg = oneTrussKg * trussCount.toDouble() * multiply;

                  // save
                  final now = FieldValue.serverTimestamp();
                  final templateId = measurementsRef.doc().id;
                  final docId = '$templateId-trussTemplate';

                  try {
                    final batch = FirebaseFirestore.instance.batch();

                    batch.set(measurementsRef.doc(docId), {
                      'projectId': projectId,
                      'buildingId': buildingId,
                      'drawingId': drawingId,

                      'measureType': 'trussTemplate',
                      'type': 'trussTemplate',
                      'templateId': templateId,
                      'templateCode': templateCode,
                      'templateName': templateName,
                      'spec': specCtrl.text.trim(),

                      // scaling
                      'trussCountBase': trussCount,
                      'multiplyingFactor': multiply,

                      // measured linework (ONE truss)
                      'topLenM_one': topLenOneM,
                      'bottomLenM_one': bottomLenOneM,
                      'strutsLenM_one': strutsLenOneM,

                      'topPolyline': _ptsToMaps(topChordPolyline),
                      'bottomPolyline': _ptsToMaps(bottomChordPolyline),
                      'strutsPolylines':
                          strutsPolylines
                              .where((p) => p.length >= 2)
                              .map((p) => _ptsToMaps(p))
                              .toList(),

                      // section + kg/m
                      'includeTop': includeTop,
                      'includeBottom': includeBottom,
                      'includeStruts': includeStruts,

                      'top': {
                        'shape': 'CHS',
                        'odMm': d(topOdCtrl, 42.4),
                        'thkMm': d(topThkCtrl, 3),
                        'useAutoKgPerM': topUseAutoKg,
                        'kgPerM': topKgPerM,
                        'kg_one': topKgOne,
                      },
                      'bottom': {
                        'shape': 'CHS',
                        'odMm': d(bottomOdCtrl, 42.4),
                        'thkMm': d(bottomThkCtrl, 3),
                        'useAutoKgPerM': bottomUseAutoKg,
                        'kgPerM': bottomKgPerM,
                        'kg_one': bottomKgOne,
                      },
                      'struts': {
                        'shape': 'CHS',
                        'odMm': d(strutsOdCtrl, 42.4),
                        'thkMm': d(strutsThkCtrl, 3),
                        'useAutoKgPerM': strutsUseAutoKg,
                        'kgPerM': strutsKgPerM,
                        'kg_one': strutsKgOne,
                      },

                      // totals
                      'steelKg_oneTruss': oneTrussKg,
                      'steelKg_total': totalKg,

                      // BOQ
                      'boqItemId': boqTrussKg!.id,
                      'boqCode': boqTrussKg!.code,
                      'boqDescription': boqTrussKg!.description,
                      'unit': 'kg',

                      'color': currentColor.value,
                      'createdAt': now,
                      'updatedAt': now,
                    });

                    await batch.commit();

                    // remember defaults (BOQ + sizes + counts)
                    lastTrussDefaults
                      ..['templateCode'] = templateCode
                      ..['templateName'] = templateName
                      ..['multiplyingFactor'] = multiply
                      ..['trussCount'] = trussCount
                      ..['steelSpec'] = specCtrl.text.trim()
                      ..['includeTop'] = includeTop
                      ..['includeBottom'] = includeBottom
                      ..['includeStruts'] = includeStruts
                      ..['topUseAutoKg'] = topUseAutoKg
                      ..['bottomUseAutoKg'] = bottomUseAutoKg
                      ..['strutsUseAutoKg'] = strutsUseAutoKg
                      ..['topOdMm'] = d(topOdCtrl, 42.4)
                      ..['topThkMm'] = d(topThkCtrl, 3)
                      ..['topKgPerM'] = topKgPerM
                      ..['bottomOdMm'] = d(bottomOdCtrl, 42.4)
                      ..['bottomThkMm'] = d(bottomThkCtrl, 3)
                      ..['bottomKgPerM'] = bottomKgPerM
                      ..['strutsOdMm'] = d(strutsOdCtrl, 42.4)
                      ..['strutsThkMm'] = d(strutsThkCtrl, 3)
                      ..['strutsKgPerM'] = strutsKgPerM
                      ..['boqTrussKg'] = pickToMap(boqTrussKg);

                    savedOk = true;

                    Get.snackbar(
                      'Saved',
                      'Truss template "$templateCode" saved (${oneTrussKg.toStringAsFixed(3)} kg/truss).',
                      snackPosition: SnackPosition.BOTTOM,
                    );

                    Navigator.pop(dctx);
                    onUpdateViewer?.call();
                  } catch (e) {
                    savedOk = false;
                    Get.snackbar(
                      'Save failed',
                      '$e',
                      snackPosition: SnackPosition.BOTTOM,
                    );
                  }
                },
                child: const Text('Save template'),
              ),
            ],
          );
        },
      ),
      barrierDismissible: false,
    );

    _disposeAll();
    return savedOk;
  }

  //   import 'dart:math';
  // import 'package:flutter/material.dart';
  // import 'package:cloud_firestore/cloud_firestore.dart';

  /// You already have these in your project:
  /// - enum RoofSaveAction { saved, cancelled, failed }
  /// - class BoqPick { String resolvedBoqCode, displayCode, description, unit; ... }

  Future<RoofSaveAction> openRoofingFromPolygon({
    required BuildContext ctx,

    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,

    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,

    // required CollectionReference<Map<String, dynamic>> measurementsRef,
    required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    VoidCallback? onCloseDraft,
    VoidCallback? onUpdateViewer,
  }) async {
    // ---------- UI helpers ----------
    void _toast(String msg) {
      try {
        if (!ctx.mounted) return;
        ScaffoldMessenger.of(ctx).hideCurrentSnackBar();
        ScaffoldMessenger.of(ctx).showSnackBar(
          SnackBar(content: Text(msg), duration: const Duration(seconds: 4)),
        );
      } catch (_) {
        // ignore
      }
    }

    Future<void> _showErrorDialog(String title, String msg) async {
      if (!ctx.mounted) return;
      await showDialog<void>(
        context: ctx,
        builder:
            (_) => AlertDialog(
              title: Text(title),
              content: SingleChildScrollView(child: Text(msg)),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(ctx),
                  child: const Text('OK'),
                ),
              ],
            ),
      );
    }

    // ---------- small helpers ----------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    double _finite(num? v, [double fb = 0]) {
      final x = (v ?? fb).toDouble();
      if (x.isNaN || x.isInfinite) return fb;
      return x;
    }

    dynamic _sanitizeJson(dynamic v) {
      // Ensures Firestore never gets NaN/Infinity + removes bad values.
      if (v == null) return null;

      if (v is num) return _finite(v);
      if (v is bool || v is String) return v;

      if (v is List) {
        return v.map(_sanitizeJson).toList();
      }

      if (v is Map) {
        final out = <String, dynamic>{};
        v.forEach((k, val) {
          final key = k.toString();
          final sv = _sanitizeJson(val);
          // keep even if null? you can skip nulls if you want:
          out[key] = sv;
        });
        return out;
      }

      // Fallback: convert unknown objects to string
      return v.toString();
    }

    // double _distPx(Offset a, Offset b) {
    //   final dx = b.dx - a.dx;
    //   final dy = b.dy - a.dy;
    //   return sqrt(dx * dx + dy * dy);
    // }

    double _polygonAreaPx2(List<Offset> pts) {
      if (pts.length < 3) return 0;
      double s = 0;
      for (int i = 0; i < pts.length; i++) {
        final j = (i + 1) % pts.length;
        s += (pts[i].dx * pts[j].dy) - (pts[j].dx * pts[i].dy);
      }
      return s.abs() / 2.0;
    }

    double _pxPerMeter(Map<String, dynamic> data) {
      final ppm = data['pixelsPerMeter'];
      if (ppm is num && ppm.toDouble() > 0) return ppm.toDouble();

      final ppu = data['pixelsPerUnit'];
      if (ppu is num && ppu.toDouble() > 0) {
        final unit =
            (data['unit'] ?? data['calibrationUnit'] ?? 'm')
                .toString()
                .toLowerCase()
                .trim();

        final u2m =
            (unit == 'm' || unit == 'meter' || unit == 'metre')
                ? 1.0
                : (unit == 'cm')
                ? 0.01
                : (unit == 'mm')
                ? 0.001
                : (unit == 'ft' || unit == 'feet')
                ? 0.3048
                : (unit == 'in' || unit == 'inch' || unit == 'inches')
                ? 0.0254
                : 1.0;

        return ppu.toDouble() / u2m;
      }
      throw Exception(
        'Drawing not calibrated (pixelsPerMeter/pixelsPerUnit missing)',
      );
    }

    double _distM(Offset a, Offset b, Map<String, dynamic> data) {
      final ppm = _pxPerMeter(data);
      return _distPx(a, b) / ppm;
    }

    String _fmt(double v, {int dp = 3}) => v.toStringAsFixed(dp);

    int _intFrom(TextEditingController c, int fb) {
      final v = int.tryParse(c.text.trim());
      return v ?? fb;
    }

    // ---------- edge type model ----------
    // enum RoofEdgeType { eave, hip, valley, ridge }

    String edgeTypeLabel(RoofEdgeType t) {
      switch (t) {
        case RoofEdgeType.eave:
          return 'Eave';
        case RoofEdgeType.hip:
          return 'Hip';
        case RoofEdgeType.valley:
          return 'Valley';
        case RoofEdgeType.ridge:
          return 'Ridge';
      }
    }

    String edgeTypeKey(RoofEdgeType t) => t.name;

    Map<RoofEdgeType, double> _edgeTotalsM(
      List<Map<String, dynamic>> edges,
      List<RoofEdgeType> types,
    ) {
      final out = <RoofEdgeType, double>{
        RoofEdgeType.eave: 0,
        RoofEdgeType.hip: 0,
        RoofEdgeType.valley: 0,
        RoofEdgeType.ridge: 0,
      };
      for (int i = 0; i < edges.length; i++) {
        final lenM = (edges[i]['lenM'] as num).toDouble();
        out[types[i]] = (out[types[i]] ?? 0) + lenM;
      }
      return out;
    }

    // ---------- validate polygon ----------
    if (polygon.length < 3) {
      _toast('Roof polygon needs at least 3 points.');
      return RoofSaveAction.cancelled;
    }

    // ---------- build edges ----------
    final edges = <Map<String, dynamic>>[];
    final edgeTypes = List<RoofEdgeType>.filled(
      polygon.length,
      RoofEdgeType.eave,
    );

    for (int i = 0; i < polygon.length; i++) {
      final p1 = polygon[i];
      final p2 = polygon[(i + 1) % polygon.length];
      final lenM = _distM(p1, p2, drawingData);
      edges.add({
        'i': i,
        'p1': {'dx': p1.dx, 'dy': p1.dy},
        'p2': {'dx': p2.dx, 'dy': p2.dy},
        'lenM': lenM,
        'type': edgeTypeKey(edgeTypes[i]),
      });
    }

    // ---------- compute plan area ----------
    final ppm = _pxPerMeter(drawingData);
    final planAreaM2 = _polygonAreaPx2(polygon) / (ppm * ppm);

    // ---------- defaults ----------
    bool usePitchAngle = true;
    double pitchDeg = 25.0;
    double slopeFactor = 1 / math.cos(pitchDeg * math.pi / 180.0);

    bool includeRoofCovering = true;
    BoqPick? boqRoofCovering;

    bool includeEdgeLengths = true;
    BoqPick? boqEave;
    BoqPick? boqRidge;
    BoqPick? boqHip;
    BoqPick? boqValley;

    // Truss
    bool includeTruss = true;
    bool combineTrussMembers = false;

    final runLengthMDefault = edges
        .map((e) => (e['lenM'] as num).toDouble())
        .fold<double>(0, (a, b) => b > a ? b : a);

    double trussSpacingM = 1.2;
    double trussRunLengthM = runLengthMDefault;

    double bottomChordPerTrussM = 6.0;
    double topChordPerTrussM = 7.0;
    double sagMemberPerTrussM = 2.0;

    double bottomChordKgPerM = 3.0;
    double topChordKgPerM = 3.0;
    double sagMemberKgPerM = 2.0;

    BoqPick? boqTrussCombined;
    BoqPick? boqTrussBottom;
    BoqPick? boqTrussTop;
    BoqPick? boqTrussSag;

    // Purlins & Rails
    bool includePurlins = true;
    bool includeRails = true;

    double purlinSpacingM = 1.0;
    double railSpacingM = 1.2;

    String purlinSizeLabel = "Purlin (custom)";
    String railSizeLabel = "Rail (custom)";

    double purlinKgPerM = 4.0;
    double railKgPerM = 3.5;

    BoqPick? boqPurlins;
    BoqPick? boqRails;

    // Fixings
    bool includeAngleCleats = true;
    bool includeBasePlates = true;
    bool includeBolts = true;

    bool angleCleatsUsePerTruss = true;
    bool basePlatesUsePerTruss = true;
    bool boltsUsePerTruss = true;

    int angleCleatsPerTruss = 4;
    int basePlatesPerTruss = 2;
    int boltsPerTruss = 8;

    int angleCleatsTotalOverride = 0;
    int basePlatesTotalOverride = 0;
    int boltsTotalOverride = 0;

    BoqPick? boqAngleCleats;
    BoqPick? boqBasePlates;
    BoqPick? boqBolts;

    // ---------- controllers ----------
    final pitchDegCtrl = TextEditingController(text: _fmt(pitchDeg, dp: 2));
    final slopeFactorCtrl = TextEditingController(
      text: _fmt(slopeFactor, dp: 4),
    );

    final runLenCtrl = TextEditingController(
      text: _fmt(trussRunLengthM, dp: 3),
    );
    final spacingCtrl = TextEditingController(text: _fmt(trussSpacingM, dp: 3));

    final bLenCtrl = TextEditingController(
      text: _fmt(bottomChordPerTrussM, dp: 3),
    );
    final tLenCtrl = TextEditingController(
      text: _fmt(topChordPerTrussM, dp: 3),
    );
    final sLenCtrl = TextEditingController(
      text: _fmt(sagMemberPerTrussM, dp: 3),
    );

    final bKgCtrl = TextEditingController(text: _fmt(bottomChordKgPerM, dp: 3));
    final tKgCtrl = TextEditingController(text: _fmt(topChordKgPerM, dp: 3));
    final sKgCtrl = TextEditingController(text: _fmt(sagMemberKgPerM, dp: 3));

    final purlinSpacingCtrl = TextEditingController(
      text: _fmt(purlinSpacingM, dp: 3),
    );
    final railSpacingCtrl = TextEditingController(
      text: _fmt(railSpacingM, dp: 3),
    );

    final purlinKgCtrl = TextEditingController(text: _fmt(purlinKgPerM, dp: 3));
    final railKgCtrl = TextEditingController(text: _fmt(railKgPerM, dp: 3));

    final purlinSizeCtrl = TextEditingController(text: purlinSizeLabel);
    final railSizeCtrl = TextEditingController(text: railSizeLabel);

    final angleCleatsPerTrussCtrl = TextEditingController(
      text: '$angleCleatsPerTruss',
    );
    final basePlatesPerTrussCtrl = TextEditingController(
      text: '$basePlatesPerTruss',
    );
    final boltsPerTrussCtrl = TextEditingController(text: '$boltsPerTruss');

    final angleCleatsTotalCtrl = TextEditingController(
      text: '$angleCleatsTotalOverride',
    );
    final basePlatesTotalCtrl = TextEditingController(
      text: '$basePlatesTotalOverride',
    );
    final boltsTotalCtrl = TextEditingController(text: '$boltsTotalOverride');

    int selectedEdgeIndex = 0;

    Map<String, dynamic> _computeTruss() {
      final run = _num(runLenCtrl.text, trussRunLengthM);
      final sp = _num(spacingCtrl.text, trussSpacingM).clamp(0.1, 9999);

      final nTruss = (run / sp).ceil() + 1;

      final bLen = _num(bLenCtrl.text, bottomChordPerTrussM);
      final tLen = _num(tLenCtrl.text, topChordPerTrussM);
      final sLen = _num(sLenCtrl.text, sagMemberPerTrussM);

      final bKgM = _num(bKgCtrl.text, bottomChordKgPerM);
      final tKgM = _num(tKgCtrl.text, topChordKgPerM);
      final sKgM = _num(sKgCtrl.text, sagMemberKgPerM);

      final totalBLen = bLen * nTruss;
      final totalTLen = tLen * nTruss;
      final totalSLen = sLen * nTruss;

      final totalBKg = totalBLen * bKgM;
      final totalTKg = totalTLen * tKgM;
      final totalSKg = totalSLen * sKgM;

      return {
        'runLengthM': run,
        'spacingM': sp,
        'count': nTruss,
        'bottom': {
          'perTrussLenM': bLen,
          'kgPerM': bKgM,
          'totalLenM': totalBLen,
          'totalKg': totalBKg,
        },
        'top': {
          'perTrussLenM': tLen,
          'kgPerM': tKgM,
          'totalLenM': totalTLen,
          'totalKg': totalTKg,
        },
        'sag': {
          'perTrussLenM': sLen,
          'kgPerM': sKgM,
          'totalLenM': totalSLen,
          'totalKg': totalSKg,
        },
        'combined': {'totalKg': totalBKg + totalTKg + totalSKg},
      };
    }

    Map<String, dynamic> _computePurlinsRails(double roofAreaM2) {
      final pSp = _num(
        purlinSpacingCtrl.text,
        purlinSpacingM,
      ).clamp(0.05, 9999);
      final rSp = _num(railSpacingCtrl.text, railSpacingM).clamp(0.05, 9999);

      final pKgM = _num(purlinKgCtrl.text, purlinKgPerM);
      final rKgM = _num(railKgCtrl.text, railKgPerM);

      final totalPurlinLenM = roofAreaM2 / pSp;
      final totalRailLenM = roofAreaM2 / rSp;

      return {
        'purlins': {
          'size': purlinSizeCtrl.text.trim(),
          'spacingM': pSp,
          'kgPerM': pKgM,
          'totalLenM': totalPurlinLenM,
          'totalKg': totalPurlinLenM * pKgM,
        },
        'rails': {
          'size': railSizeCtrl.text.trim(),
          'spacingM': rSp,
          'kgPerM': rKgM,
          'totalLenM': totalRailLenM,
          'totalKg': totalRailLenM * rKgM,
        },
      };
    }

    Map<String, dynamic> _computeFixings(int trussCount) {
      int angleTotal =
          angleCleatsUsePerTruss
              ? _intFrom(angleCleatsPerTrussCtrl, angleCleatsPerTruss) *
                  trussCount
              : _intFrom(angleCleatsTotalCtrl, angleCleatsTotalOverride);

      int baseTotal =
          basePlatesUsePerTruss
              ? _intFrom(basePlatesPerTrussCtrl, basePlatesPerTruss) *
                  trussCount
              : _intFrom(basePlatesTotalCtrl, basePlatesTotalOverride);

      int boltsTotal =
          boltsUsePerTruss
              ? _intFrom(boltsPerTrussCtrl, boltsPerTruss) * trussCount
              : _intFrom(boltsTotalCtrl, boltsTotalOverride);

      return {
        'angleCleats': {
          'totalNo': angleTotal,
          'mode': angleCleatsUsePerTruss ? 'perTruss' : 'direct',
        },
        'basePlates': {
          'totalNo': baseTotal,
          'mode': basePlatesUsePerTruss ? 'perTruss' : 'direct',
        },
        'bolts': {
          'totalNo': boltsTotal,
          'mode': boltsUsePerTruss ? 'perTruss' : 'direct',
        },
      };
    }

    // ---------- dialog ----------
    try {
      final ok = await showDialog<bool>(
        context: ctx,
        barrierDismissible: false,
        builder: (context) {
          return StatefulBuilder(
            builder: (context, setState) {
              if (usePitchAngle) {
                final deg = _num(pitchDegCtrl.text, pitchDeg);
                final rad = deg * math.pi / 180.0;
                final sf = 1 / math.cos(rad);
                slopeFactorCtrl.text = _fmt(sf, dp: 4);
              }

              final sf = _num(
                slopeFactorCtrl.text,
                slopeFactor,
              ).clamp(1.0, 10.0);
              final roofAreaM2 = planAreaM2 * sf;

              final edgeTotals = _edgeTotalsM(edges, edgeTypes);
              final truss = _computeTruss();
              final trussCount = (truss['count'] as int);

              final pr = _computePurlinsRails(roofAreaM2);
              final fx = _computeFixings(trussCount);

              return AlertDialog(
                title: const Text('Roof Take-off (Polygon)'),
                content: SizedBox(
                  width: 940,
                  child: SingleChildScrollView(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Plan: ${_fmt(planAreaM2)} m²   |   Factor: ${_fmt(sf, dp: 4)}   |   Roof: ${_fmt(roofAreaM2)} m²',
                          style: const TextStyle(fontWeight: FontWeight.w700),
                        ),
                        const SizedBox(height: 10),

                        // slope
                        Row(
                          children: [
                            Checkbox(
                              value: usePitchAngle,
                              onChanged:
                                  (v) =>
                                      setState(() => usePitchAngle = v ?? true),
                            ),
                            const Text('Use pitch°'),
                            const SizedBox(width: 10),
                            SizedBox(
                              width: 90,
                              child: TextField(
                                controller: pitchDegCtrl,
                                keyboardType: TextInputType.number,
                                decoration: const InputDecoration(
                                  labelText: 'Pitch°',
                                  isDense: true,
                                ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                            const SizedBox(width: 18),
                            Checkbox(
                              value: !usePitchAngle,
                              onChanged:
                                  (v) => setState(
                                    () => usePitchAngle = !(v ?? false),
                                  ),
                            ),
                            const Text('Use factor'),
                            const SizedBox(width: 10),
                            SizedBox(
                              width: 120,
                              child: TextField(
                                controller: slopeFactorCtrl,
                                keyboardType: TextInputType.number,
                                decoration: const InputDecoration(
                                  labelText: 'Factor',
                                  isDense: true,
                                ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                          ],
                        ),

                        const Divider(height: 26),

                        // Roof covering
                        Row(
                          children: [
                            Checkbox(
                              value: includeRoofCovering,
                              onChanged:
                                  (v) => setState(
                                    () => includeRoofCovering = v ?? true,
                                  ),
                            ),
                            const Text('Roof covering area (m²)'),
                            const SizedBox(width: 12),
                            Expanded(
                              child: Text(
                                boqRoofCovering == null
                                    ? 'BOQ: (not selected)'
                                    : 'BOQ: ${boqRoofCovering!.code} — ${boqRoofCovering!.description}',
                                overflow: TextOverflow.ellipsis,
                              ),
                            ),
                            ElevatedButton(
                              onPressed: () async {
                                final pick = await showBoqPickerDialog(context);
                                if (pick != null)
                                  setState(() => boqRoofCovering = pick);
                              },
                              child: const Text('Pick BOQ'),
                            ),
                          ],
                        ),

                        const Divider(height: 26),

                        // Edge classification
                        Row(
                          children: [
                            Checkbox(
                              value: includeEdgeLengths,
                              onChanged:
                                  (v) => setState(
                                    () => includeEdgeLengths = v ?? true,
                                  ),
                            ),
                            const Text(
                              'Classify edges (Eave/Hip/Valley/Ridge)',
                            ),
                          ],
                        ),
                        const SizedBox(height: 8),
                        SizedBox(
                          height: 210,
                          child: Row(
                            children: [
                              Expanded(
                                flex: 2,
                                child: ListView.builder(
                                  itemCount: edges.length,
                                  itemBuilder: (_, i) {
                                    final lenM =
                                        (edges[i]['lenM'] as num).toDouble();
                                    return ListTile(
                                      dense: true,
                                      selected: selectedEdgeIndex == i,
                                      title: Text(
                                        'Edge ${i + 1} • ${_fmt(lenM)} m',
                                      ),
                                      subtitle: Text(
                                        'Type: ${edgeTypeLabel(edgeTypes[i])}',
                                      ),
                                      onTap:
                                          () => setState(
                                            () => selectedEdgeIndex = i,
                                          ),
                                      trailing: DropdownButton<RoofEdgeType>(
                                        value: edgeTypes[i],
                                        items:
                                            RoofEdgeType.values
                                                .map(
                                                  (t) => DropdownMenuItem(
                                                    value: t,
                                                    child: Text(
                                                      edgeTypeLabel(t),
                                                    ),
                                                  ),
                                                )
                                                .toList(),
                                        onChanged: (t) {
                                          if (t == null) return;
                                          setState(() {
                                            edgeTypes[i] = t;
                                            edges[i]['type'] = edgeTypeKey(t);
                                          });
                                        },
                                      ),
                                    );
                                  },
                                ),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                flex: 3,
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      'Totals (m):  '
                                      'Eave ${_fmt(edgeTotals[RoofEdgeType.eave]!, dp: 3)}  |  '
                                      'Hip ${_fmt(edgeTotals[RoofEdgeType.hip]!, dp: 3)}  |  '
                                      'Valley ${_fmt(edgeTotals[RoofEdgeType.valley]!, dp: 3)}  |  '
                                      'Ridge ${_fmt(edgeTotals[RoofEdgeType.ridge]!, dp: 3)}',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.w700,
                                      ),
                                    ),
                                    const SizedBox(height: 10),
                                    _edgeBoqRow(
                                      context: context,
                                      label: 'Eaves length BOQ',
                                      enabled: includeEdgeLengths,
                                      pick: boqEave,
                                      onPick:
                                          (p) => setState(() => boqEave = p),
                                      picker: showBoqPickerDialog,
                                    ),
                                    _edgeBoqRow(
                                      context: context,
                                      label: 'Ridges length BOQ',
                                      enabled: includeEdgeLengths,
                                      pick: boqRidge,
                                      onPick:
                                          (p) => setState(() => boqRidge = p),
                                      picker: showBoqPickerDialog,
                                    ),
                                    _edgeBoqRow(
                                      context: context,
                                      label: 'Hips length BOQ',
                                      enabled: includeEdgeLengths,
                                      pick: boqHip,
                                      onPick: (p) => setState(() => boqHip = p),
                                      picker: showBoqPickerDialog,
                                    ),
                                    _edgeBoqRow(
                                      context: context,
                                      label: 'Valleys length BOQ',
                                      enabled: includeEdgeLengths,
                                      pick: boqValley,
                                      onPick:
                                          (p) => setState(() => boqValley = p),
                                      picker: showBoqPickerDialog,
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),

                        const Divider(height: 26),

                        // Truss
                        Row(
                          children: [
                            Checkbox(
                              value: includeTruss,
                              onChanged:
                                  (v) =>
                                      setState(() => includeTruss = v ?? true),
                            ),
                            const Text('Truss members (kg)'),
                            const Spacer(),
                            Checkbox(
                              value: combineTrussMembers,
                              onChanged:
                                  (v) => setState(
                                    () => combineTrussMembers = v ?? false,
                                  ),
                            ),
                            const Text('Combine'),
                          ],
                        ),
                        if (includeTruss) ...[
                          Row(
                            children: [
                              SizedBox(
                                width: 170,
                                child: TextField(
                                  controller: runLenCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'Run length (m)',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 12),
                              SizedBox(
                                width: 170,
                                child: TextField(
                                  controller: spacingCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'Spacing (m)',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 16),
                              Expanded(
                                child: Text(
                                  'Trusses: $trussCount',
                                  style: const TextStyle(
                                    fontWeight: FontWeight.w700,
                                  ),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          if (!combineTrussMembers) ...[
                            _trussMemberRow(
                              title: 'Bottom chord',
                              lenCtrl: bLenCtrl,
                              kgCtrl: bKgCtrl,
                              totalLenM:
                                  (truss['bottom']['totalLenM'] as num)
                                      .toDouble(),
                              totalKg:
                                  (truss['bottom']['totalKg'] as num)
                                      .toDouble(),
                              pick: boqTrussBottom,
                              onPick: (p) => setState(() => boqTrussBottom = p),
                              picker: showBoqPickerDialog,
                              context: context,
                            ),
                            _trussMemberRow(
                              title: 'Top chord',
                              lenCtrl: tLenCtrl,
                              kgCtrl: tKgCtrl,
                              totalLenM:
                                  (truss['top']['totalLenM'] as num).toDouble(),
                              totalKg:
                                  (truss['top']['totalKg'] as num).toDouble(),
                              pick: boqTrussTop,
                              onPick: (p) => setState(() => boqTrussTop = p),
                              picker: showBoqPickerDialog,
                              context: context,
                            ),
                            _trussMemberRow(
                              title: 'Sag member',
                              lenCtrl: sLenCtrl,
                              kgCtrl: sKgCtrl,
                              totalLenM:
                                  (truss['sag']['totalLenM'] as num).toDouble(),
                              totalKg:
                                  (truss['sag']['totalKg'] as num).toDouble(),
                              pick: boqTrussSag,
                              onPick: (p) => setState(() => boqTrussSag = p),
                              picker: showBoqPickerDialog,
                              context: context,
                            ),
                          ] else ...[
                            Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    'Combined truss: ${_fmt((truss['combined']['totalKg'] as num).toDouble())} kg',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),
                                ),
                                Expanded(
                                  child: Text(
                                    boqTrussCombined == null
                                        ? 'BOQ: (not selected)'
                                        : 'BOQ: ${boqTrussCombined!.code} — ${boqTrussCombined!.description}',
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                ),
                                ElevatedButton(
                                  onPressed: () async {
                                    final pick = await showBoqPickerDialog(
                                      context,
                                    );
                                    if (pick != null)
                                      setState(() => boqTrussCombined = pick);
                                  },
                                  child: const Text('Pick BOQ'),
                                ),
                              ],
                            ),
                          ],
                        ],

                        const Divider(height: 26),

                        // Purlins
                        Row(
                          children: [
                            Checkbox(
                              value: includePurlins,
                              onChanged:
                                  (v) => setState(
                                    () => includePurlins = v ?? true,
                                  ),
                            ),
                            const Text('Purlins (kg)'),
                          ],
                        ),
                        if (includePurlins) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: purlinSizeCtrl,
                                  decoration: const InputDecoration(
                                    labelText: 'Purlin size/label',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 10),
                              SizedBox(
                                width: 150,
                                child: TextField(
                                  controller: purlinSpacingCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'Spacing (m)',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 10),
                              SizedBox(
                                width: 150,
                                child: TextField(
                                  controller: purlinKgCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'kg/m',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 6),
                          Text(
                            'Purlins: ${_fmt((pr['purlins']['totalLenM'] as num).toDouble())} m  →  '
                            '${_fmt((pr['purlins']['totalKg'] as num).toDouble())} kg   (Area/Spacing)',
                          ),
                          const SizedBox(height: 6),
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  boqPurlins == null
                                      ? 'BOQ: (not selected)'
                                      : 'BOQ: ${boqPurlins!.code} — ${boqPurlins!.description}',
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                              ElevatedButton(
                                onPressed: () async {
                                  final pick = await showBoqPickerDialog(
                                    context,
                                  );
                                  if (pick != null)
                                    setState(() => boqPurlins = pick);
                                },
                                child: const Text('Pick BOQ'),
                              ),
                            ],
                          ),
                        ],

                        const SizedBox(height: 10),

                        // Rails
                        Row(
                          children: [
                            Checkbox(
                              value: includeRails,
                              onChanged:
                                  (v) =>
                                      setState(() => includeRails = v ?? true),
                            ),
                            const Text('Rails (kg)'),
                          ],
                        ),
                        if (includeRails) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: railSizeCtrl,
                                  decoration: const InputDecoration(
                                    labelText: 'Rail size/label',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 10),
                              SizedBox(
                                width: 150,
                                child: TextField(
                                  controller: railSpacingCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'Spacing (m)',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 10),
                              SizedBox(
                                width: 150,
                                child: TextField(
                                  controller: railKgCtrl,
                                  keyboardType: TextInputType.number,
                                  decoration: const InputDecoration(
                                    labelText: 'kg/m',
                                    isDense: true,
                                  ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 6),
                          Text(
                            'Rails: ${_fmt((pr['rails']['totalLenM'] as num).toDouble())} m  →  '
                            '${_fmt((pr['rails']['totalKg'] as num).toDouble())} kg   (Area/Spacing)',
                          ),
                          const SizedBox(height: 6),
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  boqRails == null
                                      ? 'BOQ: (not selected)'
                                      : 'BOQ: ${boqRails!.code} — ${boqRails!.description}',
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                              ElevatedButton(
                                onPressed: () async {
                                  final pick = await showBoqPickerDialog(
                                    context,
                                  );
                                  if (pick != null)
                                    setState(() => boqRails = pick);
                                },
                                child: const Text('Pick BOQ'),
                              ),
                            ],
                          ),
                        ],

                        const Divider(height: 26),

                        // Fixings
                        Row(
                          children: [
                            Checkbox(
                              value: includeAngleCleats,
                              onChanged:
                                  (v) => setState(
                                    () => includeAngleCleats = v ?? true,
                                  ),
                            ),
                            const Text('Angle cleats (No)'),
                          ],
                        ),
                        if (includeAngleCleats)
                          _fixingRow(
                            context: context,
                            title: 'Angle cleats',
                            trussCount: trussCount,
                            usePerTruss: angleCleatsUsePerTruss,
                            onToggleMode:
                                (v) =>
                                    setState(() => angleCleatsUsePerTruss = v),
                            perTrussCtrl: angleCleatsPerTrussCtrl,
                            totalCtrl: angleCleatsTotalCtrl,
                            totalNo: (fx['angleCleats']['totalNo'] as int),
                            pick: boqAngleCleats,
                            onPick: (p) => setState(() => boqAngleCleats = p),
                            picker: showBoqPickerDialog,
                          ),

                        Row(
                          children: [
                            Checkbox(
                              value: includeBasePlates,
                              onChanged:
                                  (v) => setState(
                                    () => includeBasePlates = v ?? true,
                                  ),
                            ),
                            const Text('Base plates (No)'),
                          ],
                        ),
                        if (includeBasePlates)
                          _fixingRow(
                            context: context,
                            title: 'Base plates',
                            trussCount: trussCount,
                            usePerTruss: basePlatesUsePerTruss,
                            onToggleMode:
                                (v) =>
                                    setState(() => basePlatesUsePerTruss = v),
                            perTrussCtrl: basePlatesPerTrussCtrl,
                            totalCtrl: basePlatesTotalCtrl,
                            totalNo: (fx['basePlates']['totalNo'] as int),
                            pick: boqBasePlates,
                            onPick: (p) => setState(() => boqBasePlates = p),
                            picker: showBoqPickerDialog,
                          ),

                        Row(
                          children: [
                            Checkbox(
                              value: includeBolts,
                              onChanged:
                                  (v) =>
                                      setState(() => includeBolts = v ?? true),
                            ),
                            const Text('Bolts (No)'),
                          ],
                        ),
                        if (includeBolts)
                          _fixingRow(
                            context: context,
                            title: 'Bolts',
                            trussCount: trussCount,
                            usePerTruss: boltsUsePerTruss,
                            onToggleMode:
                                (v) => setState(() => boltsUsePerTruss = v),
                            perTrussCtrl: boltsPerTrussCtrl,
                            totalCtrl: boltsTotalCtrl,
                            totalNo: (fx['bolts']['totalNo'] as int),
                            pick: boqBolts,
                            onPick: (p) => setState(() => boqBolts = p),
                            picker: showBoqPickerDialog,
                          ),
                      ],
                    ),
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(context, false),
                    child: const Text('Cancel'),
                  ),
                  ElevatedButton(
                    onPressed: () => Navigator.pop(context, true),
                    child: const Text('Save'),
                  ),
                ],
              );
            },
          );
        },
      );

      if (ok != true) return RoofSaveAction.cancelled;

      // ---------- final quantities ----------
      final sf = _num(slopeFactorCtrl.text, slopeFactor).clamp(1.0, 10.0);
      final roofAreaM2 = planAreaM2 * sf;

      final edgeTotals = _edgeTotalsM(edges, edgeTypes);
      final truss = _computeTruss();
      final trussCount = (truss['count'] as int);

      final pr = _computePurlinsRails(roofAreaM2);
      final fx = _computeFixings(trussCount);

      // ---------- build BOQ lines ----------
      final boqLines = <Map<String, dynamic>>[];

      void addLine(BoqPick pick, double qty, Map<String, dynamic> meta) {
        if (qty <= 0) return;
        boqLines.add({
          'resolvedBoqCode': pick.code,
          'displayCode': pick.code,
          'description': pick.description,
          'unit': 'm',
          'qty': qty,
          'meta': meta,
        });
      }

      if (includeRoofCovering && boqRoofCovering != null) {
        addLine(boqRoofCovering!, roofAreaM2, {'type': 'roof_area_m2'});
      }

      if (includeEdgeLengths) {
        if (boqEave != null) {
          addLine(boqEave!, edgeTotals[RoofEdgeType.eave] ?? 0, {
            'type': 'edge_m',
            'edgeType': 'eave',
          });
        }
        if (boqRidge != null) {
          addLine(boqRidge!, edgeTotals[RoofEdgeType.ridge] ?? 0, {
            'type': 'edge_m',
            'edgeType': 'ridge',
          });
        }
        if (boqHip != null) {
          addLine(boqHip!, edgeTotals[RoofEdgeType.hip] ?? 0, {
            'type': 'edge_m',
            'edgeType': 'hip',
          });
        }
        if (boqValley != null) {
          addLine(boqValley!, edgeTotals[RoofEdgeType.valley] ?? 0, {
            'type': 'edge_m',
            'edgeType': 'valley',
          });
        }
      }

      if (includeTruss) {
        if (combineTrussMembers) {
          final totalKg = (truss['combined']['totalKg'] as num).toDouble();
          if (boqTrussCombined != null) {
            addLine(boqTrussCombined!, totalKg, {
              'type': 'truss_members_kg',
              'mode': 'combined',
            });
          }
        } else {
          if (boqTrussBottom != null) {
            addLine(
              boqTrussBottom!,
              (truss['bottom']['totalKg'] as num).toDouble(),
              {'type': 'truss_members_kg', 'member': 'bottom'},
            );
          }
          if (boqTrussTop != null) {
            addLine(boqTrussTop!, (truss['top']['totalKg'] as num).toDouble(), {
              'type': 'truss_members_kg',
              'member': 'top',
            });
          }
          if (boqTrussSag != null) {
            addLine(boqTrussSag!, (truss['sag']['totalKg'] as num).toDouble(), {
              'type': 'truss_members_kg',
              'member': 'sag',
            });
          }
        }
      }

      if (includePurlins && boqPurlins != null) {
        addLine(boqPurlins!, (pr['purlins']['totalKg'] as num).toDouble(), {
          'type': 'purlins_kg',
          'size': pr['purlins']['size'],
          'spacingM': pr['purlins']['spacingM'],
          'kgPerM': pr['purlins']['kgPerM'],
          'totalLenM': pr['purlins']['totalLenM'],
          'estimator': 'roofArea/spacing',
        });
      }

      if (includeRails && boqRails != null) {
        addLine(boqRails!, (pr['rails']['totalKg'] as num).toDouble(), {
          'type': 'rails_kg',
          'size': pr['rails']['size'],
          'spacingM': pr['rails']['spacingM'],
          'kgPerM': pr['rails']['kgPerM'],
          'totalLenM': pr['rails']['totalLenM'],
          'estimator': 'roofArea/spacing',
        });
      }

      if (includeAngleCleats && boqAngleCleats != null) {
        addLine(
          boqAngleCleats!,
          (fx['angleCleats']['totalNo'] as int).toDouble(),
          {
            'type': 'angle_cleats_no',
            'mode': fx['angleCleats']['mode'],
            'trussCount': trussCount,
          },
        );
      }
      if (includeBasePlates && boqBasePlates != null) {
        addLine(
          boqBasePlates!,
          (fx['basePlates']['totalNo'] as int).toDouble(),
          {
            'type': 'base_plates_no',
            'mode': fx['basePlates']['mode'],
            'trussCount': trussCount,
          },
        );
      }
      if (includeBolts && boqBolts != null) {
        addLine(boqBolts!, (fx['bolts']['totalNo'] as int).toDouble(), {
          'type': 'bolts_no',
          'mode': fx['bolts']['mode'],
          'trussCount': trussCount,
        });
      }

      // ---------- show progress + save ----------
      if (ctx.mounted) {
        showDialog<void>(
          context: ctx,
          barrierDismissible: false,
          builder:
              (_) => const AlertDialog(
                content: SizedBox(
                  height: 56,
                  child: Row(
                    children: [
                      SizedBox(
                        width: 22,
                        height: 22,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      ),
                      SizedBox(width: 12),
                      Expanded(child: Text('Saving roof measurement...')),
                    ],
                  ),
                ),
              ),
        );
      }

      try {
        final now = DateTime.now();
        final docRef = measurementsRef.doc();

        await docRef.set({
          'type': 'roof_polygon_v3',
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,
          'label': activeLabel,
          'color': currentColor.value,
          'createdAt': Timestamp.fromDate(now),
          'updatedAt': Timestamp.fromDate(now),

          'polygon': polygon.map((p) => {'dx': p.dx, 'dy': p.dy}).toList(),
          'edges': List.generate(
            edges.length,
            (i) => {...edges[i], 'type': edgeTypeKey(edgeTypes[i])},
          ),

          'calibration': {'pixelsPerMeter': ppm},
          'planAreaM2': planAreaM2,
          'slopeFactor': sf,
          'roofAreaM2': roofAreaM2,

          'edgeTotalsM': {
            'eave': edgeTotals[RoofEdgeType.eave],
            'ridge': edgeTotals[RoofEdgeType.ridge],
            'hip': edgeTotals[RoofEdgeType.hip],
            'valley': edgeTotals[RoofEdgeType.valley],
          },

          'truss': includeTruss ? truss : null,
          'trussCombined': combineTrussMembers,

          'purlinsRails': {
            'enabledPurlins': includePurlins,
            'enabledRails': includeRails,
            ...pr,
          },

          'fixings': {
            'enabledAngleCleats': includeAngleCleats,
            'enabledBasePlates': includeBasePlates,
            'enabledBolts': includeBolts,
            ...fx,
          },

          'boqLines': boqLines,
        });

        if (ctx.mounted)
          Navigator.of(ctx, rootNavigator: true).pop(); // close progress
        _toast('Saved roof measurement successfully.');

        onCloseDraft?.call();
        onUpdateViewer?.call();
        return RoofSaveAction.saved;
      } catch (e, st) {
        if (ctx.mounted)
          Navigator.of(ctx, rootNavigator: true).pop(); // close progress
        // ✅ NOT SILENT:
        _toast('Save failed. Check error details.');
        // log full error:
        // ignore: avoid_print
        print('Roof save failed: $e\n$st');
        await _showErrorDialog('Save failed', '$e');
        return RoofSaveAction.failed;
      }
    } catch (e, st) {
      // ✅ NOT SILENT:
      _toast('Roof dialog failed.');
      // ignore: avoid_print
      print('Roof dialog failed: $e\n$st');
      await _showErrorDialog('Roof error', '$e');
      return RoofSaveAction.failed;
    } finally {
      pitchDegCtrl.dispose();
      slopeFactorCtrl.dispose();

      runLenCtrl.dispose();
      spacingCtrl.dispose();

      bLenCtrl.dispose();
      tLenCtrl.dispose();
      sLenCtrl.dispose();

      bKgCtrl.dispose();
      tKgCtrl.dispose();
      sKgCtrl.dispose();

      purlinSpacingCtrl.dispose();
      railSpacingCtrl.dispose();

      purlinKgCtrl.dispose();
      railKgCtrl.dispose();

      purlinSizeCtrl.dispose();
      railSizeCtrl.dispose();

      angleCleatsPerTrussCtrl.dispose();
      basePlatesPerTrussCtrl.dispose();
      boltsPerTrussCtrl.dispose();

      angleCleatsTotalCtrl.dispose();
      basePlatesTotalCtrl.dispose();
      boltsTotalCtrl.dispose();
    }
  }

  /// ---------- UI helpers ----------
  Widget _edgeBoqRow({
    required BuildContext context,
    required String label,
    required bool enabled,
    required BoqPick? pick,
    required void Function(BoqPick? p) onPick,
    required Future<BoqPick?> Function(BuildContext ctx) picker,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        children: [
          Expanded(child: Text(label)),
          Expanded(
            child: Text(
              pick == null
                  ? 'BOQ: (not selected)'
                  : 'BOQ: ${pick.code} — ${pick.description}',
              overflow: TextOverflow.ellipsis,
            ),
          ),
          const SizedBox(width: 12),
          ElevatedButton(
            onPressed:
                !enabled
                    ? null
                    : () async {
                      final p = await picker(context);
                      onPick(p);
                    },
            child: const Text('Pick BOQ'),
          ),
        ],
      ),
    );
  }

  Widget _trussMemberRow({
    required String title,
    required TextEditingController lenCtrl,
    required TextEditingController kgCtrl,
    required double totalLenM,
    required double totalKg,
    required BoqPick? pick,
    required void Function(BoqPick? p) onPick,
    required Future<BoqPick?> Function(BuildContext ctx) picker,
    required BuildContext context,
  }) {
    String fmt(double v, {int dp = 3}) => v.toStringAsFixed(dp);
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              SizedBox(
                width: 170,
                child: TextField(
                  controller: lenCtrl,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'Len per truss (m)',
                    isDense: true,
                  ),
                ),
              ),
              const SizedBox(width: 12),
              SizedBox(
                width: 170,
                child: TextField(
                  controller: kgCtrl,
                  keyboardType: TextInputType.number,
                  decoration: const InputDecoration(
                    labelText: 'kg/m',
                    isDense: true,
                  ),
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Text(
                  'Total: ${fmt(totalLenM)} m  |  ${fmt(totalKg)} kg',
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: Text(
                  pick == null
                      ? 'BOQ: (not selected)'
                      : 'BOQ: ${pick.code} — ${pick.description}',
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(width: 12),
              ElevatedButton(
                onPressed: () async {
                  final p = await picker(context);
                  onPick(p);
                },
                child: const Text('Pick BOQ'),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _fixingRow({
    required BuildContext context,
    required String title,
    required int trussCount,
    required bool usePerTruss,
    required void Function(bool v) onToggleMode,
    required TextEditingController perTrussCtrl,
    required TextEditingController totalCtrl,
    required int totalNo,
    required BoqPick? pick,
    required void Function(BoqPick? p) onPick,
    required Future<BoqPick?> Function(BuildContext ctx) picker,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              Switch(value: usePerTruss, onChanged: (v) => onToggleMode(v)),
              Text(usePerTruss ? 'Per truss' : 'Direct total'),
              const SizedBox(width: 12),
              if (usePerTruss) ...[
                SizedBox(
                  width: 170,
                  child: TextField(
                    controller: perTrussCtrl,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'No per truss',
                      isDense: true,
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Text('Trusses: $trussCount  →  Total: $totalNo No'),
              ] else ...[
                SizedBox(
                  width: 170,
                  child: TextField(
                    controller: totalCtrl,
                    keyboardType: TextInputType.number,
                    decoration: const InputDecoration(
                      labelText: 'Total No',
                      isDense: true,
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                Text('Total: $totalNo No'),
              ],
            ],
          ),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: Text(
                  pick == null
                      ? 'BOQ: (not selected)'
                      : 'BOQ: ${pick.code} — ${pick.description}',
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(width: 12),
              ElevatedButton(
                onPressed: () async {
                  final p = await picker(context);
                  onPick(p);
                },
                child: const Text('Pick BOQ'),
              ),
            ],
          ),
        ],
      ),
    );
  }

