  Future<FoundationSaveAction> openFoundationWallSegmentDialog({
    required Offset p1,
    required Offset p2,
    required Map<String, dynamic> drawingData,
    double? measuredLengthM,
    List<Map<String, dynamic>>? polylineSegments,
    String? wallGroupId, // optional external id
  }) async {
    // ----------------------------
    // Calibration / length
    // ----------------------------
    final rawPpu = drawingData['pixelsPerUnit'];
    final double pxPerM =
        (rawPpu is num) ? rawPpu.toDouble() : double.tryParse('$rawPpu') ?? 0.0;

    if (pxPerM <= 0) {
      Get.snackbar(
        'Calibration',
        'pixelsPerUnit is missing/invalid. Calibrate first.',
      );
      clearFoundationDraftPoints();
      update(['viewer']);
      return FoundationSaveAction.cancel;
    }

    double lenM(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      return (math.sqrt(dx * dx + dy * dy)) / pxPerM;
    }

    final baseLengthM = measuredLengthM ?? lenM(p1, p2);
    if (baseLengthM <= 0) {
      clearFoundationDraftPoints();
      update(['viewer']);
      return FoundationSaveAction.cancel;
    }

    // ✅ Ensure any previously remembered length never interferes
    for (final k in const [
      'lengthM',
      'wallLengthM',
      'baseLengthM',
      'foundationLengthM',
      'lengthEachM',
      'lengthTotalM',
    ]) {
      lastFoundationDefaults.remove(k);
    }

    // ✅ Editable length controller, ALWAYS starts from new measurement
    final lengthCtrl = TextEditingController(
      text: baseLengthM.toStringAsFixed(3),
    );

    // ----------------------------
    // Grouping (keep same group for Add another)
    // ----------------------------
    final forced = (wallGroupId ?? '').trim();
    draftFoundationGroupId ??=
        (forced.isNotEmpty ? forced : measurementsRef.doc().id);
    final foundationGroupId = draftFoundationGroupId!;
    final segmentId = measurementsRef.doc().id;

    // ----------------------------
    // Helpers: restore BOQ picks
    // ----------------------------
    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    // ----------------------------
    // Controllers (prefill from last defaults)
    // ----------------------------
    TextEditingController nCtrl(
      String key, {
      String? fallbackKey,
      String fb = '',
    }) {
      final v =
          lastFoundationDefaults[key] ??
          (fallbackKey != null ? lastFoundationDefaults[fallbackKey] : null);
      return TextEditingController(text: (v == null) ? fb : '$v');
    }

    // ✅ Building factor (REMEMBERED, default 1)
    final factorCtrl = nCtrl('buildingFactor', fb: '1');

    int factorFrom(TextEditingController c) =>
        (int.tryParse(c.text.trim()) ?? 1).clamp(1, 999999);

    // Trench
    final trenchWidthCtrl = nCtrl('trenchWidth', fb: '0.700');
    final trenchDepthCtrl = nCtrl('trenchDepth', fb: '1.200');
    final workingSpaceCtrl = nCtrl('workingSpace', fb: '0.000');

    // Blinding width (for m²)
    final blindingWidthCtrl = nCtrl(
      'blindingWidth',
      fallbackKey: 'blindW',
      fb: '0.230',
    );
    final blindingThkCtrl = nCtrl('blindingThk', fb: '0.050');

    // Strip (concrete under wall)
    final stripWidthCtrl = nCtrl(
      'stripWidth',
      fallbackKey: 'footingWidth',
      fb: '0.700',
    );
    final stripThkCtrl = nCtrl(
      'stripThk',
      fallbackKey: 'footingThk',
      fb: '0.230',
    );

    // Wall
    final wallThkCtrl = nCtrl('wallThk', fb: '0.230');
    final initialTrenchDepth =
        double.tryParse(trenchDepthCtrl.text.trim()) ?? 1.2;
    final initialStripThk = double.tryParse(stripThkCtrl.text.trim()) ?? 0.233;
    final initialBlindingThk =
        double.tryParse(blindingThkCtrl.text.trim()) ?? 0.05;
    bool autoWallHeight =
        (lastFoundationDefaults['autoWallHeight'] ?? true) == true;
    final calculatedInitialWallHeight = (initialTrenchDepth -
            initialStripThk -
            initialBlindingThk)
        .clamp(0.0, double.infinity);
    final wallHeightCtrl = TextEditingController(
      text:
          autoWallHeight
              ? calculatedInitialWallHeight.toStringAsFixed(3)
              : '${lastFoundationDefaults['wallHeight'] ?? calculatedInitialWallHeight}',
    );

    bool reuseForBackfill = lastFoundationDefaults['reuseForBackfill'] == true;

    bool includeStripVolInBackfill =
        (lastFoundationDefaults['includeStripVolInBackfill'] ??
            lastFoundationDefaults['includeFootingVolInBackfill']) ==
        true;

    bool includeWallVolInBackfill =
        lastFoundationDefaults['includeWallVolInBackfill'] == true;

    // ✅ remember toggle (default TRUE)
    bool rememberForNext =
        (lastFoundationDefaults['rememberForNext'] ?? true) == true;

    // ----------------------------
    // BOQ picks (restore previous)
    // ----------------------------
    BoqPick? boqExc = pickFromMap(lastFoundationDefaults['boqExc']);
    BoqPick? boqBackfill = pickFromMap(lastFoundationDefaults['boqBackfill']);
    BoqPick? boqDisposal = pickFromMap(lastFoundationDefaults['boqDisposal']);
    BoqPick? boqBlinding = pickFromMap(lastFoundationDefaults['boqBlinding']);

    BoqPick? boqStrip = pickFromMap(lastFoundationDefaults['boqStrip']);
    BoqPick? boqStripFormwork = pickFromMap(
      lastFoundationDefaults['boqStripFormwork'],
    );
    BoqPick? boqWall = pickFromMap(lastFoundationDefaults['boqWall']);
    bool includeDpc = lastFoundationDefaults['includeDpc'] == true;
    bool includeAntiTermite =
        lastFoundationDefaults['includeAntiTermite'] == true;
    BoqPick? boqDpc = pickFromMap(lastFoundationDefaults['boqDpc']);
    BoqPick? boqAntiTermite = pickFromMap(
      lastFoundationDefaults['boqAntiTermite'],
    );

    double parseD(TextEditingController c, double fallback) =>
        double.tryParse(c.text.trim()) ?? fallback;

    FoundationSaveAction action = FoundationSaveAction.cancel;

    do {
      action =
          await Get.dialog<FoundationSaveAction>(
            StatefulBuilder(
              builder: (ctx, setState) {
                // ----------------------------
                // Live calculations
                // ----------------------------
                final L = parseD(lengthCtrl, baseLengthM).clamp(0.0, 1e12);
                final factor = factorFrom(factorCtrl);

                final trenchWBase = parseD(trenchWidthCtrl, 0.70);
                final workSpace = parseD(workingSpaceCtrl, 0.0);
                final trenchW = (trenchWBase + workSpace).clamp(
                  0.0,
                  double.infinity,
                );
                final trenchD = parseD(trenchDepthCtrl, 1.2);

                final stripW = parseD(stripWidthCtrl, 0.70);
                final stripT = parseD(stripThkCtrl, 0.23);
                final blindingT = parseD(blindingThkCtrl, 0.05);

                final calculatedWallH = (trenchD - stripT - blindingT).clamp(
                  0.0,
                  double.infinity,
                );
                if (autoWallHeight) {
                  wallHeightCtrl.text = calculatedWallH.toStringAsFixed(3);
                }

                final wallT = parseD(wallThkCtrl, 0.23);
                final wallH = parseD(wallHeightCtrl, calculatedWallH);

                final blindW = parseD(blindingWidthCtrl, stripW);

                // EACH (for one building)
                final excavationEachM3 = trenchW * trenchD * L;

                final stripEachM3 = stripW * stripT * L;
                final stripFormworkEachM2 = 2 * stripT * L;

                final blindingEachM2 = blindW * L;

                final wallEachM2 = wallH * L;
                final wallVolEachM3 = wallT * wallH * L;

                double deducted = 0.0;
                if (includeStripVolInBackfill) deducted += stripEachM3;
                if (includeWallVolInBackfill) deducted += wallVolEachM3;

                final backfillEachM3 = (excavationEachM3 - deducted).clamp(
                  0.0,
                  double.infinity,
                );

                final disposalEachM3 =
                    reuseForBackfill
                        ? (excavationEachM3 - backfillEachM3).clamp(
                          0.0,
                          double.infinity,
                        )
                        : excavationEachM3;

                // TOTAL (×factor)
                final excavationTotalM3 = excavationEachM3 * factor;
                final backfillTotalM3 = backfillEachM3 * factor;
                final disposalTotalM3 = disposalEachM3 * factor;
                final blindingTotalM2 = blindingEachM2 * factor;
                final stripTotalM3 = stripEachM3 * factor;
                final stripFormworkTotalM2 = stripFormworkEachM2 * factor;
                final wallTotalM2 = wallEachM2 * factor;
                final derivedLengthTotalM = L * factor;
                final hasRequiredBoqs =
                    boqExc != null &&
                    boqBackfill != null &&
                    boqDisposal != null &&
                    boqBlinding != null &&
                    boqStrip != null &&
                    boqStripFormwork != null &&
                    boqWall != null &&
                    (!includeDpc || boqDpc != null) &&
                    (!includeAntiTermite || boqAntiTermite != null);

                Future<void> pickBoq(void Function(BoqPick p) apply) async {
                  final pick = await showBoqPickerDialog(context: ctx);
                  if (pick == null) return;
                  setState(() => apply(pick));
                }

