                              () => pickBoq((p) => boqStrip = p),
                              onClear: () => setState(() => boqStrip = null),
                              quantityText: '${stripTotalM3.toStringAsFixed(3)} m³',
                            ),
                            const SizedBox(height: 12),
                            boqLine(
                              'Strip formwork (2 sides) BOQ (m²)',
                              boqStripFormwork,
                              () => pickBoq((p) => boqStripFormwork = p),
                              onClear:
                                  () => setState(() => boqStripFormwork = null),
                              quantityText: '${stripFormworkTotalM2.toStringAsFixed(3)} m²',
                            ),
                            const SizedBox(height: 12),
                            boqLine(
                              'Foundation wall BOQ (m²)',
                              boqWall,
                              () => pickBoq((p) => boqWall = p),
                              onClear: () => setState(() => boqWall = null),
                              quantityText: '${wallTotalM2.toStringAsFixed(3)} m²',
                            ),

                            const SizedBox(height: 18),
                            fwPanel(
                              title: 'DPC and anti-termite',
                              subtitle:
                                  'Optional linear-metre items derived from this wall chain',
                              icon: Icons.linear_scale_rounded,
                              child: Column(
                                children: [
                                  SwitchListTile(
                                    contentPadding: EdgeInsets.zero,
                                    value: includeDpc,
                                    onChanged:
                                        (value) =>
                                            setState(() => includeDpc = value),
                                    title: const Text(
                                      'Include damp-proof course (DPC)',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    subtitle: Text(
                                      '${L.toStringAsFixed(3)} m × $factor = ${derivedLengthTotalM.toStringAsFixed(3)} m',
                                    ),
                                  ),
                                  if (includeDpc)
                                    boqLine(
                                      'DPC BOQ (m)',
                                      boqDpc,
                                      () => pickBoq((p) => boqDpc = p),
                                      onClear:
                                          () => setState(() => boqDpc = null),
                                      quantityText:
                                          '${derivedLengthTotalM.toStringAsFixed(3)} m',
                                    ),
                                  const Divider(height: 24),
                                  SwitchListTile(
                                    contentPadding: EdgeInsets.zero,
                                    value: includeAntiTermite,
                                    onChanged:
                                        (value) => setState(
                                          () => includeAntiTermite = value,
                                        ),
                                    title: const Text(
                                      'Include anti-termite treatment',
                                      style: TextStyle(
                                        fontWeight: FontWeight.w900,
                                      ),
                                    ),
                                    subtitle: Text(
                                      '${L.toStringAsFixed(3)} m × $factor = ${derivedLengthTotalM.toStringAsFixed(3)} m',
                                    ),
                                  ),
                                  if (includeAntiTermite)
                                    boqLine(
                                      'Anti-termite BOQ (m)',
                                      boqAntiTermite,
                                      () => pickBoq((p) => boqAntiTermite = p),
                                      onClear:
                                          () => setState(
                                            () => boqAntiTermite = null,
                                          ),
                                      quantityText:
                                          '${derivedLengthTotalM.toStringAsFixed(3)} m',
                                    ),
                                ],
                              ),
                            ),

                            const SizedBox(height: 18),
                            fwPanel(
                              title: 'Measurement summary',
                              subtitle:
                                  'Per segment values and final totals after building factor ×$factor',
                              icon: Icons.summarize_rounded,
                              child: Wrap(
                                spacing: 12,
                                runSpacing: 12,
                                children: [
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Excavation per segment',
                                      '${excavationEachM3.toStringAsFixed(3)} m³',
                                      Icons.terrain_rounded,
                                    ),
                                  ),
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Backfill per segment',
                                      '${backfillEachM3.toStringAsFixed(3)} m³',
                                      Icons.layers_rounded,
                                    ),
                                  ),
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Strip formwork',
                                      '${stripFormworkTotalM2.toStringAsFixed(3)} m²',
                                      Icons.view_sidebar_rounded,
                                    ),
                                  ),
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Wall per segment',
                                      '${wallEachM2.toStringAsFixed(3)} m²',
                                      Icons.account_balance_rounded,
                                    ),
                                  ),
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Measured length',
                                      '${L.toStringAsFixed(3)} m',
                                      Icons.route_rounded,
                                    ),
                                  ),
                                  SizedBox(
                                    width: 260,
                                    child: fwMetric(
                                      'Building factor',
                                      '×$factor',
                                      Icons.functions_rounded,
                                    ),
                                  ),
                                  if (includeDpc)
                                    SizedBox(
                                      width: 260,
                                      child: fwMetric(
                                        'DPC total',
                                        '${derivedLengthTotalM.toStringAsFixed(3)} m',
                                        Icons.horizontal_rule_rounded,
                                      ),
                                    ),
                                  if (includeAntiTermite)
                                    SizedBox(
                                      width: 260,
                                      child: fwMetric(
                                        'Anti-termite total',
                                        '${derivedLengthTotalM.toStringAsFixed(3)} m',
                                        Icons.pest_control_outlined,
                                      ),
                                    ),
                                ],
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                  actions: [
                    TextButton(
                      onPressed:
                          () => Get.back(result: FoundationSaveAction.cancel),
                      child: const Text('Cancel'),
                    ),
                    FilledButton.icon(
                      onPressed:
                          hasRequiredBoqs
                              ? () =>
                                  Get.back(result: FoundationSaveAction.finish)
                              : null,
                      icon: const Icon(Icons.save_rounded),
                      label: const Text('Save'),
                    ),
                  ],
                );
              },
            ),
            barrierDismissible: false,
          ) ??
          FoundationSaveAction.cancel;

      if (action == FoundationSaveAction.hide) {
        await _waitForMeasurementDialogRestore(
          title: 'Foundation wall',
          icon: Icons.account_balance_rounded,
        );
      }
    } while (action == FoundationSaveAction.hide);

    clearFoundationDraftPoints();
    update(['viewer']);

    if (action == FoundationSaveAction.cancel) {
      lengthCtrl.dispose();
      factorCtrl.dispose();
      trenchWidthCtrl.dispose();
      trenchDepthCtrl.dispose();
      workingSpaceCtrl.dispose();
      blindingWidthCtrl.dispose();
      blindingThkCtrl.dispose();
      stripWidthCtrl.dispose();
      stripThkCtrl.dispose();
      wallThkCtrl.dispose();
      wallHeightCtrl.dispose();
      return FoundationSaveAction.cancel;
    }

    // ----------------------------
    // Minimal validation: BOQs required
    // ----------------------------
    if (boqExc == null ||
        boqBackfill == null ||
        boqDisposal == null ||
        boqBlinding == null ||
        boqStrip == null ||
        boqStripFormwork == null ||
        boqWall == null ||
        (includeDpc && boqDpc == null) ||
        (includeAntiTermite && boqAntiTermite == null)) {
      Get.snackbar(
        'Missing',
        'Pick a BOQ item for every included quantity before saving.',
      );
      lengthCtrl.dispose();
      factorCtrl.dispose();
      trenchWidthCtrl.dispose();
      trenchDepthCtrl.dispose();
      workingSpaceCtrl.dispose();
      blindingWidthCtrl.dispose();
      blindingThkCtrl.dispose();
      stripWidthCtrl.dispose();
      stripThkCtrl.dispose();
      wallThkCtrl.dispose();
      wallHeightCtrl.dispose();
      return FoundationSaveAction.cancel;
    }

    // ----------------------------
    // Recompute final numbers (using editable length + factor)
    // ----------------------------
    final lenFinalM = double.tryParse(lengthCtrl.text.trim()) ?? baseLengthM;
    final factor = factorFrom(factorCtrl);

    final trenchWBase = double.tryParse(trenchWidthCtrl.text.trim()) ?? 0.70;
    final workSpace = double.tryParse(workingSpaceCtrl.text.trim()) ?? 0.0;
    final trenchW = (trenchWBase + workSpace).clamp(0.0, double.infinity);
    final trenchD = double.tryParse(trenchDepthCtrl.text.trim()) ?? 1.2;

    final stripW = double.tryParse(stripWidthCtrl.text.trim()) ?? 0.70;
    final stripT = double.tryParse(stripThkCtrl.text.trim()) ?? 0.23;
    final blindingT = double.tryParse(blindingThkCtrl.text.trim()) ?? 0.05;

    final wallT = double.tryParse(wallThkCtrl.text.trim()) ?? 0.23;
    final wallH = double.tryParse(wallHeightCtrl.text.trim()) ?? 0.6;

    final blindW = double.tryParse(blindingWidthCtrl.text.trim()) ?? stripW;

    // EACH
    final excavationEachM3 = trenchW * trenchD * lenFinalM;
    final stripEachM3 = stripW * stripT * lenFinalM;
    final stripFormworkEachM2 = 2 * stripT * lenFinalM;
    final blindingEachM2 = blindW * lenFinalM;
    final wallEachM2 = wallH * lenFinalM;

    final wallVolEachM3 = wallT * wallH * lenFinalM;

    double deducted = 0.0;
    if (includeStripVolInBackfill) deducted += stripEachM3;
    if (includeWallVolInBackfill) deducted += wallVolEachM3;

    final backfillEachM3 = (excavationEachM3 - deducted).clamp(
      0.0,
      double.infinity,
    );

    final disposalEachM3 =
        reuseForBackfill
            ? (excavationEachM3 - backfillEachM3).clamp(0.0, double.infinity)
            : excavationEachM3;

    // TOTAL
    final excavationTotalM3 = excavationEachM3 * factor;
    final backfillTotalM3 = backfillEachM3 * factor;
    final disposalTotalM3 = disposalEachM3 * factor;
    final blindingTotalM2 = blindingEachM2 * factor;
    final stripTotalM3 = stripEachM3 * factor;
    final stripFormworkTotalM2 = stripFormworkEachM2 * factor;
    final wallTotalM2 = wallEachM2 * factor;
    final derivedLengthTotalM = lenFinalM * factor;

    // ----------------------------
    // ✅ Persist defaults for next segment (Length is NOT remembered)
    // ----------------------------
    if (rememberForNext) {
      lastFoundationDefaults = {
        'rememberForNext': true,

        // ✅ factor remembered
        'buildingFactor': factor,

        'trenchWidth': trenchWBase,
        'trenchDepth': trenchD,
        'workingSpace': workSpace,

        'blindingWidth': blindW,
        'blindingThk': blindingT,

        'stripWidth': stripW,
        'stripThk': stripT,

        'wallThk': wallT,
        'wallHeight': wallH,
        'autoWallHeight': autoWallHeight,

        'reuseForBackfill': reuseForBackfill,
        'includeStripVolInBackfill': includeStripVolInBackfill,
        'includeWallVolInBackfill': includeWallVolInBackfill,
        'includeDpc': includeDpc,
        'includeAntiTermite': includeAntiTermite,

        // BOQ picks
        'boqExc': pickToMap(boqExc),
        'boqBackfill': pickToMap(boqBackfill),
        'boqDisposal': pickToMap(boqDisposal),
        'boqBlinding': pickToMap(boqBlinding),
        'boqStrip': pickToMap(boqStrip),
        'boqStripFormwork': pickToMap(boqStripFormwork),
        'boqWall': pickToMap(boqWall),
        'boqDpc': pickToMap(boqDpc),
        'boqAntiTermite': pickToMap(boqAntiTermite),
      };
    } else {
      lastFoundationDefaults['rememberForNext'] = false;
    }

    // ----------------------------
    // Firestore payload helper
    // ----------------------------
    final now = FieldValue.serverTimestamp();

    Map<String, dynamic> base({
      required String type,
      required String unit,
      required double valueEach,
      required double valueTotal,
      required BoqPick b,
    }) => {
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,

      'measureType': 'foundationWall',
      'type': type,
      'unit': unit,

      // ✅ factor quantities
      'valueEach': valueEach,
      'value': valueTotal,
      'buildingFactor': factor,

      'boqItemId': b.id,
      'boqCode': b.code,
      'boqDescription': b.description,

      // grouping
      'foundationGroupId': foundationGroupId,
      'segmentId': segmentId,

      // geometry + lengths
      'baseLengthM': baseLengthM, // measured
      'lengthEachM': lenFinalM,
      'lengthTotalM': lenFinalM * factor,

      'p1': {'x': p1.dx, 'y': p1.dy},
      'p2': {'x': p2.dx, 'y': p2.dy},
      if (polylineSegments != null && polylineSegments.isNotEmpty)
        'polylineSegments': polylineSegments,

      'color': (currentColor ?? Colors.teal).value,
      'createdAt': now,
      'updatedAt': now,
    };

    final foundationSaveProgress = 0.0.obs;
    final foundationSaveStatus = 'Preparing foundation quantities...'.obs;

    void showFoundationSavingDialog() {
      Get.dialog(
        Obx(() {
          final progress = foundationSaveProgress.value.clamp(0.0, 1.0);
          return AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(24),
            ),
            title: const Row(
              children: [
                Icon(Icons.cloud_upload_rounded, color: Color(0xFF155EEF)),
                SizedBox(width: 10),
                Text('Saving foundation wall...'),
              ],
            ),
            content: SizedBox(
              width: 390,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  LinearProgressIndicator(value: progress),
                  const SizedBox(height: 14),
                  Text(
                    foundationSaveStatus.value,
                    style: const TextStyle(fontWeight: FontWeight.w700),
                  ),
                  const SizedBox(height: 8),
                  Text(
                    '${(progress * 100).toStringAsFixed(0)}%',
                    style: const TextStyle(
                      color: Color(0xFF155EEF),
                      fontSize: 20,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
                ],
              ),
            ),
          );
        }),
        barrierDismissible: false,
      );
    }

    showFoundationSavingDialog();
    foundationSaveProgress.value = 0.10;

    try {
      final batch = FirebaseFirestore.instance.batch();
      foundationSaveStatus.value = 'Preparing BOQ outputs...';
      foundationSaveProgress.value = 0.35;

      batch.set(
        measurementsRef.doc('$segmentId-exc'),
        base(
          type: 'excavation',
          unit: 'm3',
          valueEach: excavationEachM3,
          valueTotal: excavationTotalM3,
          b: boqExc!,
        ),
      );
      batch.set(
        measurementsRef.doc('$segmentId-bk'),
        base(
          type: 'backfill',
          unit: 'm3',
          valueEach: backfillEachM3,
          valueTotal: backfillTotalM3,
          b: boqBackfill!,
        ),
      );
      batch.set(
        measurementsRef.doc('$segmentId-dis'),
        base(
          type: 'disposal',
          unit: 'm3',
          valueEach: disposalEachM3,
          valueTotal: disposalTotalM3,
          b: boqDisposal!,
        ),
      );
      batch.set(
        measurementsRef.doc('$segmentId-bl'),
        base(
          type: 'blinding',
          unit: 'm2',
          valueEach: blindingEachM2,
          valueTotal: blindingTotalM2,
          b: boqBlinding!,
        ),
      );

      batch.set(
        measurementsRef.doc('$segmentId-sc'),
        base(
          type: 'stripConcrete',
          unit: 'm3',
          valueEach: stripEachM3,
          valueTotal: stripTotalM3,
          b: boqStrip!,
        ),
      );
      batch.set(
        measurementsRef.doc('$segmentId-sf'),
        base(
          type: 'stripFormwork2Side',
          unit: 'm2',
          valueEach: stripFormworkEachM2,
          valueTotal: stripFormworkTotalM2,
          b: boqStripFormwork!,
        ),
      );

      batch.set(
        measurementsRef.doc('$segmentId-wl'),
        base(
          type: 'foundationWall',
          unit: 'm2',
          valueEach: wallEachM2,
          valueTotal: wallTotalM2,
          b: boqWall!,
        ),
      );

      if (includeDpc) {
        batch.set(measurementsRef.doc('$segmentId-dpc'), {
          ...base(
            type: 'foundationWallDpc',
            unit: 'm',
            valueEach: lenFinalM,
            valueTotal: derivedLengthTotalM,
            b: boqDpc!,
          ),
          'label': 'Damp-proof course (DPC)',
          'derivedFrom': 'foundationWallLength',
        });
      }

      if (includeAntiTermite) {
        batch.set(measurementsRef.doc('$segmentId-at'), {
          ...base(
            type: 'foundationWallAntiTermite',
            unit: 'm',
            valueEach: lenFinalM,
            valueTotal: derivedLengthTotalM,
            b: boqAntiTermite!,
          ),
          'label': 'Anti-termite treatment',
          'derivedFrom': 'foundationWallLength',
        });
      }

      // optional: one group meta doc (helps summaries)
      batch.set(measurementsRef.doc('$foundationGroupId-group'), {
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'measureType': 'foundationWall',
        'type': 'foundationWallGroup',
        'foundationGroupId': foundationGroupId,
        'buildingFactor': factor,
        'updatedAt': now,
        'createdAt': now,
      }, SetOptions(merge: true));

      foundationSaveStatus.value = 'Uploading BOQ outputs...';
      foundationSaveProgress.value = 0.72;
      await batch.commit();
      foundationSaveStatus.value = 'Finalizing...';
      foundationSaveProgress.value = 0.95;
      await Future<void>.delayed(const Duration(milliseconds: 180));
      foundationSaveProgress.value = 1.0;
      foundationSaveStatus.value = 'Saved successfully.';
      await Future<void>.delayed(const Duration(milliseconds: 220));
      if (Get.isDialogOpen == true) Get.back();

      Get.snackbar('Saved', 'Foundation wall segment saved (×$factor).');
    } catch (e) {
      if (Get.isDialogOpen == true) Get.back();
      Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
      action = FoundationSaveAction.cancel;
    } finally {
      lengthCtrl.dispose();
      factorCtrl.dispose();
      trenchWidthCtrl.dispose();
      trenchDepthCtrl.dispose();
      workingSpaceCtrl.dispose();
      blindingWidthCtrl.dispose();
      blindingThkCtrl.dispose();
      stripWidthCtrl.dispose();
      stripThkCtrl.dispose();
      wallThkCtrl.dispose();
      wallHeightCtrl.dispose();
    }

    if (action == FoundationSaveAction.finish) {
      draftFoundationGroupId = null;
    }

    update(['viewer', 'summary']);
    return action;
  }

  Future<void> openCeilingFinishesFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,
    required String projectId,
    required String buildingId,
    required String drawingId,
    // required CollectionReference<Map<String, dynamic>> measurementsRef,
    required Color currentColor,
    required String? activeLabel,
    String initialSurfaceKind = 'ceiling',
    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    // ✅ pass the remembered defaults map from controller
    // required Map<String, dynamic> lastCeilingDefaults,

    // optional: if you want to keep same group while adding segments
    // String? draftCeilingGroupId,
  }) async {
    if (polygon.length < 3) return;

    final requestedSurface = initialSurfaceKind.trim().toLowerCase();
    final finishToolKey = requestedSurface == 'ceiling' ? 'ceiling' : 'tiling';
    if (_pendingFinishPolygons.isNotEmpty &&
        (_pendingFinishDrawingId != drawingId ||
            _pendingFinishToolKey != finishToolKey)) {
      clearPendingFinishSession();
    }
    final sessionPolygons = <List<Offset>>[
      ..._pendingFinishPolygons.map(List<Offset>.from),
      List<Offset>.from(polygon),
    ];
    final restoredState = _pendingFinishFormState;
    final finishColorValue = _pendingFinishColorValue ?? currentColor.value;

    // ---------- calibration ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM =
        (drawingData['pixelsPerUnit'] is num)
            ? (drawingData['pixelsPerUnit'] as num).toDouble()
            : double.tryParse('${drawingData['pixelsPerUnit']}') ?? 0.0;

    if (!calibrated || pxPerM <= 0) {
      Get.snackbar('Not calibrated', 'Calibrate drawing to measure finishes.');
      return;
    }

    // ---------- geometry ----------
    double areaPx2(List<Offset> pts) {
      double sum = 0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        sum += (a.dx * b.dy) - (b.dx * a.dy);
      }
      return (sum / 2.0).abs();
    }

    double perimPx(List<Offset> pts) {
      double s = 0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        final dx = b.dx - a.dx;
        final dy = b.dy - a.dy;
        s += math.sqrt(dx * dx + dy * dy);
      }
      return s;
    }

    final polygonAreasM2 =
        sessionPolygons
            .map((points) => areaPx2(points) / (pxPerM * pxPerM))
            .toList();
    final polygonPerimetersM =
        sessionPolygons.map((points) => perimPx(points) / pxPerM).toList();
    final areaM2One = polygonAreasM2.fold<double>(
      0,
      (sum, value) => sum + value,
    );
    final perimeterMOne = polygonPerimetersM.fold<double>(
      0,
      (sum, value) => sum + value,
    );

    // ---------- helpers ----------
    double _d(dynamic v, double fb) =>
        (v is num) ? v.toDouble() : double.tryParse('$v') ?? fb;
    int _i(dynamic v, int fb) => int.tryParse('${v ?? ''}') ?? fb;
    String _s(dynamic v) => (v ?? '').toString().trim();

    TextEditingController ctrlNum(String key, String fallback) {
      final v = restoredState?[key] ?? lastCeilingDefaults[key];
      return TextEditingController(text: v == null ? fallback : '$v');
    }

    TextEditingController ctrlText(String key) {
      final v = restoredState?[key] ?? lastCeilingDefaults[key];
      return TextEditingController(text: v == null ? '' : '$v');
    }

    bool lastBool(String key, bool fb) {
      final v = restoredState?[key] ?? lastCeilingDefaults[key];
      return (v is bool) ? v : fb;
    }

    TextEditingController floorCtrl(String key, String fallback) {
      final v = restoredState?[key] ?? lastTileDefaults[key];
      return TextEditingController(text: v == null ? fallback : '$v');
    }

    TextEditingController floorTextCtrl(String key) {
      final v = restoredState?[key] ?? lastTileDefaults[key];
      return TextEditingController(text: v == null ? '' : '$v');
    }

    bool lastFloorBool(String key, bool fb) {
      final v = restoredState?[key] ?? lastTileDefaults[key];
      return v is bool ? v : fb;
    }

    Future<void> _pickInto(
      TextEditingController code,
      TextEditingController desc,
      BuildContext ctx,
    ) async {
      final pick = await showBoqPickerDialog(context: ctx);
      if (pick == null) return;
      code.text = pick.code.trim();
      desc.text = pick.description.trim();
    }

    // ---------- controllers (REMEMBERED) ----------
    final factorCtrl = ctrlNum('buildingFactor', '1'); // x buildings/floors
    final qtyCtrl = ctrlNum('qtySamePolygon', '1'); // same size repeated

    final wastePctCtrl = ctrlNum('wastePct', '0'); // 0..30 typically

    // Cornice
    final useCorniceOverride = ValueNotifier<bool>(
      lastBool('useCorniceOverride', false),
    );
    final corniceLenOverrideCtrl = ctrlNum(
      'corniceLenOverrideM',
      perimeterMOne.toStringAsFixed(3),
    );

    // Access panels
    final panelWmmCtrl = ctrlNum('panelWmm', '600');
    final panelHmmCtrl = ctrlNum('panelHmm', '600');
    final panelExtraPctCtrl = ctrlNum('panelExtraPct', '0'); // extra % panels

    // Branderings spacing
    final brandSpacingMmCtrl = ctrlNum('brandSpacingMm', '600');

    // Includes
    final includeGypsum = ValueNotifier<bool>(lastBool('includeGypsum', true));
    final includeCornice = ValueNotifier<bool>(
      lastBool('includeCornice', true),
    );
    final includeAccessPanels = ValueNotifier<bool>(
      lastBool('includeAccessPanels', true),
    );
    final includeBranderings = ValueNotifier<bool>(
      lastBool('includeBranderings', true),
    );

    // Optional: paint/decoration BOQs (same area m2)
    final includeDecorationPaint = ValueNotifier<bool>(
      lastBool('includeDecorationPaint', false),
    );

    // BOQs (REMEMBERED)
    final boqGypsumCode = ctrlText('boqGypsumCode');
    final boqGypsumDesc = ctrlText('boqGypsumDesc');

    final boqCorniceCode = ctrlText('boqCorniceCode');
    final boqCorniceDesc = ctrlText('boqCorniceDesc');

    final boqPanelsCode = ctrlText('boqPanelsCode');
    final boqPanelsDesc = ctrlText('boqPanelsDesc');

    final boqBranderingsCode = ctrlText('boqBranderingsCode');
    final boqBranderingsDesc = ctrlText('boqBranderingsDesc');

    final boqPaintCode = ctrlText('boqPaintCode');
    final boqPaintDesc = ctrlText('boqPaintDesc');

    // Floor / wall finish controls. These live in this dialog so ceiling and
    // floor finishes share the same traced polygon workflow.
    final restoredSurfaceKind =
        (restoredState?['surfaceKind'] ?? initialSurfaceKind)
            .toString()
            .trim()
            .toLowerCase();
    var surfaceKind =
        const {'ceiling', 'floor', 'wall'}.contains(restoredSurfaceKind)
            ? restoredSurfaceKind
            : 'ceiling';
    var includeCeilingInSave =
        restoredState?['includeCeilingInSave'] is bool
            ? restoredState!['includeCeilingInSave'] as bool
            : surfaceKind == 'ceiling';
    var includeFloorWallInSave =
        restoredState?['includeFloorWallInSave'] is bool
            ? restoredState!['includeFloorWallInSave'] as bool
            : surfaceKind != 'ceiling';
    var floorFinishType =
        (restoredState?['floorFinishType'] ??
                lastTileDefaults['floorFinishType'] ??
                'tiles')
            .toString();
    if (!const {
      'tiles',
      'terrazzo',
      'sandScreed',
      'granolithicScreed',
    }.contains(floorFinishType)) {
      floorFinishType = 'tiles';
    }
    final floorSkirtingOverrideCtrl = floorCtrl(
      'floorSkirtingOverrideM',
      perimeterMOne.toStringAsFixed(3),
    );
    final terrazzoTreadsLengthCtrl = floorCtrl('terrazzoTreadsLengthM', '0');
    final wallOpeningDeductionCtrl = floorCtrl('wallOpeningDeductionM2', '0');
    final includeFloorSkirting = ValueNotifier<bool>(
      lastFloorBool('includeFloorSkirting', true),
    );
    final useFloorSkirtingOverride = ValueNotifier<bool>(
      lastFloorBool('useFloorSkirtingOverride', false),
    );
    final includeFloorBacking = ValueNotifier<bool>(
      lastFloorBool('includeFloorBacking', true),
    );
    final includeTerrazzoTreads = ValueNotifier<bool>(
      lastFloorBool('includeTerrazzoTreads', false),
    );
    final includeWallOpeningDeduction = ValueNotifier<bool>(
      lastFloorBool('includeWallOpeningDeduction', false),
    );
    final floorFinishBoqCode = floorTextCtrl('floorFinishBoqCode');
    final floorFinishBoqDesc = floorTextCtrl('floorFinishBoqDesc');
    final floorBackingBoqCode = floorTextCtrl('floorBackingBoqCode');
    final floorBackingBoqDesc = floorTextCtrl('floorBackingBoqDesc');
    final floorSkirtingBoqCode = floorTextCtrl('floorSkirtingBoqCode');
    final floorSkirtingBoqDesc = floorTextCtrl('floorSkirtingBoqDesc');
    final terrazzoTreadsBoqCode = floorTextCtrl('terrazzoTreadsBoqCode');
    final terrazzoTreadsBoqDesc = floorTextCtrl('terrazzoTreadsBoqDesc');

    Map<String, dynamic> captureFormState() => <String, dynamic>{
      'surfaceKind': surfaceKind,
      'includeCeilingInSave': includeCeilingInSave,
      'includeFloorWallInSave': includeFloorWallInSave,
      'buildingFactor': factorCtrl.text,
      'qtySamePolygon': qtyCtrl.text,
      'wastePct': wastePctCtrl.text,
      'useCorniceOverride': useCorniceOverride.value,
      'corniceLenOverrideM': corniceLenOverrideCtrl.text,
      'panelWmm': panelWmmCtrl.text,
      'panelHmm': panelHmmCtrl.text,
      'panelExtraPct': panelExtraPctCtrl.text,
      'brandSpacingMm': brandSpacingMmCtrl.text,
      'includeGypsum': includeGypsum.value,
      'includeCornice': includeCornice.value,
      'includeAccessPanels': includeAccessPanels.value,
      'includeBranderings': includeBranderings.value,
      'includeDecorationPaint': includeDecorationPaint.value,
      'boqGypsumCode': boqGypsumCode.text,
      'boqGypsumDesc': boqGypsumDesc.text,
      'boqCorniceCode': boqCorniceCode.text,
      'boqCorniceDesc': boqCorniceDesc.text,
      'boqPanelsCode': boqPanelsCode.text,
      'boqPanelsDesc': boqPanelsDesc.text,
      'boqBranderingsCode': boqBranderingsCode.text,
      'boqBranderingsDesc': boqBranderingsDesc.text,
      'boqPaintCode': boqPaintCode.text,
      'boqPaintDesc': boqPaintDesc.text,
      'floorFinishType': floorFinishType,
      'floorSkirtingOverrideM': floorSkirtingOverrideCtrl.text,
      'terrazzoTreadsLengthM': terrazzoTreadsLengthCtrl.text,
      'wallOpeningDeductionM2': wallOpeningDeductionCtrl.text,
      'includeFloorSkirting': includeFloorSkirting.value,
      'useFloorSkirtingOverride': useFloorSkirtingOverride.value,
      'includeFloorBacking': includeFloorBacking.value,
      'includeTerrazzoTreads': includeTerrazzoTreads.value,
      'includeWallOpeningDeduction': includeWallOpeningDeduction.value,
      'floorFinishBoqCode': floorFinishBoqCode.text,
      'floorFinishBoqDesc': floorFinishBoqDesc.text,
      'floorBackingBoqCode': floorBackingBoqCode.text,
      'floorBackingBoqDesc': floorBackingBoqDesc.text,
      'floorSkirtingBoqCode': floorSkirtingBoqCode.text,
      'floorSkirtingBoqDesc': floorSkirtingBoqDesc.text,
      'terrazzoTreadsBoqCode': terrazzoTreadsBoqCode.text,
      'terrazzoTreadsBoqDesc': terrazzoTreadsBoqDesc.text,
    };

    String? errorText;

    // ---------- dialog ----------
    final action =
        await Get.dialog<_CeilingFinishesDialogAction>(
          StatefulBuilder(
            builder: (ctx, setState) {
              final factor = _i(factorCtrl.text, 1).clamp(1, 999999);
              final qty = _i(qtyCtrl.text, 1).clamp(1, 999999);
              final mult = factor * qty;

              final wastePct = _d(wastePctCtrl.text, 0).clamp(0.0, 50.0);
              final wasteFactor = 1.0 + (wastePct / 100.0);

              final totalAreaM2 = areaM2One * mult;
              final totalPerimM = perimeterMOne * mult;

              // cornice length
              final corniceLenMOne =
                  useCorniceOverride.value
                      ? _d(corniceLenOverrideCtrl.text, perimeterMOne)
                      : perimeterMOne;
              final corniceLenMTotal = corniceLenMOne * mult;

              // access panels
              final pw = (_i(panelWmmCtrl.text, 600).clamp(50, 5000)) / 1000.0;
              final ph = (_i(panelHmmCtrl.text, 600).clamp(50, 5000)) / 1000.0;
              final panelArea = (pw * ph).clamp(0.0001, 999999.0);
              final basePanels = (totalAreaM2 / panelArea);
              final panelExtraPct = _d(
                panelExtraPctCtrl.text,
                0,
              ).clamp(0.0, 200.0);
              final panelsWithExtra =
                  basePanels * (1.0 + panelExtraPct / 100.0);
              final panelsCount = panelsWithExtra.ceil();

              // branderings approximation:
              // we assume ceiling strips in one direction:
              // total length ≈ (area / spacing) * 1.0   (dimensionless)
              // This approximates total running meters of battens.
              final spacingM =
                  (_i(brandSpacingMmCtrl.text, 600).clamp(50, 5000)) / 1000.0;
              final branderingsMTotal =
                  spacingM > 0 ? (totalAreaM2 / spacingM) : 0.0;

              // final quantities with waste (where applicable)
              final gypsumM2 = totalAreaM2 * wasteFactor;
              final paintM2 = totalAreaM2 * wasteFactor;
              final corniceM = corniceLenMTotal * wasteFactor;
              final branderingsM = branderingsMTotal * wasteFactor;

              final wallOpeningDeduction =
                  surfaceKind == 'wall' && includeWallOpeningDeduction.value
                      ? _d(
                        wallOpeningDeductionCtrl.text,
                        0,
                      ).clamp(0.0, totalAreaM2)
                      : 0.0;
              final floorFinishAreaM2 =
                  (totalAreaM2 - wallOpeningDeduction) * wasteFactor;
              final floorSkirtingMOne =
                  useFloorSkirtingOverride.value
                      ? _d(floorSkirtingOverrideCtrl.text, perimeterMOne)
                      : perimeterMOne;
              final floorSkirtingM = floorSkirtingMOne * mult;
              final terrazzoTreadsMOne = _d(
                terrazzoTreadsLengthCtrl.text,
                0,
              ).clamp(0.0, double.infinity);
              final terrazzoTreadsM = terrazzoTreadsMOne * mult;

              String floorFinishLabel([String? savedSurfaceKind]) {
                if ((savedSurfaceKind ?? surfaceKind) == 'wall') {
                  return 'Wall tiles';
                }
                switch (floorFinishType) {
                  case 'terrazzo':
                    return 'Terrazzo floor finish';
                  case 'sandScreed':
                    return 'Sand and cement screed';
                  case 'granolithicScreed':
                    return 'Granolithic screed';
                  default:
                    return 'Floor tiles';
                }
              }

              Widget headerPill(IconData icon, String label) {
                return Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 7,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.14),
                    borderRadius: BorderRadius.circular(999),
                    border: Border.all(color: Colors.white.withOpacity(0.20)),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(icon, size: 16, color: Colors.white),
                      const SizedBox(width: 6),
                      Text(
                        label,
                        style: const TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.w800,
                          fontSize: 12,
                        ),
                      ),
                    ],
                  ),
                );
              }

              Widget metricCard(String label, String value, IconData icon) {
                return Expanded(
                  child: Container(
                    padding: const EdgeInsets.all(14),
                    decoration: BoxDecoration(
                      gradient: const LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [Color(0xFFEFF4FF), Color(0xFFF8FAFC)],
                      ),
                      borderRadius: BorderRadius.circular(18),
                      border: Border.all(color: const Color(0xFFD9E5FF)),
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 38,
                          height: 38,
                          decoration: BoxDecoration(
                            color: AqsColors.primary,
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Icon(icon, color: Colors.white, size: 20),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                label,
                                style: const TextStyle(
                                  color: AqsColors.muted,
                                  fontSize: 12,
                                  fontWeight: FontWeight.w800,
                                ),
                              ),
                              const SizedBox(height: 3),
                              Text(
                                value,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: AqsColors.ink,
                                  fontSize: 16,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }

              Widget finishBoqRow({
                required String title,
                required TextEditingController code,
                required TextEditingController desc,
              }) {
                return Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: AqsColors.border),
                  ),
                  child: Row(
                    children: [
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              style: const TextStyle(
                                color: AqsColors.muted,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                            const SizedBox(height: 5),
                            Text(
                              code.text.trim().isEmpty
                                  ? 'No BOQ selected'
                                  : '${code.text.trim()} — ${desc.text.trim()}',
                              maxLines: 2,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                color:
                                    code.text.trim().isEmpty
                                        ? AqsColors.subtle
                                        : AqsColors.ink,
                                fontWeight: FontWeight.w800,
                              ),
                            ),
                          ],
                        ),
                      ),
                      const SizedBox(width: 10),
                      OutlinedButton.icon(
                        onPressed: () async {
                          await _pickInto(code, desc, ctx);
                          setState(() {});
                        },
                        icon: const Icon(Icons.search_rounded),
                        label: const Text('Pick'),
                      ),
                    ],
                  ),
                );
              }

              return Dialog(
                insetPadding: const EdgeInsets.all(24),
                backgroundColor: Colors.transparent,
                surfaceTintColor: Colors.transparent,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(30),
                ),
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 860),
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(30),
                      boxShadow: [
                        BoxShadow(
                          color: AqsColors.primaryDark.withOpacity(0.20),
                          blurRadius: 36,
                          offset: const Offset(0, 20),
                        ),
                      ],
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(30),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Container(
                            width: double.infinity,
                            padding: const EdgeInsets.fromLTRB(28, 26, 24, 24),
                            decoration: const BoxDecoration(
                              gradient: LinearGradient(
                                begin: Alignment.topLeft,
                                end: Alignment.bottomRight,
                                colors: [
                                  AqsColors.primaryDark,
                                  AqsColors.primary,
                                ],
                              ),
                            ),
                            child: Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Container(
                                  width: 48,
                                  height: 48,
                                  decoration: BoxDecoration(
                                    color: Colors.white.withOpacity(0.14),
                                    borderRadius: BorderRadius.circular(16),
                                    border: Border.all(
                                      color: Colors.white.withOpacity(0.22),
                                    ),
                                  ),
                                  child: const Icon(
                                    Icons.grid_view_rounded,
                                    color: Colors.white,
                                  ),
                                ),
                                const SizedBox(width: 14),
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        'Ceiling & floor finishes',
                                        style: const TextStyle(
                                          color: Colors.white,
                                          fontSize: 26,
                                          fontWeight: FontWeight.w900,
                                        ),
                                      ),
                                      const SizedBox(height: 8),
                                      Wrap(
                                        spacing: 8,
                                        runSpacing: 8,
                                        children: [
                                          headerPill(
                                            Icons.square_foot_rounded,
                                            '${areaM2One.toStringAsFixed(3)} m² combined',
                                          ),
                                          headerPill(
                                            Icons.timeline_rounded,
                                            '${perimeterMOne.toStringAsFixed(3)} m combined',
                                          ),
                                          headerPill(
                                            Icons.layers_outlined,
                                            '${sessionPolygons.length} area${sessionPolygons.length == 1 ? '' : 's'} selected',
                                          ),
                                          headerPill(
                                            Icons.copy_all_rounded,
                                            'Multiplier $mult',
                                          ),
                                        ],
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                            ),
                          ),
                          Flexible(
                            child: SingleChildScrollView(
                              padding: const EdgeInsets.all(28),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  SegmentedButton<String>(
                                    segments: const [
                                      ButtonSegment(
                                        value: 'ceiling',
                                        label: Text('Ceiling'),
                                        icon: Icon(Icons.border_top_rounded),
                                      ),
                                      ButtonSegment(
                                        value: 'floor',
                                        label: Text('Floor'),
                                        icon: Icon(Icons.grid_on_rounded),
                                      ),
                                      ButtonSegment(
                                        value: 'wall',
                                        label: Text('Wall tiles'),
                                        icon: Icon(Icons.format_paint_rounded),
                                      ),
                                    ],
                                    selected: {surfaceKind},
                                    onSelectionChanged:
                                        (selection) => setState(() {
                                          surfaceKind = selection.first;
                                          if (surfaceKind == 'ceiling') {
                                            includeCeilingInSave = true;
                                          } else {
                                            includeFloorWallInSave = true;
                                          }
                                          errorText = null;
                                        }),
                                  ),
                                  CheckboxListTile(
                                    value:
                                        surfaceKind == 'ceiling'
                                            ? includeCeilingInSave
                                            : includeFloorWallInSave,
                                    onChanged:
                                        (value) => setState(() {
                                          if (surfaceKind == 'ceiling') {
                                            includeCeilingInSave =
                                                value ?? false;
                                          } else {
                                            includeFloorWallInSave =
                                                value ?? false;
                                          }
                                        }),
                                    contentPadding: EdgeInsets.zero,
                                    title: Text(
                                      surfaceKind == 'ceiling'
                                          ? 'Include ceiling finishes in this save'
                                          : 'Include ${surfaceKind == 'wall' ? 'wall tiles' : 'floor finishes'} in this save',
                                    ),
                                    subtitle: Text(
                                      'Saving: ${[if (includeCeilingInSave) 'Ceiling', if (includeFloorWallInSave) surfaceKind == 'wall' ? 'Wall tiles' : 'Floor'].join(' + ')}',
                                    ),
                                  ),
                                  const SizedBox(height: 16),
                                  Row(
                                    children: [
                                      metricCard(
                                        'Total area',
                                        '${totalAreaM2.toStringAsFixed(3)} m²',
                                        Icons.crop_square_rounded,
                                      ),
                                      const SizedBox(width: 10),
                                      metricCard(
                                        'Total perimeter',
                                        '${totalPerimM.toStringAsFixed(3)} m',
                                        Icons.timeline_rounded,
                                      ),
                                      const SizedBox(width: 10),
                                      metricCard(
                                        'Waste',
                                        '${wastePct.toStringAsFixed(1)}%',
                                        Icons.percent_rounded,
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 16),

                                  Row(
                                    children: [
                                      Expanded(
                                        child: TextField(
                                          controller: factorCtrl,
                                          keyboardType: TextInputType.number,
                                          decoration: const InputDecoration(
                                            labelText:
                                                'Multiply factor (x buildings)',
                                            border: OutlineInputBorder(),
                                            isDense: true,
                                          ),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                      ),
                                      const SizedBox(width: 8),
                                      Expanded(
                                        child: TextField(
                                          controller: qtyCtrl,
                                          keyboardType: TextInputType.number,
                                          decoration: const InputDecoration(
                                            labelText:
                                                'Qty same panels (same polygon)',
                                            border: OutlineInputBorder(),
                                            isDense: true,
                                          ),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                      ),
                                    ],
                                  ),
                                  const SizedBox(height: 8),

                                  TextField(
                                    controller: wastePctCtrl,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                          decimal: true,
                                        ),
                                    decoration: const InputDecoration(
                                      labelText: 'Waste / laps / allowance (%)',
                                      border: OutlineInputBorder(),
                                      isDense: true,
                                    ),
                                    onChanged: (_) => setState(() {}),
                                  ),

                                  const SizedBox(height: 8),

                                  if (errorText != null) ...[
                                    const SizedBox(height: 8),
                                    Container(
                                      width: double.infinity,
                                      padding: const EdgeInsets.all(12),
                                      decoration: BoxDecoration(
                                        color: const Color(0xFFFFF1F3),
                                        borderRadius: BorderRadius.circular(14),
                                        border: Border.all(
                                          color: const Color(0xFFFECDD6),
                                        ),
                                      ),
                                      child: Text(
                                        errorText!,
                                        style: const TextStyle(
                                          color: Color(0xFFC01048),
                                          fontWeight: FontWeight.w700,
                                        ),
                                      ),
                                    ),
                                  ],

                                  if (surfaceKind == 'ceiling') ...[
                                    const Divider(height: 22),

                                    // 1) Gypsum ceiling (m2)
                                    ValueListenableBuilder<bool>(
                                      valueListenable: includeGypsum,
                                      builder:
                                          (_, v, __) => CheckboxListTile(
                                            value: v,
                                            onChanged:
                                                (x) => setState(
                                                  () =>
                                                      includeGypsum.value =
                                                          x ?? true,
                                                ),
                                            dense: true,
                                            contentPadding: EdgeInsets.zero,
                                            title: Text(
                                              'Gypsum plasterboards (m²) = ${gypsumM2.toStringAsFixed(3)}',
                                            ),
                                          ),
                                    ),
                                    if (includeGypsum.value) ...[
                                      Row(
                                        children: [
                                          Expanded(
                                            child: TextField(
                                              controller: boqGypsumCode,
                                              readOnly: true,
                                              decoration: const InputDecoration(
                                                labelText:
                                                    'BOQ: Gypsum ceiling (m²)',
                                                border: OutlineInputBorder(),
                                                isDense: true,
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 8),
                                          OutlinedButton.icon(
                                            onPressed: () async {
                                              await _pickInto(
                                                boqGypsumCode,
                                                boqGypsumDesc,
                                                ctx,
                                              );
                                              setState(() {});
                                            },
                                            icon: const Icon(
                                              Icons.search,
                                              size: 18,
                                            ),
                                            label: const Text('Pick'),
                                          ),
                                        ],
                                      ),
                                      const SizedBox(height: 6),
                                      Text(
                                        boqGypsumDesc.text,
                                        style: const TextStyle(fontSize: 11),
                                      ),
                                    ],

                                    const SizedBox(height: 12),

                                    // 2) Cornice (m)
                                    ValueListenableBuilder<bool>(
                                      valueListenable: includeCornice,
                                      builder:
                                          (_, v, __) => CheckboxListTile(
                                            value: v,
                                            onChanged:
                                                (x) => setState(
                                                  () =>
                                                      includeCornice.value =
                                                          x ?? true,
                                                ),
                                            dense: true,
                                            contentPadding: EdgeInsets.zero,
                                            title: Text(
                                              'Cornice (m) = ${corniceM.toStringAsFixed(3)}',
                                            ),
                                            subtitle: Text(
                                              useCorniceOverride.value
                                                  ? 'Using override length'
                                                  : 'Using polygon perimeter',
                                            ),
                                          ),
                                    ),
                                    if (includeCornice.value) ...[
                                      ValueListenableBuilder<bool>(
                                        valueListenable: useCorniceOverride,
                                        builder:
                                            (_, v, __) => CheckboxListTile(
                                              value: v,
                                              onChanged:
                                                  (x) => setState(
                                                    () =>
                                                        useCorniceOverride
                                                            .value = x ?? false,
                                                  ),
                                              dense: true,
                                              contentPadding: EdgeInsets.zero,
                                              title: const Text(
                                                'Override cornice length (m)',
                                              ),
                                            ),
                                      ),
                                      if (useCorniceOverride.value) ...[
                                        TextField(
                                          controller: corniceLenOverrideCtrl,
                                          keyboardType:
                                              const TextInputType.numberWithOptions(
                                                decimal: true,
                                              ),
                                          decoration: const InputDecoration(
                                            labelText:
                                                'Cornice length per ONE polygon (m)',
                                            border: OutlineInputBorder(),
                                            isDense: true,
                                          ),
                                          onChanged: (_) => setState(() {}),
                                        ),
                                        const SizedBox(height: 8),
                                      ],
                                      Row(
                                        children: [
                                          Expanded(
                                            child: TextField(
                                              controller: boqCorniceCode,
                                              readOnly: true,
                                              decoration: const InputDecoration(
                                                labelText: 'BOQ: Cornice (m)',
                                                border: OutlineInputBorder(),
                                                isDense: true,
                                              ),
                                            ),
                                          ),
                                          const SizedBox(width: 8),
                                          OutlinedButton.icon(
                                            onPressed: () async {
                                              await _pickInto(
                                                boqCorniceCode,
                                                boqCorniceDesc,
                                                ctx,
                                              );
                                              setState(() {});
                                            },
                                            icon: const Icon(
                                              Icons.search,
                                              size: 18,
                                            ),
                                            label: const Text('Pick'),
                                          ),
                                        ],
                                      ),
                                      const SizedBox(height: 6),
                                      Text(
                                        boqCorniceDesc.text,
                                        style: const TextStyle(fontSize: 11),
                                      ),
                                    ],

                                    const SizedBox(height: 12),

                                    // 3) Access panels (Nos)
                                    ValueListenableBuilder<bool>(
                                      valueListenable: includeAccessPanels,
                                      builder:
                                          (_, v, __) => CheckboxListTile(
                                            value: v,
                                            onChanged:
                                                (x) => setState(
                                                  () =>
                                                      includeAccessPanels
                                                          .value = x ?? true,
                                                ),
                                            dense: true,
                                            contentPadding: EdgeInsets.zero,
                                            title: Text(
                                              'Access panels (Nos) = $panelsCount',
                                            ),
                                            subtitle: Text(
                                              'Panel ${_i(panelWmmCtrl.text, 600)} x ${_i(panelHmmCtrl.text, 600)} mm',
                                            ),
                                          ),
                                    ),
                                    if (includeAccessPanels.value) ...[
                                      Row(
                                        children: [
                                          Expanded(
                                            child: TextField(
                                              controller: panelWmmCtrl,
                                              keyboardType:
                                                  TextInputType.number,
                                              decoration: const InputDecoration(
