                    FilledButton(
                      onPressed:
                          canSave
                              ? () {
                                // edge/tag + boq validation
                                final ridgeLen = _sumTag('ridge');
                                final hipLen = _sumTag('hip');
                                final valleyLen = _sumTag('valley');
                                final eaveLen = _sumTag('eave');

                                if (!timberOnly &&
                                    eaveLen > 0 &&
                                    boqFasciaCode.text.trim().isEmpty) {
                                  setState(
                                    () =>
                                        errorText =
                                            'Pick the fascia boarding BOQ for the tagged eave.',
                                  );
                                  return;
                                }

                                if (!timberOnly &&
                                    includeRidge.value &&
                                    boqRidgeCode.text.trim().isNotEmpty &&
                                    ridgeLen <= 0) {
                                  setState(
                                    () =>
                                        errorText =
                                            'Tag at least one edge as RIDGE (or untick ridge capping).',
                                  );
                                  return;
                                }
                                if (!timberOnly &&
                                    includeHips.value &&
                                    boqHipCode.text.trim().isNotEmpty &&
                                    hipLen <= 0) {
                                  setState(
                                    () =>
                                        errorText =
                                            'Tag at least one edge as HIP (or untick hip capping).',
                                  );
                                  return;
                                }
                                if (!timberOnly &&
                                    includeValleys.value &&
                                    boqValleyCode.text.trim().isNotEmpty &&
                                    valleyLen <= 0) {
                                  setState(
                                    () =>
                                        errorText =
                                            'Tag at least one edge as VALLEY (or untick valleys).',
                                  );
                                  return;
                                }

                                Get.back(result: true);
                              }
                              : null,
                      child: const Text('Save'),
