      includeSheeting.dispose();
      includeRidge.dispose();
      includeHips.dispose();
      includeValleys.dispose();
      includeRafters.dispose();
      includeWallPlates.dispose();
      includeTieBeams.dispose();
      includeKingPosts.dispose();
      includeStrutsPosts.dispose();
      includePurlins.dispose();

      boqSheetCode.dispose();
      boqSheetDesc.dispose();
      boqRidgeCode.dispose();
      boqRidgeDesc.dispose();
      boqHipCode.dispose();
      boqHipDesc.dispose();
      boqValleyCode.dispose();
      boqValleyDesc.dispose();
      boqFasciaCode.dispose();
      boqFasciaDesc.dispose();

      boqRaftersCode.dispose();
      boqRaftersDesc.dispose();
      boqWallPlateCode.dispose();
      boqWallPlateDesc.dispose();
      boqTieCode.dispose();
      boqTieDesc.dispose();
      boqKingCode.dispose();
      boqKingDesc.dispose();
      boqStrutsCode.dispose();
      boqStrutsDesc.dispose();
      boqPurlinsCode.dispose();
      boqPurlinsDesc.dispose();
      return;
    }

    // ---------- compute for save ----------
    final factor = _i(factorCtrl.text, 1).clamp(1, 999999);
    final qty = _i(qtyCtrl.text, 1).clamp(1, 999999);
    final mult = factor * qty;

    final pitchDeg = _d(pitchDegCtrl.text, 30).clamp(0.0, 89.0);
    final pitchRad = _degToRad(pitchDeg);
    final barrelChordM = _d(barrelChordCtrl.text, 0.0);
    var barrelRadiusM = _d(barrelRadiusCtrl.text, 0.0);
    final barrelRiseM = _d(barrelRiseCtrl.text, 0.0);
    if (roofGeometry == 'barrel' &&
        barrelRadiusM <= 0 &&
        barrelChordM > 0 &&
        barrelRiseM > 0) {
      barrelRadiusM =
          (barrelChordM * barrelChordM) / (8 * barrelRiseM) + barrelRiseM / 2;
    }
    var developedWidthM = barrelChordM;
    var geometryFactor = 1.0;
    if (roofGeometry == 'pitched') {
      geometryFactor = (1.0 / math.cos(pitchRad)).clamp(1.0, 100.0).toDouble();
    } else if (roofGeometry == 'barrel') {
      final centralAngleRad = 2 * math.asin(barrelChordM / (2 * barrelRadiusM));
      developedWidthM = barrelRadiusM * centralAngleRad;
      geometryFactor = developedWidthM / barrelChordM;
    } else if (roofGeometry == 'custom') {
      geometryFactor = _d(customSurfaceFactorCtrl.text, 1.0);
    }

    final planAreaAll = planAreaM2One * mult;
    final perimeterAll = perimeterMOne * mult;

    final ridgeLenAll = _sumTag('ridge') * mult;
    final hipLenAll = _sumTag('hip') * mult;
    final valleyLenAll = _sumTag('valley') * mult;
    final eaveLenAll = _sumTag('eave') * mult;

    final eaveLenUsed =
        (eaveLenAll > 0) ? eaveLenAll : _fallbackEaveLen(perimeterAll);

    final spanPlanMAll =
        (eaveLenUsed > 0)
            ? (planAreaAll / eaveLenUsed)
            : math.sqrt(planAreaAll);
    final slopeSpanMAll = spanPlanMAll * geometryFactor;

    final purlinSpacingM =
        (_i(purlinSpacingMmCtrl.text, 1500).clamp(1, 1000000)) / 1000.0;
    final rafterSpacingM =
        (_i(rafterSpacingMmCtrl.text, 600).clamp(1, 1000000)) / 1000.0;

    final grossDevelopedAreaM2 = planAreaAll * geometryFactor;
    final openingDeductionM2One = _d(
      openingDeductionCtrl.text,
      0.0,
    ).clamp(0.0, double.infinity);
    final openingDeductionM2All = openingDeductionM2One * mult;
    final sheetingM2All = math.max(
      0.0,
      grossDevelopedAreaM2 - openingDeductionM2All,
    );
    final wastePercent = _d(wastePercentCtrl.text, 0.0).clamp(0.0, 100.0);
    final wasteAreaM2 = sheetingM2All * wastePercent / 100.0;
    final procurementAreaM2 = sheetingM2All + wasteAreaM2;

    final purlinCount = ((slopeSpanMAll / purlinSpacingM).ceil() + 1).clamp(
      0,
      999999,
    );
    final purlinsMAll = purlinCount * eaveLenUsed;

    final rafterCount = ((eaveLenUsed / rafterSpacingM).ceil() + 1).clamp(
      0,
      999999,
    );
    final raftersMAll = rafterCount * slopeSpanMAll;

    final wallPlatesMAll = eaveLenUsed;
    final tieBeamsMAll = rafterCount * spanPlanMAll;

    final trussSpacingM =
        (_i(trussSpacingMmCtrl.text, 2000).clamp(1, 1000000)) / 1000.0;
    final ridgeUsed = ridgeLenAll > 0 ? ridgeLenAll : eaveLenUsed;
    final trussCount =
        (ridgeUsed > 0)
            ? ((ridgeUsed / trussSpacingM).ceil() + 1).clamp(0, 999999)
            : 0;

    final kingH = _d(kingPostHeightCtrl.text, 1.0).clamp(0.0, 1000.0);
    final kingPostsMAll = trussCount * kingH;

    final strutsPerTruss = _i(strutsPerTrussCtrl.text, 2).clamp(0, 999999);
    final strutL = _d(strutLengthCtrl.text, 1.2).clamp(0.0, 1000.0);
    final strutsMAll = trussCount * strutsPerTruss * strutL;

    // ---------- save ----------
    // If you want persistent groupId like slabs, do:
    // draftRoofGroupId ??= measurementsRef.doc().id;
    // final roofGroupId = draftRoofGroupId!;
    final roofGroupId = measurementsRef.doc().id;

    final now = FieldValue.serverTimestamp();

    Map<String, dynamic> common() => {
      'projectId': projectId,
      'buildingId': buildingId,
      'drawingId': drawingId,
      'measureType':
          coveringOnly
              ? 'roofsheeting'
              : timberOnly
              ? 'compositeRoofing'
              : 'roofSheetingAndTimber',
      'roofGroupId': roofGroupId,
      'polygon': polyData,
      'color': currentColor.value,
      'label': activeLabel ?? 'Roof',
      'createdAt': now,
      'updatedAt': now,

      // multipliers
      'qtySamePolygon': qty,
      'buildingFactor': factor,
      'multiplierTotal': mult,

      // geometry and developed-surface calculation
      'roofGeometry': roofGeometry,
      'pitchDeg': pitchDeg,
      'useSlopeArea': roofGeometry == 'pitched',
      'slopeFactor': geometryFactor,
      'geometryFactor': geometryFactor,
      'barrelChordM': barrelChordM,
      'barrelRadiusM': barrelRadiusM,
      'barrelRiseM': barrelRiseM,
      'barrelDevelopedWidthM': developedWidthM,
      'customSurfaceFactor': _d(customSurfaceFactorCtrl.text, 1.0),

      // geometry base
      'planAreaM2_one': planAreaM2One,
      'perimeterM_one': perimeterMOne,
      'planAreaM2_total': planAreaAll,
      'perimeterM_total': perimeterAll,
      'grossDevelopedAreaM2_total': grossDevelopedAreaM2,
      'openingDeductionM2_one': openingDeductionM2One,
      'openingDeductionM2_total': openingDeductionM2All,
      'netCoveringAreaM2_total': sheetingM2All,
      'wastePercent': wastePercent,
      'wasteAreaM2_total': wasteAreaM2,
      'procurementAreaM2_total': procurementAreaM2,

      // tags snapshot
      'edgeTags':
          edges
              .map((e) => {'i': e.index, 'tag': e.tag, 'lenM': e.lengthM})
              .toList(),
      'edgeTotalsM': {
        for (final tag in const [
          'eave',
          'ridge',
          'hip',
          'valley',
          'verge',
          'gutter',
          'sideAbutment',
          'headAbutment',
          'apron',
          'penetration',
          'expansionJoint',
          'curvedEnd',
        ])
          tag: _sumTag(tag) * mult,
      },

      // derived spans
      'eaveLenUsedM_total': eaveLenUsed,
      'spanPlanM_total': spanPlanMAll,
      'spanSlopeM_total': slopeSpanMAll,

      // spacing inputs
      'purlinSpacingMm': _i(purlinSpacingMmCtrl.text, 1500),
      'rafterSpacingMm': _i(rafterSpacingMmCtrl.text, 600),
      'trussSpacingMm': _i(trussSpacingMmCtrl.text, 2000),
    };

    var savingDialogOpen = true;
    Get.dialog<void>(
      PopScope(
        canPop: false,
        child: Dialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(22),
          ),
          child: const Padding(
            padding: EdgeInsets.symmetric(horizontal: 28, vertical: 26),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                SizedBox(
                  width: 38,
                  height: 38,
                  child: CircularProgressIndicator(strokeWidth: 3),
                ),
                SizedBox(width: 18),
                Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Saving roof measurement…',
                      style: TextStyle(
                        fontSize: 16,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    SizedBox(height: 4),
                    Text('Please wait while the BOQ quantities are updated.'),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
      barrierDismissible: false,
    );
    await Future<void>.delayed(Duration.zero);

    void closeSavingDialog() {
      if (!savingDialogOpen) return;
      savingDialogOpen = false;
      if (Get.isDialogOpen == true) Get.back<void>();
    }

    try {
      final batch = FirebaseFirestore.instance.batch();

      if (!timberOnly &&
          includeSheeting.value &&
          boqSheetCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-sheet'), {
          ...common(),
          'type': 'roofSheeting',
          'unit': 'm2',
          'value': sheetingM2All,
          'valueOne_planM2': planAreaM2One,
          'valueOne_slopeM2': math.max(
            0.0,
            planAreaM2One * geometryFactor - openingDeductionM2One,
          ),
          'grossDevelopedAreaM2': grossDevelopedAreaM2,
          'openingDeductionM2': openingDeductionM2All,
          'procurementAreaM2': procurementAreaM2,
          'boqCode': boqSheetCode.text.trim(),
          'boqDescription': boqSheetDesc.text.trim(),
        });
      }

      if (!timberOnly &&
          eaveLenAll > 0 &&
          boqFasciaCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-fascia'), {
          ...common(),
          'type': 'roofFasciaBoarding',
          'unit': 'm',
          'value': eaveLenAll,
          'valueOne': _sumTag('eave'),
          'sourceEdgeType': 'eave',
          'boqCode': boqFasciaCode.text.trim(),
          'boqDescription': boqFasciaDesc.text.trim(),
        });
      }

      if (!timberOnly &&
          includeRidge.value &&
          boqRidgeCode.text.trim().isNotEmpty &&
          ridgeLenAll > 0) {
        batch.set(measurementsRef.doc('$roofGroupId-ridge'), {
          ...common(),
          'type': 'roofRidgeCapping',
          'unit': 'm',
          'value': ridgeLenAll,
          'valueOne': _sumTag('ridge'),
          'boqCode': boqRidgeCode.text.trim(),
          'boqDescription': boqRidgeDesc.text.trim(),
        });
      }

      if (!timberOnly &&
          includeHips.value &&
          boqHipCode.text.trim().isNotEmpty &&
          hipLenAll > 0) {
        batch.set(measurementsRef.doc('$roofGroupId-hip'), {
          ...common(),
          'type': 'roofHipCapping',
          'unit': 'm',
          'value': hipLenAll,
          'valueOne': _sumTag('hip'),
          'boqCode': boqHipCode.text.trim(),
          'boqDescription': boqHipDesc.text.trim(),
        });
      }

      if (!timberOnly &&
          includeValleys.value &&
          boqValleyCode.text.trim().isNotEmpty &&
          valleyLenAll > 0) {
        batch.set(measurementsRef.doc('$roofGroupId-valley'), {
          ...common(),
          'type': 'roofValleys',
          'unit': 'm',
          'value': valleyLenAll,
          'valueOne': _sumTag('valley'),
          'boqCode': boqValleyCode.text.trim(),
          'boqDescription': boqValleyDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includePurlins.value &&
          boqPurlinsCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-purlins'), {
          ...common(),
          'type': 'roofPurlins50x50',
          'unit': 'm',
          'value': purlinsMAll,
          'count': purlinCount,
          'boqCode': boqPurlinsCode.text.trim(),
          'boqDescription': boqPurlinsDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includeRafters.value &&
          boqRaftersCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-rafters'), {
          ...common(),
          'type': 'roofRafters150x50',
          'unit': 'm',
          'value': raftersMAll,
          'count': rafterCount,
          'boqCode': boqRaftersCode.text.trim(),
          'boqDescription': boqRaftersDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includeWallPlates.value &&
          boqWallPlateCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-wallplates'), {
          ...common(),
          'type': 'roofWallPlates150x50',
          'unit': 'm',
          'value': wallPlatesMAll,
          'boqCode': boqWallPlateCode.text.trim(),
          'boqDescription': boqWallPlateDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includeTieBeams.value &&
          boqTieCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-tiebeams'), {
          ...common(),
          'type': 'roofTieBeams150x50',
          'unit': 'm',
          'value': tieBeamsMAll,
          'count': rafterCount,
          'boqCode': boqTieCode.text.trim(),
          'boqDescription': boqTieDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includeKingPosts.value &&
          boqKingCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-kingposts'), {
          ...common(),
          'type': 'roofKingPosts150x50',
          'unit': 'm',
          'value': kingPostsMAll,
          'count': trussCount,
          'kingPostHeightM': kingH,
          'boqCode': boqKingCode.text.trim(),
          'boqDescription': boqKingDesc.text.trim(),
        });
      }

      if (!coveringOnly &&
          includeStrutsPosts.value &&
          boqStrutsCode.text.trim().isNotEmpty) {
        batch.set(measurementsRef.doc('$roofGroupId-struts'), {
          ...common(),
          'type': 'roofStrutsPosts100x50',
          'unit': 'm',
          'value': strutsMAll,
          'countTrusses': trussCount,
          'strutsPerTruss': strutsPerTruss,
          'strutLengthM': strutL,
          'boqCode': boqStrutsCode.text.trim(),
          'boqDescription': boqStrutsDesc.text.trim(),
        });
      }

      await batch.commit();

      // ✅ REMEMBER everything for next time
      lastRoofDefaults
        ..['buildingFactor'] = factor
        ..['qtySamePolygon'] = qty
        ..['roofGeometry'] = roofGeometry
        ..['pitchDeg'] = pitchDeg
        ..['useSlopeArea'] = roofGeometry == 'pitched'
        ..['barrelChordM'] = barrelChordM
        ..['barrelRadiusM'] = barrelRadiusM
        ..['barrelRiseM'] = barrelRiseM
        ..['customSurfaceFactor'] = _d(customSurfaceFactorCtrl.text, 1.0)
        ..['openingDeductionM2'] = openingDeductionM2One
        ..['wastePercent'] = wastePercent
        ..['purlinSpacingMm'] = _i(purlinSpacingMmCtrl.text, 1500)
        ..['rafterSpacingMm'] = _i(rafterSpacingMmCtrl.text, 600)
        ..['trussSpacingMm'] = _i(trussSpacingMmCtrl.text, 2000)
        ..['kingPostHeightM'] = kingH
        ..['strutsPerTruss'] = strutsPerTruss
        ..['strutLengthM'] = strutL
        ..['includeSheeting'] = includeSheeting.value
        ..['includeRidge'] = includeRidge.value
        ..['includeHips'] = includeHips.value
        ..['includeValleys'] = includeValleys.value
        ..['includeRafters'] = includeRafters.value
        ..['includeWallPlates'] = includeWallPlates.value
        ..['includeTieBeams'] = includeTieBeams.value
        ..['includeKingPosts'] = includeKingPosts.value
        ..['includeStrutsPosts'] = includeStrutsPosts.value
        ..['includePurlins'] = includePurlins.value
        ..['boqSheetCode'] = boqSheetCode.text.trim()
        ..['boqSheetDesc'] = boqSheetDesc.text.trim()
        ..['boqRidgeCode'] = boqRidgeCode.text.trim()
        ..['boqRidgeDesc'] = boqRidgeDesc.text.trim()
        ..['boqHipCode'] = boqHipCode.text.trim()
        ..['boqHipDesc'] = boqHipDesc.text.trim()
        ..['boqValleyCode'] = boqValleyCode.text.trim()
        ..['boqValleyDesc'] = boqValleyDesc.text.trim()
        ..['boqFasciaCode'] = boqFasciaCode.text.trim()
        ..['boqFasciaDesc'] = boqFasciaDesc.text.trim()
        ..['boqRaftersCode'] = boqRaftersCode.text.trim()
        ..['boqRaftersDesc'] = boqRaftersDesc.text.trim()
        ..['boqWallPlateCode'] = boqWallPlateCode.text.trim()
        ..['boqWallPlateDesc'] = boqWallPlateDesc.text.trim()
        ..['boqTieCode'] = boqTieCode.text.trim()
        ..['boqTieDesc'] = boqTieDesc.text.trim()
        ..['boqKingCode'] = boqKingCode.text.trim()
        ..['boqKingDesc'] = boqKingDesc.text.trim()
        ..['boqStrutsCode'] = boqStrutsCode.text.trim()
        ..['boqStrutsDesc'] = boqStrutsDesc.text.trim()
        ..['boqPurlinsCode'] = boqPurlinsCode.text.trim()
        ..['boqPurlinsDesc'] = boqPurlinsDesc.text.trim()
        ..['edgeTags'] =
            edges.map((e) => {'i': e.index, 'tag': e.tag}).toList();

      closeSavingDialog();
      Get.snackbar('Saved', 'Roof items saved (qty $qty × factor x$factor).');
    } catch (e) {
      closeSavingDialog();
      Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
    } finally {
      closeSavingDialog();
      factorCtrl.dispose();
      qtyCtrl.dispose();
      pitchDegCtrl.dispose();
      barrelChordCtrl.dispose();
      barrelRadiusCtrl.dispose();
      barrelRiseCtrl.dispose();
      customSurfaceFactorCtrl.dispose();
      openingDeductionCtrl.dispose();
      wastePercentCtrl.dispose();
      purlinSpacingMmCtrl.dispose();
      rafterSpacingMmCtrl.dispose();
      trussSpacingMmCtrl.dispose();
      kingPostHeightCtrl.dispose();
      strutsPerTrussCtrl.dispose();
      strutLengthCtrl.dispose();

      includeSheeting.dispose();
      includeRidge.dispose();
      includeHips.dispose();
      includeValleys.dispose();
      includeRafters.dispose();
      includeWallPlates.dispose();
      includeTieBeams.dispose();
      includeKingPosts.dispose();
      includeStrutsPosts.dispose();
      includePurlins.dispose();

      boqSheetCode.dispose();
      boqSheetDesc.dispose();
      boqRidgeCode.dispose();
      boqRidgeDesc.dispose();
      boqHipCode.dispose();
      boqHipDesc.dispose();
      boqValleyCode.dispose();
      boqValleyDesc.dispose();
      boqFasciaCode.dispose();
      boqFasciaDesc.dispose();

      boqRaftersCode.dispose();
      boqRaftersDesc.dispose();
      boqWallPlateCode.dispose();
      boqWallPlateDesc.dispose();
      boqTieCode.dispose();
      boqTieDesc.dispose();
      boqKingCode.dispose();
      boqKingDesc.dispose();
      boqStrutsCode.dispose();
      boqStrutsDesc.dispose();
      boqPurlinsCode.dispose();
      boqPurlinsDesc.dispose();
    }
  }

  Future<TrussSaveAction> openTrussTemplateFromSegment({
    required Offset p1World,
    required Offset p2World,
    required Map<String, dynamic> drawingData,

    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,

    required CollectionReference<Map<String, dynamic>> measurementsRef,
    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    // required Map<String, dynamic> lastTrussDefaults,
    VoidCallback? onCloseDraft,
    VoidCallback? onUpdateViewer,
  }) async {
    // ---------- helpers ----------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    int _int(dynamic v, int fb) {
      if (v is int) return v;
      if (v is num) return v.round();
      return int.tryParse('${v ?? ''}') ?? fb;
    }

    int clampInt(int v, int lo, int hi) => v < lo ? lo : (v > hi ? hi : v);

    double _distPx(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      return math.sqrt(dx * dx + dy * dy);
    }

    double distM(Offset aWorld, Offset bWorld) {
      final calibrated = drawingData['calibrated'] == true;
      final pxPerM = _num(drawingData['pixelsPerUnit'], 0);
      if (!calibrated || pxPerM <= 0) return 0;
      return _distPx(aWorld, bWorld) / pxPerM;
    }

    const steelDensity = 7850.0; // kg/m3

    double kgPerM_CHS({required double odMm, required double tMm}) {
      final Do = odMm / 1000.0;
      final t = tMm / 1000.0;
      final Di = (Do - 2.0 * t);
      if (Do <= 0 || t <= 0 || Di <= 0) return 0.0;
      final area = (math.pi / 4.0) * (Do * Do - Di * Di);
      return area * steelDensity;
    }

    double kgPerM_ZThinPlate({
      required double webMm,
      required double flangeMm,
      required double lipMm,
      required double tMm,
    }) {
      final devMm = webMm + flangeMm + lipMm + flangeMm + lipMm;
      final devM = devMm / 1000.0;
      final tM = tMm / 1000.0;
      if (devM <= 0 || tM <= 0) return 0.0;
      return (devM * tM) * steelDensity;
    }

    TextEditingController _ctrl(String key, String fallback) {
      final v = lastTrussDefaults[key] ?? fallback;
      return TextEditingController(text: '$v');
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    InputDecoration decoDense(String label) => const InputDecoration(
      border: OutlineInputBorder(),
      isDense: true,
    ).copyWith(labelText: label);

    Widget boqLine({
      required BuildContext ctx,
      required String title,
      required BoqPick? pick,
      required VoidCallback onPick,
      required VoidCallback onClear,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              const SizedBox(width: 8),
              OutlinedButton(onPressed: onClear, child: const Text('Clear')),
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    double d(TextEditingController c, double fb) =>
        double.tryParse(c.text.trim()) ?? fb;
    int ii(TextEditingController c, int fb) =>
        int.tryParse(c.text.trim()) ?? fb;

    // ---------- validation ----------
    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0);
    if (!calibrated || pxPerM <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Calibrate drawing first (pixelsPerUnit).',
      );
      return TrussSaveAction.cancel;
    }

    final spanM = distM(p1World, p2World);
    if (spanM <= 0) {
      Get.snackbar('Invalid', 'Span is zero. Check points/calibration.');
      return TrussSaveAction.cancel;
    }

    // ---------- defaults/controllers ----------
    final trussNameCtrl = _ctrl(
      'trussName',
      (activeLabel ?? 'Truss T1').trim(),
    );
    final trussCountCtrl = _ctrl('trussCount', '16');
    final factorCtrl = _ctrl('multiplyingFactor', '1'); // repeats

    // CHS settings
    bool includeTop = (lastTrussDefaults['includeTop'] ?? true) == true;
    bool includeBottom = (lastTrussDefaults['includeBottom'] ?? true) == true;
    bool includeStruts = (lastTrussDefaults['includeStruts'] ?? true) == true;

    bool useAutoTop = (lastTrussDefaults['useAutoTop'] ?? true) == true;
    bool useAutoBottom = (lastTrussDefaults['useAutoBottom'] ?? true) == true;
    bool useAutoStruts = (lastTrussDefaults['useAutoStruts'] ?? true) == true;

    final topOdCtrl = _ctrl('topOdMm', '42.4');
    final topThkCtrl = _ctrl('topThkMm', '3');
    final topKgPerMCtrl = _ctrl('topKgPerM', '2.915');
    final topLenPerTrussCtrl = _ctrl(
      'topLenPerTrussM',
      (2 * spanM).toStringAsFixed(3),
    );
    final topPiecesCtrl = _ctrl('topPiecesPerTruss', '2');

    final botOdCtrl = _ctrl('botOdMm', '42.4');
    final botThkCtrl = _ctrl('botThkMm', '3');
    final botKgPerMCtrl = _ctrl('botKgPerM', '2.915');
    final botLenPerTrussCtrl = _ctrl(
      'botLenPerTrussM',
      spanM.toStringAsFixed(3),
    );
    final botPiecesCtrl = _ctrl('botPiecesPerTruss', '1');

    final strOdCtrl = _ctrl('strutsOdMm', '42.4');
    final strThkCtrl = _ctrl('strutsThkMm', '3');
    final strKgPerMCtrl = _ctrl('strutsKgPerM', '2.915');
    final strLenPerTrussCtrl = _ctrl(
      'strutsLenPerTrussM',
      (0.60 * spanM).toStringAsFixed(3),
    );
    final strPiecesCtrl = _ctrl('strutsPiecesPerTruss', '2');

    // Cleats / Base plates (Nos)
    bool includeCleats = (lastTrussDefaults['includeCleats'] ?? true) == true;
    bool includeBasePlates =
        (lastTrussDefaults['includeBasePlates'] ?? true) == true;

    final cleatsPerTrussCtrl = _ctrl('cleatsPerTruss', '4');
    final basePlatesPerTrussCtrl = _ctrl('basePlatesPerTruss', '2');

    // Z purlins (kg) -> in truss template we usually input total length (base)
    bool includeZPurlin = (lastTrussDefaults['includeZPurlin'] ?? true) == true;
    bool useAutoZ = (lastTrussDefaults['useAutoKgZ'] ?? true) == true;
    final zWebCtrl = _ctrl('zWebMm', '125');
    final zFlangeCtrl = _ctrl('zFlangeMm', '50');
    final zLipCtrl = _ctrl('zLipMm', '20');
    final zThkCtrl = _ctrl('zThkMm', '2.0');
    final zKgPerMCtrl = _ctrl('zKgPerM', '3.82');
    final zTotalLenBaseCtrl = _ctrl('zTotalLenBaseM', '0'); // user can fill

    // BOQ picks (remembered)
    BoqPick? boqTop = pickFromMap(lastTrussDefaults['boqTopChord']);
    BoqPick? boqBottom = pickFromMap(lastTrussDefaults['boqBottomChord']);
    BoqPick? boqStruts = pickFromMap(lastTrussDefaults['boqStruts']);
    BoqPick? boqCleats = pickFromMap(lastTrussDefaults['boqCleats']);
    BoqPick? boqBasePlates = pickFromMap(lastTrussDefaults['boqBasePlates']);
    BoqPick? boqZPurlin = pickFromMap(lastTrussDefaults['boqZPurlin']);

    // ---------- dialog ----------
    final ctx = Get.context;
    if (ctx == null) return TrussSaveAction.cancel;

    TrussSaveAction action =
        await Get.dialog<TrussSaveAction>(
          StatefulBuilder(
            builder: (dctx, setState) {
              final factor = d(factorCtrl, 1).clamp(0.01, 999999.0);
              final factorInt = clampInt(factor.round(), 1, 999999);

              final trussCountBase = clampInt(
                ii(trussCountCtrl, 16),
                1,
                999999,
              );
              final trussCount = trussCountBase * factorInt;

              // auto kg/m
              final topAuto = kgPerM_CHS(
                odMm: d(topOdCtrl, 42.4),
                tMm: d(topThkCtrl, 3),
              );
              final botAuto = kgPerM_CHS(
                odMm: d(botOdCtrl, 42.4),
                tMm: d(botThkCtrl, 3),
              );
              final strAuto = kgPerM_CHS(
                odMm: d(strOdCtrl, 42.4),
                tMm: d(strThkCtrl, 3),
              );
              final zAuto = kgPerM_ZThinPlate(
                webMm: d(zWebCtrl, 125),
                flangeMm: d(zFlangeCtrl, 50),
                lipMm: d(zLipCtrl, 20),
                tMm: d(zThkCtrl, 2.0),
              );

              final topKgPerM = clampD(
                useAutoTop ? topAuto : d(topKgPerMCtrl, 2.915),
                0.0,
                99999.0,
              );
              final botKgPerM = clampD(
                useAutoBottom ? botAuto : d(botKgPerMCtrl, 2.915),
                0.0,
                99999.0,
              );
              final strKgPerM = clampD(
                useAutoStruts ? strAuto : d(strKgPerMCtrl, 2.915),
                0.0,
                99999.0,
              );
              final zKgPerM = clampD(
                useAutoZ ? zAuto : d(zKgPerMCtrl, 3.82),
                0.0,
                99999.0,
              );

              // member totals
              final topLenPerTruss = d(
                topLenPerTrussCtrl,
                2 * spanM,
              ).clamp(0, 9e9);
              final botLenPerTruss = d(botLenPerTrussCtrl, spanM).clamp(0, 9e9);
              final strLenPerTruss = d(
                strLenPerTrussCtrl,
                0.6 * spanM,
              ).clamp(0, 9e9);

              final topPieces = clampInt(ii(topPiecesCtrl, 2), 0, 999999);
              final botPieces = clampInt(ii(botPiecesCtrl, 1), 0, 999999);
              final strPieces = clampInt(ii(strPiecesCtrl, 2), 0, 999999);

              final topLenTotal = topLenPerTruss * topPieces * trussCount;
              final botLenTotal = botLenPerTruss * botPieces * trussCount;
              final strLenTotal = strLenPerTruss * strPieces * trussCount;

              final topKgTotal = topLenTotal * topKgPerM;
              final botKgTotal = botLenTotal * botKgPerM;
              final strKgTotal = strLenTotal * strKgPerM;

              final cleatsNos =
                  clampInt(ii(cleatsPerTrussCtrl, 4), 0, 999999) * trussCount;
              final basePlatesNos =
                  clampInt(ii(basePlatesPerTrussCtrl, 2), 0, 999999) *
                  trussCount;

              final zTotalLenBase = d(zTotalLenBaseCtrl, 0).clamp(0.0, 9e9);
              final zTotalLen =
                  zTotalLenBase * factor; // keep as double scaling
              final zTotalKg = zTotalLen * zKgPerM;

              Widget section(String t) => Padding(
                padding: const EdgeInsets.only(top: 12, bottom: 6),
                child: Text(
                  t,
                  style: const TextStyle(fontWeight: FontWeight.w800),
                ),
              );

              return AlertDialog(
                title: const Text('Truss takeoff (2 taps)'),
                content: SizedBox(
                  width: 760,
                  child: SingleChildScrollView(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Measured span = ${spanM.toStringAsFixed(3)} m',
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                        const SizedBox(height: 8),

                        TextField(
                          controller: trussNameCtrl,
                          decoration: decoDense('Truss label (e.g. T1)'),
                          onChanged: (_) => setState(() {}),
                        ),
                        const SizedBox(height: 8),

                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: trussCountCtrl,
                                decoration: decoDense('Truss count (base)'),
                                keyboardType: TextInputType.number,
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                controller: factorCtrl,
                                decoration: decoDense('Multiplying factor'),
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 6),
                        Text(
                          'Trusses = $trussCountBase × $factorInt = $trussCount',
                          style: const TextStyle(fontSize: 12),
                        ),

                        const Divider(height: 22),

                        section('CHS truss members (kg)'),

                        // TOP
                        SwitchListTile(
                          value: includeTop,
                          onChanged: (v) => setState(() => includeTop = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text(
                            'Top chord (kg)  • total ≈ ${topKgTotal.toStringAsFixed(1)}',
                          ),
                        ),
                        if (includeTop) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: topOdCtrl,
                                  decoration: decoDense('OD (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: topThkCtrl,
                                  decoration: decoDense('Thk (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),
                          SwitchListTile(
                            value: useAutoTop,
                            onChanged: (v) => setState(() => useAutoTop = v),
                            contentPadding: EdgeInsets.zero,
                            title: const Text('Use auto kg/m'),
                            subtitle: Text(
                              'Auto kg/m ≈ ${topAuto.toStringAsFixed(3)}',
                            ),
                          ),
                          if (!useAutoTop)
                            TextField(
                              controller: topKgPerMCtrl,
                              decoration: decoDense('Manual kg/m'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          const SizedBox(height: 8),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: topLenPerTrussCtrl,
                                  decoration: decoDense('Length per truss (m)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: topPiecesCtrl,
                                  decoration: decoDense('Pieces per truss'),
                                  keyboardType: TextInputType.number,
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Top chord BOQ (kg)',
                            pick: boqTop,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null) setState(() => boqTop = pick);
                            },
                            onClear: () => setState(() => boqTop = null),
                          ),
                          const Divider(height: 22),
                        ],

                        // BOTTOM
                        SwitchListTile(
                          value: includeBottom,
                          onChanged: (v) => setState(() => includeBottom = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text(
                            'Bottom chord (kg)  • total ≈ ${botKgTotal.toStringAsFixed(1)}',
                          ),
                        ),
                        if (includeBottom) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: botOdCtrl,
                                  decoration: decoDense('OD (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: botThkCtrl,
                                  decoration: decoDense('Thk (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),
                          SwitchListTile(
                            value: useAutoBottom,
                            onChanged: (v) => setState(() => useAutoBottom = v),
                            contentPadding: EdgeInsets.zero,
                            title: const Text('Use auto kg/m'),
                            subtitle: Text(
                              'Auto kg/m ≈ ${botAuto.toStringAsFixed(3)}',
                            ),
                          ),
                          if (!useAutoBottom)
                            TextField(
                              controller: botKgPerMCtrl,
                              decoration: decoDense('Manual kg/m'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          const SizedBox(height: 8),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: botLenPerTrussCtrl,
                                  decoration: decoDense('Length per truss (m)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: botPiecesCtrl,
                                  decoration: decoDense('Pieces per truss'),
                                  keyboardType: TextInputType.number,
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Bottom chord BOQ (kg)',
                            pick: boqBottom,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null)
                                setState(() => boqBottom = pick);
                            },
                            onClear: () => setState(() => boqBottom = null),
                          ),
                          const Divider(height: 22),
                        ],

                        // STRUTS
                        SwitchListTile(
                          value: includeStruts,
                          onChanged: (v) => setState(() => includeStruts = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text(
                            'Struts (kg)  • total ≈ ${strKgTotal.toStringAsFixed(1)}',
                          ),
                        ),
                        if (includeStruts) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: strOdCtrl,
                                  decoration: decoDense('OD (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: strThkCtrl,
                                  decoration: decoDense('Thk (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),
                          SwitchListTile(
                            value: useAutoStruts,
                            onChanged: (v) => setState(() => useAutoStruts = v),
                            contentPadding: EdgeInsets.zero,
                            title: const Text('Use auto kg/m'),
                            subtitle: Text(
                              'Auto kg/m ≈ ${strAuto.toStringAsFixed(3)}',
                            ),
                          ),
                          if (!useAutoStruts)
                            TextField(
                              controller: strKgPerMCtrl,
                              decoration: decoDense('Manual kg/m'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          const SizedBox(height: 8),
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: strLenPerTrussCtrl,
                                  decoration: decoDense(
                                    'Total strut length per truss (m)',
                                  ),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: strPiecesCtrl,
                                  decoration: decoDense('Pieces per truss'),
                                  keyboardType: TextInputType.number,
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Struts BOQ (kg)',
                            pick: boqStruts,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null)
                                setState(() => boqStruts = pick);
                            },
                            onClear: () => setState(() => boqStruts = null),
                          ),
                          const Divider(height: 22),
                        ],

                        section('Connections (Nos)'),
                        SwitchListTile(
                          value: includeCleats,
                          onChanged: (v) => setState(() => includeCleats = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text('Cleats (Nos) • total = $cleatsNos'),
                        ),
                        if (includeCleats) ...[
                          TextField(
                            controller: cleatsPerTrussCtrl,
                            decoration: decoDense('Cleats per truss (Nos)'),
                            keyboardType: TextInputType.number,
                            onChanged: (_) => setState(() {}),
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Cleats BOQ (Nos)',
                            pick: boqCleats,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null)
                                setState(() => boqCleats = pick);
                            },
                            onClear: () => setState(() => boqCleats = null),
                          ),
                          const Divider(height: 22),
                        ],

                        SwitchListTile(
                          value: includeBasePlates,
                          onChanged:
                              (v) => setState(() => includeBasePlates = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text(
                            'Base plates (Nos) • total = $basePlatesNos',
                          ),
                        ),
                        if (includeBasePlates) ...[
                          TextField(
                            controller: basePlatesPerTrussCtrl,
                            decoration: decoDense(
                              'Base plates per truss (Nos)',
                            ),
                            keyboardType: TextInputType.number,
                            onChanged: (_) => setState(() {}),
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Base plates BOQ (Nos)',
                            pick: boqBasePlates,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null)
                                setState(() => boqBasePlates = pick);
                            },
                            onClear: () => setState(() => boqBasePlates = null),
                          ),
                          const Divider(height: 22),
                        ],

                        section('Purlins (Z section) (kg)'),
                        SwitchListTile(
                          value: includeZPurlin,
                          onChanged: (v) => setState(() => includeZPurlin = v),
                          contentPadding: EdgeInsets.zero,
                          title: Text(
                            'Z-Purlins (kg) • total ≈ ${zTotalKg.toStringAsFixed(1)}',
                          ),
                          subtitle: const Text(
                            'In truss template, enter TOTAL Z length (base). Roof-plane spacing comes from roof tool.',
                          ),
                        ),
                        if (includeZPurlin) ...[
                          Row(
                            children: [
                              Expanded(
                                child: TextField(
                                  controller: zWebCtrl,
                                  decoration: decoDense('Web (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: zFlangeCtrl,
                                  decoration: decoDense('Flange (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: zLipCtrl,
                                  decoration: decoDense('Lip (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                              const SizedBox(width: 8),
                              Expanded(
                                child: TextField(
                                  controller: zThkCtrl,
                                  decoration: decoDense('Thk (mm)'),
                                  keyboardType:
                                      const TextInputType.numberWithOptions(
                                        decimal: true,
                                      ),
                                  onChanged: (_) => setState(() {}),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 8),
                          SwitchListTile(
                            value: useAutoZ,
                            onChanged: (v) => setState(() => useAutoZ = v),
                            contentPadding: EdgeInsets.zero,
                            title: const Text(
                              'Use auto kg/m from Z dimensions',
                            ),
                            subtitle: Text(
                              'Auto kg/m ≈ ${zAuto.toStringAsFixed(3)}',
                            ),
                          ),
                          if (!useAutoZ)
                            TextField(
                              controller: zKgPerMCtrl,
                              decoration: decoDense('Manual kg/m'),
                              keyboardType:
                                  const TextInputType.numberWithOptions(
                                    decimal: true,
                                  ),
                              onChanged: (_) => setState(() {}),
                            ),
                          const SizedBox(height: 8),
                          TextField(
                            controller: zTotalLenBaseCtrl,
                            decoration: decoDense('TOTAL Z length (base m)'),
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            onChanged: (_) => setState(() {}),
                          ),
                          const SizedBox(height: 10),
                          boqLine(
                            ctx: dctx,
                            title: 'Z-Purlins BOQ (kg)',
                            pick: boqZPurlin,
                            onPick: () async {
                              final pick = await showBoqPickerDialog(
                                context: dctx,
                              );
                              if (pick != null)
                                setState(() => boqZPurlin = pick);
                            },
                            onClear: () => setState(() => boqZPurlin = null),
                          ),
                        ],
                      ],
                    ),
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed:
                        () => Navigator.pop(dctx, TrussSaveAction.cancel),
                    child: const Text('Cancel'),
                  ),
                  OutlinedButton(
                    onPressed:
                        () => Navigator.pop(dctx, TrussSaveAction.addMore),
                    child: const Text('Save & Add another'),
                  ),
                  FilledButton(
                    onPressed:
                        () => Navigator.pop(dctx, TrussSaveAction.finish),
