            },
          ),
          barrierDismissible: false,
        ) ??
        TrussSaveAction.cancel;

    // ---------- dispose helper ----------
    void disposeAll() {
      for (final c in [
        trussNameCtrl,
        trussCountCtrl,
        factorCtrl,
        topOdCtrl,
        topThkCtrl,
        topKgPerMCtrl,
        topLenPerTrussCtrl,
        topPiecesCtrl,
        botOdCtrl,
        botThkCtrl,
        botKgPerMCtrl,
        botLenPerTrussCtrl,
        botPiecesCtrl,
        strOdCtrl,
        strThkCtrl,
        strKgPerMCtrl,
        strLenPerTrussCtrl,
        strPiecesCtrl,
        cleatsPerTrussCtrl,
        basePlatesPerTrussCtrl,
        zWebCtrl,
        zFlangeCtrl,
        zLipCtrl,
        zThkCtrl,
        zKgPerMCtrl,
        zTotalLenBaseCtrl,
      ]) {
        c.dispose();
      }
    }

    if (action == TrussSaveAction.cancel) {
      disposeAll();
      onCloseDraft?.call();
      return TrussSaveAction.cancel;
    }

    // ---------- recompute for save ----------
    final factor = d(factorCtrl, 1).clamp(0.01, 999999.0);
    final factorInt = clampInt(factor.round(), 1, 999999);

    final trussCountBase = clampInt(ii(trussCountCtrl, 16), 1, 999999);
    final trussCount = trussCountBase * factorInt;

    final topAuto = kgPerM_CHS(odMm: d(topOdCtrl, 42.4), tMm: d(topThkCtrl, 3));
    final botAuto = kgPerM_CHS(odMm: d(botOdCtrl, 42.4), tMm: d(botThkCtrl, 3));
    final strAuto = kgPerM_CHS(odMm: d(strOdCtrl, 42.4), tMm: d(strThkCtrl, 3));
    final zAuto = kgPerM_ZThinPlate(
      webMm: d(zWebCtrl, 125),
      flangeMm: d(zFlangeCtrl, 50),
      lipMm: d(zLipCtrl, 20),
      tMm: d(zThkCtrl, 2.0),
    );

    final topKgPerM = clampD(
      useAutoTop ? topAuto : d(topKgPerMCtrl, 2.915),
      0.0,
      9999.0,
    );
    final botKgPerM = clampD(
      useAutoBottom ? botAuto : d(botKgPerMCtrl, 2.915),
      0.0,
      9999.0,
    );
    final strKgPerM = clampD(
      useAutoStruts ? strAuto : d(strKgPerMCtrl, 2.915),
      0.0,
      9999.0,
    );
    final zKgPerM = clampD(
      useAutoZ ? zAuto : d(zKgPerMCtrl, 3.82),
      0.0,
      99999.0,
    );

    final topLenPerTruss = clampD(d(topLenPerTrussCtrl, 2 * spanM), 0.0, 9e9);
    final botLenPerTruss = clampD(d(botLenPerTrussCtrl, spanM), 0.0, 9e9);
    final strLenPerTruss = clampD(d(strLenPerTrussCtrl, 0.6 * spanM), 0.0, 9e9);

    final topPieces = clampInt(ii(topPiecesCtrl, 2), 0, 999999);
    final botPieces = clampInt(ii(botPiecesCtrl, 1), 0, 999999);
    final strPieces = clampInt(ii(strPiecesCtrl, 2), 0, 999999);

    final topLenTotal = topLenPerTruss * topPieces * trussCount;
    final botLenTotal = botLenPerTruss * botPieces * trussCount;
    final strLenTotal = strLenPerTruss * strPieces * trussCount;

    final topKgTotal = topLenTotal * topKgPerM;
    final botKgTotal = botLenTotal * botKgPerM;
    final strKgTotal = strLenTotal * strKgPerM;

    final cleatsNos =
        clampInt(ii(cleatsPerTrussCtrl, 4), 0, 999999) * trussCount;
    final basePlatesNos =
        clampInt(ii(basePlatesPerTrussCtrl, 2), 0, 999999) * trussCount;

    final zTotalLenBase = d(zTotalLenBaseCtrl, 0).clamp(0, 9e9);
    final zTotalLen = zTotalLenBase * factor;
    final zTotalKg = zTotalLen * zKgPerM;

    // ---------- validations (BOQ required if included) ----------
    String? missingBoq() {
      if (includeTop && boqTop == null) return 'Top chord';
      if (includeBottom && boqBottom == null) return 'Bottom chord';
      if (includeStruts && boqStruts == null) return 'Struts';
      if (includeCleats && boqCleats == null) return 'Cleats';
      if (includeBasePlates && boqBasePlates == null) return 'Base plates';
      if (includeZPurlin && boqZPurlin == null) return 'Z-Purlins';
      return null;
    }

    final miss = missingBoq();
    if (miss != null) {
      Get.snackbar('Missing BOQ', 'Pick BOQ for: $miss');
      disposeAll();
      return TrussSaveAction.cancel;
    }

    // ---------- save (batch) ----------
    final now = FieldValue.serverTimestamp();
    final templateId = measurementsRef.doc().id;

    try {
      final batch = FirebaseFirestore.instance.batch();

      // meta/template doc (stores the measured span line)
      batch.set(measurementsRef.doc('$templateId-trussTemplate'), {
        'projectId': projectId,
        'buildingId': buildingId,
        'drawingId': drawingId,
        'measureType': 'trussTemplate',
        'type': 'trussTemplate',
        'trussName': trussNameCtrl.text.trim(),
        'spanM': spanM,
        'trussCountBase': trussCountBase,
        'multiplyingFactor': factor,
        'multiplyingFactorInt': factorInt,
        'trussCount': trussCount,
        'p1': {'x': p1World.dx, 'y': p1World.dy},
        'p2': {'x': p2World.dx, 'y': p2World.dy},
        'color': currentColor.value,
        'createdAt': now,
        'updatedAt': now,
      });

      void saveKgItem({
        required String suffix,
        required String type,
        required bool include,
        required double totalKg,
        required double totalLenM,
        required double kgPerM,
        required Map<String, dynamic> section,
        required BoqPick boq,
        required String label,
      }) {
        if (!include || totalKg <= 0.0) return;
        batch.set(measurementsRef.doc('$templateId-$suffix'), {
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,
          'measureType': 'trussTemplate',
          'type': type,
          'unit': 'kg',
          'value': totalKg,
          'totalLengthM': totalLenM,
          'kgPerM': kgPerM,
          'section': section,
          'trussCount': trussCount,
          'trussCountBase': trussCountBase,
          'multiplyingFactor': factor,
          'templateId': templateId,
          'boqItemId': boq.id,
          'boqCode': boq.code,
          'boqDescription': boq.description,
          'label': label,
          'color': currentColor.value,
          'createdAt': now,
          'updatedAt': now,
        });
      }

      void saveNosItem({
        required String suffix,
        required String type,
        required bool include,
        required int nos,
        required int perTruss,
        required BoqPick boq,
        required String label,
      }) {
        if (!include || nos <= 0) return;
        batch.set(measurementsRef.doc('$templateId-$suffix'), {
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,
          'measureType': 'trussTemplate',
          'type': type,
          'unit': 'nos',
          'value': nos,
          'perTruss': perTruss,
          'trussCount': trussCount,
          'trussCountBase': trussCountBase,
          'multiplyingFactor': factor,
          'templateId': templateId,
          'boqItemId': boq.id,
          'boqCode': boq.code,
          'boqDescription': boq.description,
          'label': label,
          'color': currentColor.value,
          'createdAt': now,
          'updatedAt': now,
        });
      }

      // CHS items
      if (includeTop && boqTop != null) {
        saveKgItem(
          suffix: 'topChord',
          type: 'trussTopChord',
          include: true,
          totalKg: topKgTotal,
          totalLenM: topLenTotal,
          kgPerM: topKgPerM,
          section: {
            'shape': 'CHS',
            'odMm': d(topOdCtrl, 42.4),
            'thkMm': d(topThkCtrl, 3),
            'usedAutoKgPerM': useAutoTop,
            'lenPerTrussM': topLenPerTruss,
            'piecesPerTruss': topPieces,
          },
          boq: boqTop!,
          label: '${trussNameCtrl.text.trim()} - Top chord',
        );
      }

      if (includeBottom && boqBottom != null) {
        saveKgItem(
          suffix: 'bottomChord',
          type: 'trussBottomChord',
          include: true,
          totalKg: botKgTotal,
          totalLenM: botLenTotal,
          kgPerM: botKgPerM,
          section: {
            'shape': 'CHS',
            'odMm': d(botOdCtrl, 42.4),
            'thkMm': d(botThkCtrl, 3),
            'usedAutoKgPerM': useAutoBottom,
            'lenPerTrussM': botLenPerTruss,
            'piecesPerTruss': botPieces,
          },
          boq: boqBottom!,
          label: '${trussNameCtrl.text.trim()} - Bottom chord',
        );
      }

      if (includeStruts && boqStruts != null) {
        saveKgItem(
          suffix: 'struts',
          type: 'trussStruts',
          include: true,
          totalKg: strKgTotal,
          totalLenM: strLenTotal,
          kgPerM: strKgPerM,
          section: {
            'shape': 'CHS',
            'odMm': d(strOdCtrl, 42.4),
            'thkMm': d(strThkCtrl, 3),
            'usedAutoKgPerM': useAutoStruts,
            'lenPerTrussM': strLenPerTruss,
            'piecesPerTruss': strPieces,
          },
          boq: boqStruts!,
          label: '${trussNameCtrl.text.trim()} - Struts',
        );
      }

      // Cleats / Base plates
      if (includeCleats && boqCleats != null) {
        saveNosItem(
          suffix: 'cleats',
          type: 'trussCleats',
          include: true,
          nos: cleatsNos,
          perTruss: clampInt(ii(cleatsPerTrussCtrl, 4), 0, 999999),
          boq: boqCleats!,
          label: '${trussNameCtrl.text.trim()} - Cleats',
        );
      }

      if (includeBasePlates && boqBasePlates != null) {
        saveNosItem(
          suffix: 'basePlates',
          type: 'trussBasePlates',
          include: true,
          nos: basePlatesNos,
          perTruss: clampInt(ii(basePlatesPerTrussCtrl, 2), 0, 999999),
          boq: boqBasePlates!,
          label: '${trussNameCtrl.text.trim()} - Base plates',
        );
      }

      // Z purlins (kg)
      if (includeZPurlin && boqZPurlin != null && zTotalKg > 0) {
        batch.set(measurementsRef.doc('$templateId-zPurlin'), {
          'projectId': projectId,
          'buildingId': buildingId,
          'drawingId': drawingId,
          'measureType': 'trussTemplate',
          'type': 'trussZPurlins',
          'unit': 'kg',
          'value': zTotalKg,
          'totalLengthM': zTotalLen,
          'totalLengthMBase': zTotalLenBase,
          'kgPerM': zKgPerM,
          'section': {
            'shape': 'Z',
            'webMm': d(zWebCtrl, 125),
            'flangeMm': d(zFlangeCtrl, 50),
            'lipMm': d(zLipCtrl, 20),
            'thkMm': d(zThkCtrl, 2.0),
            'usedAutoKgPerM': useAutoZ,
          },
          'multiplyingFactor': factor,
          'templateId': templateId,
          'boqItemId': boqZPurlin!.id,
          'boqCode': boqZPurlin!.code,
          'boqDescription': boqZPurlin!.description,
          'label': '${trussNameCtrl.text.trim()} - Z-Purlins',
          'color': currentColor.value,
          'createdAt': now,
          'updatedAt': now,
        });
      }

      await batch.commit();

      // ✅ remember defaults (BOQ + values)
      lastTrussDefaults
        ..['trussName'] = trussNameCtrl.text.trim()
        ..['trussCount'] = trussCountBase
        ..['multiplyingFactor'] = factor
        ..['includeTop'] = includeTop
        ..['includeBottom'] = includeBottom
        ..['includeStruts'] = includeStruts
        ..['useAutoTop'] = useAutoTop
        ..['useAutoBottom'] = useAutoBottom
        ..['useAutoStruts'] = useAutoStruts
        ..['topOdMm'] = d(topOdCtrl, 42.4)
        ..['topThkMm'] = d(topThkCtrl, 3)
        ..['topKgPerM'] = topKgPerM
        ..['topLenPerTrussM'] = topLenPerTruss
        ..['topPiecesPerTruss'] = topPieces
        ..['botOdMm'] = d(botOdCtrl, 42.4)
        ..['botThkMm'] = d(botThkCtrl, 3)
        ..['botKgPerM'] = botKgPerM
        ..['botLenPerTrussM'] = botLenPerTruss
        ..['botPiecesPerTruss'] = botPieces
        ..['strutsOdMm'] = d(strOdCtrl, 42.4)
        ..['strutsThkMm'] = d(strThkCtrl, 3)
        ..['strutsKgPerM'] = strKgPerM
        ..['strutsLenPerTrussM'] = strLenPerTruss
        ..['strutsPiecesPerTruss'] = strPieces
        ..['includeCleats'] = includeCleats
        ..['includeBasePlates'] = includeBasePlates
        ..['cleatsPerTruss'] = clampInt(ii(cleatsPerTrussCtrl, 4), 0, 999999)
        ..['basePlatesPerTruss'] = clampInt(
          ii(basePlatesPerTrussCtrl, 2),
          0,
          999999,
        )
        ..['includeZPurlin'] = includeZPurlin
        ..['useAutoKgZ'] = useAutoZ
        ..['zWebMm'] = d(zWebCtrl, 125)
        ..['zFlangeMm'] = d(zFlangeCtrl, 50)
        ..['zLipMm'] = d(zLipCtrl, 20)
        ..['zThkMm'] = d(zThkCtrl, 2.0)
        ..['zKgPerM'] = zKgPerM
        ..['zTotalLenBaseM'] = zTotalLenBase
        ..['boqTopChord'] = pickToMap(boqTop)
        ..['boqBottomChord'] = pickToMap(boqBottom)
        ..['boqStruts'] = pickToMap(boqStruts)
        ..['boqCleats'] = pickToMap(boqCleats)
        ..['boqBasePlates'] = pickToMap(boqBasePlates)
        ..['boqZPurlin'] = pickToMap(boqZPurlin);

      Get.snackbar(
        'Saved',
        'Truss items saved (${trussNameCtrl.text.trim()}).',
      );
    } catch (e) {
      Get.snackbar('Save failed', '$e', snackPosition: SnackPosition.BOTTOM);
      disposeAll();
      return TrussSaveAction.cancel;
    } finally {
      disposeAll();
    }

    onCloseDraft?.call();
    onUpdateViewer?.call();
    return action;
  }

  Future<RoofSaveAction> openTrussTemplateFromPolygon({
    required List<Offset> polygon,
    required Map<String, dynamic> drawingData,

    required String projectId,
    required String buildingId,
    required String drawingId,
    required Color currentColor,
    required String? activeLabel,

    required CollectionReference<Map<String, dynamic>> measurementsRef,

    // required Future<BoqPick?> Function(BuildContext ctx) showBoqPickerDialog,

    /// 🔥 remembers last entries (including BOQ picks)
    // required Map<String, dynamic> lastTrussDefaults,
    VoidCallback? onCloseDraft,
    VoidCallback? onUpdateViewer,
  }) async {
    // ---------------- helpers ----------------
    double _num(dynamic v, double fb) {
      if (v is num) return v.toDouble();
      return double.tryParse('${v ?? ''}') ?? fb;
    }

    double _distPx(Offset a, Offset b) {
      final dx = b.dx - a.dx;
      final dy = b.dy - a.dy;
      return math.sqrt(dx * dx + dy * dy);
    }

    double _polyAreaPx2(List<Offset> pts) {
      if (pts.length < 3) return 0.0;
      double s = 0.0;
      for (int i = 0; i < pts.length; i++) {
        final a = pts[i];
        final b = pts[(i + 1) % pts.length];
        s += (a.dx * b.dy) - (b.dx * a.dy);
      }
      return (s.abs() / 2.0);
    }

    // steel weights
    const steelDensity = 7850.0; // kg/m3

    double kgPerM_CHS({required double odMm, required double tMm}) {
      final Do = odMm / 1000.0;
      final t = tMm / 1000.0;
      final Di = (Do - 2.0 * t);
      if (Do <= 0 || t <= 0 || Di <= 0) return 0.0;
      final area = (math.pi / 4.0) * (Do * Do - Di * Di);
      return area * steelDensity;
    }

    double kgPerM_ZThinPlate({
      required double webMm,
      required double flangeMm,
      required double lipMm,
      required double tMm,
    }) {
      // developed length approximation for cold formed Z
      final devMm = webMm + flangeMm + lipMm + flangeMm + lipMm;
      final devM = devMm / 1000.0;
      final tM = tMm / 1000.0;
      if (devM <= 0 || tM <= 0) return 0.0;
      return (devM * tM) * steelDensity; // kg/m
    }

    TextEditingController _ctrl(String key, String fallback) {
      final v = lastTrussDefaults[key] ?? fallback;
      return TextEditingController(text: '$v');
    }

    Map<String, dynamic>? pickToMap(BoqPick? p) {
      if (p == null) return null;
      return {'id': p.id, 'code': p.code, 'description': p.description};
    }

    BoqPick? pickFromMap(dynamic v) {
      if (v is! Map) return null;
      final m = Map<String, dynamic>.from(v);
      final id = (m['id'] ?? '').toString();
      final code = (m['code'] ?? '').toString();
      final desc = (m['description'] ?? '').toString();
      if (id.isEmpty && code.isEmpty && desc.isEmpty) return null;
      return BoqPick(id: id, code: code, description: desc);
    }

    InputDecoration decoDense(String label) => const InputDecoration(
      border: OutlineInputBorder(),
      isDense: true,
    ).copyWith(labelText: label);

    Widget boqLine({
      required BuildContext ctx,
      required String title,
      required BoqPick? pick,
      required VoidCallback onPick,
      required VoidCallback onClear,
    }) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: InputDecorator(
                  decoration: const InputDecoration(
                    border: OutlineInputBorder(),
                    isDense: true,
                    labelText: 'BOQ code',
                  ),
                  child: Text(
                    (pick?.code ?? '').trim().isEmpty ? '—' : pick!.code,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ),
              const SizedBox(width: 8),
              OutlinedButton.icon(
                onPressed: onPick,
                icon: const Icon(Icons.search, size: 18),
                label: const Text('Pick'),
              ),
              const SizedBox(width: 8),
              OutlinedButton(onPressed: onClear, child: const Text('Clear')),
            ],
          ),
          if ((pick?.description ?? '').trim().isNotEmpty) ...[
            const SizedBox(height: 6),
            Text(
              pick!.description,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontSize: 12),
            ),
          ],
        ],
      );
    }

    int clampInt(int v, int lo, int hi) => v < lo ? lo : (v > hi ? hi : v);

    double d(TextEditingController c, double fb) =>
        double.tryParse(c.text.trim()) ?? fb;
    int ii(TextEditingController c, int fb) =>
        int.tryParse(c.text.trim()) ?? fb;

    void alertError(String msg) {
      Get.defaultDialog(
        title: 'Save failed',
        middleText: msg,
        textConfirm: 'OK',
        confirmTextColor: Colors.white,
        onConfirm: () => Get.back(),
      );
    }

    void alertOk(String msg) {
      Get.snackbar(
        'Saved',
        msg,
        snackPosition: SnackPosition.BOTTOM,
        duration: const Duration(seconds: 3),
      );
    }

    // ---------------- validation ----------------
    if (polygon.length < 3) {
      Get.snackbar('Polygon', 'Truss outline needs at least 3 points.');
      return RoofSaveAction.cancel;
    }

    final calibrated = drawingData['calibrated'] == true;
    final pxPerM = _num(drawingData['pixelsPerUnit'], 0);
    if (!calibrated || pxPerM <= 0) {
      Get.snackbar(
        'Not calibrated',
        'Calibrate drawing first (pixelsPerUnit).',
      );
      return RoofSaveAction.cancel;
    }

    // ---------------- geometry from polygon ----------------
    // bbox
    double minX = polygon.first.dx, maxX = polygon.first.dx;
    double minY = polygon.first.dy, maxY = polygon.first.dy;
    for (final p in polygon) {
      if (p.dx < minX) minX = p.dx;
      if (p.dx > maxX) maxX = p.dx;
      if (p.dy < minY) minY = p.dy;
      if (p.dy > maxY) maxY = p.dy;
    }

    final bboxWidthM = (maxX - minX) / pxPerM; // span approx
    final bboxHeightM = (maxY - minY) / pxPerM; // rise approx
    final planAreaM2 = _polyAreaPx2(polygon) / (pxPerM * pxPerM);

    // helpful: polygon perimeter
    final n = polygon.length;
    final perimeterM = List.generate(n, (i) {
      final a = polygon[i];
      final b = polygon[(i + 1) % n];
      return _distPx(a, b) / pxPerM;
    }).fold<double>(0.0, (s, v) => s + v);

    // ---------------- defaults / controllers ----------------
    final nameCtrl = _ctrl('trussName', (activeLabel ?? 'Truss T1').trim());
    final typeCtrl = _ctrl('trussType', 'T1');
    final clearSpanCtrl = _ctrl('clearSpanM', bboxWidthM.toStringAsFixed(3));
    final riseCtrl = _ctrl('riseM', bboxHeightM.toStringAsFixed(3));

    // main roof params (to compute quantities)
    final roofLengthCtrl = _ctrl('roofLengthM', '24'); // along building
    final trussSpacingCtrl = _ctrl(
      'trussSpacingM',
      '1.50',
    ); // spacing along roof length
    final purlinSpacingCtrl = _ctrl(
      'purlinSpacingM',
      '1.20',
    ); // spacing along slope

    final multiplyingFactorCtrl = _ctrl('multiplyingFactor', '1');

    // CHS sections
    bool useAutoKgTop = (lastTrussDefaults['useAutoKgTop'] ?? true) == true;
    bool useAutoKgBottom =
        (lastTrussDefaults['useAutoKgBottom'] ?? true) == true;
    bool useAutoKgStruts =
        (lastTrussDefaults['useAutoKgStruts'] ?? true) == true;
    bool useAutoKgBracing =
        (lastTrussDefaults['useAutoKgBracing'] ?? true) == true;

    final topOdCtrl = _ctrl('topOdMm', '42.4');
    final topThkCtrl = _ctrl('topThkMm', '3');
    final topKgPerMCtrl = _ctrl('topKgPerM', '2.915');

    final botOdCtrl = _ctrl('botOdMm', '42.4');
    final botThkCtrl = _ctrl('botThkMm', '3');
    final botKgPerMCtrl = _ctrl('botKgPerM', '2.915');

    final strutsOdCtrl = _ctrl('strutsOdMm', '42.4');
    final strutsThkCtrl = _ctrl('strutsThkMm', '3');
    final strutsKgPerMCtrl = _ctrl('strutsKgPerM', '2.915');

    final bracingOdCtrl = _ctrl('bracingOdMm', '42.4');
    final bracingThkCtrl = _ctrl('bracingThkMm', '3');
    final bracingKgPerMCtrl = _ctrl('bracingKgPerM', '2.915');

    // “shape factors” (very practical defaults)
    // You can tune these for your typical truss drawings.
    final strutsFactorCtrl = _ctrl(
      'strutsFactor',
      '0.80',
    ); // × bottom chord length
    final bracingFactorCtrl = _ctrl(
      'bracingFactor',
      '0.60',
    ); // × bottom chord length

    // Cleats + Base plates
    final cleatsPerIntersectionCtrl = _ctrl('cleatsPerIntersection', '1');
    final basePlatesPerTrussCtrl = _ctrl('basePlatesPerTruss', '2');

    // Z purlins (kg)
    bool useAutoKgZ = (lastTrussDefaults['useAutoKgZ'] ?? true) == true;
    final zWebCtrl = _ctrl('zWebMm', '125');
    final zFlangeCtrl = _ctrl('zFlangeMm', '50');
    final zLipCtrl = _ctrl('zLipMm', '20');
    final zThkCtrl = _ctrl('zThkMm', '2.0');
    final zKgPerMCtrl = _ctrl('zKgPerM', '3.82');

    // include toggles
    bool includeSteel = (lastTrussDefaults['includeSteel'] ?? true) == true;
    bool includeTop = (lastTrussDefaults['includeTop'] ?? true) == true;
    bool includeBottom = (lastTrussDefaults['includeBottom'] ?? true) == true;
    bool includeStruts = (lastTrussDefaults['includeStruts'] ?? true) == true;
    bool includeBracing = (lastTrussDefaults['includeBracing'] ?? true) == true;
    bool includeCleats = (lastTrussDefaults['includeCleats'] ?? true) == true;
    bool includeBasePlates =
        (lastTrussDefaults['includeBasePlates'] ?? true) == true;
    bool includeZPurlins =
        (lastTrussDefaults['includeZPurlins'] ?? true) == true;

    // BOQ picks (remembered)
    BoqPick? boqTop = pickFromMap(lastTrussDefaults['boqTopChord']);
    BoqPick? boqBottom = pickFromMap(lastTrussDefaults['boqBottomChord']);
    BoqPick? boqStruts = pickFromMap(lastTrussDefaults['boqStruts']);
    BoqPick? boqBracing = pickFromMap(lastTrussDefaults['boqBracing']);
    BoqPick? boqCleats = pickFromMap(lastTrussDefaults['boqCleats']);
    BoqPick? boqBasePlates = pickFromMap(lastTrussDefaults['boqBasePlates']);
    BoqPick? boqZPurlins = pickFromMap(lastTrussDefaults['boqZPurlins']);

    // ---------------- dialog ----------------
    final ctx = Get.context;
    if (ctx == null) return RoofSaveAction.cancel;

    RoofSaveAction action =
        await Get.dialog<RoofSaveAction>(
          StatefulBuilder(
            builder: (dctx, setState) {
              // live compute
              final clearSpanM = d(
                clearSpanCtrl,
                bboxWidthM,
              ).clamp(0.1, 999999.0);
              final riseM = d(riseCtrl, bboxHeightM).clamp(0.0, 999999.0);
              final roofLengthM = d(roofLengthCtrl, 24).clamp(0.1, 999999.0);
              final trussSpacingM = d(trussSpacingCtrl, 1.5).clamp(0.2, 20.0);
              final purlinSpacingM = d(purlinSpacingCtrl, 1.2).clamp(0.1, 10.0);

              final multiplyingFactor = d(
                multiplyingFactorCtrl,
                1,
              ).clamp(0.01, 999999.0);
              final factorInt = clampInt(multiplyingFactor.round(), 1, 999999);

              // derive slope length (one side)
              final halfSpan = clearSpanM / 2.0;
              final slopeLenOneSideM = math.sqrt(
                halfSpan * halfSpan + riseM * riseM,
              );

              // truss count along length
              final trussesNoBase = math.max(
                1,
                (roofLengthM / trussSpacingM).ceil() + 1,
              );
              final trussesNo = trussesNoBase * factorInt;

              // purlin rows along slope (per slope)
              final purlinRowsBase = math.max(
                1,
                (slopeLenOneSideM / purlinSpacingM).ceil() + 1,
              );

              // intersections (each purlin row intersects each truss, both slopes)
              final intersectionsBase = purlinRowsBase * trussesNoBase * 2;
              final intersections = intersectionsBase * factorInt;

              // CHS lengths per truss (base)
              final topChordLenPerTruss = 2.0 * slopeLenOneSideM; // two sides
              final bottomChordLenPerTruss = clearSpanM;

              final strutsFactor = d(strutsFactorCtrl, 0.8).clamp(0.0, 10.0);
              final bracingFactor = d(bracingFactorCtrl, 0.6).clamp(0.0, 10.0);

              final strutsLenPerTruss = bottomChordLenPerTruss * strutsFactor;
              final bracingLenPerTruss = bottomChordLenPerTruss * bracingFactor;

              // kg/m auto
              final topKgAuto = kgPerM_CHS(
                odMm: d(topOdCtrl, 42.4),
                tMm: d(topThkCtrl, 3),
              );
              final botKgAuto = kgPerM_CHS(
                odMm: d(botOdCtrl, 42.4),
                tMm: d(botThkCtrl, 3),
              );
              final strutsKgAuto = kgPerM_CHS(
                odMm: d(strutsOdCtrl, 42.4),
                tMm: d(strutsThkCtrl, 3),
              );
              final bracingKgAuto = kgPerM_CHS(
                odMm: d(bracingOdCtrl, 42.4),
                tMm: d(bracingThkCtrl, 3),
              );

              // final topKgPerM = (useAutoKgTop
              //         ? topKgAuto
              //         : d(topKgPerMCtrl, 2.915))
              //     .clamp(0.0, 99999.0);

              final topKgPerM = clampD(
                useAutoKgTop ? topKgAuto : d(topKgPerMCtrl, 2.915),
                0.0,
                99999.0,
              );

              final botKgPerM = (useAutoKgBottom
                      ? botKgAuto
                      : d(botKgPerMCtrl, 2.915))
                  .clamp(0.0, 99999.0);
              final strutsKgPerM = (useAutoKgStruts
                      ? strutsKgAuto
                      : d(strutsKgPerMCtrl, 2.915))
                  .clamp(0.0, 99999.0);
              final bracingKgPerM = (useAutoKgBracing
                      ? bracingKgAuto
                      : d(bracingKgPerMCtrl, 2.915))
                  .clamp(0.0, 99999.0);

              // totals (BASE)
              final topLenBase = topChordLenPerTruss * trussesNoBase;
              final botLenBase = bottomChordLenPerTruss * trussesNoBase;
              final strutsLenBase = strutsLenPerTruss * trussesNoBase;
              final bracingLenBase = bracingLenPerTruss * trussesNoBase;

              final topKgBase = topLenBase * topKgPerM;
              final botKgBase = botLenBase * botKgPerM;
              final strutsKgBase = strutsLenBase * strutsKgPerM;
              final bracingKgBase = bracingLenBase * bracingKgPerM;

              // totals (SCALED)
              double scale(double v) => v * multiplyingFactor;
              final topKg = scale(topKgBase);
              final botKg = scale(botKgBase);
              final strutsKg = scale(strutsKgBase);
              final bracingKg = scale(bracingKgBase);

              // cleats + base plates
              final cleatsPerIntersection = clampInt(
                ii(cleatsPerIntersectionCtrl, 1),
                0,
                999999,
              );
              final cleatsBase = intersectionsBase * cleatsPerIntersection;
              final cleats = cleatsBase * factorInt;

              final basePlatesPerTruss = clampInt(
                ii(basePlatesPerTrussCtrl, 2),
                0,
                999999,
              );
              final basePlatesBase = trussesNoBase * basePlatesPerTruss;
              final basePlates = basePlatesBase * factorInt;

              // Z purlins (length = roofLength * rows * 2 slopes)
              final zKgAuto = kgPerM_ZThinPlate(
                webMm: d(zWebCtrl, 125),
                flangeMm: d(zFlangeCtrl, 50),
                lipMm: d(zLipCtrl, 20),
                tMm: d(zThkCtrl, 2.0),
              );
              final zKgPerM = (useAutoKgZ ? zKgAuto : d(zKgPerMCtrl, 3.82))
                  .clamp(0.0, 99999.0);

              final zLenBase = roofLengthM * purlinRowsBase * 2;
              final zKgBase = zLenBase * zKgPerM;
              final zLen = scale(zLenBase);
              final zKg = scale(zKgBase);

              return AlertDialog(
                title: const Text('Truss template takeoff (fast)'),
                content: SizedBox(
                  width: 820,
                  child: SingleChildScrollView(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          'Polygon bbox(span≈${bboxWidthM.toStringAsFixed(3)}m, rise≈${bboxHeightM.toStringAsFixed(3)}m) • '
                          'polyArea≈${planAreaM2.toStringAsFixed(3)}m² • perimeter≈${perimeterM.toStringAsFixed(3)}m',
                          style: const TextStyle(fontSize: 12),
                        ),
                        const SizedBox(height: 10),

                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: nameCtrl,
                                decoration: decoDense('Template name'),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                controller: typeCtrl,
                                decoration: decoDense('Type (e.g. T1)'),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 10),

                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: clearSpanCtrl,
                                decoration: decoDense('Clear span (m)'),
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                controller: riseCtrl,
                                decoration: decoDense('Rise (m)'),
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                          ],
                        ),

                        const SizedBox(height: 10),
                        Row(
                          children: [
                            Expanded(
                              child: TextField(
                                controller: roofLengthCtrl,
                                decoration: decoDense(
                                  'Roof length along building (m)',
                                ),
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                            const SizedBox(width: 8),
                            Expanded(
                              child: TextField(
                                controller: trussSpacingCtrl,
                                decoration: decoDense('Truss spacing (m)'),
                                keyboardType:
                                    const TextInputType.numberWithOptions(
                                      decimal: true,
                                    ),
                                onChanged: (_) => setState(() {}),
                              ),
                            ),
                          ],
                        ),

